                      onChange={e => setHours({ breakDurationMinutes: Number(e.target.value) })} />
                  </div>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4 pt-2 border-t">
                <div>
                  <Label>Max Late Minutes / Month</Label>
