export function Sidebar({ isCollapsed, onToggle, activeModule, onModuleChange }: SidebarProps) {
  const { user, logout } = useAuth();

  if (!user) return null;

  const filteredNavItems = navItems.filter(item => {
    if (!item.roles.includes(user.role)) return false;

    // Filter department-specific tabs for employee role
    if (item.department && user.role === 'employee') {
      const userDeptType = typeof (user as any).department === 'object' 
        ? ((user as any).department as any)?.type 
        : null;
      return userDeptType === item.department;
    }

    return true;
  });

  const handleNavClick = (itemId: string) => {
    onModuleChange(itemId);
  };

  return (
    <div
      className={cn(
        'flex flex-col h-screen bg-slate-900 text-white transition-all duration-300 border-r border-slate-800',
        isCollapsed ? 'w-16' : 'w-64'
      )}
    >
      {/* Logo */}
      <div className="flex items-center justify-between h-16 px-4 border-b border-slate-800">
        {!isCollapsed && (
          <div className="flex items-center gap-2">
            <img src="/logo.png" alt="PYPE ERP" className="w-8 h-8 object-contain rounded-lg" />
            <span className="font-bold text-lg tracking-tight">PYPE ERP</span>
          </div>
        )}
        {isCollapsed && (
          <img src="/logo.png" alt="PYPE ERP" className="w-8 h-8 object-contain rounded-lg mx-auto" />
        )}
        <Button
          variant="ghost"
          size="icon"
          onClick={onToggle}
          className="text-slate-400 hover:text-white hover:bg-slate-800"
        >
          {isCollapsed ? <ChevronRight className="w-4 h-4" /> : <ChevronLeft className="w-4 h-4" />}
        </Button>
      </div>

      {/* Navigation */}
      <ScrollArea className="flex-1 py-4">
        <nav className="px-2 space-y-1">
          {filteredNavItems.map((item) => (
            <NavItemComponent
              key={item.id}
              item={item}
              isCollapsed={isCollapsed}
              isActive={activeModule === item.id || (item.children?.some(c => c.id === activeModule) ?? false)}
              activeChild={activeModule}
              onClick={handleNavClick}
            />
          ))}
        </nav>
      </ScrollArea>

      {/* User Info & Logout */}
      <div className="border-t border-slate-800 p-4">
        {!isCollapsed && (
          <div className="mb-4 px-2">
            <p className="text-sm font-medium text-white">{user.name}</p>
            <p className="text-xs text-slate-400 capitalize">{user.role.replace('_', ' ')}</p>
          </div>
        )}
        <Button
          variant="ghost"
          className={cn(
            'w-full text-slate-400 hover:text-white hover:bg-slate-800',
            isCollapsed && 'px-2'
          )}
          onClick={logout}
        >
          <LogOut className="w-4 h-4" />
          {!isCollapsed && <span className="ml-2">Logout</span>}
        </Button>
      </div>
    </div>
  );
}

interface NavItemComponentProps {
  item: NavItem;
  isCollapsed: boolean;
  isActive: boolean;
  activeChild: string;
  onClick: (id: string) => void;
  level?: number;
}

function NavItemComponent({ item, isCollapsed, isActive, activeChild, onClick, level = 0 }: NavItemComponentProps) {
  const [isExpanded, setIsExpanded] = React.useState(isActive);
  const Icon = item.icon;

  const hasChildren = item.children && item.children.length > 0;

  const handleClick = () => {
    if (hasChildren) {
      setIsExpanded(!isExpanded);
    } else {
      onClick(item.id);
    }
  };

  const handleChildClick = (childId: string) => {
    onClick(childId);
  };

  return (
    <div>
      <button
        onClick={handleClick}
        className={cn(
          'w-full flex items-center gap-3 px-3 py-2 rounded-md text-sm font-medium transition-colors',
          isActive
            ? 'bg-blue-600 text-white'
            : 'text-slate-300 hover:bg-slate-800 hover:text-white',
          isCollapsed && 'justify-center px-2'
        )}
        style={{ paddingLeft: isCollapsed ? undefined : `${12 + level * 12}px` }}
      >
        <Icon className="w-4 h-4 flex-shrink-0" />
        {!isCollapsed && (
          <>
            <span className="flex-1 text-left">{item.label}</span>
            {item.badge && (
              <Badge variant="destructive" className="text-xs">
                {item.badge}
              </Badge>
            )}
            {hasChildren && (
              <ChevronRight
                className={cn(
                  'w-4 h-4 transition-transform',
                  isExpanded && 'rotate-90'
                )}
              />
            )}
          </>
        )}
      </button>

      {/* Child Items */}
      {!isCollapsed && hasChildren && isExpanded && (
        <div className="mt-1 ml-4 space-y-1 border-l border-slate-700">
          {item.children!.map((child) => (
            <button
              key={child.id}
              onClick={() => handleChildClick(child.id)}
              className={cn(
                'w-full flex items-center gap-3 px-3 py-2 rounded-md text-sm transition-colors',
                activeChild === child.id
                  ? 'bg-blue-600/50 text-white'
                  : 'text-slate-400 hover:bg-slate-800 hover:text-white'
              )}
            >
              <child.icon className="w-4 h-4 flex-shrink-0" />
              <span className="flex-1 text-left">{child.label}</span>
              {child.badge && (
                <Badge variant="destructive" className="text-xs">
                  {child.badge}
                </Badge>
              )}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Edit, Trash2, Calendar, Copy } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import api from '@/lib/api';
import { useAuth } from '@/hooks/useAuth';
import { toast } from 'sonner';

export function AdmissionSessionsPanel() {
  const { user } = useAuth();
  const canWrite = ['org_admin', 'superadmin'].includes(user?.role || '');
  const [sessions, setSessions] = useState<any[]>([]);
  const [universities, setUniversities] = useState<any[]>([]);
  const [universityFilter, setUniversityFilter] = useState('');
  const [loading, setLoading] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    subDepartmentId: '',
    startDate: '',
    endDate: '',
    examDate: '',
    reregPaymentClosingDate: '',
    status: 'pending'
  });

  useEffect(() => {
    fetchSessions();
    fetchDepartments();
    fetchUniversities();
  }, [universityFilter]);

  const fetchSessions = async () => {
    setLoading(true);
    try {
      const q = universityFilter && universityFilter !== 'all' ? `?universityId=${universityFilter}` : '';
      const res = await api.get(`/operations/sessions${q}`);
      setSessions(res.data.data || []);
    } catch (err) {
      console.error('Failed to fetch sessions:', err);
    } finally {
      setLoading(false);
    }
  };

  const fetchDepartments = async () => {
    try {
      const res = await api.get('/departments');
      // Filter to operations-type departments only, as AdmissionSession.subDepartmentId refs Department
      const all = res.data.data || [];
      setDepartments(all.filter((d: any) => d.type === 'operations'));
    } catch (err) {
      console.error('Failed to fetch departments:', err);
    }
  };

  const fetchUniversities = async () => {
    try {
      const res = await api.get('/operations/universities');
      setUniversities(res.data.data || []);
    } catch (err) {
      console.error('Failed to fetch universities:', err);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const payload: any = {
        name: formData.name,
        subDepartmentId: formData.subDepartmentId,
        startDate: formData.startDate,
        endDate: formData.endDate,
        status: formData.status
      };
      if (formData.examDate) payload.examDate = formData.examDate;
      if (formData.reregPaymentClosingDate) payload.reregPaymentClosingDate = formData.reregPaymentClosingDate;

      if (editingId) {
        await api.put(`/operations/sessions/${editingId}`, payload);
      } else {
        await api.post('/operations/sessions', payload);
      }
      setDialogOpen(false);
      resetForm();
      fetchSessions();
    } catch (err: any) {
      alert(err.response?.data?.message || 'Failed to save session');
    }
  };

  const handleEdit = (s: any) => {
    const subDeptId = typeof s.subDepartmentId === 'object'
      ? (s.subDepartmentId?.id || s.subDepartmentId?.id)
      : s.subDepartmentId;
    setEditingId(s.id || s.id);
    setFormData({
      name: s.name || '',
      subDepartmentId: subDeptId?.toString() || '',
      startDate: s.startDate ? new Date(s.startDate).toISOString().split('T')[0] : '',
      endDate: s.endDate ? new Date(s.endDate).toISOString().split('T')[0] : '',
      examDate: s.examDate ? new Date(s.examDate).toISOString().split('T')[0] : '',
      reregPaymentClosingDate: s.reregPaymentClosingDate ? new Date(s.reregPaymentClosingDate).toISOString().split('T')[0] : '',
      status: s.status || 'pending'
    });
    setDialogOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this session?')) return;
    try {
      await api.delete(`/operations/sessions/${id}`);
      fetchSessions();
    } catch (err) {
      console.error('Failed to delete session:', err);
    }
  };

  const handleDuplicate = async (id: string) => {
    if (!confirm('Duplicate this session?')) return;
    try {
      await api.post(`/operations/sessions/${id}/duplicate`);
      fetchSessions();
      toast.success('Session duplicated successfully');
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to duplicate session');
    }
  };

  const resetForm = () => {
    setEditingId(null);
    setFormData({ name: '', subDepartmentId: '', startDate: '', endDate: '', examDate: '', reregPaymentClosingDate: '', status: 'pending' });
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Admission Session Management</h2>
          <p className="text-muted-foreground">Manage admission sessions and cycles</p>
        </div>
        {canWrite && (
          <Dialog open={dialogOpen} onOpenChange={(open) => { setDialogOpen(open); if (!open) resetForm(); }}>
            <DialogTrigger asChild>
              <Button><Plus className="w-4 h-4 mr-2" />Add Session</Button>
            </DialogTrigger>
          <DialogContent className="max-w-lg">
            <DialogHeader>
              <DialogTitle>{editingId ? 'Edit Session' : 'Add New Session'}</DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <Label>Session Name</Label>
                <Input value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} required />
              </div>
              <div>
                <Label>Department</Label>
                <Select value={formData.subDepartmentId} onValueChange={(v) => setFormData({ ...formData, subDepartmentId: v })}>
                  <SelectTrigger><SelectValue placeholder="Select department" /></SelectTrigger>
                  <SelectContent>
                    {departments.filter(d => d && (d.id || d.id)).map((d) => (
                      <SelectItem key={d.id || d.id} value={(d.id || d.id).toString()}>
                        {d.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Start Date</Label>
                  <Input type="date" value={formData.startDate} onChange={(e) => setFormData({ ...formData, startDate: e.target.value })} required />
                </div>
                <div>
                  <Label>End Date</Label>
                  <Input type="date" value={formData.endDate} onChange={(e) => setFormData({ ...formData, endDate: e.target.value })} required />
                </div>
              </div>
              <div>
                <Label>Exam Date (optional)</Label>
                <Input type="date" value={formData.examDate} onChange={(e) => setFormData({ ...formData, examDate: e.target.value })} />
              </div>
              <div>
                <Label>Re-registration Payment Closing Date (optional)</Label>
                <Input type="date" value={formData.reregPaymentClosingDate} onChange={(e) => setFormData({ ...formData, reregPaymentClosingDate: e.target.value })} />
              </div>
              <div>
                <Label>Status</Label>
                <Select value={formData.status} onValueChange={(v) => setFormData({ ...formData, status: v })}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="pending">Pending</SelectItem>
                    <SelectItem value="approved">Approved</SelectItem>
                    <SelectItem value="active">Active</SelectItem>
                    <SelectItem value="closed">Closed</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="flex gap-2">
                <Button type="submit" className="flex-1">Save</Button>
                <Button type="button" variant="outline" onClick={() => setDialogOpen(false)}>Cancel</Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>
        )}
      </div>

      <div className="flex justify-end mb-4">
        <Select value={universityFilter} onValueChange={setUniversityFilter}>
          <SelectTrigger className="w-[200px]">
            <SelectValue placeholder="All Universities" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Universities</SelectItem>
            {universities.map(u => (
              <SelectItem key={u.id} value={u.id}>{u.name}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <Card>
        <CardHeader><CardTitle>Admission Sessions</CardTitle></CardHeader>
        <CardContent>
          {loading ? (
            <div className="text-center py-8">Loading...</div>
          ) : sessions.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">No sessions found</div>
          ) : (
            <div className="space-y-2">
              {sessions.filter(s => s && (s.id || s.id)).map((s) => {
                const sid = s.id || s.id;
                const subDeptName = typeof s.subDepartmentId === 'object' ? s.subDepartmentId?.name : '';
                return (
                  <div key={sid} className="flex items-center justify-between p-4 border rounded-lg hover:bg-muted/50">
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center">
                        <Calendar className="w-5 h-5 text-primary" />
                      </div>
                      <div>
                        <div className="font-medium">{s.name}</div>
                        <div className="text-sm text-muted-foreground">
                          {subDeptName && `${subDeptName} • `}
                          {s.startDate && new Date(s.startDate).toLocaleDateString()} – {s.endDate && new Date(s.endDate).toLocaleDateString()}
                        </div>
                        {s.examDate && (
                          <div className="text-xs text-muted-foreground">Exam: {new Date(s.examDate).toLocaleDateString()}</div>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <Badge>{s.status}</Badge>
                      {canWrite && (
                        <>
                          <Button title="Duplicate" variant="ghost" size="sm" onClick={() => handleDuplicate(sid)}><Copy className="w-4 h-4" /></Button>
                          <Button title="Edit" variant="ghost" size="sm" onClick={() => handleEdit(s)}><Edit className="w-4 h-4" /></Button>
                          <Button title="Delete" variant="ghost" size="sm" onClick={() => handleDelete(sid)}><Trash2 className="w-4 h-4" /></Button>
                        </>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Edit, Trash2, Megaphone, RefreshCw } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import api from '@/lib/api';

import { useAuth } from '@/hooks/useAuth';

const PRIORITY_COLORS: Record<string, string> = {
  high: 'bg-red-100 text-red-800',
  medium: 'bg-yellow-100 text-yellow-800',
  low: 'bg-green-100 text-green-800',
};

const TYPE_COLORS: Record<string, string> = {
  general: 'bg-blue-100 text-blue-800',
  hr: 'bg-purple-100 text-purple-800',
  ops: 'bg-orange-100 text-orange-800',
  finance: 'bg-emerald-100 text-emerald-800',
  sales: 'bg-cyan-100 text-cyan-800',
};

export function AnnouncementsPanel() {
  const { user } = useAuth();
  const canManage = ['hr_admin', 'org_admin', 'superadmin'].includes(user?.role || '');
  const [announcements, setAnnouncements] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState({
    title: '', content: '', type: 'general', priority: 'medium', expiresAt: '',
  });

  useEffect(() => { fetchAnnouncements(); }, []);

  const fetchAnnouncements = async () => {
    setLoading(true);
    try {
      const res = await api.get('/hr/announcements');
      setAnnouncements(res.data.data || []);
    } catch { toast.error('Failed to load announcements'); }
    finally { setLoading(false); }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const payload = { ...form, expiresAt: form.expiresAt || undefined };
      if (editingId) {
        await api.put(`/hr/announcements/${editingId}`, payload);
        toast.success('Announcement updated');
      } else {
        await api.post('/hr/announcements', payload);
        toast.success('Announcement published');
      }
      setDialogOpen(false);
      resetForm();
      fetchAnnouncements();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to save');
    }
  };

  const handleEdit = (a: any) => {
    setEditingId(a.id || a.id);
    setForm({
      title: a.title || '',
      content: a.content || '',
      type: a.type || 'general',
      priority: a.priority || 'medium',
      expiresAt: a.expiresAt ? new Date(a.expiresAt).toISOString().split('T')[0] : '',
    });
    setDialogOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this announcement?')) return;
    try {
      await api.delete(`/hr/announcements/${id}`);
      toast.success('Deleted');
      fetchAnnouncements();
    } catch { toast.error('Failed to delete'); }
  };

  const resetForm = () => {
    setEditingId(null);
    setForm({ title: '', content: '', type: 'general', priority: 'medium', expiresAt: '' });
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Announcements</h2>
          <p className="text-muted-foreground text-sm">Publish org-wide announcements visible to all employees</p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={fetchAnnouncements}>
            <RefreshCw className="w-4 h-4 mr-1" /> Refresh
          </Button>
          {canManage && (
            <Button size="sm" onClick={() => { resetForm(); setDialogOpen(true); }}>
              <Plus className="w-4 h-4 mr-1" /> New Announcement
            </Button>
          )}
        </div>
      </div>

      <Card>
        <CardHeader><CardTitle>Published Announcements</CardTitle></CardHeader>
        <CardContent>
          {loading ? (
            <div className="space-y-3">{[1,2,3].map(i => <div key={i} className="h-20 bg-muted rounded-lg animate-pulse" />)}</div>
          ) : announcements.length === 0 ? (
            <div className="text-center py-12 text-muted-foreground">
              <Megaphone className="w-10 h-10 mx-auto mb-3 opacity-30" />
              <p>No announcements yet</p>
            </div>
          ) : (
            <div className="space-y-3">
              {announcements.map(a => {
                const aid = a.id || a.id;
                return (
                  <div key={aid} className="flex items-start gap-4 p-4 border rounded-lg hover:bg-muted/30 transition-colors">
                    <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
                      <Megaphone className="w-5 h-5 text-primary" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="font-semibold">{a.title}</p>
                      <p className="text-sm text-muted-foreground mt-0.5 line-clamp-2">{a.content}</p>
                      <div className="flex flex-wrap items-center gap-2 mt-2">
                        <Badge className={`text-xs ${TYPE_COLORS[a.type] || ''}`}>{a.type}</Badge>
                        <Badge className={`text-xs ${PRIORITY_COLORS[a.priority] || ''}`}>{a.priority}</Badge>
                        {a.postedBy?.name && <span className="text-xs text-muted-foreground">by {a.postedBy.name}</span>}
                        <span className="text-xs text-muted-foreground">{new Date(a.postedAt || a.createdAt).toLocaleDateString()}</span>
                        {a.expiresAt && <span className="text-xs text-orange-600">Expires {new Date(a.expiresAt).toLocaleDateString()}</span>}
                      </div>
                    </div>
                    <div className="flex gap-1 shrink-0">
                      {canManage && (
                        <>
                          <Button variant="ghost" size="sm" onClick={() => handleEdit(a)}><Edit className="w-4 h-4" /></Button>
                          <Button variant="ghost" size="sm" onClick={() => handleDelete(aid)}><Trash2 className="w-4 h-4" /></Button>
                        </>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>

      {canManage && (
      <Dialog open={dialogOpen} onOpenChange={open => { setDialogOpen(open); if (!open) resetForm(); }}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>{editingId ? 'Edit Announcement' : 'New Announcement'}</DialogTitle>
          </DialogHeader>
          <form onSubmit={handleSubmit} className="space-y-4 pt-2">
            <div className="space-y-1">
              <Label>Title</Label>
              <Input value={form.title} onChange={e => setForm(f => ({ ...f, title: e.target.value }))} required />
            </div>
            <div className="space-y-1">
              <Label>Content</Label>
              <Textarea rows={4} value={form.content} onChange={e => setForm(f => ({ ...f, content: e.target.value }))} required />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <Label>Type</Label>
                <Select value={form.type} onValueChange={v => setForm(f => ({ ...f, type: v }))}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="general">General</SelectItem>
                    <SelectItem value="hr">HR</SelectItem>
                    <SelectItem value="ops">Operations</SelectItem>
                    <SelectItem value="finance">Finance</SelectItem>
                    <SelectItem value="sales">Sales</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1">
                <Label>Priority</Label>
                <Select value={form.priority} onValueChange={v => setForm(f => ({ ...f, priority: v }))}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="low">Low</SelectItem>
                    <SelectItem value="medium">Medium</SelectItem>
                    <SelectItem value="high">High</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="space-y-1">
              <Label>Expires On (optional)</Label>
              <Input type="date" value={form.expiresAt} onChange={e => setForm(f => ({ ...f, expiresAt: e.target.value }))} />
            </div>
            <div className="flex gap-2 pt-2">
              <Button type="submit" className="flex-1">{editingId ? 'Update' : 'Publish'}</Button>
              <Button type="button" variant="outline" onClick={() => setDialogOpen(false)}>Cancel</Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Edit, Trash2 } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { useAuth } from '@/hooks/useAuth';
import api from '@/lib/api';

export function AttendancePanel() {
  const { user } = useAuth();
  const isHR = user?.role === 'hr_admin';
  const canViewAll = ['hr_admin', 'org_admin', 'ceo'].includes(user?.role || '');
  const [attendance, setAttendance] = useState<any[]>([]);
  const [employees, setEmployees] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    employeeId: '',
    date: new Date().toISOString().split('T')[0],
    status: 'present',
    checkIn: '09:00',
    checkOut: '18:00',
    notes: ''
  });

  useEffect(() => {
    fetchAttendance();
    if (canViewAll) fetchEmployees();
  }, []);

  const fetchAttendance = async () => {
    setLoading(true);
    try {
      // HR sees all; employees see only their own
      const endpoint = canViewAll ? '/hr/attendance' : '/hr/attendance/my';
      const response = await api.get(endpoint);
      setAttendance(response.data.data || []);
    } catch (error) {
      console.error('Failed to fetch attendance:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    try {
      const response = await api.get('/users');
      setEmployees(response.data.data || []);
    } catch (error) {
      console.error('Failed to fetch employees:', error);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      // Combine date + time strings into full ISO datetime for the Date fields
      const toISO = (date: string, time: string) => {
        if (!date || !time) return undefined;
        return new Date(`${date}T${time}:00`).toISOString();
      };
      const payload: any = {
        employeeId: formData.employeeId,
        date: new Date(formData.date).toISOString(),
        status: formData.status,
        notes: formData.notes,
      };
      if (formData.checkIn) payload.checkIn = toISO(formData.date, formData.checkIn);
      if (formData.checkOut) payload.checkOut = toISO(formData.date, formData.checkOut);

      if (editingId) {
        await api.put(`/hr/attendance/${editingId}`, payload);
      } else {
        await api.post('/hr/attendance', payload);
      }
      setDialogOpen(false);
      resetForm();
      fetchAttendance();
    } catch (error: any) {
      console.error('Failed to save attendance:', error);
      alert(error.response?.data?.message || 'Failed to save attendance');
    }
  };

  const handleEdit = (record: any) => {
    const recId = record.id || record.id;
    const empId = record.employeeId?.id || record.employeeId?.id || record.employeeId || '';
    setEditingId(recId);
    setFormData({
      employeeId: empId?.toString() || '',
      date: record.date ? new Date(record.date).toISOString().split('T')[0] : '',
      status: record.status || 'present',
      checkIn: record.checkIn ? new Date(record.checkIn).toTimeString().slice(0, 5) : '09:00',
      checkOut: record.checkOut ? new Date(record.checkOut).toTimeString().slice(0, 5) : '18:00',
      notes: record.notes || ''
    });
    setDialogOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this attendance record?')) return;
    try {
      await api.delete(`/hr/attendance/${id}`);
      fetchAttendance();
    } catch (error) {
      console.error('Failed to delete attendance:', error);
    }
  };

  const resetForm = () => {
    setEditingId(null);
    setFormData({
      employeeId: '',
      date: new Date().toISOString().split('T')[0],
      status: 'present',
      checkIn: '09:00',
      checkOut: '18:00',
      notes: ''
    });
  };

  const getStatusBadge = (status: string) => {
    const variants: any = {
      present: 'bg-green-100 text-green-800',
      absent: 'bg-red-100 text-red-800',
      late: 'bg-yellow-100 text-yellow-800',
      half_day: 'bg-blue-100 text-blue-800',
      leave: 'bg-purple-100 text-purple-800'
    };
    return <Badge className={variants[status] || ''}>{status?.replace('_', ' ')}</Badge>;
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Attendance {canViewAll ? 'Management' : 'Records'}</h2>
          <p className="text-muted-foreground">{canViewAll ? 'Track and manage employee attendance' : 'Your attendance history'}</p>
        </div>
        {isHR && (
        <Dialog open={dialogOpen} onOpenChange={(open) => { setDialogOpen(open); if (!open) resetForm(); }}>          <DialogTrigger asChild>
            <Button><Plus className="w-4 h-4 mr-2" />Mark Attendance</Button>
          </DialogTrigger>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>{editingId ? 'Edit Attendance' : 'Mark Attendance'}</DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <Label>Employee</Label>
                <Select value={formData.employeeId} onValueChange={(value) => setFormData({...formData, employeeId: value})}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select employee" />
                  </SelectTrigger>
                  <SelectContent>
                    {employees.filter(emp => emp && (emp.id || emp.id)).map((emp) => (
                      <SelectItem key={emp.id || emp.id} value={(emp.id || emp.id).toString()}>
                        {emp.name || `${emp.firstName || ''} ${emp.lastName || ''}`.trim()}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label>Date</Label>
                <Input type="date" value={formData.date} onChange={(e) => setFormData({...formData, date: e.target.value})} required />
              </div>
              <div>
                <Label>Status</Label>
                <Select value={formData.status} onValueChange={(value) => setFormData({...formData, status: value})}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="present">Present</SelectItem>
                    <SelectItem value="absent">Absent</SelectItem>
                    <SelectItem value="late">Late</SelectItem>
                    <SelectItem value="half_day">Half Day</SelectItem>
                    <SelectItem value="leave">Leave</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Check In</Label>
                  <Input type="time" value={formData.checkIn} onChange={(e) => setFormData({...formData, checkIn: e.target.value})} />
                </div>
                <div>
                  <Label>Check Out</Label>
                  <Input type="time" value={formData.checkOut} onChange={(e) => setFormData({...formData, checkOut: e.target.value})} />
                </div>
              </div>
              <div>
                <Label>Notes</Label>
                <Input value={formData.notes} onChange={(e) => setFormData({...formData, notes: e.target.value})} placeholder="Optional notes" />
              </div>
              <div className="flex gap-2">
                <Button type="submit" className="flex-1">Save</Button>
                <Button type="button" variant="outline" onClick={() => setDialogOpen(false)}>Cancel</Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>
        )}
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Attendance Records</CardTitle>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="text-center py-8">Loading...</div>
          ) : attendance.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">No attendance records found</div>
          ) : (
            <div className="space-y-2">
              {attendance.filter(rec => rec && (rec.id || rec.id)).map((record) => {
                const recId = record.id || record.id;
                return (
                <div key={recId} className="flex items-center justify-between p-4 border rounded-lg hover:bg-muted/50">
                  <div className="flex-1">
                    <div className="font-medium">
                      {record.employeeId?.name || record.employee?.name || record.user?.name || 'Unknown'}
                    </div>
                    <div className="text-sm text-muted-foreground">
                      {new Date(record.date).toLocaleDateString()} • {record.checkIn ? new Date(record.checkIn).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '--'} - {record.checkOut ? new Date(record.checkOut).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '--'}
                    </div>
                    {record.notes && <div className="text-xs text-muted-foreground mt-1">{record.notes}</div>}
                  </div>
                  <div className="flex items-center gap-2">
                    {getStatusBadge(record.status)}
                    {isHR && (
                      <>
                        <Button variant="ghost" size="sm" onClick={() => handleEdit(record)}>
                          <Edit className="w-4 h-4" />
                        </Button>
                        <Button variant="ghost" size="sm" onClick={() => handleDelete(recId)}>
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </>
                    )}
                  </div>
                </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
