export function BranchesPanel() {
  const [branches, setBranches] = useState<Branch[]>([]);
  const [allUsers, setAllUsers] = useState<OrgUser[]>([]);
  const [allDepts, setAllDepts] = useState<Dept[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  // Create / Edit dialog
  const [branchDialog, setBranchDialog] = useState(false);
  const [editingBranch, setEditingBranch] = useState<Branch | null>(null);
  const [form, setForm] = useState({
    name: '', code: '', address: '', city: '', state: '', branchManagerId: '',
  });

  // Assign manager dialog (includes dept selection)
  const [managerDialog, setManagerDialog] = useState(false);
  const [managerTarget, setManagerTarget] = useState<Branch | null>(null);
  const [managerUserId, setManagerUserId] = useState('');
  const [selectedDeptIds, setSelectedDeptIds] = useState<string[]>([]);

  // Manage departments dialog (for existing branch, no manager change)
  const [deptDialog, setDeptDialog] = useState(false);
  const [deptTarget, setDeptTarget] = useState<Branch | null>(null);
  const [deptSelection, setDeptSelection] = useState<string[]>([]);

  const fetchAll = async () => {
    setLoading(true);
    try {
      const [branchRes, userRes, deptRes] = await Promise.all([
        api.get('/org/branches'),
        api.get('/users'),
        api.get('/departments'),
      ]);
      setBranches(branchRes.data.data || []);
      setAllUsers(userRes.data.data || []);
      setAllDepts(deptRes.data.data || []);
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to load branches');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchAll(); }, []);

  // Depts available as "additional" — excludes auto-created branch depts AND finance/hr (those are org-wide)
  const RESTRICTED_TYPES = new Set(['finance', 'hr']);

  const getAvailableExtraDepts = (branch: Branch | null) => {
    const autoIds = new Set<string>();
    branches.forEach(b => {
      if (b.salesDeptId) autoIds.add(b.salesDeptId.id);
      if (b.operationsDeptId) autoIds.add(b.operationsDeptId.id);
    });
    if (branch?.salesDeptId) autoIds.add(branch.salesDeptId.id);
    if (branch?.operationsDeptId) autoIds.add(branch.operationsDeptId.id);
    return allDepts.filter(d => !autoIds.has(d.id) && !RESTRICTED_TYPES.has(d.type));
  };

  const toggleDept = (id: string, list: string[], setList: (v: string[]) => void) => {
    setList(list.includes(id) ? list.filter(x => x !== id) : [...list, id]);
  };

  // ── Create / Edit ──
  const openCreate = () => {
    setEditingBranch(null);
    setForm({ name: '', code: '', address: '', city: '', state: '', branchManagerId: '' });
    setBranchDialog(true);
  };

  const openEdit = (b: Branch) => {
    setEditingBranch(b);
    setForm({ name: b.name, code: b.code, address: b.address, city: b.city || '', state: b.state || '', branchManagerId: '' });
    setBranchDialog(true);
  };

  const handleSave = async () => {
    if (!form.name || !form.code || !form.address) {
      toast.error('Name, branch code, and address are required'); return;
    }
    setSaving(true);
    try {
      if (editingBranch) {
        await api.patch(`/org/branches/${editingBranch.id}`, {
          name: form.name, address: form.address, city: form.city, state: form.state,
        });
      } else {
        await api.post('/org/branches', {
          name: form.name, code: form.code, address: form.address,
          city: form.city, state: form.state,
          branchManagerId: form.branchManagerId || undefined,
        });
      }
      toast.success(editingBranch ? 'Branch updated' : 'Branch created with Sales & Operations departments');
      setBranchDialog(false);
      fetchAll();
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to save branch');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (b: Branch) => {
    if (!confirm(`Delete branch "${b.name}"? This will also remove its Sales and Operations departments.`)) return;
    try {
      await api.delete(`/org/branches/${b.id}`);
      toast.success('Branch deleted');
      fetchAll();
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to delete branch');
    }
  };

  // ── Assign Manager ──
  const openAssignManager = (b: Branch) => {
    setManagerTarget(b);
    setManagerUserId(b.branchManagerId?.id || '');
    setSelectedDeptIds((b.additionalDeptIds || []).map(d => d.id));
    setManagerDialog(true);
  };

  const handleAssignManager = async () => {
    if (!managerTarget) return;
    setSaving(true);
    try {
      await api.patch(`/org/branches/${managerTarget.id}/manager`, {
        userId: managerUserId || null,
        additionalDeptIds: selectedDeptIds,
      });
      toast.success('Branch manager updated');
      setManagerDialog(false);
      fetchAll();
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to assign manager');
    } finally {
      setSaving(false);
    }
  };

  // ── Manage Departments (no manager change) ──
  const openManageDepts = (b: Branch) => {
    setDeptTarget(b);
    setDeptSelection((b.additionalDeptIds || []).map(d => d.id));
    setDeptDialog(true);
  };

  const handleSaveDepts = async () => {
    if (!deptTarget) return;
    setSaving(true);
    try {
      await api.patch(`/org/branches/${deptTarget.id}/departments`, {
        additionalDeptIds: deptSelection,
      });
      toast.success('Branch departments updated');
      setDeptDialog(false);
      fetchAll();
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to update departments');
    } finally {
      setSaving(false);
    }
  };

  const toggleStatus = async (b: Branch) => {
    try {
      await api.patch(`/org/branches/${b.id}`, { status: b.status === 'active' ? 'inactive' : 'active' });
      fetchAll();
    } catch { toast.error('Failed to update status'); }
  };

  if (loading) {
    return <div className="flex items-center justify-center h-64 text-muted-foreground">Loading branches...</div>;
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold tracking-tight">Branches</h2>
          <p className="text-muted-foreground text-sm">
            Manage organization branches and departments
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" onClick={fetchAll} className="flex-1 sm:flex-none">
            <RefreshCw className="w-4 h-4 mr-2" />
            Refresh
          </Button>
          <Button size="sm" onClick={() => setBranchDialog(true)} className="flex-1 sm:flex-none">
            <Plus className="w-4 h-4 mr-2" />
            New Branch
          </Button>
        </div>
      </div>

      {/* Branch cards */}
      {branches.length === 0 ? (
        <div className="border-2 border-dashed rounded-xl p-16 text-center">
          <Building2 className="h-12 w-12 text-muted-foreground mx-auto mb-3" />
          <p className="text-muted-foreground mb-4">No branches yet.</p>
          <Button onClick={openCreate}><Plus className="h-4 w-4 mr-2" /> Create First Branch</Button>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
          {branches.map(b => (
            <div key={b.id}
              className={`border rounded-xl p-5 bg-white shadow-sm hover:shadow-md transition-shadow ${b.status === 'inactive' ? 'opacity-60' : ''}`}>
              {/* Header */}
              <div className="flex items-start justify-between mb-3">
                <div>
                  <div className="flex items-center gap-2">
                    <span className="text-xs font-mono bg-slate-100 text-slate-600 px-2 py-0.5 rounded">{b.code}</span>
                    <Badge variant={b.status === 'active' ? 'default' : 'secondary'} className="text-xs">{b.status}</Badge>
                  </div>
                  <h3 className="font-bold text-base mt-1">{b.name}</h3>
                  <div className="flex items-center gap-1 text-xs text-muted-foreground mt-0.5">
                    <MapPin className="h-3 w-3" />
                    {b.address}{b.city ? `, ${b.city}` : ''}{b.state ? `, ${b.state}` : ''}
                  </div>
                </div>
                <div className="flex gap-1">
                  <button onClick={() => openEdit(b)} className="w-7 h-7 rounded-lg border flex items-center justify-center hover:bg-indigo-50 text-indigo-600">
                    <Edit2 className="h-3.5 w-3.5" />
                  </button>
                  <button onClick={() => handleDelete(b)} className="w-7 h-7 rounded-lg border flex items-center justify-center hover:bg-red-50 text-red-500">
                    <Trash2 className="h-3.5 w-3.5" />
                  </button>
                </div>
              </div>

              {/* Branch Manager */}
              <div className="mb-3 p-3 rounded-lg bg-slate-50 border">
                <div className="flex items-center justify-between">
                  <span className="text-xs font-semibold text-slate-500 uppercase tracking-wide">Branch Manager</span>
                  <button onClick={() => openAssignManager(b)} className="text-xs text-indigo-600 hover:underline flex items-center gap-1">
                    <UserPlus className="h-3 w-3" />{b.branchManagerId ? 'Change' : 'Assign'}
                  </button>
                </div>
                {b.branchManagerId ? (
                  <div className="flex items-center gap-2 mt-2">
                    <div className="w-7 h-7 rounded-full bg-indigo-600 flex items-center justify-center text-white text-xs font-bold">
                      {b.branchManagerId.name.charAt(0)}
                    </div>
                    <div>
                      <p className="text-sm font-medium">{b.branchManagerId.name}</p>
                      <p className="text-xs text-muted-foreground">{b.branchManagerId.designation || b.branchManagerId.role.replace(/_/g, ' ')}</p>
                    </div>
                  </div>
                ) : (
                  <p className="text-xs text-amber-600 mt-1">No manager assigned</p>
                )}
              </div>

              {/* Departments */}
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <p className="text-xs font-semibold text-slate-500 uppercase tracking-wide">Departments</p>
                  <button onClick={() => openManageDepts(b)} className="text-xs text-indigo-600 hover:underline flex items-center gap-1">
                    <Layers className="h-3 w-3" /> Manage
                  </button>
                </div>

                {/* Auto depts */}
                <div className="flex gap-2">
                  {b.salesDeptId && (
                    <div className="flex-1 flex items-center gap-2 p-2 rounded-lg border"
                      style={{ borderColor: DEPT_TYPE_COLORS.sales + '44', background: DEPT_TYPE_COLORS.sales + '11' }}>
                      <TrendingUp className="h-4 w-4 shrink-0" style={{ color: DEPT_TYPE_COLORS.sales }} />
                      <div>
                        <p className="text-xs font-semibold" style={{ color: DEPT_TYPE_COLORS.sales }}>Sales</p>
                        <p className="text-[10px] text-muted-foreground truncate">{b.salesDeptId.name}</p>
                      </div>
                    </div>
                  )}
                  {b.operationsDeptId && (
                    <div className="flex-1 flex items-center gap-2 p-2 rounded-lg border"
                      style={{ borderColor: DEPT_TYPE_COLORS.operations + '44', background: DEPT_TYPE_COLORS.operations + '11' }}>
                      <Settings className="h-4 w-4 shrink-0" style={{ color: DEPT_TYPE_COLORS.operations }} />
                      <div>
                        <p className="text-xs font-semibold" style={{ color: DEPT_TYPE_COLORS.operations }}>Operations</p>
                        <p className="text-[10px] text-muted-foreground truncate">{b.operationsDeptId.name}</p>
                      </div>
                    </div>
                  )}
                </div>

                {/* Additional depts */}
                {(b.additionalDeptIds || []).length > 0 && (
                  <div className="flex flex-wrap gap-1 mt-1">
                    {(b.additionalDeptIds || []).map(d => (
                      <span key={d.id} className="text-[10px] px-2 py-0.5 rounded-full border font-medium"
                        style={{
                          borderColor: (DEPT_TYPE_COLORS[d.type] || '#6366f1') + '55',
                          background: (DEPT_TYPE_COLORS[d.type] || '#6366f1') + '11',
                          color: DEPT_TYPE_COLORS[d.type] || '#6366f1',
                        }}>
                        {d.name}
                      </span>
                    ))}
                  </div>
                )}
              </div>

              <button onClick={() => toggleStatus(b)}
                className="mt-3 w-full text-xs text-muted-foreground hover:text-foreground border rounded-lg py-1.5 transition-colors">
                {b.status === 'active' ? 'Deactivate branch' : 'Activate branch'}
              </button>
            </div>
          ))}
        </div>
      )}

      {/* ── Create / Edit Dialog ── */}
      <Dialog open={branchDialog} onOpenChange={setBranchDialog}>
        <DialogContent className="max-w-md">
          <DialogHeader><DialogTitle>{editingBranch ? 'Edit Branch' : 'Create Branch'}</DialogTitle></DialogHeader>
          <div className="space-y-3 py-2">
            <div className="space-y-1">
              <Label>Branch Name *</Label>
              <Input placeholder="e.g. Delhi North Branch" value={form.name}
                onChange={e => setForm(p => ({ ...p, name: e.target.value }))} />
            </div>
            {!editingBranch && (
              <div className="space-y-1">
                <Label>Branch Code *</Label>
                <Input placeholder="e.g. DEL-N" value={form.code}
                  onChange={e => setForm(p => ({ ...p, code: e.target.value.toUpperCase() }))} />
              </div>
            )}
            <div className="space-y-1">
              <Label>Location / Address *</Label>
              <Input placeholder="Street address or area" value={form.address}
                onChange={e => setForm(p => ({ ...p, address: e.target.value }))} />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <Label>City</Label>
                <Input placeholder="City" value={form.city}
                  onChange={e => setForm(p => ({ ...p, city: e.target.value }))} />
              </div>
              <div className="space-y-1">
                <Label>State</Label>
                <Input placeholder="State" value={form.state}
                  onChange={e => setForm(p => ({ ...p, state: e.target.value }))} />
              </div>
            </div>
            {!editingBranch && (
              <>
                <div className="space-y-1">
                  <Label>Branch Manager (optional)</Label>
                  <Select value={form.branchManagerId || '__none__'}
                    onValueChange={v => setForm(p => ({ ...p, branchManagerId: v === '__none__' ? '' : v }))}>
                    <SelectTrigger><SelectValue placeholder="Assign later..." /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="__none__">Assign later</SelectItem>
                      {allUsers.map(u => (
                        <SelectItem key={u.id} value={u.id}>
                          {u.name} — {u.role.replace(/_/g, ' ')} {u.userId ? `(${u.userId})` : ''}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <p className="text-xs text-muted-foreground bg-blue-50 border border-blue-200 rounded-lg p-2">
                  Creating this branch will automatically generate a <strong>Sales</strong> and <strong>Operations</strong> department for it.
                </p>
              </>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setBranchDialog(false)}>Cancel</Button>
            <Button onClick={handleSave} disabled={saving || !form.name || !form.code || !form.address}>
              {saving ? 'Saving...' : editingBranch ? 'Save Changes' : 'Create Branch'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* ── Assign Manager Dialog ── */}
      <Dialog open={managerDialog} onOpenChange={setManagerDialog}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Assign Branch Manager — {managerTarget?.name}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div className="space-y-1">
              <Label>Manager</Label>
              <Select value={managerUserId || '__none__'}
                onValueChange={v => setManagerUserId(v === '__none__' ? '' : v)}>
                <SelectTrigger><SelectValue placeholder="Choose a person..." /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="__none__">Remove manager</SelectItem>
                  {allUsers.map(u => (
                    <SelectItem key={u.id} value={u.id}>
                      {u.name} — {u.role.replace(/_/g, ' ')} {u.userId ? `(${u.userId})` : ''}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Additional departments */}
            <div className="space-y-2">
              <Label>Additional Department Access</Label>
              <p className="text-xs text-muted-foreground">
                Sales and Operations are always included. Select any extra departments this manager should access.
              </p>
              <ScrollArea className="h-48 border rounded-lg p-3">
                <div className="space-y-2">
                  {/* Always-included auto depts (disabled) */}
                  {managerTarget?.salesDeptId && (
                    <div className="flex items-center gap-2 opacity-50">
                      <Checkbox checked disabled />
                      <span className="text-sm">{managerTarget.salesDeptId.name}</span>
                      <span className="text-xs text-muted-foreground">(auto)</span>
                    </div>
                  )}
                  {managerTarget?.operationsDeptId && (
                    <div className="flex items-center gap-2 opacity-50">
                      <Checkbox checked disabled />
                      <span className="text-sm">{managerTarget.operationsDeptId.name}</span>
                      <span className="text-xs text-muted-foreground">(auto)</span>
                    </div>
                  )}
                  {/* Selectable extra depts */}
                  {getAvailableExtraDepts(managerTarget).map(d => (
                    <div key={d.id} className="flex items-center gap-2 cursor-pointer"
                      onClick={() => toggleDept(d.id, selectedDeptIds, setSelectedDeptIds)}>
                      <Checkbox checked={selectedDeptIds.includes(d.id)}
                        onCheckedChange={() => toggleDept(d.id, selectedDeptIds, setSelectedDeptIds)} />
                      <span className="text-sm">{d.name}</span>
                      <span className="text-xs text-muted-foreground capitalize">{d.type}</span>
                    </div>
                  ))}
                  {getAvailableExtraDepts(managerTarget).length === 0 && (
                    <p className="text-xs text-muted-foreground text-center py-4">No other departments available</p>
                  )}
                </div>
              </ScrollArea>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setManagerDialog(false)}>Cancel</Button>
            <Button onClick={handleAssignManager} disabled={saving}>
              {saving ? 'Saving...' : 'Confirm'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* ── Manage Departments Dialog ── */}
      <Dialog open={deptDialog} onOpenChange={setDeptDialog}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Manage Departments — {deptTarget?.name}</DialogTitle>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <p className="text-sm text-muted-foreground">
              Select which additional departments the branch manager can access beyond Sales and Operations.
            </p>
            <ScrollArea className="h-56 border rounded-lg p-3">
              <div className="space-y-2">
                {deptTarget?.salesDeptId && (
                  <div className="flex items-center gap-2 opacity-50">
                    <Checkbox checked disabled />
                    <span className="text-sm">{deptTarget.salesDeptId.name}</span>
                    <span className="text-xs text-muted-foreground">(auto)</span>
                  </div>
                )}
                {deptTarget?.operationsDeptId && (
                  <div className="flex items-center gap-2 opacity-50">
                    <Checkbox checked disabled />
                    <span className="text-sm">{deptTarget.operationsDeptId.name}</span>
                    <span className="text-xs text-muted-foreground">(auto)</span>
                  </div>
                )}
                {getAvailableExtraDepts(deptTarget).map(d => (
                  <div key={d.id} className="flex items-center gap-2 cursor-pointer"
                    onClick={() => toggleDept(d.id, deptSelection, setDeptSelection)}>
                    <Checkbox checked={deptSelection.includes(d.id)}
                      onCheckedChange={() => toggleDept(d.id, deptSelection, setDeptSelection)} />
                    <span className="text-sm">{d.name}</span>
                    <span className="text-xs text-muted-foreground capitalize">{d.type}</span>
                  </div>
                ))}
                {getAvailableExtraDepts(deptTarget).length === 0 && (
                  <p className="text-xs text-muted-foreground text-center py-4">No other departments available</p>
                )}
              </div>
            </ScrollArea>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDeptDialog(false)}>Cancel</Button>
            <Button onClick={handleSaveDepts} disabled={saving}>
              {saving ? 'Saving...' : 'Save Departments'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useAuth } from '@/hooks/useAuth';
import api from '@/lib/api';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Send, Bell, Loader2 } from 'lucide-react';
import { toast } from 'sonner';

export function BroadcastNotificationsPanel() {
  const { user } = useAuth();
  const isFinance = ['finance_admin', 'finance'].includes(user?.role || '');
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  // Lists for dropdowns
  const [students, setStudents] = useState<any[]>([]);
  const [centers, setCenters] = useState<any[]>([]);

  // Form state
  const [form, setForm] = useState({
    target: isFinance ? 'centers' : 'students', // default targets
    targetId: '',
    title: '',
    message: '',
    priority: 'medium',
    link: ''
  });

  useEffect(() => {
    fetchTargetLists();
  }, []);

  // Update target default if role changes
  useEffect(() => {
    setForm(prev => ({
      ...prev,
      target: isFinance ? 'centers' : 'students',
      targetId: ''
    }));
  }, [user]);

  const fetchTargetLists = async () => {
    setLoading(true);
    try {
      const centersRes = await api.get('/operations/centers');
      setCenters(centersRes.data.data || []);

      if (!isFinance) {
        const studentsRes = await api.get('/students');
        setStudents(studentsRes.data.data || []);
      }
    } catch (error) {
      console.error('Failed to load targeting details:', error);
      toast.error('Failed to load recipient selection lists');
    } finally {
      setLoading(false);
    }
  };

  const handleTargetChange = (val: string) => {
    setForm({
      ...form,
      target: val,
      targetId: '',
      title: val === 'centers' && isFinance ? 'Pending Fee Notification' : form.title
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.title.trim() || !form.message.trim()) {
      toast.error('Please enter a title and message');
      return;
    }
    if (['student', 'center'].includes(form.target) && !form.targetId) {
      toast.error('Please select a specific recipient');
      return;
    }

    setSubmitting(true);
    try {
      await api.post('/notifications/broadcast', {
        target: form.target,
        targetId: form.targetId || undefined,
        title: form.title,
        message: form.message,
        priority: form.priority,
        link: form.link || undefined
      });
      toast.success('Notification broadcasted successfully');
      setForm(prev => ({
        ...prev,
        title: '',
        message: '',
        targetId: '',
        link: ''
      }));
    } catch (error: any) {
      console.error('Failed to send notification:', error);
      toast.error(error.response?.data?.message || 'Failed to send notification');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="space-y-6 max-w-3xl mx-auto">
      <div>
        <h2 className="text-2xl font-bold tracking-tight">Send Notifications</h2>
        <p className="text-muted-foreground text-sm">
          Compose and broadcast system and exam notifications to students and study centers.
        </p>
      </div>

      <Card className="border-none shadow-xl bg-card/60 backdrop-blur-xl">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Bell className="w-5 h-5 text-primary" />
            <span>Compose Notification</span>
          </CardTitle>
          <CardDescription>
            {isFinance 
              ? 'Select targeted study centers and compose fee pending warnings.' 
              : 'Select target group and compose notifications or exam circulars.'}
          </CardDescription>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="w-8 h-8 animate-spin text-primary" />
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {/* Target Type */}
                <div className="space-y-1">
                  <Label>Recipient Target</Label>
                  <Select value={form.target} onValueChange={handleTargetChange}>
                    <SelectTrigger>
                      <SelectValue placeholder="Select target group" />
                    </SelectTrigger>
                    <SelectContent>
                      {!isFinance && <SelectItem value="students">All Students</SelectItem>}
                      {!isFinance && <SelectItem value="student">Specific Student</SelectItem>}
                      <SelectItem value="centers">All Study Centers</SelectItem>
                      <SelectItem value="center">Specific Study Center</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                {/* Specific Recipient Selection */}
                {['student', 'center'].includes(form.target) && (
                  <div className="space-y-1">
                    <Label>{form.target === 'student' ? 'Select Student' : 'Select Study Center'}</Label>
                    <Select value={form.targetId} onValueChange={(val) => setForm({ ...form, targetId: val })}>
                      <SelectTrigger>
                        <SelectValue placeholder={form.target === 'student' ? 'Choose a student' : 'Choose a center'} />
                      </SelectTrigger>
                      <SelectContent>
                        {form.target === 'student'
                          ? students.map(s => <SelectItem key={s.id} value={s.id}>{s.name} ({s.enrollmentNo})</SelectItem>)
                          : centers.map(c => <SelectItem key={c.id} value={c.id}>{c.name} ({c.code})</SelectItem>)
                        }
                      </SelectContent>
                    </Select>
                  </div>
                )}
              </div>

              {/* Notification Priority */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1">
                  <Label>Priority</Label>
                  <Select value={form.priority} onValueChange={(val) => setForm({ ...form, priority: val })}>
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="low">Low</SelectItem>
                      <SelectItem value="medium">Medium</SelectItem>
                      <SelectItem value="high">High / Urgent</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                {/* Redirect Link (Optional) */}
                <div className="space-y-1">
                  <Label>Redirect Link (Optional)</Label>
                  <Input 
                    value={form.link} 
                    onChange={e => setForm({ ...form, link: e.target.value })} 
                    placeholder="e.g. exams, invoices, student-applications"
                  />
                </div>
              </div>

              {/* Title */}
              <div className="space-y-1">
                <Label>Notification Title</Label>
                <Input 
                  value={form.title} 
                  onChange={e => setForm({ ...form, title: e.target.value })} 
                  placeholder={form.target.includes('student') ? 'Exam notification' : 'Important Announcement'} 
                  required
                />
              </div>

              {/* Message */}
              <div className="space-y-1">
                <Label>Message Content</Label>
                <Textarea 
                  value={form.message} 
                  onChange={e => setForm({ ...form, message: e.target.value })} 
                  placeholder="Type the message body here..." 
                  className="min-h-[120px]"
                  required
                />
              </div>

              {/* Submit Button */}
              <Button type="submit" disabled={submitting} className="w-full md:w-auto">
                {submitting ? (
                  <>
                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                    Sending...
                  </>
                ) : (
                  <>
                    <Send className="w-4 h-4 mr-2" />
                    Send Notification
                  </>
                )}
              </Button>
            </form>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  RefreshCw, Search, Target, Award, Star, ChevronDown, ChevronUp,
  Users, TrendingUp, AlertCircle, CheckCircle2, Building2,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { toast } from 'sonner';
import api from '@/lib/api';

// ─── Types ────────────────────────────────────────────────────────────────────
interface KPI {
  id: string; title: string; description?: string;
  target: number; achieved: number; unit: string;
  period: string; status: 'on_track' | 'at_risk' | 'achieved' | 'missed';
}
interface KRA {
  id: string; area: string; description?: string;
  weightage: number; rating?: number; remarks?: string;
}
interface EmployeeReport {
  userId: string; name: string; email: string;
  designation?: string; role: string; department: string; status: string;
  overallRating?: number; lastReviewDate?: string; nextReviewDate?: string; reviewRemarks?: string;
  kpis: KPI[]; kpiSummary: { total: number; achieved: number; atRisk: number; missed: number; avgPct: number };
  kras: KRA[]; kraSummary: { total: number; avgRating: string | null; totalWeightage: number };
}

// ─── Helpers ──────────────────────────────────────────────────────────────────
const KPI_STATUS: Record<string, { label: string; cls: string }> = {
  on_track: { label: 'On Track', cls: 'bg-blue-100 text-blue-700' },
  at_risk:  { label: 'At Risk',  cls: 'bg-yellow-100 text-yellow-700' },
  achieved: { label: 'Achieved', cls: 'bg-green-100 text-green-700' },
  missed:   { label: 'Missed',   cls: 'bg-red-100 text-red-700' },
};

function StarRow({ value }: { value?: number }) {
  return (
    <div className="flex gap-0.5">
      {[1,2,3,4,5].map(n => (
        <Star key={n} className={cn('w-3.5 h-3.5', n <= (value || 0) ? 'fill-yellow-400 text-yellow-400' : 'text-gray-200')} />
      ))}
    </div>
  );
}

function KpiBar({ kpi }: { kpi: KPI }) {
  const pct = Math.min(100, Math.round((kpi.achieved / kpi.target) * 100));
  const st = KPI_STATUS[kpi.status];
  return (
    <div className="space-y-1">
      <div className="flex items-center justify-between text-xs">
        <span className="font-medium truncate max-w-[180px]">{kpi.title}</span>
        <div className="flex items-center gap-2 shrink-0">
          <span className="text-muted-foreground">{kpi.achieved}/{kpi.target} {kpi.unit}</span>
          <Badge className={cn('text-[9px] py-0 px-1.5', st.cls)}>{st.label}</Badge>
        </div>
      </div>
      <div className="h-1.5 bg-muted rounded-full overflow-hidden">
        <div
          className={cn('h-full rounded-full transition-all', pct >= 100 ? 'bg-green-500' : pct >= 60 ? 'bg-blue-500' : 'bg-yellow-500')}
          style={{ width: `${pct}%` }}
        />
      </div>
      <p className="text-[10px] text-muted-foreground">Period: {kpi.period} · {pct}% complete</p>
    </div>
  );
}

// ─── Employee Card ────────────────────────────────────────────────────────────
function EmployeeKPICard({ emp }: { emp: EmployeeReport }) {
  const [expanded, setExpanded] = useState(false);

  return (
    <Card className="hover:border-primary/30 transition-colors">
      <CardContent className="p-4">
        {/* Header row */}
        <div className="flex items-start justify-between gap-3">
          <div className="flex items-center gap-3 min-w-0">
            <div className="w-10 h-10 rounded-xl bg-primary/10 text-primary flex items-center justify-center font-bold text-sm shrink-0">
              {emp.name.charAt(0)}
            </div>
            <div className="min-w-0">
              <p className="font-semibold text-sm truncate">{emp.name}</p>
              <p className="text-xs text-muted-foreground">{emp.designation || emp.role.replace(/_/g, ' ')} · {emp.department}</p>
            </div>
          </div>
          <div className="flex items-center gap-2 shrink-0">
            {emp.overallRating && <StarRow value={emp.overallRating} />}
            <button onClick={() => setExpanded(!expanded)} className="text-muted-foreground hover:text-foreground transition-colors">
              {expanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
            </button>
          </div>
        </div>

        {/* Summary chips */}
        <div className="flex flex-wrap gap-2 mt-3">
          {emp.kpis.length > 0 && (
            <>
              <span className="text-[10px] bg-blue-50 text-blue-700 px-2 py-0.5 rounded-full font-medium">
                {emp.kpiSummary.achieved}/{emp.kpiSummary.total} KPIs achieved
              </span>
              <span className="text-[10px] bg-muted px-2 py-0.5 rounded-full font-medium">
                Avg {emp.kpiSummary.avgPct}%
              </span>
              {emp.kpiSummary.atRisk > 0 && (
                <span className="text-[10px] bg-yellow-50 text-yellow-700 px-2 py-0.5 rounded-full font-medium">
                  {emp.kpiSummary.atRisk} at risk
                </span>
              )}
              {emp.kpiSummary.missed > 0 && (
                <span className="text-[10px] bg-red-50 text-red-700 px-2 py-0.5 rounded-full font-medium">
                  {emp.kpiSummary.missed} missed
                </span>
              )}
            </>
          )}
          {emp.kras.length > 0 && emp.kraSummary.avgRating && (
            <span className="text-[10px] bg-purple-50 text-purple-700 px-2 py-0.5 rounded-full font-medium">
              KRA avg: {emp.kraSummary.avgRating}/5
            </span>
          )}
        </div>

        {/* Expanded detail */}
        {expanded && (
          <div className="mt-4 space-y-4 border-t pt-4">
            {emp.kpis.length > 0 && (
              <div>
                <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-2 flex items-center gap-1">
                  <Target className="w-3 h-3" /> KPIs
                </p>
                <div className="space-y-3">
                  {emp.kpis.map(kpi => <KpiBar key={kpi.id} kpi={kpi} />)}
                </div>
              </div>
            )}

            {emp.kras.length > 0 && (
              <div>
                <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-2 flex items-center gap-1">
                  <Award className="w-3 h-3" /> KRAs
                  {emp.kraSummary.totalWeightage !== 100 && (
                    <span className="text-yellow-600 ml-1">({emp.kraSummary.totalWeightage}% total)</span>
                  )}
                </p>
                <div className="space-y-2">
                  {emp.kras.map(kra => (
                    <div key={kra.id} className="flex items-center justify-between py-1.5 border-b last:border-0">
                      <div className="min-w-0">
                        <p className="text-xs font-medium truncate">{kra.area}</p>
                        <p className="text-[10px] text-muted-foreground">Weightage: {kra.weightage}%{kra.remarks ? ` · "${kra.remarks}"` : ''}</p>
                      </div>
                      <StarRow value={kra.rating} />
                    </div>
                  ))}
                </div>
              </div>
            )}

            {emp.reviewRemarks && (
              <div className="p-3 rounded-lg bg-muted/50 text-xs text-muted-foreground italic">
                "{emp.reviewRemarks}"
              </div>
            )}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

// ─── Main Panel ───────────────────────────────────────────────────────────────
export function CEOKPIReportPanel() {
  const [data, setData] = useState<EmployeeReport[]>([]);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState('');
  const [tab, setTab] = useState('all');

  const fetchReport = async () => {
    setLoading(true);
    try {
      const res = await api.get('/ceo/kpi-kra-report');
      setData(res.data.data || []);
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to load KPI/KRA report');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchReport(); }, []);

  const filtered = data.filter(emp => {
    const matchSearch = !search ||
      emp.name.toLowerCase().includes(search.toLowerCase()) ||
      emp.department.toLowerCase().includes(search.toLowerCase()) ||
      emp.designation?.toLowerCase().includes(search.toLowerCase());

    if (tab === 'at_risk') return matchSearch && emp.kpiSummary.atRisk > 0;
    if (tab === 'missed')  return matchSearch && emp.kpiSummary.missed > 0;
    if (tab === 'top')     return matchSearch && (emp.overallRating || 0) >= 4;
    return matchSearch;
  });

  // Org-wide stats
  const totalEmployees = data.length;
  const totalKPIs = data.reduce((s, e) => s + e.kpis.length, 0);
  const achievedKPIs = data.reduce((s, e) => s + e.kpiSummary.achieved, 0);
  const atRiskCount = data.filter(e => e.kpiSummary.atRisk > 0).length;
  const avgOrgRating = data.filter(e => e.overallRating).length
    ? (data.reduce((s, e) => s + (e.overallRating || 0), 0) / data.filter(e => e.overallRating).length).toFixed(1)
    : '—';

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h2 className="text-2xl font-bold">KPI & KRA Report</h2>
          <p className="text-sm text-muted-foreground mt-1">Organisation-wide performance indicators and key result areas.</p>
        </div>
        <Button variant="outline" size="sm" onClick={fetchReport} disabled={loading}>
          <RefreshCw className={cn('w-4 h-4 mr-1', loading && 'animate-spin')} /> Refresh
        </Button>
      </div>

      {/* Org-wide summary */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <Card><CardContent className="pt-5 flex items-center gap-3">
          <div className="p-2.5 rounded-xl bg-primary/10 text-primary"><Users className="w-5 h-5" /></div>
          <div><p className="text-2xl font-bold">{totalEmployees}</p><p className="text-xs text-muted-foreground">Employees with data</p></div>
        </CardContent></Card>
        <Card><CardContent className="pt-5 flex items-center gap-3">
          <div className="p-2.5 rounded-xl bg-green-100 text-green-700"><CheckCircle2 className="w-5 h-5" /></div>
          <div><p className="text-2xl font-bold">{achievedKPIs}/{totalKPIs}</p><p className="text-xs text-muted-foreground">KPIs Achieved</p></div>
        </CardContent></Card>
        <Card><CardContent className="pt-5 flex items-center gap-3">
          <div className="p-2.5 rounded-xl bg-yellow-100 text-yellow-700"><AlertCircle className="w-5 h-5" /></div>
          <div><p className="text-2xl font-bold">{atRiskCount}</p><p className="text-xs text-muted-foreground">Employees at risk</p></div>
        </CardContent></Card>
        <Card><CardContent className="pt-5 flex items-center gap-3">
          <div className="p-2.5 rounded-xl bg-purple-100 text-purple-700"><TrendingUp className="w-5 h-5" /></div>
          <div><p className="text-2xl font-bold">{avgOrgRating}</p><p className="text-xs text-muted-foreground">Avg overall rating</p></div>
        </CardContent></Card>
      </div>

      {/* Search + filter */}
      <div className="flex items-center gap-3 flex-wrap">
        <div className="relative flex-1 min-w-[200px] max-w-xs">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input className="pl-9" placeholder="Search by name, dept..." value={search} onChange={e => setSearch(e.target.value)} />
        </div>
      </div>

      <Tabs value={tab} onValueChange={setTab}>
        <TabsList>
          <TabsTrigger value="all">All ({data.length})</TabsTrigger>
          <TabsTrigger value="at_risk">At Risk ({data.filter(e => e.kpiSummary.atRisk > 0).length})</TabsTrigger>
          <TabsTrigger value="missed">Missed KPIs ({data.filter(e => e.kpiSummary.missed > 0).length})</TabsTrigger>
          <TabsTrigger value="top">Top Rated ({data.filter(e => (e.overallRating || 0) >= 4).length})</TabsTrigger>
        </TabsList>

        <TabsContent value={tab} className="mt-4">
          {loading ? (
            <div className="space-y-3">{[1,2,3,4].map(i => <div key={i} className="h-20 bg-muted rounded-xl animate-pulse" />)}</div>
          ) : filtered.length === 0 ? (
            <Card><CardContent className="py-16 text-center text-muted-foreground">
              <Building2 className="w-10 h-10 mx-auto mb-3 opacity-30" />
              <p>{data.length === 0 ? 'No KPI/KRA data found. HR needs to add them via employee profiles.' : 'No employees match this filter.'}</p>
            </CardContent></Card>
          ) : (
            <div className="space-y-3">
              {filtered.map(emp => <EmployeeKPICard key={emp.userId} emp={emp} />)}
            </div>
          )}
        </TabsContent>
      </Tabs>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Search, RefreshCw, CheckCircle2, Clock, AlertTriangle, ListTodo, Filter, Plus } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { cn } from '@/lib/utils';
import api from '@/lib/api';
import { toast } from 'sonner';

interface Task {
  id: string;
  title: string;
  description: string;
  assignedTo?: { id: string; name: string; email: string };
  assignedBy?: { id: string; name: string; email: string };
  departmentId?: { id: string; name: string };
  priority: 'low' | 'medium' | 'high' | 'critical';
  status: 'pending' | 'in_progress' | 'completed' | 'overdue';
  deadline: string;
  completedAt?: string;
  remarks?: string;
  escalationStatus?: string;
  createdAt: string;
}

interface Department {
  id: string;
  name: string;
}

interface Manager {
  id: string;
  name: string;
  email: string;
  role: string;
  designation?: string;
  departmentId?: { id: string; name: string };
}

const emptyForm = {
  title: '',
  description: '',
  assignedTo: '',
  departmentId: '',
  priority: 'medium',
  deadline: '',
};

const STATUS_STYLES: Record<string, string> = {
  completed:   'bg-success/10 text-success border-success/20',
  in_progress: 'bg-primary/10 text-primary border-primary/20',
  pending:     'bg-muted text-muted-foreground border-border',
  overdue:     'bg-destructive/10 text-destructive border-destructive/20',
};

const PRIORITY_STYLES: Record<string, string> = {
  critical: 'bg-red-500/10 text-red-500',
  high:     'bg-orange-500/10 text-orange-500',
  medium:   'bg-yellow-500/10 text-yellow-500',
  low:      'bg-blue-500/10 text-blue-500',
};

const ESCALATION_STYLES: Record<string, string> = {
  escalated_ceo:  'bg-red-500/10 text-red-500',
  escalated_dept: 'bg-orange-500/10 text-orange-500',
  overdue_employee: 'bg-yellow-500/10 text-yellow-500',
};

function isOverdue(deadline: string, status: string) {
  return status !== 'completed' && new Date(deadline) < new Date();
}

export function CEOTasksPanel() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [departments, setDepartments] = useState<Department[]>([]);
  const [managers, setManagers] = useState<Manager[]>([]);
  const [loading, setLoading] = useState(false);
  const [assignDialog, setAssignDialog] = useState(false);
  const [form, setForm] = useState(emptyForm);
  const [submitting, setSubmitting] = useState(false);

  // Filters
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [priorityFilter, setPriorityFilter] = useState('all');
  const [deptFilter, setDeptFilter] = useState('all');

  const fetchTasks = async () => {
    setLoading(true);
    try {
      const params: any = {};
      if (statusFilter !== 'all') params.status = statusFilter;
      if (priorityFilter !== 'all') params.priority = priorityFilter;
      if (deptFilter !== 'all') params.departmentId = deptFilter;

      const res = await api.get('/tasks', { params });
      setTasks(res.data.data || []);
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to load tasks');
    } finally {
      setLoading(false);
    }
  };

  const fetchDepartments = async () => {
    try {
      const res = await api.get('/departments');
      setDepartments(res.data.data || []);
    } catch { /* intentionally silent */ }
  };

  const fetchManagers = async () => {
    try {
      const res = await api.get('/ceo/managers');
      setManagers(res.data.data || []);
    } catch { /* intentionally silent */ }
  };

  useEffect(() => {
    fetchDepartments();
    fetchManagers();
  }, []);

  useEffect(() => {
    fetchTasks();
  }, [statusFilter, priorityFilter, deptFilter]);

  const filtered = tasks.filter(t => {
    if (!search) return true;
    const q = search.toLowerCase();
    return (
      t.title.toLowerCase().includes(q) ||
      t.description?.toLowerCase().includes(q) ||
      t.assignedTo?.name?.toLowerCase().includes(q) ||
      t.departmentId?.name?.toLowerCase().includes(q)
    );
  });

  const handleAssign = async () => {
    if (!form.title || !form.assignedTo || !form.departmentId || !form.deadline) {
      toast.error('Please fill in all required fields');
      return;
    }
    setSubmitting(true);
    try {
      await api.post('/ceo/tasks', form);
      toast.success('Task assigned successfully');
      setAssignDialog(false);
      setForm(emptyForm);
      fetchTasks();
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to assign task');
    } finally {
      setSubmitting(false);
    }
  };

  // When manager is selected, auto-fill their department
  const handleManagerChange = (managerId: string) => {
    const mgr = managers.find(m => m.id === managerId);
    setForm(f => ({
      ...f,
      assignedTo: managerId,
      departmentId: mgr?.departmentId?.id || f.departmentId,
    }));
  };

  // Summary counts
  const counts = {
    total: tasks.length,
    completed: tasks.filter(t => t.status === 'completed').length,
    overdue: tasks.filter(t => t.status === 'overdue' || isOverdue(t.deadline, t.status)).length,
    inProgress: tasks.filter(t => t.status === 'in_progress').length,
    pending: tasks.filter(t => t.status === 'pending').length,
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Organisation Tasks</h2>
          <p className="text-muted-foreground text-sm mt-1">Complete task list across all departments.</p>
        </div>
        <div className="flex items-center gap-2">
          <Button size="sm" onClick={() => setAssignDialog(true)}>
            <Plus className="w-4 h-4 mr-2" />
            Assign Task
          </Button>
          <Button variant="outline" size="sm" onClick={fetchTasks} disabled={loading}>
            <RefreshCw className={cn('w-4 h-4 mr-2', loading && 'animate-spin')} />
            Refresh
          </Button>
        </div>
      </div>

      {/* Summary KPIs */}
      <div className="grid grid-cols-2 lg:grid-cols-5 gap-3">
        {[
          { label: 'Total', value: counts.total, icon: <ListTodo className="w-4 h-4" />, color: 'bg-muted text-foreground' },
          { label: 'Completed', value: counts.completed, icon: <CheckCircle2 className="w-4 h-4" />, color: 'bg-success/10 text-success' },
          { label: 'In Progress', value: counts.inProgress, icon: <Clock className="w-4 h-4" />, color: 'bg-primary/10 text-primary' },
          { label: 'Pending', value: counts.pending, icon: <Clock className="w-4 h-4" />, color: 'bg-muted text-muted-foreground' },
          { label: 'Overdue', value: counts.overdue, icon: <AlertTriangle className="w-4 h-4" />, color: 'bg-destructive/10 text-destructive' },
        ].map(({ label, value, icon, color }) => (
          <Card key={label}>
            <CardContent className="pt-4 pb-4 flex items-center gap-3">
              <div className={cn('p-2 rounded-lg', color)}>{icon}</div>
              <div>
                <p className="text-xl font-bold">{value}</p>
                <p className="text-[11px] text-muted-foreground">{label}</p>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Filters */}
      <Card>
        <CardContent className="pt-4 pb-4">
          <div className="flex flex-wrap gap-3 items-center">
            <div className="relative flex-1 min-w-[200px]">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input
                placeholder="Search tasks, assignees, departments..."
                value={search}
                onChange={e => setSearch(e.target.value)}
                className="pl-9"
              />
            </div>
            <div className="flex items-center gap-2">
              <Filter className="w-4 h-4 text-muted-foreground" />
            </div>
            <Select value={statusFilter} onValueChange={setStatusFilter}>
              <SelectTrigger className="w-36">
                <SelectValue placeholder="Status" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Status</SelectItem>
                <SelectItem value="pending">Pending</SelectItem>
                <SelectItem value="in_progress">In Progress</SelectItem>
                <SelectItem value="completed">Completed</SelectItem>
                <SelectItem value="overdue">Overdue</SelectItem>
              </SelectContent>
            </Select>
            <Select value={priorityFilter} onValueChange={setPriorityFilter}>
              <SelectTrigger className="w-36">
                <SelectValue placeholder="Priority" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Priority</SelectItem>
                <SelectItem value="critical">Critical</SelectItem>
                <SelectItem value="high">High</SelectItem>
                <SelectItem value="medium">Medium</SelectItem>
                <SelectItem value="low">Low</SelectItem>
              </SelectContent>
            </Select>
            <Select value={deptFilter} onValueChange={setDeptFilter}>
              <SelectTrigger className="w-44">
                <SelectValue placeholder="Department" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Departments</SelectItem>
                {departments.map(d => (
                  <SelectItem key={d.id} value={d.id}>{d.name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
            {(statusFilter !== 'all' || priorityFilter !== 'all' || deptFilter !== 'all' || search) && (
              <Button variant="ghost" size="sm" onClick={() => { setStatusFilter('all'); setPriorityFilter('all'); setDeptFilter('all'); setSearch(''); }}>
                Clear
              </Button>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Task List */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base">
            {filtered.length} task{filtered.length !== 1 ? 's' : ''}
            {search || statusFilter !== 'all' || priorityFilter !== 'all' || deptFilter !== 'all' ? ' (filtered)' : ''}
          </CardTitle>
        </CardHeader>
        <CardContent className="p-0">
          {loading ? (
            <div className="space-y-px">
              {[1,2,3,4,5].map(i => (
                <div key={i} className="h-20 bg-muted/50 animate-pulse mx-4 mb-2 rounded-lg" />
              ))}
            </div>
          ) : filtered.length === 0 ? (
            <div className="py-16 text-center text-muted-foreground">
              <ListTodo className="w-10 h-10 mx-auto mb-3 opacity-30" />
              <p>No tasks found</p>
            </div>
          ) : (
            <div className="divide-y divide-border">
              {filtered.map(task => {
                const actuallyOverdue = isOverdue(task.deadline, task.status);
                const displayStatus = actuallyOverdue && task.status !== 'completed' ? 'overdue' : task.status;

                return (
                  <div key={task.id} className="px-5 py-4 hover:bg-muted/30 transition-colors">
                    <div className="flex items-start justify-between gap-4">
                      <div className="flex-1 min-w-0">
                        {/* Title row */}
                        <div className="flex items-center gap-2 flex-wrap mb-1.5">
                          <span className="font-semibold text-sm">{task.title}</span>
                          <Badge className={cn('text-[10px] font-bold uppercase border', STATUS_STYLES[displayStatus])}>
                            {displayStatus.replace('_', ' ')}
                          </Badge>
                          <Badge className={cn('text-[10px] font-bold uppercase', PRIORITY_STYLES[task.priority])}>
                            {task.priority}
                          </Badge>
                          {task.escalationStatus && task.escalationStatus !== 'none' && (
                            <Badge className={cn('text-[10px] font-bold uppercase', ESCALATION_STYLES[task.escalationStatus] || 'bg-muted text-muted-foreground')}>
                              {task.escalationStatus.replace(/_/g, ' ')}
                            </Badge>
                          )}
                        </div>

                        {/* Description */}
                        <p className="text-xs text-muted-foreground line-clamp-1 mb-2">{task.description}</p>

                        {/* Meta row */}
                        <div className="flex flex-wrap gap-x-4 gap-y-1 text-[11px] text-muted-foreground">
                          <span>
                            <span className="font-medium text-foreground/70">Assigned to:</span>{' '}
                            {task.assignedTo?.name || '—'}
                          </span>
                          <span>
                            <span className="font-medium text-foreground/70">By:</span>{' '}
                            {task.assignedBy?.name || '—'}
                          </span>
                          <span>
                            <span className="font-medium text-foreground/70">Dept:</span>{' '}
                            {task.departmentId?.name || '—'}
                          </span>
                          <span className={cn(actuallyOverdue && task.status !== 'completed' ? 'text-destructive font-semibold' : '')}>
                            <span className="font-medium text-foreground/70">Deadline:</span>{' '}
                            {new Date(task.deadline).toLocaleDateString()}
                          </span>
                          {task.completedAt && (
                            <span className="text-success">
                              <span className="font-medium">Completed:</span>{' '}
                              {new Date(task.completedAt).toLocaleDateString()}
                            </span>
                          )}
                        </div>

                        {task.remarks && (
                          <p className="text-[11px] text-muted-foreground mt-1.5 italic">"{task.remarks}"</p>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Assign Task Dialog */}
      <Dialog open={assignDialog} onOpenChange={setAssignDialog}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>Assign Task to Manager</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 pt-2">
            <div className="space-y-2">
              <Label>Title <span className="text-destructive">*</span></Label>
              <Input
                value={form.title}
                onChange={e => setForm(f => ({ ...f, title: e.target.value }))}
                placeholder="Task title..."
              />
            </div>
            <div className="space-y-2">
              <Label>Description</Label>
              <Textarea
                value={form.description}
                onChange={e => setForm(f => ({ ...f, description: e.target.value }))}
                placeholder="Describe the task..."
                rows={3}
              />
            </div>
            <div className="space-y-2">
              <Label>Assign To (Manager) <span className="text-destructive">*</span></Label>
              <Select value={form.assignedTo} onValueChange={handleManagerChange}>
                <SelectTrigger>
                  <SelectValue placeholder="Select a manager..." />
                </SelectTrigger>
                <SelectContent>
                  {managers.map(m => (
                    <SelectItem key={m.id} value={m.id}>
                      <span className="font-medium">{m.name}</span>
                      <span className="text-muted-foreground ml-2 text-xs">
                        {m.departmentId?.name ? `· ${m.departmentId.name}` : ''} · {m.role.replace(/_/g, ' ')}
                      </span>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Department <span className="text-destructive">*</span></Label>
              <Select value={form.departmentId} onValueChange={v => setForm(f => ({ ...f, departmentId: v }))}>
                <SelectTrigger>
                  <SelectValue placeholder="Select department..." />
                </SelectTrigger>
                <SelectContent>
                  {departments.map(d => (
                    <SelectItem key={d.id} value={d.id}>{d.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Priority</Label>
                <Select value={form.priority} onValueChange={v => setForm(f => ({ ...f, priority: v }))}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="low">Low</SelectItem>
                    <SelectItem value="medium">Medium</SelectItem>
                    <SelectItem value="high">High</SelectItem>
                    <SelectItem value="critical">Critical</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>Deadline <span className="text-destructive">*</span></Label>
                <Input
                  type="date"
                  value={form.deadline}
                  onChange={e => setForm(f => ({ ...f, deadline: e.target.value }))}
                  min={new Date().toISOString().split('T')[0]}
                />
              </div>
            </div>
            <div className="flex gap-2 pt-2">
              <Button className="flex-1" onClick={handleAssign} disabled={submitting}>
                {submitting ? 'Assigning...' : 'Assign Task'}
              </Button>
              <Button variant="outline" onClick={() => { setAssignDialog(false); setForm(emptyForm); }}>
                Cancel
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

