  RefreshCw,
  Clock,
  CheckCircle,
  XCircle,
  AlertTriangle,
  User,
  ChevronDown,
  ChevronUp,
  Building2,
  GraduationCap,
  TrendingUp,
  Users,
} from 'lucide-react';
