                    <tbody className="divide-y">
                      {commOut.map((item) => (
                        <tr key={item.id} className="hover:bg-slate-50/50">
                          <td className="px-4 py-3 font-medium whitespace-nowrap">{item.studyCenter?.name || '-'}</td>
