  impact: string;
  status: string;
  currentLevel: number;
  maxLevel: number;
  raisedAt: string;
  chain: { level: number; role: string; action?: string; remarks?: string; actionAt?: string }[];
}

const STATUS_COLOR: Record<string, string> = {
  active:   'bg-warning/10 text-warning',
  resolved: 'bg-success/10 text-success',
