    programId: '',
    registrationFee: '0',
    tuitionFee: '0',
    examFee: '0',
    gstPercentage: '18'
  });

  useEffect(() => {
    fetchFees();
    fetchPrograms();
  }, []);

  const fetchFees = async () => {
    setLoading(true);
    try {
      const res = await api.get('/finance/fees');
      setFees(res.data.data || []);
    } catch (err) {
      console.error('Failed to fetch fees:', err);
    } finally {
      setLoading(false);
    }
