    try {
      if (editingId) {
        await api.put(`/finance/fees/${editingId}`, payload);
      } else {
        await api.post('/finance/fees', payload);
      }
      setDialogOpen(false);
      resetForm();
      fetchFees();
    } catch (err: any) {
      alert(err.response?.data?.message || 'Failed to save fee structure');
    }
