                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Pencil, RefreshCw, DollarSign } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent } from '@/components/ui/card';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import api from '@/lib/api';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';

interface University { id: string; name: string; code: string; }
interface AuthFee { id: string; universityId: University; amount: number; currency: string; updatedAt: string; }

export function FinanceAuthFeePanel() {
  const [fees, setFees] = useState<AuthFee[]>([]);
  const [universities, setUniversities] = useState<University[]>([]);
  const [loading, setLoading] = useState(false);
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState<AuthFee | null>(null);
  const [form, setForm] = useState({ universityId: '', amount: '', currency: 'INR' });
  const [submitting, setSubmitting] = useState(false);

  const fetchFees = async () => {
    setLoading(true);
    try {
      const res = await api.get('/finance/auth-fees');
      setFees(res.data.data || []);
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to load auth fees');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchFees();
    api.get('/operations/universities').then(r => setUniversities(r.data.data || [])).catch(() => {});
  }, []);

  const openCreate = () => { setEditing(null); setForm({ universityId: '', amount: '', currency: 'INR' }); setOpen(true); };
  const openEdit = (fee: AuthFee) => {
    setEditing(fee);
    setForm({ universityId: fee.universityId.id, amount: String(fee.amount), currency: fee.currency });
    setOpen(true);
  };

  const handleSubmit = async () => {
    if (!form.universityId || !form.amount) { toast.error('University and amount are required'); return; }
    const amount = parseFloat(form.amount);
    if (isNaN(amount) || amount <= 0) { toast.error('Amount must be greater than zero'); return; }

    setSubmitting(true);
    try {
      if (editing) {
        await api.put(`/finance/auth-fees/${editing.id}`, { amount, currency: form.currency });
      } else {
        await api.post('/finance/auth-fees', { universityId: form.universityId, amount, currency: form.currency });
      }
      toast.success(editing ? 'Auth fee updated' : 'Auth fee configured');
      setOpen(false);
      fetchFees();
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to save');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">University Auth Fees</h2>
          <p className="text-muted-foreground text-sm mt-1">Configure the authorisation fee required per university for study center onboarding.</p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={fetchFees} disabled={loading}>
            <RefreshCw className={cn('w-4 h-4 mr-2', loading && 'animate-spin')} />Refresh
          </Button>
          <Button size="sm" onClick={openCreate}><Plus className="w-4 h-4 mr-2" />Add Fee</Button>
        </div>
      </div>

      {loading ? (
        <div className="space-y-3">{[1,2,3].map(i => <div key={i} className="h-16 bg-muted rounded-xl animate-pulse" />)}</div>
      ) : fees.length === 0 ? (
        <Card><CardContent className="py-16 text-center text-muted-foreground">
          <DollarSign className="w-10 h-10 mx-auto mb-3 opacity-30" />
          <p>No auth fees configured yet.</p>
        </CardContent></Card>
      ) : (
        <div className="space-y-3">
          {fees.map(fee => (
            <Card key={fee.id} className="hover:border-primary/30 transition-colors">
              <CardContent className="p-4 flex items-center justify-between">
                <div>
                  <p className="font-semibold text-sm">{fee.universityId.name}</p>
                  <p className="text-xs text-muted-foreground">{fee.universityId.code}</p>
                </div>
                <div className="flex items-center gap-4">
                  <span className="text-lg font-bold">{fee.currency} {fee.amount.toLocaleString()}</span>
                  <Button variant="ghost" size="sm" onClick={() => openEdit(fee)}>
                    <Pencil className="w-4 h-4" />
                  </Button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent>
          <DialogHeader><DialogTitle>{editing ? 'Edit Auth Fee' : 'Configure Auth Fee'}</DialogTitle></DialogHeader>
          <div className="space-y-4 py-2">
            {!editing && (
              <div className="space-y-1">
                <Label>University</Label>
                <Select value={form.universityId} onValueChange={v => setForm(p => ({ ...p, universityId: v }))}>
                  <SelectTrigger><SelectValue placeholder="Select university" /></SelectTrigger>
                  <SelectContent>
                    {universities.map(u => (
                      <SelectItem key={u.id} value={u.id}>{u.name} ({u.code})</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}
            <div className="space-y-1">
              <Label>Amount</Label>
              <Input
                type="number"
                min="0.01"
                step="0.01"
                value={form.amount}
                onChange={e => setForm(p => ({ ...p, amount: e.target.value }))}
                placeholder="e.g. 5000"
              />
            </div>
            <div className="space-y-1">
              <Label>Currency</Label>
              <Input value={form.currency} onChange={e => setForm(p => ({ ...p, currency: e.target.value }))} placeholder="INR" />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setOpen(false)}>Cancel</Button>
            <Button onClick={handleSubmit} disabled={submitting}>
              {submitting ? 'Saving...' : editing ? 'Update' : 'Save'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { CheckCircle, XCircle, RefreshCw, DollarSign, FileText, ExternalLink, Key, Copy } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent } from '@/components/ui/card';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import api from '@/lib/api';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';

const SERVER_BASE = '';

interface AuthFeeEntry { universityId: string; universityName: string; amount: number | null; }
interface PaymentProof { url: string; uploadedAt: string; remarks?: string; }
interface Center {
  id: string;
  name: string;
  code: string;
  email: string;
  contact: string;
  address: string;
  verifiedBy?: { name: string };
  verifiedAt?: string;
  authFees: AuthFeeEntry[];
  paymentProof?: PaymentProof;
  createdAt: string;
}
interface Credentials { email: string; password: string; }

export function FinanceCenterVerificationPanel() {
  const [centers, setCenters] = useState<Center[]>([]);
  const [loading, setLoading] = useState(false);
  const [dialog, setDialog] = useState<{ center: Center; action: 'approve' | 'reject' } | null>(null);
  const [remarks, setRemarks] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [credentials, setCredentials] = useState<Credentials | null>(null);

  const loadCenters = async () => {
    setLoading(true);
    try {
      const res = await api.get('/finance/centers/pending-payment');
      setCenters(res.data.data || []);
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to load centers');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadCenters(); }, []);

  const handleAction = async () => {
    if (!dialog) return;
    if (dialog.action === 'reject' && !remarks.trim()) {
      toast.error('Remarks are required when rejecting');
      return;
    }
    setSubmitting(true);
    try {
      const res = await api.put(`/finance/centers/${dialog.center.id}/finance-verify`, {
        action: dialog.action,
        remarks,
      });
      setDialog(null);
      setRemarks('');
      loadCenters();
      if (dialog.action === 'approve' && res.data._credentials) {
        setCredentials(res.data._credentials);
      } else {
        toast.success(dialog.action === 'approve' ? 'Center activated' : 'Center rejected');
      }
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Action failed');
    } finally {
      setSubmitting(false);
    }
  };

  const totalFee = (fees: AuthFeeEntry[]) =>
    fees.reduce((sum, f) => sum + (f.amount || 0), 0);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Pending Payment Verification</h2>
          <p className="text-muted-foreground text-sm mt-1">Verify authorisation fee payment for study centers.</p>
        </div>
        <Button variant="outline" size="sm" onClick={loadCenters} disabled={loading}>
          <RefreshCw className={cn('w-4 h-4 mr-2', loading && 'animate-spin')} />Refresh
        </Button>
      </div>

      {loading ? (
        <div className="space-y-3">{[1,2,3].map(i => <div key={i} className="h-24 bg-muted rounded-xl animate-pulse" />)}</div>
      ) : centers.length === 0 ? (
        <Card><CardContent className="py-16 text-center text-muted-foreground">
          <DollarSign className="w-10 h-10 mx-auto mb-3 opacity-30" />
          <p>No centers pending payment verification.</p>
        </CardContent></Card>
      ) : (
        <div className="space-y-4">
          {centers.map(c => (
            <Card key={c.id} className="hover:border-primary/30 transition-colors">
              <CardContent className="p-5">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <h4 className="font-semibold">{c.name}</h4>
                      <Badge variant="outline" className="text-[10px]">{c.code}</Badge>
                    </div>
                    <p className="text-xs text-muted-foreground">{c.email} · {c.contact}</p>
                    {c.verifiedBy && (
                      <p className="text-xs text-muted-foreground mt-0.5">Docs verified by: {c.verifiedBy.name}</p>
                    )}
                    <div className="mt-3 space-y-1">
                      {c.authFees.map(f => (
                        <div key={f.universityId} className="flex items-center justify-between text-xs">
                          <span className="text-muted-foreground">{f.universityName}</span>
                          {f.amount !== null ? (
                            <span className="font-semibold">&#8377;{f.amount.toLocaleString()}</span>
                          ) : (
                            <Badge variant="destructive" className="text-[10px]">Fee not configured</Badge>
                          )}
                        </div>
                      ))}
                      <div className="flex items-center justify-between text-sm font-bold pt-1 border-t border-border mt-1">
                        <span>Total</span>
                        <span>&#8377;{totalFee(c.authFees).toLocaleString()}</span>
                      </div>
                    </div>
                    {c.paymentProof ? (
                      <div className="mt-3 p-3 rounded-lg bg-muted/50 border border-border">
                        <p className="text-xs font-semibold mb-1 flex items-center gap-1">
                          <FileText className="w-3 h-3" /> Payment Proof
                        </p>
                        <a
                          href={`${SERVER_BASE}${c.paymentProof.url}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-xs text-primary flex items-center gap-1 hover:underline"
                        >
                          View Receipt <ExternalLink className="w-3 h-3" />
                        </a>
                        {c.paymentProof.remarks && (
                          <p className="text-xs text-muted-foreground mt-1">{c.paymentProof.remarks}</p>
                        )}
                        <p className="text-xs text-muted-foreground mt-0.5">
                          Uploaded: {new Date(c.paymentProof.uploadedAt).toLocaleDateString()}
                        </p>
                      </div>
                    ) : (
                      <p className="text-xs text-muted-foreground mt-2 italic">No payment proof uploaded yet.</p>
                    )}
                  </div>
                  <div className="flex gap-2 shrink-0">
                    <Button size="sm" variant="outline" className="text-destructive border-destructive/30 hover:bg-destructive/10"
                      onClick={() => { setDialog({ center: c, action: 'reject' }); setRemarks(''); }}>
                      <XCircle className="w-4 h-4 mr-1" />Reject
                    </Button>
                    <Button size="sm" onClick={() => { setDialog({ center: c, action: 'approve' }); setRemarks(''); }}>
                      <CheckCircle className="w-4 h-4 mr-1" />Approve
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Approve / Reject dialog */}
      <Dialog open={!!dialog} onOpenChange={() => { setDialog(null); setRemarks(''); }}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              {dialog?.action === 'approve' ? 'Approve & Activate' : 'Reject'} — {dialog?.center.name}
            </DialogTitle>
          </DialogHeader>
          {dialog?.action === 'approve' && (
            <p className="text-sm text-muted-foreground">
              Approving will activate the study center and generate login credentials.
            </p>
          )}
          <div className="space-y-3 py-2">
            <Label>Remarks {dialog?.action === 'reject' && <span className="text-destructive">*</span>}</Label>
            <Textarea
              value={remarks}
              onChange={e => setRemarks(e.target.value)}
              placeholder={dialog?.action === 'reject' ? 'Reason for rejection (required)' : 'Optional remarks'}
              rows={3}
            />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => { setDialog(null); setRemarks(''); }}>Cancel</Button>
            <Button
              onClick={handleAction}
              disabled={submitting}
              variant={dialog?.action === 'reject' ? 'destructive' : 'default'}
            >
              {submitting ? 'Processing...' : dialog?.action === 'approve' ? 'Approve & Activate' : 'Reject'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Credentials modal — shown once after approval */}
      <Dialog open={!!credentials} onOpenChange={() => setCredentials(null)}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Key className="w-5 h-5 text-primary" /> Study Center Login Credentials
            </DialogTitle>
          </DialogHeader>
          <p className="text-sm text-muted-foreground">
            Save these credentials — the password will not be shown again.
          </p>
          <div className="space-y-3 py-2">
            <div className="space-y-1">
              <Label>Email / Username</Label>
              <div className="flex gap-2">
                <Input readOnly value={credentials?.email || ''} />
                <Button size="icon" variant="outline" onClick={() => { navigator.clipboard.writeText(credentials?.email || ''); toast.success('Email copied'); }}>
                  <Copy className="w-4 h-4" />
                </Button>
              </div>
            </div>
            <div className="space-y-1">
              <Label>Password</Label>
              <div className="flex gap-2">
                <Input readOnly value={credentials?.password || ''} />
                <Button size="icon" variant="outline" onClick={() => { navigator.clipboard.writeText(credentials?.password || ''); toast.success('Password copied'); }}>
                  <Copy className="w-4 h-4" />
                </Button>
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button onClick={() => setCredentials(null)}>Done</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { RefreshCw, CheckCircle, XCircle, Search, GraduationCap, Clock, AlertCircle, Ban } from 'lucide-react';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { cn } from '@/lib/utils';
import api from '@/lib/api';
import { toast } from 'sonner';

interface Enrollment {
  id: string;
  enrollmentNumber?: string;
  studentName: string;
  studentEmail: string;
  studentPhone: string;
  programId: { name: string; code: string } | string;
  studyCenterId: { name: string; code: string } | string;
  program?: { name: string; code: string } | null;
  studyCenter?: { name: string; code: string } | null;
  status: string;
  departmentRemarks?: string;
  financeRemarks?: string;
  payment?: { amount: number; debitedAt: string; walletId?: string } | null;
  createdAt: string;
  enrolledAt?: string;
}

interface Summary {
  payment_pending: number;
  document_review: number;
  finance_review: number;
  enrolled: number;
  rejected: number;
  department_rejected: number;
}

const STATUS_META: Record<string, { label: string; color: string; icon: React.ReactNode }> = {
  payment_pending:     { label: 'Fee Pending',      color: 'bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400', icon: <Clock className="w-3 h-3" /> },
  document_review:     { label: 'Doc Review',       color: 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400',         icon: <AlertCircle className="w-3 h-3" /> },
  finance_review:      { label: 'Finance Review',   color: 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400', icon: <Clock className="w-3 h-3" /> },
  enrolled:            { label: 'Enrolled',         color: 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400',     icon: <CheckCircle className="w-3 h-3" /> },
  rejected:            { label: 'Rejected',         color: 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400',             icon: <XCircle className="w-3 h-3" /> },
  department_rejected: { label: 'Dept Rejected',    color: 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400',             icon: <Ban className="w-3 h-3" /> },
};

const FILTER_TABS = [
  { key: '', label: 'All' },
  { key: 'payment_pending', label: 'Fee Pending' },
  { key: 'document_review', label: 'Doc Review' },
  { key: 'finance_review', label: 'Finance Review' },
  { key: 'enrolled', label: 'Enrolled' },
  { key: 'rejected', label: 'Rejected' },
];

export function FinanceEnrollmentsPanel() {
  const [enrollments, setEnrollments] = useState<Enrollment[]>([]);
  const [summary, setSummary] = useState<Summary | null>(null);
  const [loading, setLoading] = useState(false);
  const [statusFilter, setStatusFilter] = useState('');
  const [search, setSearch] = useState('');
  const [rejectDialog, setRejectDialog] = useState<{ open: boolean; id: string }>({ open: false, id: '' });
  const [remarks, setRemarks] = useState('');

  const fetchData = async (status = statusFilter, q = search) => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (status) params.set('status', status);
      if (q) params.set('search', q);
      const res = await api.get(`/finance/enrollments/all?${params}`);
      setEnrollments(res.data.data || []);
      setSummary(res.data.summary || null);
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to load enrollments');
    } finally {
      setLoading(false);
    }
  };

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { fetchData(); }, []);

  const handleTabChange = (key: string) => {
    setStatusFilter(key);
    fetchData(key, search);
  };

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    fetchData(statusFilter, search);
  };

  const handleApprove = async (id: string) => {
    try {
      await api.put(`/finance/enrollments/${id}/approve`);
      toast.success('Student enrolled successfully');
      fetchData();
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to approve');
    }
  };

  const handleReject = async () => {
    try {
      await api.put(`/finance/enrollments/${rejectDialog.id}/reject`, { remarks });
      toast.success('Enrollment rejected');
      setRejectDialog({ open: false, id: '' });
      setRemarks('');
      fetchData();
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to reject');
    }
  };

  const getProgramName = (e: Enrollment) =>
    e.program && typeof e.program === 'object'
      ? `${e.program.name} (${e.program.code})`
      : (typeof e.programId === 'object' ? `${(e.programId as any).name} (${(e.programId as any).code})` : e.programId);

  const getCenterName = (e: Enrollment) =>
    e.studyCenter && typeof e.studyCenter === 'object'
      ? `${e.studyCenter.name} (${e.studyCenter.code})`
      : (typeof e.studyCenterId === 'object' ? `${(e.studyCenterId as any).name}` : e.studyCenterId);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h2 className="text-2xl font-bold">Student Enrollments</h2>
          <p className="text-muted-foreground text-sm mt-1">All student enrollment data across every stage.</p>
        </div>
        <Button variant="outline" size="sm" onClick={() => fetchData()} disabled={loading}>
          <RefreshCw className={cn('w-4 h-4 mr-2', loading && 'animate-spin')} />Refresh
        </Button>
      </div>

      {/* Summary Cards */}
      {summary && (
        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3">
          <SummaryCard label="Fee Pending" count={summary.payment_pending} icon={<Clock className="w-4 h-4" />} color="text-orange-500 bg-orange-50 dark:bg-orange-900/20" onClick={() => handleTabChange('payment_pending')} />
          <SummaryCard label="Doc Review" count={summary.document_review} icon={<AlertCircle className="w-4 h-4" />} color="text-blue-500 bg-blue-50 dark:bg-blue-900/20" onClick={() => handleTabChange('document_review')} />
          <SummaryCard label="Finance Review" count={summary.finance_review} icon={<Clock className="w-4 h-4" />} color="text-yellow-500 bg-yellow-50 dark:bg-yellow-900/20" onClick={() => handleTabChange('finance_review')} />
          <SummaryCard label="Enrolled" count={summary.enrolled} icon={<GraduationCap className="w-4 h-4" />} color="text-green-500 bg-green-50 dark:bg-green-900/20" onClick={() => handleTabChange('enrolled')} />
          <SummaryCard label="Rejected" count={summary.rejected} icon={<XCircle className="w-4 h-4" />} color="text-red-500 bg-red-50 dark:bg-red-900/20" onClick={() => handleTabChange('rejected')} />
          <SummaryCard label="Dept Rejected" count={summary.department_rejected} icon={<Ban className="w-4 h-4" />} color="text-red-400 bg-red-50 dark:bg-red-900/20" onClick={() => handleTabChange('department_rejected')} />
        </div>
      )}

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-3">
        {/* Status tabs */}
        <div className="flex flex-wrap gap-1">
          {FILTER_TABS.map(tab => (
            <button
              key={tab.key}
              onClick={() => handleTabChange(tab.key)}
              className={cn(
                'px-3 py-1.5 rounded-lg text-xs font-medium transition-colors',
                statusFilter === tab.key
                  ? 'bg-primary text-primary-foreground'
                  : 'bg-muted text-muted-foreground hover:bg-muted/80'
              )}
            >
              {tab.label}
              {summary && tab.key && (
                <span className="ml-1.5 opacity-70">
                  {summary[tab.key as keyof Summary] ?? 0}
                </span>
              )}
            </button>
          ))}
        </div>

        {/* Search */}
        <form onSubmit={handleSearch} className="flex gap-2 ml-auto">
          <div className="relative">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground" />
            <Input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Search name, email, ID..."
              className="pl-8 h-8 text-sm w-56"
            />
          </div>
          <Button type="submit" size="sm" variant="outline" className="h-8">Search</Button>
        </form>
      </div>

      {/* Table */}
      {loading ? (
        <div className="space-y-3">{[1,2,3,4].map(i => <div key={i} className="h-16 bg-muted rounded-xl animate-pulse" />)}</div>
      ) : enrollments.length === 0 ? (
        <Card>
          <CardContent className="py-16 text-center text-muted-foreground">
            <GraduationCap className="w-10 h-10 mx-auto mb-3 opacity-20" />
            <p>No enrollments found{statusFilter ? ` with status "${statusFilter.replace('_', ' ')}"` : ''}.</p>
          </CardContent>
        </Card>
      ) : (
        <div className="rounded-xl border border-border overflow-hidden">
          <table className="w-full text-sm">
            <thead className="bg-muted/50 border-b border-border">
              <tr>
                <th className="text-left p-3 font-medium text-muted-foreground">Student</th>
                <th className="text-left p-3 font-medium text-muted-foreground hidden md:table-cell">Program</th>
                <th className="text-left p-3 font-medium text-muted-foreground hidden lg:table-cell">Center</th>
                <th className="text-left p-3 font-medium text-muted-foreground hidden sm:table-cell">Fee Paid</th>
                <th className="text-left p-3 font-medium text-muted-foreground">Status</th>
                <th className="text-left p-3 font-medium text-muted-foreground hidden lg:table-cell">Date</th>
                <th className="text-right p-3 font-medium text-muted-foreground">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {enrollments.map(e => {
                const meta = STATUS_META[e.status] || { label: e.status, color: 'bg-muted text-muted-foreground', icon: null };
                return (
                  <tr key={e.id} className="hover:bg-muted/30 transition-colors">
                    <td className="p-3">
                      <p className="font-medium">{e.studentName}</p>
                      <p className="text-xs text-muted-foreground">{e.studentEmail}</p>
                      {e.enrollmentNumber && <p className="text-[10px] text-muted-foreground font-mono">{e.enrollmentNumber}</p>}
                    </td>
                    <td className="p-3 hidden md:table-cell text-muted-foreground">{getProgramName(e)}</td>
                    <td className="p-3 hidden lg:table-cell text-muted-foreground">{getCenterName(e)}</td>
                    <td className="p-3 hidden sm:table-cell">
                      {e.payment ? (
                        <div className="space-y-0.5">
                          <span className="text-green-600 font-semibold block">₹{e.payment.amount.toLocaleString()}</span>
                          <span className="text-[10px] text-muted-foreground block">
                            Paid: {new Date(e.payment.debitedAt || e.createdAt).toLocaleDateString()}
                          </span>
                          <span className="text-[10px] text-muted-foreground block font-mono">
                            Wallet: {e.payment.walletId ? e.payment.walletId.slice(0, 8) : 'N/A'}
                          </span>
                        </div>
                      ) : (
                        <span className="text-muted-foreground text-xs">—</span>
                      )}
                    </td>
                    <td className="p-3">
                      <span className={cn('inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[11px] font-semibold', meta.color)}>
                        {meta.icon}{meta.label}
                      </span>
                      {(e.financeRemarks || e.departmentRemarks) && (
                        <p className="text-[10px] text-muted-foreground mt-0.5 max-w-[160px] truncate" title={e.financeRemarks || e.departmentRemarks}>
                          {e.financeRemarks || e.departmentRemarks}
                        </p>
                      )}
                    </td>
                    <td className="p-3 hidden lg:table-cell text-muted-foreground text-xs">
                      {new Date(e.createdAt).toLocaleDateString()}
                    </td>
                    <td className="p-3 text-right">
                      {e.status === 'finance_review' && (
                        <div className="flex gap-1.5 justify-end">
                          <Button size="sm" variant="outline" className="h-7 text-xs text-green-600 border-green-300 hover:bg-green-50 dark:hover:bg-green-900/20" onClick={() => handleApprove(e.id)}>
                            <CheckCircle className="w-3 h-3 mr-1" />Enroll
                          </Button>
                          <Button size="sm" variant="outline" className="h-7 text-xs text-red-600 border-red-300 hover:bg-red-50 dark:hover:bg-red-900/20" onClick={() => { setRejectDialog({ open: true, id: e.id }); setRemarks(''); }}>
                            <XCircle className="w-3 h-3 mr-1" />Reject
                          </Button>
                        </div>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* Reject Dialog */}
      <Dialog open={rejectDialog.open} onOpenChange={o => setRejectDialog(d => ({ ...d, open: o }))}>
        <DialogContent>
          <DialogHeader><DialogTitle>Reject Enrollment</DialogTitle></DialogHeader>
          <div className="space-y-2 py-2">
            <Label>Remarks (required)</Label>
            <Input value={remarks} onChange={e => setRemarks(e.target.value)} placeholder="Reason for rejection..." />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setRejectDialog({ open: false, id: '' })}>Cancel</Button>
            <Button variant="destructive" onClick={handleReject} disabled={!remarks.trim()}>Reject</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

function SummaryCard({ label, count, icon, color, onClick }: { label: string; count: number; icon: React.ReactNode; color: string; onClick: () => void }) {
  return (
    <Card className="cursor-pointer hover:border-primary/40 transition-colors" onClick={onClick}>
      <CardContent className="p-4 flex items-center gap-3">
        <div className={cn('p-2 rounded-lg', color)}>{icon}</div>
        <div>
          <p className="text-xl font-bold">{count}</p>
          <p className="text-[11px] text-muted-foreground">{label}</p>
        </div>
      </CardContent>
    </Card>
  );
}

import { useState, useEffect } from 'react';
import { RefreshCw, CheckCircle, XCircle, Clock, DollarSign, AlertCircle } from 'lucide-react';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { cn } from '@/lib/utils';
import api from '@/lib/api';
import { toast } from 'sonner';

interface SalaryConfig {
  id: string;
  userId: { id: string; name: string; email: string; designation?: string; role: string; departmentId?: { name: string } };
  basicSalary: number;
  allowances: { hra: number; transport: number; medical: number; other: number };
  deductions: { pf: number; tax: number; insurance: number; other: number };
  lateDeductionPerMinute: number;
  effectiveFrom: string;
  approvalStatus: 'pending_approval' | 'approved' | 'rejected';
  approvedBy?: { name: string; email: string };
  approvedAt?: string;
  rejectedRemarks?: string;
  createdBy?: { name: string };
  updatedAt: string;
}

interface Summary { pending_approval: number; approved: number; rejected: number }

const STATUS_META = {
  pending_approval: { label: 'Pending', color: 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400', icon: <Clock className="w-3 h-3" /> },
  approved:         { label: 'Approved', color: 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400', icon: <CheckCircle className="w-3 h-3" /> },
  rejected:         { label: 'Rejected', color: 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400', icon: <XCircle className="w-3 h-3" /> },
};

const TABS = [
  { key: '', label: 'All' },
  { key: 'pending_approval', label: 'Pending' },
  { key: 'approved', label: 'Approved' },
  { key: 'rejected', label: 'Rejected' },
];

export function FinanceSalaryApprovalPanel() {
  const [configs, setConfigs] = useState<SalaryConfig[]>([]);
  const [summary, setSummary] = useState<Summary | null>(null);
  const [loading, setLoading] = useState(false);
  const [statusFilter, setStatusFilter] = useState('pending_approval');
  const [rejectDialog, setRejectDialog] = useState<{ open: boolean; id: string }>({ open: false, id: '' });
  const [remarks, setRemarks] = useState('');
  const [detailConfig, setDetailConfig] = useState<SalaryConfig | null>(null);

  const fetchData = async (status = statusFilter) => {
    setLoading(true);
    try {
      const params = status ? `?status=${status}` : '';
      const res = await api.get(`/finance/salary-configs${params}`);
      setConfigs(res.data.data || []);
      setSummary(res.data.summary || null);
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to load salary configs');
    } finally {
      setLoading(false);
    }
  };

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { fetchData(); }, []);

  const handleTabChange = (key: string) => {
    setStatusFilter(key);
    fetchData(key);
  };

  const handleApprove = async (id: string) => {
    try {
      await api.put(`/finance/salary-configs/${id}/approve`, { action: 'approve' });
      toast.success('Salary config approved');
      fetchData();
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to approve');
    }
  };

  const handleReject = async () => {
    try {
      await api.put(`/finance/salary-configs/${rejectDialog.id}/approve`, { action: 'reject', remarks });
      toast.success('Salary config rejected');
      setRejectDialog({ open: false, id: '' });
      setRemarks('');
      fetchData();
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to reject');
    }
  };

  const gross = (c: SalaryConfig) =>
    c.basicSalary + Object.values(c.allowances).reduce((s, v) => s + (v || 0), 0);
  const net = (c: SalaryConfig) =>
    gross(c) - Object.values(c.deductions).reduce((s, v) => s + (v || 0), 0);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h2 className="text-2xl font-bold">Salary Config Approvals</h2>
          <p className="text-muted-foreground text-sm mt-1">Review and approve salary configurations set by HR.</p>
        </div>
        <Button variant="outline" size="sm" onClick={() => fetchData()} disabled={loading}>
          <RefreshCw className={cn('w-4 h-4 mr-2', loading && 'animate-spin')} />Refresh
        </Button>
      </div>

      {/* Summary */}
      {summary && (
        <div className="grid grid-cols-3 gap-3">
          <Card className="cursor-pointer hover:border-yellow-400/50 transition-colors" onClick={() => handleTabChange('pending_approval')}>
            <CardContent className="p-4 flex items-center gap-3">
              <div className="p-2 rounded-lg bg-yellow-50 dark:bg-yellow-900/20 text-yellow-600"><Clock className="w-4 h-4" /></div>
              <div>
                <p className="text-xl font-bold">{summary.pending_approval}</p>
                <p className="text-xs text-muted-foreground">Pending</p>
              </div>
            </CardContent>
          </Card>
          <Card className="cursor-pointer hover:border-green-400/50 transition-colors" onClick={() => handleTabChange('approved')}>
            <CardContent className="p-4 flex items-center gap-3">
              <div className="p-2 rounded-lg bg-green-50 dark:bg-green-900/20 text-green-600"><CheckCircle className="w-4 h-4" /></div>
              <div>
                <p className="text-xl font-bold">{summary.approved}</p>
                <p className="text-xs text-muted-foreground">Approved</p>
              </div>
            </CardContent>
          </Card>
          <Card className="cursor-pointer hover:border-red-400/50 transition-colors" onClick={() => handleTabChange('rejected')}>
            <CardContent className="p-4 flex items-center gap-3">
              <div className="p-2 rounded-lg bg-red-50 dark:bg-red-900/20 text-red-500"><XCircle className="w-4 h-4" /></div>
              <div>
                <p className="text-xl font-bold">{summary.rejected}</p>
                <p className="text-xs text-muted-foreground">Rejected</p>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Filter tabs */}
      <div className="flex gap-1 flex-wrap">
        {TABS.map(tab => (
          <button
            key={tab.key}
            onClick={() => handleTabChange(tab.key)}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-medium transition-colors',
              statusFilter === tab.key
                ? 'bg-primary text-primary-foreground'
                : 'bg-muted text-muted-foreground hover:bg-muted/80'
            )}
          >
            {tab.label}
            {summary && tab.key && (
              <span className="ml-1.5 opacity-70">{summary[tab.key as keyof Summary] ?? 0}</span>
            )}
          </button>
        ))}
      </div>

      {/* List */}
      {loading ? (
        <div className="space-y-3">{[1,2,3].map(i => <div key={i} className="h-24 bg-muted rounded-xl animate-pulse" />)}</div>
      ) : configs.length === 0 ? (
        <Card>
          <CardContent className="py-16 text-center text-muted-foreground">
            <DollarSign className="w-10 h-10 mx-auto mb-3 opacity-20" />
            <p>No salary configs{statusFilter ? ` with status "${statusFilter.replace('_', ' ')}"` : ''}.</p>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-3">
          {configs.map(config => {
            const meta = STATUS_META[config.approvalStatus];
            const grossAmt = gross(config);
            const netAmt = net(config);
            return (
              <Card key={config.id} className="hover:border-primary/30 transition-colors">
                <CardContent className="p-5">
                  <div className="flex items-start justify-between gap-4 flex-wrap">
                    <div className="flex-1 min-w-0">
                      {/* Status + name */}
                      <div className="flex items-center gap-2 flex-wrap mb-1">
                        <span className={cn('inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[11px] font-semibold', meta.color)}>
                          {meta.icon}{meta.label}
                        </span>
                        <span className="font-semibold">{config.userId?.name}</span>
                        <Badge variant="outline" className="text-xs capitalize">{config.userId?.role?.replace(/_/g, ' ')}</Badge>
                        {config.userId?.designation && <Badge variant="outline" className="text-xs">{config.userId.designation}</Badge>}
                        {config.userId?.departmentId && <span className="text-xs text-muted-foreground">{config.userId.departmentId.name}</span>}
                      </div>
                      <p className="text-xs text-muted-foreground mb-3">{config.userId?.email}</p>

                      {/* Salary breakdown */}
                      <div className="grid grid-cols-2 sm:grid-cols-5 gap-3 text-sm">
                        <div>
                          <p className="text-xs text-muted-foreground">Basic</p>
                          <p className="font-semibold">₹{config.basicSalary.toLocaleString()}</p>
                        </div>
                        <div>
                          <p className="text-xs text-muted-foreground">HRA</p>
                          <p className="font-semibold">₹{(config.allowances.hra || 0).toLocaleString()}</p>
                        </div>
                        <div>
                          <p className="text-xs text-muted-foreground">Gross</p>
                          <p className="font-semibold text-blue-600">₹{grossAmt.toLocaleString()}</p>
                        </div>
                        <div>
                          <p className="text-xs text-muted-foreground">Deductions</p>
                          <p className="font-semibold text-red-500">
                            ₹{Object.values(config.deductions).reduce((s, v) => s + (v || 0), 0).toLocaleString()}
                          </p>
                        </div>
                        <div>
                          <p className="text-xs text-muted-foreground">Net</p>
                          <p className="font-semibold text-green-600">₹{netAmt.toLocaleString()}</p>
                        </div>
                      </div>

                      {/* Meta info */}
                      <div className="flex items-center gap-4 mt-2 text-xs text-muted-foreground flex-wrap">
                        {config.createdBy && <span>Set by: {config.createdBy.name}</span>}
                        <span>Updated: {new Date(config.updatedAt).toLocaleDateString()}</span>
                        {config.approvedBy && <span>Reviewed by: {config.approvedBy.name}</span>}
                        {config.rejectedRemarks && (
                          <span className="text-red-500 flex items-center gap-1">
                            <AlertCircle className="w-3 h-3" />{config.rejectedRemarks}
                          </span>
                        )}
                      </div>
                    </div>

                    {/* Actions */}
                    <div className="flex gap-2 shrink-0">
                      <Button size="sm" variant="ghost" className="text-xs text-muted-foreground" onClick={() => setDetailConfig(config)}>
                        Details
                      </Button>
                      {config.approvalStatus === 'pending_approval' && (
                        <>
                          <Button size="sm" variant="outline" className="text-green-600 border-green-300 hover:bg-green-50 dark:hover:bg-green-900/20" onClick={() => handleApprove(config.id)}>
                            <CheckCircle className="w-3.5 h-3.5 mr-1" />Approve
                          </Button>
                          <Button size="sm" variant="outline" className="text-red-600 border-red-300 hover:bg-red-50 dark:hover:bg-red-900/20" onClick={() => { setRejectDialog({ open: true, id: config.id }); setRemarks(''); }}>
                            <XCircle className="w-3.5 h-3.5 mr-1" />Reject
                          </Button>
                        </>
                      )}
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Reject Dialog */}
      <Dialog open={rejectDialog.open} onOpenChange={o => setRejectDialog(d => ({ ...d, open: o }))}>
        <DialogContent>
          <DialogHeader><DialogTitle>Reject Salary Config</DialogTitle></DialogHeader>
          <div className="space-y-2 py-2">
            <Label>Reason for rejection (required)</Label>
            <Input value={remarks} onChange={e => setRemarks(e.target.value)} placeholder="e.g. Basic salary exceeds approved band..." />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setRejectDialog({ open: false, id: '' })}>Cancel</Button>
            <Button variant="destructive" onClick={handleReject} disabled={!remarks.trim()}>Reject</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Detail Dialog */}
      <Dialog open={!!detailConfig} onOpenChange={o => !o && setDetailConfig(null)}>
        <DialogContent className="max-w-md">
          <DialogHeader><DialogTitle>Salary Config — {detailConfig?.userId?.name}</DialogTitle></DialogHeader>
          {detailConfig && (
            <div className="space-y-4 py-2 text-sm">
              <div className="grid grid-cols-2 gap-3">
                <div><p className="text-xs text-muted-foreground">Basic Salary</p><p className="font-semibold">₹{detailConfig.basicSalary.toLocaleString()}</p></div>
                <div><p className="text-xs text-muted-foreground">Late/min</p><p className="font-semibold">₹{detailConfig.lateDeductionPerMinute}</p></div>
              </div>
              <div>
                <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-2">Allowances</p>
                <div className="grid grid-cols-2 gap-2">
                  {Object.entries(detailConfig.allowances).map(([k, v]) => (
                    <div key={k} className="flex justify-between p-2 rounded-lg bg-muted/40">
                      <span className="capitalize text-muted-foreground">{k}</span>
                      <span className="font-medium">₹{(v || 0).toLocaleString()}</span>
                    </div>
                  ))}
                </div>
              </div>
              <div>
                <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-2">Deductions</p>
                <div className="grid grid-cols-2 gap-2">
                  {Object.entries(detailConfig.deductions).map(([k, v]) => (
                    <div key={k} className="flex justify-between p-2 rounded-lg bg-muted/40">
                      <span className="capitalize text-muted-foreground">{k}</span>
                      <span className="font-medium text-red-500">₹{(v || 0).toLocaleString()}</span>
                    </div>
                  ))}
                </div>
              </div>
              <div className="grid grid-cols-3 gap-3 p-3 rounded-xl bg-muted/50 font-semibold">
                <div><p className="text-xs text-muted-foreground">Gross</p><p className="text-blue-600">₹{gross(detailConfig).toLocaleString()}</p></div>
                <div><p className="text-xs text-muted-foreground">Deductions</p><p className="text-red-500">₹{Object.values(detailConfig.deductions).reduce((s, v) => s + (v || 0), 0).toLocaleString()}</p></div>
                <div><p className="text-xs text-muted-foreground">Net</p><p className="text-green-600">₹{net(detailConfig).toLocaleString()}</p></div>
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setDetailConfig(null)}>Close</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Target, Plus, RefreshCw, Users, TrendingUp, Edit2, Trash2 } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';
import api from '@/lib/api';
import { toast } from 'sonner';

interface SalesUser {
  id: string;
  name: string;
  email: string;
  role: string;
  designation?: string;
  status: string;
}

interface SalesTarget {
  id: string;
  employeeId: { id: string; name: string; email: string } | null;
  type: 'revenue' | 'students' | 'centers';
  period: string;
  target: number;
  achieved: number;
  incentive?: number;
  createdAt: string;
}

const TYPE_LABELS: Record<string, string> = {
  revenue: 'Revenue',
  students: 'Students',
  centers: 'Centers',
};

const progressColor = (pct: number) => {
  if (pct >= 100) return 'bg-success';
  if (pct >= 60) return 'bg-primary';
  if (pct >= 30) return 'bg-warning';
  return 'bg-error';
};

export function FinanceSalesTargetsPanel() {
  const [users, setUsers] = useState<SalesUser[]>([]);
  const [targets, setTargets] = useState<SalesTarget[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [editTarget, setEditTarget] = useState<SalesTarget | null>(null);
  const [form, setForm] = useState({
    employeeId: '',
    type: 'revenue' as 'revenue' | 'students' | 'centers',
    period: new Date().toISOString().slice(0, 7), // YYYY-MM
    target: '',
    achieved: '',
    incentive: '',
  });
  const [saving, setSaving] = useState(false);

  const fetchAll = async () => {
    setLoading(true);
    try {
      const [usersRes, targetsRes] = await Promise.all([
        api.get('/finance/sales-users'),
        api.get('/finance/targets'),
      ]);
      setUsers(usersRes.data.data || []);
      // Filter targets that belong to sales users
      const salesUserIds = new Set((usersRes.data.data || []).map((u: SalesUser) => u.id));
      const allTargets: SalesTarget[] = targetsRes.data.data || [];
      setTargets(allTargets.filter(t => t.employeeId && salesUserIds.has(t.employeeId.id)));
    } catch (e: any) {
      toast.error('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchAll(); }, []);

  const openCreate = () => {
    setEditTarget(null);
    setForm({ employeeId: '', type: 'revenue', period: new Date().toISOString().slice(0, 7), target: '', achieved: '', incentive: '' });
    setShowForm(true);
  };

  const openEdit = (t: SalesTarget) => {
    setEditTarget(t);
    setForm({
      employeeId: t.employeeId?.id || '',
      type: t.type,
      period: t.period,
      target: String(t.target),
      achieved: String(t.achieved),
      incentive: t.incentive != null ? String(t.incentive) : '',
    });
    setShowForm(true);
  };

  const handleSave = async () => {
    if (!form.employeeId || !form.target || !form.period) {
      toast.error('Employee, period and target value are required');
      return;
    }
    setSaving(true);
    try {
      const payload = {
        employeeId: form.employeeId,
        type: form.type,
        period: form.period,
        target: Number(form.target),
        achieved: Number(form.achieved || 0),
        ...(form.incentive ? { incentive: Number(form.incentive) } : {}),
      };
      if (editTarget) {
        await api.put(`/finance/targets/${editTarget.id}`, payload);
        toast.success('Target updated');
      } else {
        await api.post('/finance/targets', payload);
        toast.success('Target assigned');
      }
      setShowForm(false);
      fetchAll();
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to save target');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this target?')) return;
    try {
      await api.delete(`/finance/targets/${id}`);
      toast.success('Target deleted');
      fetchAll();
    } catch {
      toast.error('Failed to delete');
    }
  };

  const totalTargets = targets.length;
  const achieved100 = targets.filter(t => t.target > 0 && t.achieved >= t.target).length;
  const avgProgress = targets.length
    ? Math.round(targets.reduce((s, t) => s + (t.target > 0 ? Math.min(100, (t.achieved / t.target) * 100) : 0), 0) / targets.length)
    : 0;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Sales Targets</h2>
          <p className="text-sm text-muted-foreground mt-1">Assign and track targets for the sales team</p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={fetchAll} disabled={loading}>
            <RefreshCw className={cn('w-4 h-4 mr-2', loading && 'animate-spin')} />
            Refresh
          </Button>
          <Button size="sm" onClick={openCreate}>
            <Plus className="w-4 h-4 mr-2" />
            Assign Target
          </Button>
        </div>
      </div>

      {/* Summary */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card>
          <CardContent className="p-5 flex items-center gap-4">
            <div className="p-3 rounded-xl bg-primary/10 text-primary"><Target className="w-5 h-5" /></div>
            <div>
              <p className="text-xs text-muted-foreground uppercase font-medium">Total Targets</p>
              <p className="text-2xl font-bold">{totalTargets}</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-5 flex items-center gap-4">
            <div className="p-3 rounded-xl bg-success/10 text-success"><TrendingUp className="w-5 h-5" /></div>
            <div>
              <p className="text-xs text-muted-foreground uppercase font-medium">Achieved 100%</p>
              <p className="text-2xl font-bold">{achieved100}</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-5 flex items-center gap-4">
            <div className="p-3 rounded-xl bg-warning/10 text-warning"><Users className="w-5 h-5" /></div>
            <div>
              <p className="text-xs text-muted-foreground uppercase font-medium">Avg Progress</p>
              <p className="text-2xl font-bold">{avgProgress}%</p>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Form */}
      {showForm && (
        <Card className="border-primary/30">
          <CardHeader>
            <CardTitle className="text-base">{editTarget ? 'Edit Target' : 'Assign New Target'}</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              <div className="space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase">Sales User</label>
                <select
                  className="w-full border border-border rounded-lg px-3 py-2 text-sm bg-background"
                  value={form.employeeId}
                  onChange={e => setForm(f => ({ ...f, employeeId: e.target.value }))}
                >
                  <option value="">Select user...</option>
                  {users.map(u => (
                    <option key={u.id} value={u.id}>{u.name} ({u.role})</option>
                  ))}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase">Type</label>
                <select
                  className="w-full border border-border rounded-lg px-3 py-2 text-sm bg-background"
                  value={form.type}
                  onChange={e => setForm(f => ({ ...f, type: e.target.value as any }))}
                >
                  <option value="revenue">Revenue</option>
                  <option value="students">Students</option>
                  <option value="centers">Centers</option>
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase">Period (YYYY-MM)</label>
                <input
                  type="month"
                  className="w-full border border-border rounded-lg px-3 py-2 text-sm bg-background"
                  value={form.period}
                  onChange={e => setForm(f => ({ ...f, period: e.target.value }))}
                />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase">Target Value</label>
                <input
                  type="number"
                  min="0"
                  className="w-full border border-border rounded-lg px-3 py-2 text-sm bg-background"
                  placeholder="e.g. 100000"
                  value={form.target}
                  onChange={e => setForm(f => ({ ...f, target: e.target.value }))}
                />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase">Achieved (optional)</label>
                <input
                  type="number"
                  min="0"
                  className="w-full border border-border rounded-lg px-3 py-2 text-sm bg-background"
                  placeholder="0"
                  value={form.achieved}
                  onChange={e => setForm(f => ({ ...f, achieved: e.target.value }))}
                />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-medium text-muted-foreground uppercase">Incentive (optional)</label>
                <input
                  type="number"
                  min="0"
                  className="w-full border border-border rounded-lg px-3 py-2 text-sm bg-background"
                  placeholder="e.g. 5000"
                  value={form.incentive}
                  onChange={e => setForm(f => ({ ...f, incentive: e.target.value }))}
                />
              </div>
            </div>
            <div className="flex gap-2 mt-4">
              <Button size="sm" onClick={handleSave} disabled={saving}>
                {saving ? 'Saving...' : editTarget ? 'Update' : 'Assign'}
              </Button>
              <Button size="sm" variant="outline" onClick={() => setShowForm(false)}>Cancel</Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Targets list */}
      <Card>
        <CardHeader>
          <CardTitle>Assigned Targets</CardTitle>
          <CardDescription>All targets assigned to sales team members</CardDescription>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="space-y-3">{[1,2,3].map(i => <div key={i} className="h-16 bg-muted rounded-xl animate-pulse" />)}</div>
          ) : targets.length === 0 ? (
            <div className="py-12 text-center text-muted-foreground">
              <Target className="w-10 h-10 mx-auto mb-3 opacity-20" />
              <p className="font-medium">No targets assigned yet</p>
              <p className="text-sm mt-1">Click "Assign Target" to get started.</p>
            </div>
          ) : (
            <div className="space-y-3">
              {targets.map(t => {
                const pct = t.target > 0 ? Math.min(100, Math.round((t.achieved / t.target) * 100)) : 0;
                return (
                  <div key={t.id} className="flex items-center gap-4 p-4 rounded-xl border border-border hover:border-primary/30 transition-colors">
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 flex-wrap mb-1">
                        <span className="font-semibold text-sm">{t.employeeId?.name || 'Unknown'}</span>
                        <Badge variant="outline" className="text-[10px] uppercase">{TYPE_LABELS[t.type]}</Badge>
                        <Badge variant="outline" className="text-[10px]">{t.period}</Badge>
                        {t.incentive ? <Badge variant="outline" className="text-[10px] text-success border-success/30">₹{t.incentive.toLocaleString()} incentive</Badge> : null}
                      </div>
                      <div className="flex items-center gap-3 mt-2">
                        <div className="flex-1 h-2 bg-muted rounded-full overflow-hidden">
                          <div className={cn('h-full rounded-full transition-all', progressColor(pct))} style={{ width: `${pct}%` }} />
                        </div>
                        <span className="text-xs font-bold shrink-0 w-10 text-right">{pct}%</span>
                        <span className="text-xs text-muted-foreground shrink-0">
                          {t.achieved.toLocaleString()} / {t.target.toLocaleString()}
                        </span>
                      </div>
                    </div>
                    <div className="flex gap-1 shrink-0">
                      <Button size="icon" variant="ghost" className="h-8 w-8" onClick={() => openEdit(t)}>
                        <Edit2 className="w-3.5 h-3.5" />
                      </Button>
                      <Button size="icon" variant="ghost" className="h-8 w-8 text-destructive hover:text-destructive" onClick={() => handleDelete(t.id)}>
                        <Trash2 className="w-3.5 h-3.5" />
                      </Button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Search, Filter, RefreshCw, FileSpreadsheet } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import api from '@/lib/api';
import { toast } from 'sonner';
import * as XLSX from 'xlsx';

const statusColor = (s: string) => {
  if (!s) return 'bg-gray-100 text-gray-500';
  const l = s.toLowerCase();
  if (l === 'paid') return 'bg-green-100 text-green-700 border border-green-200';
  if (l === 'due' || l === 'pending') return 'bg-amber-100 text-amber-700 border border-amber-200';
  if (l === 'not applicable') return 'bg-slate-100 text-slate-400';
  return 'bg-blue-100 text-blue-700';
};

const fmtDate = (d: string | null | undefined): string => {
  if (!d) return '-';
  const dt = new Date(d);
  if (isNaN(dt.getTime())) return '-';
  const dd = String(dt.getDate()).padStart(2, '0');
  const mm = String(dt.getMonth() + 1).padStart(2, '0');
  const yyyy = dt.getFullYear();
  return `${dd}/${mm}/${yyyy}`;
};

interface FilterState {
  universityId: string;
  programId: string;
  sessionId: string;
  search: string;
  dateFrom: string;
  dateTo: string;
}

const EMPTY_FILTERS: FilterState = {
  universityId: '__all__',
  programId: '__all__',
  sessionId: '__all__',
  search: '',
  dateFrom: '',
  dateTo: '',
};

export function FinanceTotalReportPanel() {
  const [rows, setRows] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);

  // UI filter state (what the user sees in the dropdowns)
  const [uiFilters, setUiFilters] = useState<FilterState>(EMPTY_FILTERS);
  // Applied filter state (what is actually sent to the server)
  const [appliedFilters, setAppliedFilters] = useState<FilterState>(EMPTY_FILTERS);

  const [universities, setUniversities] = useState<any[]>([]);
  const [programs, setPrograms] = useState<any[]>([]);
  const [sessions, setSessions] = useState<any[]>([]);

  // Fetch report whenever appliedFilters changes — no stale closure issues
  useEffect(() => {
    const params = new URLSearchParams();
    if (appliedFilters.universityId !== '__all__') params.set('universityId', appliedFilters.universityId);
    if (appliedFilters.programId !== '__all__') params.set('programId', appliedFilters.programId);
    if (appliedFilters.sessionId !== '__all__') params.set('sessionId', appliedFilters.sessionId);
    if (appliedFilters.search) params.set('search', appliedFilters.search);
    if (appliedFilters.dateFrom) params.set('dateFrom', appliedFilters.dateFrom);
    if (appliedFilters.dateTo) params.set('dateTo', appliedFilters.dateTo);

    setLoading(true);
    api.get(`/finance/total-report?${params.toString()}`)
      .then(res => setRows(res.data.data || []))
      .catch(() => toast.error('Failed to load report'))
      .finally(() => setLoading(false));
  }, [appliedFilters]);

  // Load filter options on mount
  useEffect(() => {
    Promise.all([
      api.get('/operations/universities').catch(() => ({ data: { data: [] } })),
      api.get('/operations/programs').catch(() => ({ data: { data: [] } })),
      api.get('/operations/sessions').catch(() => ({ data: { data: [] } })),
    ]).then(([uRes, pRes, sRes]) => {
      setUniversities(uRes.data.data || []);
      setPrograms(pRes.data.data || []);
      setSessions(sRes.data.data || []);
    });
  }, []);

  const handleApply = () => setAppliedFilters({ ...uiFilters });

  const handleReset = () => {
    setUiFilters(EMPTY_FILTERS);
    setAppliedFilters(EMPTY_FILTERS);
  };

  const exportExcel = () => {
    const data = rows.map((r, i) => ({
      '#': i + 1,
      'Student': r.studentName,
      'Enrollment No': r.enrollmentNumber || '',
      'Admission Date': fmtDate(r.admissionDate),
      'Admission Session': r.admissionSession,
      'Center Name': r.centerName,
      'Sub Center / Branch': r.subCenterName || '',
      'Program': r.program,
      'University': r.university,
      'Center Payment (INR)': r.centerPaymentAmount ?? '',
      'Center Payment Status': r.centerPaymentStatus,
      'Payment For': r.centerPaymentFor,
      'University Payment (INR)': r.universityPaymentAmount ?? '',
      'University Payment Status': r.universityPaymentStatus,
      'Coordinator Name': r.coordinatorName || 'Null',
      'Coordinator Payment (INR)': r.coordinatorPaymentAmount ?? '',
      'Coordinator Payment Status': r.coordinatorPaymentStatus,
      'Commission From Uni (INR)': r.commissionInAmount ?? '',
      'Commission From Uni Date': fmtDate(r.commissionInDate),
      'Commission From Uni Status': r.commissionInStatus || '',
      'Commission To Center (INR)': r.commissionOutAmount ?? '',
      'Commission To Center Date': fmtDate(r.commissionOutDate),
      'Commission To Center Status': r.commissionOutStatus || '',
    }));
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Total Report');
    ws['!cols'] = Object.keys(data[0] || {}).map(() => ({ wch: 22 }));
    XLSX.writeFile(wb, `finance_total_report_${new Date().toISOString().split('T')[0]}.xlsx`);
    toast.success('Report exported successfully');
  };

  const totalCenterPaid = rows.filter(r => r.centerPaymentStatus === 'Paid').reduce((s, r) => s + (r.centerPaymentAmount || 0), 0);
  const totalCenterDue = rows.filter(r => r.centerPaymentStatus === 'Due').length;
  const totalUniPaid = rows.filter(r => r.universityPaymentStatus === 'paid').reduce((s, r) => s + (r.universityPaymentAmount || 0), 0);

  return (
    <div className="space-y-5">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h2 className="text-2xl font-bold">Total Data Report</h2>
          <p className="text-muted-foreground text-sm">Complete enrollment, payment, commissions and coordinator fee overview</p>
        </div>
        <Button onClick={exportExcel} disabled={rows.length === 0} className="flex items-center gap-2">
          <FileSpreadsheet className="w-4 h-4" />
          Export Excel
        </Button>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        {[
          { label: 'Total Records', value: rows.length, color: 'text-slate-700' },
          { label: 'Center Fees Collected', value: 'INR ' + totalCenterPaid.toLocaleString('en-IN'), color: 'text-green-700' },
          { label: 'Center Fees Due', value: totalCenterDue + ' students', color: 'text-amber-700' },
          { label: 'University Fees Paid', value: 'INR ' + totalUniPaid.toLocaleString('en-IN'), color: 'text-blue-700' },
        ].map((stat) => (
          <Card key={stat.label} className="border shadow-sm">
            <CardContent className="pt-4 pb-3">
              <p className="text-xs text-muted-foreground">{stat.label}</p>
              <p className={'text-xl font-bold mt-1 ' + stat.color}>{stat.value}</p>
            </CardContent>
          </Card>
        ))}
      </div>

      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Filter className="w-4 h-4" /> Filters
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {/* Row 1: Search & Date Filters */}
            <div className="flex flex-wrap gap-4 items-end">
              <div className="flex-1 min-w-[240px]">
                <label className="text-xs font-semibold text-muted-foreground block mb-1">Search</label>
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                  <Input
                    placeholder="Search student or center..."
                    className="pl-9 w-full"
                    value={uiFilters.search}
                    onChange={e => setUiFilters(f => ({ ...f, search: e.target.value }))}
                    onKeyDown={e => e.key === 'Enter' && handleApply()}
                  />
                </div>
              </div>

              <div className="w-[180px]">
                <label className="text-xs font-semibold text-muted-foreground block mb-1">From Date</label>
                <Input
                  type="date"
                  value={uiFilters.dateFrom}
                  onChange={e => setUiFilters(f => ({ ...f, dateFrom: e.target.value }))}
                />
              </div>

              <div className="w-[180px]">
                <label className="text-xs font-semibold text-muted-foreground block mb-1">To Date</label>
                <Input
                  type="date"
                  value={uiFilters.dateTo}
                  onChange={e => setUiFilters(f => ({ ...f, dateTo: e.target.value }))}
                />
              </div>
            </div>

            {/* Row 2: Select Dropdowns & Buttons */}
            <div className="flex flex-wrap gap-4 items-center justify-between pt-2 border-t border-muted/50">
              <div className="flex flex-wrap gap-3 items-center flex-1">
                <div className="w-[200px]">
                  <label className="text-xs font-semibold text-muted-foreground block mb-1">University</label>
                  <Select value={uiFilters.universityId} onValueChange={v => setUiFilters(f => ({ ...f, universityId: v }))}>
                    <SelectTrigger><SelectValue placeholder="All Universities" /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="__all__">All Universities</SelectItem>
                      {universities.map((u: any) => <SelectItem key={u.id} value={u.id}>{u.name}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>

                <div className="w-[200px]">
                  <label className="text-xs font-semibold text-muted-foreground block mb-1">Program</label>
                  <Select value={uiFilters.programId} onValueChange={v => setUiFilters(f => ({ ...f, programId: v }))}>
                    <SelectTrigger><SelectValue placeholder="All Programs" /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="__all__">All Programs</SelectItem>
                      {programs.map((p: any) => <SelectItem key={p.id} value={p.id}>{p.name}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>

                <div className="w-[200px]">
                  <label className="text-xs font-semibold text-muted-foreground block mb-1">Session</label>
                  <Select value={uiFilters.sessionId} onValueChange={v => setUiFilters(f => ({ ...f, sessionId: v }))}>
                    <SelectTrigger><SelectValue placeholder="All Sessions" /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="__all__">All Sessions</SelectItem>
                      {sessions.map((s: any) => <SelectItem key={s.id} value={s.id}>{s.name}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="flex gap-2 self-end mt-4 sm:mt-0">
                <Button onClick={handleApply} disabled={loading}>
                  {loading ? <RefreshCw className="w-3.5 h-3.5 animate-spin mr-1.5" /> : null}
                  Apply Filters
                </Button>
                <Button variant="outline" onClick={handleReset}>Reset</Button>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardContent className="p-0">
          {loading ? (
            <div className="py-12 text-center text-muted-foreground">Loading report...</div>
          ) : rows.length === 0 ? (
            <div className="py-12 text-center text-muted-foreground">No data found. Adjust filters and try again.</div>
          ) : (
            <div className="overflow-x-auto rounded-xl">
              <table className="min-w-max w-full text-sm">
                <thead className="bg-muted/60 border-b">
                  <tr>
                    {[
                      '#', 'Student', 'Enroll No', 'Admission Date', 'Admission Session', 'Center Name', 'Sub Center (Branch)',
                      'Program', 'University',
                      'Payment (INR)', 'Payment Status', 'Payment For',
                      'University Payment (INR)', 'Uni. Payment Status',
                      'Coordinator Name', 'Coord. Payment (INR)', 'Coord. Status',
                      'Comm. From Uni (INR)', 'Comm. From Uni Date', 'Comm. From Uni Status',
                      'Comm. To Center (INR)', 'Comm. To Center Date', 'Comm. To Center Status'
                    ].map(h => (
                      <th key={h} className="px-3 py-2.5 text-left text-xs font-semibold text-muted-foreground whitespace-nowrap">
                        {h}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {rows.map((r, i) => (
                    <tr key={r.id} className="hover:bg-muted/30 transition-colors">
                      <td className="px-3 py-2.5 text-muted-foreground text-xs">{i + 1}</td>
                      <td className="px-3 py-2.5 font-medium whitespace-nowrap">{r.studentName}</td>
                      <td className="px-3 py-2.5 text-xs font-mono text-muted-foreground">{r.enrollmentNumber || '-'}</td>
                      <td className="px-3 py-2.5 whitespace-nowrap text-xs">
                        {fmtDate(r.admissionDate)}
                      </td>
                      <td className="px-3 py-2.5 whitespace-nowrap">{r.admissionSession || '-'}</td>
                      <td className="px-3 py-2.5 whitespace-nowrap">{r.centerName || '-'}</td>
                      <td className="px-3 py-2.5 text-xs text-muted-foreground">{r.subCenterName || '-'}</td>
                      <td className="px-3 py-2.5 whitespace-nowrap">{r.program || '-'}</td>
                      <td className="px-3 py-2.5 whitespace-nowrap">{r.university || '-'}</td>
                      <td className="px-3 py-2.5 font-semibold">
                        {r.centerPaymentAmount != null ? 'INR ' + Number(r.centerPaymentAmount).toLocaleString('en-IN') : '-'}
                      </td>
                      <td className="px-3 py-2.5">
                        <span className={'text-xs px-2 py-0.5 rounded-full font-medium ' + statusColor(r.centerPaymentStatus)}>
                          {r.centerPaymentStatus}
                        </span>
                      </td>
                      <td className="px-3 py-2.5 text-xs text-muted-foreground capitalize">
                        {r.centerPaymentFor?.replace(/_/g, ' ') || '-'}
                      </td>
                      <td className="px-3 py-2.5 font-semibold">
                        {r.universityPaymentAmount != null ? 'INR ' + Number(r.universityPaymentAmount).toLocaleString('en-IN') : '-'}
                      </td>
                      <td className="px-3 py-2.5">
                        <span className={'text-xs px-2 py-0.5 rounded-full font-medium ' + statusColor(r.universityPaymentStatus)}>
                          {r.universityPaymentStatus}
                        </span>
                      </td>
                      <td className="px-3 py-2.5 text-xs">{r.coordinatorName || 'Null'}</td>
                      <td className="px-3 py-2.5 font-semibold">
                        {r.coordinatorPaymentAmount != null ? 'INR ' + Number(r.coordinatorPaymentAmount).toLocaleString('en-IN') : '-'}
                      </td>
                      <td className="px-3 py-2.5">
                        <span className={'text-xs px-2 py-0.5 rounded-full font-medium ' + statusColor(r.coordinatorPaymentStatus)}>
                          {r.coordinatorPaymentStatus}
                        </span>
                      </td>
                      {/* Commission from University */}
                      <td className="px-3 py-2.5 font-semibold">
                        {r.commissionInAmount != null ? 'INR ' + Number(r.commissionInAmount).toLocaleString('en-IN') : '-'}
                      </td>
                      <td className="px-3 py-2.5 whitespace-nowrap text-xs">
                        {fmtDate(r.commissionInDate)}
                      </td>
                      <td className="px-3 py-2.5">
                        <span className={'text-xs px-2 py-0.5 rounded-full font-medium ' + statusColor(r.commissionInStatus)}>
                          {r.commissionInStatus}
                        </span>
                      </td>
                      {/* Commission to Center */}
                      <td className="px-3 py-2.5 font-semibold">
                        {r.commissionOutAmount != null ? 'INR ' + Number(r.commissionOutAmount).toLocaleString('en-IN') : '-'}
                      </td>
                      <td className="px-3 py-2.5 whitespace-nowrap text-xs">
                        {fmtDate(r.commissionOutDate)}
                      </td>
                      <td className="px-3 py-2.5">
                        <span className={'text-xs px-2 py-0.5 rounded-full font-medium ' + statusColor(r.commissionOutStatus)}>
                          {r.commissionOutStatus}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { RefreshCw, CheckCircle, Clock, DollarSign, Upload, Calendar, FileText } from 'lucide-react';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import api from '@/lib/api';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';

interface Student {
  id: string;
  name: string;
  email: string;
  enrollmentNo: string;
  program: {
    name: string;
    code: string;
  };
  center: {
    name: string;
    code: string;
  };
}

interface UniversityFeePayment {
  id: string;
  semesterOrYear: string;
  amount: number;
  status: string;
  referenceNo?: string;
  paidAt?: string;
  screenshot?: string;
  createdAt: string;
  student: Student;
}

export function FinanceUniversityFeePanel() {
  const [payments, setPayments] = useState<UniversityFeePayment[]>([]);
  const [universities, setUniversities] = useState<any[]>([]);
  const [centers, setCenters] = useState<any[]>([]);
  const [universityFilter, setUniversityFilter] = useState('');
  const [centerFilter, setCenterFilter] = useState('');
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'pending' | 'paid'>('pending');
  const [payDialog, setPayDialog] = useState<{ open: boolean; payment: UniversityFeePayment | null }>({ open: false, payment: null });
  const [submitting, setSubmitting] = useState(false);
  const [form, setForm] = useState({
    referenceNo: '',
    paidAt: new Date().toISOString().split('T')[0],
    screenshot: null as File | null
  });

  const fetchPayments = async (status = activeTab) => {
    setLoading(true);
    try {
      const query = new URLSearchParams();
      query.append('status', status);
      if (universityFilter && universityFilter !== 'all') query.append('universityId', universityFilter);
      if (centerFilter && centerFilter !== 'all') query.append('centerId', centerFilter);

      const res = await api.get(`/finance/university-fees?${query.toString()}`);
      setPayments(res.data.data || []);
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to load university fees');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPayments();
    fetchUniversities();
    fetchCenters();
  }, [activeTab, universityFilter, centerFilter]);

  const fetchUniversities = async () => {
    try {
      const res = await api.get('/operations/universities');
      setUniversities(res.data.data || []);
    } catch (err) {}
  };

  const fetchCenters = async () => {
    try {
      const res = await api.get('/operations/centers');
      setCenters(res.data.data || []);
    } catch (err) {}
  };

  const handlePayClick = (p: UniversityFeePayment) => {
    setPayDialog({ open: true, payment: p });
    setForm({
      referenceNo: '',
      paidAt: new Date().toISOString().split('T')[0],
      screenshot: null
    });
  };

  const handlePaySubmit = async () => {
    if (!payDialog.payment) return;
    setSubmitting(true);

    try {
      const formData = new FormData();
      formData.append('referenceNo', form.referenceNo);
      formData.append('paidAt', form.paidAt);
      if (form.screenshot) {
        formData.append('screenshot', form.screenshot);
      }

      await api.post(`/finance/university-fees/${payDialog.payment.id}/pay`, formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });

      toast.success('University fee marked as paid successfully');
      setPayDialog({ open: false, payment: null });
      fetchPayments();
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to submit payment');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h2 className="text-2xl font-bold">University Fee Payments</h2>
          <p className="text-muted-foreground text-sm mt-1">Manage and track university-side fee disbursements for students.</p>
        </div>
        <Button variant="outline" size="sm" onClick={() => fetchPayments()} disabled={loading}>
          <RefreshCw className={cn('w-4 h-4 mr-2', loading && 'animate-spin')} />Refresh
        </Button>
      </div>

      <div className="flex gap-2">
        <Select value={universityFilter} onValueChange={setUniversityFilter}>
          <SelectTrigger className="w-[200px]">
            <SelectValue placeholder="All Universities" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Universities</SelectItem>
            {universities.map(u => <SelectItem key={u.id} value={u.id}>{u.name}</SelectItem>)}
          </SelectContent>
        </Select>

        <Select value={centerFilter} onValueChange={setCenterFilter}>
          <SelectTrigger className="w-[200px]">
            <SelectValue placeholder="All Centers" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Centers</SelectItem>
            {centers.map(c => <SelectItem key={c.id} value={c.id}>{c.name}</SelectItem>)}
          </SelectContent>
        </Select>
      </div>

      <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as any)} className="space-y-4">
        <TabsList>
          <TabsTrigger value="pending" className="flex items-center gap-1.5">
            <Clock className="w-3.5 h-3.5 text-orange-500" /> Pending
          </TabsTrigger>
          <TabsTrigger value="paid" className="flex items-center gap-1.5">
            <CheckCircle className="w-3.5 h-3.5 text-green-500" /> Paid
          </TabsTrigger>
        </TabsList>

        <TabsContent value="pending" className="space-y-4 mt-2">
          {loading ? (
            <div className="space-y-3">{[1, 2, 3].map(i => <div key={i} className="h-16 bg-muted rounded-xl animate-pulse" />)}</div>
          ) : payments.length === 0 ? (
            <Card><CardContent className="py-16 text-center text-muted-foreground">
              <DollarSign className="w-10 h-10 mx-auto mb-3 opacity-30" />
              <p>No pending university fee payments found.</p>
            </CardContent></Card>
          ) : (
            <div className="rounded-xl border border-border overflow-hidden bg-card text-card-foreground">
              <table className="w-full text-sm">
                <thead className="bg-muted/50 border-b border-border">
                  <tr>
                    <th className="text-left p-3 font-medium text-muted-foreground">Student</th>
                    <th className="text-left p-3 font-medium text-muted-foreground">Program</th>
                    <th className="text-left p-3 font-medium text-muted-foreground">Cycle</th>
                    <th className="text-left p-3 font-medium text-muted-foreground">Uni Fee</th>
                    <th className="text-right p-3 font-medium text-muted-foreground">Action</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {payments.map(p => (
                    <tr key={p.id} className="hover:bg-muted/20 transition-colors">
                      <td className="p-3">
                        <p className="font-medium text-sm">{p.student?.name}</p>
                        <p className="text-xs text-muted-foreground">{p.student?.enrollmentNo}</p>
                      </td>
                      <td className="p-3">
                        <p className="text-sm">{p.student?.program?.name}</p>
                        <p className="text-xs text-muted-foreground">{p.student?.center?.name}</p>
                      </td>
                      <td className="p-3">
                        <Badge variant="outline">{p.semesterOrYear}</Badge>
                      </td>
                      <td className="p-3 font-bold text-blue-600">
                        ₹{p.amount.toLocaleString()}
                      </td>
                      <td className="p-3 text-right">
                        <Button size="sm" onClick={() => handlePayClick(p)}>Record Payment</Button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </TabsContent>

        <TabsContent value="paid" className="space-y-4 mt-2">
          {loading ? (
            <div className="space-y-3">{[1, 2, 3].map(i => <div key={i} className="h-16 bg-muted rounded-xl animate-pulse" />)}</div>
          ) : payments.length === 0 ? (
            <Card><CardContent className="py-16 text-center text-muted-foreground">
              <CheckCircle className="w-10 h-10 mx-auto mb-3 opacity-30" />
              <p>No paid university fee payments recorded yet.</p>
            </CardContent></Card>
          ) : (
            <div className="rounded-xl border border-border overflow-hidden bg-card text-card-foreground">
              <table className="w-full text-sm">
                <thead className="bg-muted/50 border-b border-border">
                  <tr>
                    <th className="text-left p-3 font-medium text-muted-foreground">Student</th>
                    <th className="text-left p-3 font-medium text-muted-foreground">Program</th>
                    <th className="text-left p-3 font-medium text-muted-foreground">Paid Details</th>
                    <th className="text-left p-3 font-medium text-muted-foreground">Amount</th>
                    <th className="text-left p-3 font-medium text-muted-foreground">Proof</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {payments.map(p => (
                    <tr key={p.id} className="hover:bg-muted/20 transition-colors">
                      <td className="p-3">
                        <p className="font-medium text-sm">{p.student?.name}</p>
                        <p className="text-xs text-muted-foreground">{p.student?.enrollmentNo}</p>
                      </td>
                      <td className="p-3">
                        <p className="text-sm">{p.student?.program?.name}</p>
                        <p className="text-xs text-muted-foreground">{p.semesterOrYear}</p>
                      </td>
                      <td className="p-3">
                        <p className="text-xs font-mono">Ref: {p.referenceNo || 'N/A'}</p>
                        {p.paidAt && (
                          <p className="text-[11px] text-muted-foreground">
                            Date: {new Date(p.paidAt).toLocaleDateString()}
                          </p>
                        )}
                      </td>
                      <td className="p-3 font-bold text-green-600">
                        ₹{p.amount.toLocaleString()}
                      </td>
                      <td className="p-3">
                        {p.screenshot ? (
                          <a
                            href={`${(import.meta.env.VITE_API_URL || '').replace('/api/v1', '')}${p.screenshot}`}
                            target="_blank"
                            rel="noreferrer"
                            className="inline-flex items-center gap-1 text-xs text-primary hover:underline"
                          >
                            <FileText className="w-3.5 h-3.5" /> View Proof
                          </a>
                        ) : (
                          <span className="text-xs text-muted-foreground">—</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </TabsContent>
      </Tabs>

      <Dialog open={payDialog.open} onOpenChange={(o) => setPayDialog(d => ({ ...d, open: o }))}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Record University Fee Payment</DialogTitle>
          </DialogHeader>

          <div className="space-y-4 py-2">
            <div className="bg-muted/40 p-3 rounded-lg text-sm space-y-1">
              <p><strong>Student:</strong> {payDialog.payment?.student?.name}</p>
              <p><strong>Program:</strong> {payDialog.payment?.student?.program?.name}</p>
              <p><strong>University Fee Amount:</strong> ₹{payDialog.payment?.amount.toLocaleString()}</p>
              <p><strong>Billing Cycle:</strong> {payDialog.payment?.semesterOrYear}</p>
            </div>

            <div className="space-y-1">
              <Label htmlFor="refNo">Reference / Transaction Number</Label>
              <Input
                id="refNo"
                value={form.referenceNo}
                onChange={(e) => setForm(f => ({ ...f, referenceNo: e.target.value }))}
                placeholder="e.g. TXN982741982"
                required
              />
            </div>

            <div className="space-y-1">
              <Label htmlFor="payDate">Payment Date</Label>
              <div className="relative">
                <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                <Input
                  id="payDate"
                  type="date"
                  value={form.paidAt}
                  onChange={(e) => setForm(f => ({ ...f, paidAt: e.target.value }))}
                  className="pl-9"
                  required
                />
              </div>
            </div>

            <div className="space-y-1">
              <Label htmlFor="proof">Upload Receipt / Screenshot (Optional)</Label>
              <div className="flex items-center gap-3">
                <Input
                  id="proof"
                  type="file"
                  accept="image/*,application/pdf"
                  onChange={(e) => {
                    const files = e.target.files;
                    if (files && files.length > 0) {
                      setForm(f => ({ ...f, screenshot: files[0] }));
                    }
                  }}
                  className="hidden"
                />
                <Button
                  type="button"
                  variant="outline"
                  className="w-full flex items-center justify-center gap-2 h-10 border-dashed"
                  onClick={() => document.getElementById('proof')?.click()}
                >
                  <Upload className="w-4 h-4" />
                  {form.screenshot ? form.screenshot.name : 'Select file'}
                </Button>
              </div>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setPayDialog({ open: false, payment: null })}>Cancel</Button>
            <Button onClick={handlePaySubmit} disabled={submitting || !form.referenceNo}>
              {submitting ? 'Submitting...' : 'Mark Paid'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import {
  RefreshCw, UserPlus, Trash2, ChevronDown, ChevronUp,
  Building2, Layers, MapPin, Users, Search,
} from 'lucide-react';
import { toast } from 'sonner';
import api from '@/lib/api';

// ─── Types ────────────────────────────────────────────────────────────────────
interface Dept { id: string; name: string; type: string; }
interface SubDept { id: string; name: string; parentDeptId: string | { id: string; name: string }; }
interface Branch {
  id: string; name: string; code: string; address: string; city?: string;
  branchManagerId?: { id: string; name: string; role: string; designation?: string };
  salesDeptId?: { id: string; name: string; type: string };
  operationsDeptId?: { id: string; name: string; type: string };
}
interface OrgUser { id: string; name: string; email: string; role: string; designation?: string; }
interface DesignationNode {
  id: string;
  title: string;
  level: number;
  maxHeadcount: number;
  departmentId?: Dept;
  subDepartmentId?: SubDept;
  branchId?: { id: string; name: string; code: string };
  parentDesignationId?: { id: string; title: string };
  filledBy: OrgUser[];
  status: string;
}

const ROLE_COLORS: Record<string, string> = {
  org_admin: '#7c3aed', ceo: '#2563eb', ops_admin: '#ea580c',
  finance_admin: '#16a34a', hr_admin: '#db2777', sales_admin: '#ca8a04',
  center_admin: '#0d9488', ops_sub_admin: '#f97316', employee: '#6b7280', staff: '#94a3b8',
};

// ─── HR Org Node (view + assign only, no edit/delete/add-child) ───────────────
function HROrgNode({
  node, allNodes, onAssign, onUnassign, depth = 0,
}: {
  node: DesignationNode; allNodes: DesignationNode[];
  onAssign: (n: DesignationNode) => void;
  onUnassign: (n: DesignationNode, userId: string) => void;
  depth?: number;
}) {
  const [expanded, setExpanded] = useState(true);
  const children = allNodes.filter(n => n.parentDesignationId?.id === node.id);
  const filled = node.filledBy?.length || 0;
  const vacant = node.maxHeadcount - filled;
  const isFull = vacant <= 0;

  const boxColor = node.branchId
    ? '#0891b2'
    : node.departmentId
      ? (ROLE_COLORS[node.departmentId.type] || '#6366f1')
      : '#6366f1';

  const subDeptName = node.subDepartmentId
    ? (typeof node.subDepartmentId === 'object' ? node.subDepartmentId.name : '')
    : null;

  return (
    <div className="flex flex-col items-center">
      <div className="relative group" style={{ minWidth: 190 }}>
        <div
          className="rounded-xl border-2 bg-white shadow-md px-4 py-3 text-center transition-all hover:shadow-lg"
          style={{ borderColor: boxColor, minWidth: 190 }}
        >
          {/* Branch badge */}
          {node.branchId && (
            <span className="text-[10px] font-semibold uppercase tracking-wide px-2 py-0.5 rounded-full mb-1 inline-flex items-center gap-1"
              style={{ background: '#0891b222', color: '#0891b2' }}>
              <Building2 className="h-2.5 w-2.5" />
              {node.branchId.name} [{node.branchId.code}]
            </span>
          )}

          {/* Dept badge */}
          {node.departmentId && !node.branchId && (
            <span className="text-[10px] font-semibold uppercase tracking-wide px-2 py-0.5 rounded-full mb-1 inline-block"
              style={{ background: boxColor + '22', color: boxColor }}>
              {node.departmentId.name}
            </span>
          )}

          {/* Sub-dept badge */}
          {subDeptName && (
            <span className="text-[10px] font-medium px-2 py-0.5 rounded-full mb-1 inline-flex items-center gap-1 bg-slate-100 text-slate-600">
              <Layers className="h-2.5 w-2.5" />{subDeptName}
            </span>
          )}

          <p className="font-bold text-sm text-gray-800 leading-tight">{node.title}</p>

          <div className="flex items-center justify-center gap-1 mt-1">
            <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${isFull ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>
              {filled}/{node.maxHeadcount} filled
            </span>
          </div>

          {/* People in this slot */}
          {filled > 0 && (
            <div className="mt-2 space-y-1">
              {node.filledBy.map(u => (
                <div key={u.id} className="flex items-center gap-1 bg-gray-50 rounded-lg px-2 py-1 group/person">
                  <div
                    className="w-5 h-5 rounded-full flex items-center justify-center text-white text-[9px] font-bold shrink-0"
                    style={{ background: ROLE_COLORS[u.role] || '#6366f1' }}
                  >
                    {u.name.charAt(0)}
                  </div>
                  <span className="text-xs text-gray-700 truncate flex-1 text-left">{u.name}</span>
                  <span className="text-[9px] text-gray-400 capitalize hidden group-hover/person:inline">
                    {u.role.replace(/_/g, ' ')}
                  </span>
                  <button
                    onClick={() => onUnassign(node, u.id)}
                    className="text-red-400 hover:text-red-600 opacity-0 group-hover/person:opacity-100 transition-opacity ml-1"
                    title="Remove from position"
                  >
                    <Trash2 className="h-3 w-3" />
                  </button>
                </div>
              ))}
            </div>
          )}

          {/* Assign button for vacant slots */}
          {vacant > 0 && (
            <button
              onClick={() => onAssign(node)}
              className="mt-2 w-full flex items-center justify-center gap-1 text-xs border border-dashed rounded-lg py-1.5 text-gray-400 hover:text-indigo-600 hover:border-indigo-400 transition-colors"
            >
              <UserPlus className="h-3 w-3" />
              {vacant} vacant {vacant === 1 ? 'slot' : 'slots'} — assign
            </button>
          )}
        </div>
      </div>

      {children.length > 0 && (
        <>
          <div className="w-px bg-gray-300" style={{ height: 24 }} />
          <button onClick={() => setExpanded(!expanded)} className="text-gray-400 hover:text-gray-600 mb-1">
            {expanded ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
          </button>
          {expanded && (
            <div className="flex flex-col items-center">
              {children.length > 1 ? (
                <div className="relative flex items-start">
                  <div className="absolute top-0 left-1/2 -translate-x-1/2"
                    style={{ width: `calc(100% - 190px)`, height: 1, background: '#d1d5db', top: 0 }}
                  />
                  {children.map(child => (
                    <div key={child.id} className="flex flex-col items-center" style={{ padding: '0 20px' }}>
                      <div className="w-px bg-gray-300" style={{ height: 20 }} />
                      <HROrgNode node={child} allNodes={allNodes} onAssign={onAssign} onUnassign={onUnassign} depth={depth + 1} />
                    </div>
                  ))}
                </div>
              ) : (
                <HROrgNode node={children[0]} allNodes={allNodes} onAssign={onAssign} onUnassign={onUnassign} depth={depth + 1} />
              )}
            </div>
          )}
        </>
      )}
    </div>
  );
}

// ─── Main HR Org Chart Panel ──────────────────────────────────────────────────
export function HROrgChartPanel() {
  const [nodes, setNodes] = useState<DesignationNode[]>([]);
  const [allUsers, setAllUsers] = useState<OrgUser[]>([]);
  const [allBranches, setAllBranches] = useState<Branch[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [search, setSearch] = useState('');

  // Assign dialog
  const [assignDialog, setAssignDialog] = useState(false);
  const [assignTarget, setAssignTarget] = useState<DesignationNode | null>(null);
  const [assignUserId, setAssignUserId] = useState('');
  const [userSearch, setUserSearch] = useState('');

  const fetchAll = async () => {
    setLoading(true);
    try {
      const [nodesRes, usersRes, branchRes] = await Promise.all([
        api.get('/org/designations'),
        api.get('/users'),
        api.get('/org/branches'),
      ]);
      setNodes(nodesRes.data.data || []);
      setAllUsers(usersRes.data.data || []);
      setAllBranches(branchRes.data.data || []);
    } catch {
      toast.error('Failed to load org chart');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchAll(); }, []);

  const openAssign = (node: DesignationNode) => {
    setAssignTarget(node);
    setAssignUserId('');
    setUserSearch('');
    setAssignDialog(true);
  };

  const handleAssign = async () => {
    if (!assignTarget || !assignUserId) return;
    setSaving(true);
    try {
      await api.patch(`/org/designations/${assignTarget.id}/assign`, { userId: assignUserId });
      toast.success('User assigned to position');
      setAssignDialog(false);
      fetchAll();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to assign');
    } finally {
      setSaving(false);
    }
  };

  const handleUnassign = async (node: DesignationNode, userId: string) => {
    if (!confirm('Remove this person from the position?')) return;
    try {
      await api.patch(`/org/designations/${node.id}/unassign`, { userId });
      toast.success('Removed from position');
      fetchAll();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to remove');
    }
  };

  // Stats
  const totalPositions = nodes.reduce((s, n) => s + n.maxHeadcount, 0);
  const totalFilled = nodes.reduce((s, n) => s + (n.filledBy?.length || 0), 0);
  const totalVacant = totalPositions - totalFilled;

  const globalRoots = nodes.filter(n => !n.parentDesignationId && !n.branchId);

  // Filter nodes by search (title or filled person name)
  const searchLower = search.toLowerCase();
  const matchesSearch = (node: DesignationNode) => {
    if (!searchLower) return true;
    if (node.title.toLowerCase().includes(searchLower)) return true;
    if (node.filledBy?.some(u => u.name.toLowerCase().includes(searchLower))) return true;
    return false;
  };

  // Users not yet in any position
  const assignedUserIds = new Set(nodes.flatMap(n => (n.filledBy || []).map(u => u.id)));
  const unplacedUsers = allUsers.filter(u =>
    !assignedUserIds.has(u.id) && !['ceo', 'org_admin', 'superadmin'].includes(u.role)
  );

  // Filtered users for assign dialog
  const filteredUsers = allUsers
    .filter(u => !assignTarget?.filledBy?.find(f => f.id === u.id))
    .filter(u => !userSearch || u.name.toLowerCase().includes(userSearch.toLowerCase()) || u.email.toLowerCase().includes(userSearch.toLowerCase()));

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64 text-muted-foreground">
        <RefreshCw className="w-5 h-5 animate-spin mr-2" /> Loading org chart...
      </div>
    );
  }

  return (
    <div className="space-y-5">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h2 className="text-xl font-bold">Organisation Chart</h2>
          <p className="text-sm text-muted-foreground">
            View the org hierarchy and assign employees to vacant positions
          </p>
        </div>
        <Button size="sm" variant="outline" onClick={fetchAll}>
          <RefreshCw className="h-4 w-4 mr-1" /> Refresh
        </Button>
      </div>

      {/* Summary stats */}
      <div className="grid grid-cols-3 gap-4">
        <div className="border rounded-xl p-4 text-center">
          <p className="text-2xl font-bold">{totalPositions}</p>
          <p className="text-xs text-muted-foreground mt-0.5">Total Positions</p>
        </div>
        <div className="border rounded-xl p-4 text-center bg-green-50">
          <p className="text-2xl font-bold text-green-700">{totalFilled}</p>
          <p className="text-xs text-muted-foreground mt-0.5">Filled</p>
        </div>
        <div className="border rounded-xl p-4 text-center bg-amber-50">
          <p className="text-2xl font-bold text-amber-700">{totalVacant}</p>
          <p className="text-xs text-muted-foreground mt-0.5">Vacant</p>
        </div>
      </div>

      {/* Search */}
      <div className="relative max-w-xs">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
        <Input
          className="pl-9"
          placeholder="Search positions or people..."
          value={search}
          onChange={e => setSearch(e.target.value)}
        />
      </div>

      {/* Legend */}
      <div className="flex flex-wrap gap-3 text-xs text-muted-foreground">
        <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-full bg-amber-200 inline-block" /> Vacant slots</span>
        <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-full bg-green-200 inline-block" /> Fully filled</span>
        <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-full bg-cyan-200 inline-block" /> Branch position</span>
        <span className="text-muted-foreground">Hover a person to remove · Click vacant slot to assign</span>
      </div>

      {nodes.length === 0 ? (
        <div className="border-2 border-dashed rounded-xl p-16 text-center">
          <Users className="h-12 w-12 text-muted-foreground mx-auto mb-3" />
          <p className="text-muted-foreground">No org chart defined yet.</p>
          <p className="text-sm text-muted-foreground mt-1">Ask your Org Admin to set up the hierarchy first.</p>
        </div>
      ) : (
        <>
          {/* Global / Head Office chart */}
          {globalRoots.length > 0 && (
            <div className="overflow-auto border rounded-xl bg-gray-50 p-8">
              <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-6 text-center">
                Organisation — Head Office
              </p>
              <div className="inline-flex gap-12 justify-center min-w-full pb-4">
                {globalRoots
                  .filter(r => !search || matchesSearch(r) || nodes.some(n => n.parentDesignationId?.id === r.id && matchesSearch(n)))
                  .map(root => (
                    <HROrgNode
                      key={root.id}
                      node={root}
                      allNodes={nodes}
                      onAssign={openAssign}
                      onUnassign={handleUnassign}
                    />
                  ))}
              </div>
            </div>
          )}

          {/* Branch sections */}
          {allBranches.length > 0 && (
            <div className="space-y-4">
              <p className="text-sm font-semibold text-muted-foreground uppercase tracking-wide">
                Branch Hierarchies ({allBranches.length})
              </p>
              {allBranches.map(branch => {
                const branchRoots = nodes.filter(n => n.branchId?.id === branch.id && !n.parentDesignationId);
                const mgr = branch.branchManagerId;
                return (
                  <div key={branch.id} className="border-2 rounded-2xl p-5 bg-cyan-50/50" style={{ borderColor: '#0891b244' }}>
                    <div className="flex items-center gap-3 mb-4">
                      <div className="w-9 h-9 rounded-xl bg-cyan-600 flex items-center justify-center text-white">
                        <Building2 className="h-5 w-5" />
                      </div>
                      <div>
                        <div className="flex items-center gap-2">
                          <span className="font-bold text-base text-cyan-900">{branch.name}</span>
                          <span className="text-xs font-mono bg-cyan-100 text-cyan-700 px-2 py-0.5 rounded">{branch.code}</span>
                        </div>
                        <div className="flex items-center gap-1 text-xs text-cyan-700 mt-0.5">
                          <MapPin className="h-3 w-3" />{branch.address}{branch.city ? `, ${branch.city}` : ''}
                        </div>
                      </div>
                      {mgr && (
                        <Badge variant="outline" className="ml-auto text-xs">
                          Manager: {mgr.name}
                        </Badge>
                      )}
                    </div>

                    {branchRoots.length > 0 ? (
                      <div className="overflow-auto">
                        <div className="inline-flex gap-10 justify-center min-w-full pb-4 pt-2">
                          {branchRoots.map(root => (
                            <HROrgNode
                              key={root.id}
                              node={root}
                              allNodes={nodes}
                              onAssign={openAssign}
                              onUnassign={handleUnassign}
                            />
                          ))}
                        </div>
                      </div>
                    ) : (
                      <p className="text-sm text-muted-foreground text-center py-4">
                        No positions defined for this branch yet.
                      </p>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </>
      )}

      {/* Unplaced employees */}
      {unplacedUsers.length > 0 && (
        <div className="border rounded-xl p-4 bg-amber-50">
          <p className="text-sm font-semibold text-amber-700 mb-2">
            {unplacedUsers.length} employee{unplacedUsers.length !== 1 ? 's' : ''} not yet placed in the chart
          </p>
          <div className="flex flex-wrap gap-2">
            {unplacedUsers.map(u => (
              <span key={u.id} className="text-xs bg-white border rounded-full px-3 py-1 flex items-center gap-1.5">
                <span
                  className="w-4 h-4 rounded-full inline-flex items-center justify-center text-white text-[9px] font-bold"
                  style={{ background: ROLE_COLORS[u.role] || '#6366f1' }}
                >
                  {u.name.charAt(0)}
                </span>
                {u.name}
                <span className="text-gray-400">({u.role.replace(/_/g, ' ')})</span>
              </span>
            ))}
          </div>
        </div>
      )}

      {/* Assign User Dialog */}
      <Dialog open={assignDialog} onOpenChange={setAssignDialog}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>
              Assign to "{assignTarget?.title}"
              {assignTarget?.branchId && (
                <span className="text-sm font-normal text-cyan-600 ml-2">
                  [{assignTarget.branchId.code}]
                </span>
              )}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            {/* Position info */}
            <div className="p-3 rounded-lg bg-muted/50 text-sm space-y-1">
              {assignTarget?.departmentId && (
                <p className="text-muted-foreground">
                  Department: <span className="font-medium text-foreground">{assignTarget.departmentId.name}</span>
                </p>
              )}
              {assignTarget?.subDepartmentId && typeof assignTarget.subDepartmentId === 'object' && (
                <p className="text-muted-foreground">
                  Sub-dept: <span className="font-medium text-foreground">{assignTarget.subDepartmentId.name}</span>
                </p>
              )}
              <p className="text-muted-foreground">
                Slots available: <span className="font-medium text-amber-600">
                  {(assignTarget?.maxHeadcount || 1) - (assignTarget?.filledBy?.length || 0)}
                </span>
              </p>
            </div>

            {/* Search users */}
            <div className="space-y-1">
              <Label>Search Employee</Label>
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                <Input
                  className="pl-9"
                  placeholder="Name or email..."
                  value={userSearch}
                  onChange={e => setUserSearch(e.target.value)}
                />
              </div>
            </div>

            <div className="space-y-1">
              <Label>Select Person</Label>
              <Select value={assignUserId} onValueChange={setAssignUserId}>
                <SelectTrigger><SelectValue placeholder="Choose an employee..." /></SelectTrigger>
                <SelectContent>
                  {filteredUsers.length === 0 ? (
                    <div className="px-3 py-4 text-sm text-muted-foreground text-center">No matching employees</div>
                  ) : (
                    filteredUsers.map(u => (
                      <SelectItem key={u.id} value={u.id}>
                        <div className="flex items-center gap-2">
                          <span
                            className="w-5 h-5 rounded-full inline-flex items-center justify-center text-white text-[9px] font-bold shrink-0"
                            style={{ background: ROLE_COLORS[u.role] || '#6366f1' }}
                          >
                            {u.name.charAt(0)}
                          </span>
                          <span>{u.name}</span>
                          <span className="text-xs text-muted-foreground">— {u.role.replace(/_/g, ' ')}</span>
                        </div>
                      </SelectItem>
                    ))
                  )}
                </SelectContent>
              </Select>
            </div>

            {/* Selected user preview */}
            {assignUserId && (() => {
              const u = allUsers.find(x => x.id === assignUserId);
              if (!u) return null;
              return (
                <div className="flex items-center gap-3 p-3 rounded-lg border bg-primary/5 border-primary/20">
                  <div
                    className="w-9 h-9 rounded-full flex items-center justify-center text-white font-bold"
                    style={{ background: ROLE_COLORS[u.role] || '#6366f1' }}
                  >
                    {u.name.charAt(0)}
                  </div>
                  <div>
                    <p className="font-semibold text-sm">{u.name}</p>
                    <p className="text-xs text-muted-foreground">{u.email} · {u.role.replace(/_/g, ' ')}</p>
                  </div>
                </div>
              );
            })()}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setAssignDialog(false)}>Cancel</Button>
            <Button onClick={handleAssign} disabled={saving || !assignUserId}>
              {saving ? 'Assigning...' : 'Assign to Position'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Edit, Trash2, Key, Users, ArrowRightLeft, TrendingUp, TrendingDown } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import api from '@/lib/api';

interface User {
  id?: string;
  name: string;
  email: string;
  role: string;
  designation?: string;
  departmentId?: string;
  additionalDepartmentIds?: string[];
  subDepartmentId?: string;
  reportingTo?: string;
  department?: { name: string; id?: string };
  additionalDepartments?: { id: string; name: string }[];
  subDepartment?: { name: string };
  reportingToUser?: { name: string };
  status?: string;
}

interface Department {
  id?: string;
  name: string;
  type: string;
  managerId?: string;
  parentDepartmentId?: string;
}

interface SubDepartment {
  id?: string;
  name: string;
  parentDeptId: string;
}

interface DesignationOption {
  id: string;
  title: string;
  departmentId?: { id: string; name: string };
  maxHeadcount: number;
  filledBy: any[];
}

export function HRUsersPanel() {
  const [users, setUsers] = useState<User[]>([]);
  const [departments, setDepartments] = useState<Department[]>([]);
  const [subDepartments, setSubDepartments] = useState<SubDepartment[]>([]);
  const [designations, setDesignations] = useState<DesignationOption[]>([]);
  const [loading, setLoading] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [passwordDialogOpen, setPasswordDialogOpen] = useState(false);
  const [transferDialogOpen, setTransferDialogOpen] = useState(false);
  const [promotionDialogOpen, setPromotionDialogOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [selectedUserId, setSelectedUserId] = useState<string | null>(null);
  const [selectedUser, setSelectedUser] = useState<User | null>(null);

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    role: 'employee',
    designation: '',
    departmentId: '',
    additionalDepartmentIds: [] as string[],
    subDepartmentId: '',
    reportingTo: '',
  });

  const [transferData, setTransferData] = useState({
    departmentId: '',
    subDepartmentId: '',
    reason: '',
  });

  const [promotionData, setPromotionData] = useState({
    newDesignation: '',
    newRole: 'employee',
    reportingTo: '',
    type: 'promotion' as 'promotion' | 'demotion',
  });

  const [passwordData, setPasswordData] = useState({
    newPassword: '',
    confirmPassword: '',
  });

  useEffect(() => {
    fetchUsers();
    fetchDepartments();
    fetchSubDepartments();
    fetchDesignations();
  }, []);

  useEffect(() => {
    // Fetch sub-departments when department changes
    if (formData.departmentId) {
      fetchSubDepartmentsByParent(formData.departmentId);
    }
  }, [formData.departmentId]);

  useEffect(() => {
    // Fetch sub-departments when transfer department changes
    if (transferData.departmentId) {
      fetchSubDepartmentsByParent(transferData.departmentId);
    }
  }, [transferData.departmentId]);

  const fetchUsers = async () => {
    setLoading(true);
    try {
      const response = await api.get('/users');
      const allUsers = response.data.data || response.data || [];
      // Exclude top-level admin roles — everyone else is headcount
      const staffUsers = allUsers.filter((user: User) =>
        !['ceo', 'org_admin', 'superadmin'].includes(user.role)
      );
      setUsers(staffUsers);
    } catch (_error) {
      console.error('Failed to fetch users:', _error);
    } finally {
      setLoading(false);
    }
  };

  const fetchDepartments = async () => {
    try {
      const response = await api.get('/departments');
      setDepartments(response.data.data || response.data || []);
    } catch (_error) {
      console.error('Failed to fetch departments:', _error);
    }
  };

  const fetchSubDepartments = async () => {
    try {
      const response = await api.get('/sub-departments');
      setSubDepartments(response.data.data || response.data || []);
    } catch (_error) {
      console.error('Failed to fetch sub-departments:', _error);
    }
  };

  const fetchDesignations = async () => {
    try {
      const response = await api.get('/org/designations');
      setDesignations(response.data.data || []);
    } catch (_error) {
      // Designations may not exist yet — that's fine
    }
  };

  const fetchSubDepartmentsByParent = async (parentId: string) => {
    try {
      const response = await api.get(`/sub-departments?parentDeptId=${parentId}`);
      setSubDepartments(response.data.data || response.data || []);
    } catch (_error) {
      console.error('Failed to fetch sub-departments:', _error);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const additionalDepts = formData.additionalDepartmentIds.filter(id => id && id !== formData.departmentId);
      if (editingUser) {
        const userId = editingUser.id || editingUser.id;
        await api.put(`/users/${userId}`, {
          name: formData.name,
          email: formData.email,
          role: formData.role,
          designation: formData.designation || undefined,
          departmentId: (formData.departmentId && formData.departmentId !== 'none') ? formData.departmentId : undefined,
          additionalDepartmentIds: additionalDepts,
          subDepartmentId: (formData.subDepartmentId && formData.subDepartmentId !== 'none') ? formData.subDepartmentId : undefined,
          reportingTo: (formData.reportingTo && formData.reportingTo !== 'none') ? formData.reportingTo : undefined,
        });
      } else {
        await api.post('/users', {
          ...formData,
          additionalDepartmentIds: additionalDepts,
          departmentId: (formData.departmentId && formData.departmentId !== 'none') ? formData.departmentId : undefined,
          subDepartmentId: (formData.subDepartmentId && formData.subDepartmentId !== 'none') ? formData.subDepartmentId : undefined,
          reportingTo: (formData.reportingTo && formData.reportingTo !== 'none') ? formData.reportingTo : undefined,
        });
      }
      setDialogOpen(false);
      resetForm();
      fetchUsers();
    } catch (_error) {
      console.error('Failed to save user:', _error);
      alert('Failed to save user. Please try again.');
    }
  };

  const handleTransfer = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedUser) return;

    try {
      const userId = selectedUser.id || selectedUser.id;
      await api.put(`/users/${userId}`, {
        departmentId: (transferData.departmentId && transferData.departmentId !== 'none') ? transferData.departmentId : undefined,
        subDepartmentId: (transferData.subDepartmentId && transferData.subDepartmentId !== 'none') ? transferData.subDepartmentId : undefined,
      });

      setTransferDialogOpen(false);
      setTransferData({ departmentId: '', subDepartmentId: '', reason: '' });
      setSelectedUser(null);
      fetchUsers();
      alert('Employee transferred successfully!');
    } catch (_error) {
      console.error('Failed to transfer employee:', _error);
      alert('Failed to transfer employee. Please try again.');
    }
  };

  const handlePromotionDemotion = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedUser) return;

    try {
      const userId = selectedUser.id || selectedUser.id;
      await api.put(`/users/${userId}`, {
        designation: promotionData.newDesignation,
        role: promotionData.newRole,
        reportingTo: (promotionData.reportingTo && promotionData.reportingTo !== 'none') ? promotionData.reportingTo : undefined,
      });

      setPromotionDialogOpen(false);
      setPromotionData({ newDesignation: '', newRole: 'employee', reportingTo: '', type: 'promotion' });
      setSelectedUser(null);
      fetchUsers();
      alert(`Employee ${promotionData.type === 'promotion' ? 'promoted' : 'demoted'} successfully!`);
    } catch (_error) {
      console.error(`Failed to ${promotionData.type} employee:`, _error);
      alert(`Failed to ${promotionData.type} employee. Please try again.`);
    }
  };

  const handlePasswordChange = async (e: React.FormEvent) => {
    e.preventDefault();

    if (passwordData.newPassword !== passwordData.confirmPassword) {
      alert('Passwords do not match!');
      return;
    }

    if (passwordData.newPassword.length < 6) {
      alert('Password must be at least 6 characters long!');
      return;
    }

    try {
      await api.put(`/users/${selectedUserId}`, {
        password: passwordData.newPassword,
      });
      setPasswordDialogOpen(false);
      setPasswordData({ newPassword: '', confirmPassword: '' });
      setSelectedUserId(null);
      alert('Password updated successfully!');
    } catch (_error) {
      console.error('Failed to update password:', _error);
      alert('Failed to update password. Please try again.');
    }
  };

  const handleDelete = async (userId: string) => {
    if (!confirm('Are you sure you want to delete this user?')) return;

    try {
      await api.delete(`/users/${userId}`);
      fetchUsers();
    } catch (_error) {
      console.error('Failed to delete user:', _error);
      alert('Failed to delete user. Please try again.');
    }
  };

  const openEditDialog = (user: User) => {
    setEditingUser(user);
    const deptId = typeof user.departmentId === 'object' && user.departmentId !== null
      ? ((user.departmentId as any).id || (user.departmentId as any).id)
      : user.departmentId;
    const subDeptId = typeof user.subDepartmentId === 'object' && user.subDepartmentId !== null
      ? ((user.subDepartmentId as any).id || (user.subDepartmentId as any).id)
      : user.subDepartmentId;
    const reportingToId = typeof user.reportingTo === 'object' && user.reportingTo !== null
      ? ((user.reportingTo as any).id || (user.reportingTo as any).id)
      : user.reportingTo;
    const additionalIds = (user.additionalDepartments || []).map((d: any) =>
      typeof d === 'object' ? (d.id || d.id) : d
    ).filter(Boolean);
    setFormData({
      name: user.name,
      email: user.email,
      password: '',
      role: user.role,
      designation: user.designation || '',
      departmentId: deptId?.toString() || '',
      additionalDepartmentIds: additionalIds,
      subDepartmentId: subDeptId?.toString() || '',
      reportingTo: reportingToId?.toString() || '',
    });
    setDialogOpen(true);
  };

  const openTransferDialog = (user: User) => {
    setSelectedUser(user);
    setTransferData({
      departmentId: user.departmentId || '',
      subDepartmentId: user.subDepartmentId || '',
      reason: '',
    });
    setTransferDialogOpen(true);
  };

  const openPromotionDialog = (user: User, type: 'promotion' | 'demotion') => {
    setSelectedUser(user);
    setPromotionData({
      newDesignation: user.designation || '',
      newRole: user.role,
      reportingTo: user.reportingTo || '',
      type,
    });
    setPromotionDialogOpen(true);
  };

  const openPasswordDialog = (userId: string) => {
    setSelectedUserId(userId);
    setPasswordData({ newPassword: '', confirmPassword: '' });
    setPasswordDialogOpen(true);
  };

  const resetForm = () => {
    setFormData({
      name: '',
      email: '',
      password: '',
      role: 'employee',
      designation: '',
      departmentId: '',
      additionalDepartmentIds: [],
      subDepartmentId: '',
      reportingTo: '',
    });
    setEditingUser(null);
  };

  const getRoleBadgeColor = (role: string) => {
    const map: Record<string, string> = {
      employee: 'bg-blue-100 text-blue-800',
      staff: 'bg-green-100 text-green-800',
      hr_admin: 'bg-orange-100 text-orange-800',
      finance_admin: 'bg-emerald-100 text-emerald-800',
      ops_admin: 'bg-indigo-100 text-indigo-800',
      ops_sub_admin: 'bg-violet-100 text-violet-800',
      sales_admin: 'bg-pink-100 text-pink-800',
      center_admin: 'bg-cyan-100 text-cyan-800',
      bde: 'bg-yellow-100 text-yellow-800',
    };
    return map[role] || 'bg-gray-100 text-gray-800';
  };

  if (loading) {
    return (
      <Card>
        <CardContent className="p-8">
          <div className="text-center text-muted-foreground">Loading users...</div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between">
        <div>
          <CardTitle>User Management</CardTitle>
          <p className="text-sm text-muted-foreground mt-1">
            Manage all staff accounts — HR, Finance, Ops, Sales, and Employees
          </p>
        </div>
        <Dialog open={dialogOpen} onOpenChange={(open) => {
          setDialogOpen(open);
          if (!open) resetForm();
        }}>
          <DialogTrigger asChild>
            <Button>
              <Plus className="w-4 h-4 mr-2" />
              Add Employee User
            </Button>
          </DialogTrigger>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>
                {editingUser ? 'Edit Employee User' : 'Create Employee User'}
              </DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <Label htmlFor="name">Full Name</Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  required
                />
              </div>
              <div>
                <Label htmlFor="email">Email</Label>
                <Input
                  id="email"
                  type="email"
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  required
                />
              </div>
              {!editingUser && (
                <div>
                  <Label htmlFor="password">Password</Label>
                  <Input
                    id="password"
                    type="password"
                    value={formData.password}
                    onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                    required
                    minLength={6}
                    placeholder="Minimum 6 characters"
                  />
                </div>
              )}
              <div>
                <Label htmlFor="designation">Designation</Label>
                {designations.length > 0 ? (
                  <Select
                    value={formData.designation}
                    onValueChange={(value) => {
                      // Auto-fill department if designation has one
                      const desig = designations.find(d => d.title === value);
                      setFormData({
                        ...formData,
                        designation: value,
                        departmentId: desig?.departmentId?.id || formData.departmentId,
                      });
                    }}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Select from org chart..." />
                    </SelectTrigger>
                    <SelectContent>
                      {designations.map(d => {
                        const filled = d.filledBy?.length || 0;
                        const vacant = d.maxHeadcount - filled;
                        return (
                          <SelectItem key={d.id} value={d.title} disabled={vacant <= 0}>
                            {d.title}
                            {d.departmentId ? ` — ${d.departmentId.name}` : ''}
                            {vacant <= 0 ? ' (Full)' : ` (${vacant} open)`}
                          </SelectItem>
                        );
                      })}
                    </SelectContent>
                  </Select>
                ) : (
                  <Input
                    id="designation"
                    value={formData.designation}
                    onChange={(e) => setFormData({ ...formData, designation: e.target.value })}
                    placeholder="e.g., Senior Manager, Team Lead"
                  />
                )}
                {designations.length === 0 && (
                  <p className="text-xs text-muted-foreground mt-1">
                    Tip: Org Admin can define positions in the Hierarchy chart for structured assignment.
                  </p>
                )}
              </div>
              <div>
                <Label htmlFor="role">Role</Label>
                <Select
                  value={formData.role}
                  onValueChange={(value) => setFormData({ ...formData, role: value })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="employee">Employee</SelectItem>
                    <SelectItem value="staff">Staff</SelectItem>
                    <SelectItem value="hr_admin">HR Admin</SelectItem>
                    <SelectItem value="finance_admin">Finance Admin</SelectItem>
                    <SelectItem value="ops_admin">Operations Admin</SelectItem>
                    <SelectItem value="ops_sub_admin">Ops Sub Admin</SelectItem>
                    <SelectItem value="sales_admin">Sales Admin</SelectItem>
                    <SelectItem value="center_admin">Center Admin</SelectItem>
                    <SelectItem value="bde">BDE</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label htmlFor="department">Primary Department</Label>
                <Select
                  value={formData.departmentId}
                  onValueChange={(value) => {
                    setFormData({ ...formData, departmentId: value, subDepartmentId: '' });
                  }}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select department (optional)" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">No Department</SelectItem>
                    {departments.map((dept) => (
                      <SelectItem key={dept.id || dept.id} value={(dept.id || dept.id)!}>
                        {dept.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              {/* Additional departments — for branch managers etc. */}
              <div>
                <Label>Additional Departments <span className="text-xs text-muted-foreground font-normal">(for branch managers with multi-dept access)</span></Label>
                <div className="mt-2 border rounded-lg p-3 space-y-2 max-h-36 overflow-y-auto bg-muted/30">
                  {departments
                    .filter(d => (d.id || d.id) !== formData.departmentId && (d.id || d.id) !== 'none')
                    .map(dept => {
                      const deptId = (dept.id || dept.id)!;
                      const checked = formData.additionalDepartmentIds.includes(deptId);
                      return (
                        <label key={deptId} className="flex items-center gap-2 cursor-pointer text-sm">
                          <input
                            type="checkbox"
                            checked={checked}
                            onChange={() => {
                              const next = checked
                                ? formData.additionalDepartmentIds.filter(id => id !== deptId)
                                : [...formData.additionalDepartmentIds, deptId];
                              setFormData({ ...formData, additionalDepartmentIds: next });
                            }}
                            className="rounded"
                          />
                          {dept.name}
                          <span className="text-xs text-muted-foreground">({dept.type})</span>
                        </label>
                      );
                    })}
                  {departments.length === 0 && <p className="text-xs text-muted-foreground">No departments available</p>}
                </div>
              </div>
              {formData.departmentId && subDepartments.length > 0 && (
                <div>
                  <Label htmlFor="subDepartment">Sub-Department</Label>
                  <Select
                    value={formData.subDepartmentId}
                    onValueChange={(value) => setFormData({ ...formData, subDepartmentId: value })}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Select sub-department (optional)" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="none">No Sub-Department</SelectItem>
                      {subDepartments.map((subDept) => (
                        <SelectItem key={subDept.id || subDept.id} value={(subDept.id || subDept.id)!}>
                          {subDept.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              )}
              <div>
                <Label htmlFor="reportingTo">Reports To</Label>
                <Select
                  value={formData.reportingTo}
                  onValueChange={(value) => setFormData({ ...formData, reportingTo: value })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select reporting manager (optional)" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">No Manager</SelectItem>
                    {users.filter(u => (u.id || u.id) !== (editingUser?.id || editingUser?.id)).map((user) => (
                      <SelectItem key={user.id || user.id} value={(user.id || user.id)!}>
                        {user.name} {user.designation ? `(${user.designation})` : ''}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="flex justify-end gap-2">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => {
                    setDialogOpen(false);
                    resetForm();
                  }}
                >
                  Cancel
                </Button>
                <Button type="submit">
                  {editingUser ? 'Update' : 'Create'} User
                </Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>
      </CardHeader>
      <CardContent>
        {users.length === 0 ? (
          <div className="text-center py-12 text-muted-foreground">
            <Users className="w-12 h-12 mx-auto mb-4 opacity-50" />
            <p>No users found</p>
            <p className="text-sm">Create your first user to get started</p>
          </div>
        ) : (
          <div className="space-y-4">
            {users.map((user) => {
              const userId = user.id || user.id || '';
              return (
                <div
                  key={userId}
                  className="flex items-center justify-between p-4 border rounded-lg hover:bg-muted/50 transition-colors"
                >
                  <div className="flex-1">
                    <div className="flex items-center gap-3">
                      <h3 className="font-semibold">{user.name}</h3>
                      <Badge className={getRoleBadgeColor(user.role)}>
                        {user.role}
                      </Badge>
                      {user.status === 'inactive' && (
                        <Badge variant="outline" className="bg-red-50 text-red-700">
                          Inactive
                        </Badge>
                      )}
                    </div>
                    <p className="text-sm text-muted-foreground mt-1">{user.email}</p>
                    {user.designation && (
                      <p className="text-xs text-muted-foreground mt-1">
                        Designation: {user.designation}
                      </p>
                    )}
                    {user.department && (
                      <p className="text-xs text-muted-foreground mt-1">
                        Department: {user.department.name}
                        {user.subDepartment && ` → ${user.subDepartment.name}`}
                      </p>
                    )}
                    {user.additionalDepartments && user.additionalDepartments.length > 0 && (
                      <p className="text-xs text-muted-foreground mt-0.5">
                        Also: {user.additionalDepartments.map((d: any) => d.name || d).join(', ')}
                      </p>
                    )}
                    {user.reportingToUser && (
                      <p className="text-xs text-muted-foreground mt-1">
                        Reports to: {user.reportingToUser.name}
                      </p>
                    )}
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => openTransferDialog(user)}
                      title="Transfer Employee"
                    >
                      <ArrowRightLeft className="w-4 h-4" />
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => openPromotionDialog(user, 'promotion')}
                      title="Promote Employee"
                    >
                      <TrendingUp className="w-4 h-4" />
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => openPromotionDialog(user, 'demotion')}
                      title="Demote Employee"
                    >
                      <TrendingDown className="w-4 h-4" />
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => openPasswordDialog(userId)}
                      title="Change Password"
                    >
                      <Key className="w-4 h-4" />
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => openEditDialog(user)}
                    >
                      <Edit className="w-4 h-4" />
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleDelete(userId)}
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </CardContent>

      {/* Password Change Dialog */}
      <Dialog open={passwordDialogOpen} onOpenChange={setPasswordDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Change User Password</DialogTitle>
          </DialogHeader>
          <form onSubmit={handlePasswordChange} className="space-y-4">
            <div>
              <Label htmlFor="newPassword">New Password</Label>
              <Input
                id="newPassword"
                type="password"
                value={passwordData.newPassword}
                onChange={(e) => setPasswordData({ ...passwordData, newPassword: e.target.value })}
                required
                minLength={6}
                placeholder="Minimum 6 characters"
              />
            </div>
            <div>
              <Label htmlFor="confirmPassword">Confirm Password</Label>
              <Input
                id="confirmPassword"
                type="password"
                value={passwordData.confirmPassword}
                onChange={(e) => setPasswordData({ ...passwordData, confirmPassword: e.target.value })}
                required
                minLength={6}
                placeholder="Re-enter password"
              />
            </div>
            <div className="flex justify-end gap-2">
              <Button
                type="button"
                variant="outline"
                onClick={() => {
                  setPasswordDialogOpen(false);
                  setPasswordData({ newPassword: '', confirmPassword: '' });
                }}
              >
                Cancel
              </Button>
              <Button type="submit">Update Password</Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>

      {/* Transfer Employee Dialog */}
      <Dialog open={transferDialogOpen} onOpenChange={setTransferDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Transfer Employee</DialogTitle>
          </DialogHeader>
          {selectedUser && (
            <div className="mb-4 p-3 bg-muted rounded-lg">
              <p className="font-semibold">{selectedUser.name}</p>
              <p className="text-sm text-muted-foreground">
                Current: {selectedUser.department?.name || 'No Department'}
              </p>
            </div>
          )}
          <form onSubmit={handleTransfer} className="space-y-4">
            <div>
              <Label htmlFor="transferDepartment">New Department</Label>
              <Select
                value={transferData.departmentId}
                onValueChange={(value) => {
                  setTransferData({ ...transferData, departmentId: value, subDepartmentId: '' });
                }}
                required
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select department" />
                </SelectTrigger>
                <SelectContent>
                  {departments.map((dept) => (
                    <SelectItem key={dept.id || dept.id} value={(dept.id || dept.id)!}>
                      {dept.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            {transferData.departmentId && subDepartments.length > 0 && (
              <div>
                <Label htmlFor="transferSubDepartment">Sub-Department</Label>
                <Select
                  value={transferData.subDepartmentId}
                  onValueChange={(value) => setTransferData({ ...transferData, subDepartmentId: value })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select sub-department (optional)" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">No Sub-Department</SelectItem>
                    {subDepartments.map((subDept) => (
                      <SelectItem key={subDept.id || subDept.id} value={(subDept.id || subDept.id)!}>
                        {subDept.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}
            <div>
              <Label htmlFor="transferReason">Reason for Transfer</Label>
              <Input
                id="transferReason"
                value={transferData.reason}
                onChange={(e) => setTransferData({ ...transferData, reason: e.target.value })}
                placeholder="Optional"
              />
            </div>
            <div className="flex justify-end gap-2">
              <Button
                type="button"
                variant="outline"
                onClick={() => {
                  setTransferDialogOpen(false);
                  setTransferData({ departmentId: '', subDepartmentId: '', reason: '' });
                }}
              >
                Cancel
              </Button>
              <Button type="submit">Transfer Employee</Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>

      {/* Promotion/Demotion Dialog */}
      <Dialog open={promotionDialogOpen} onOpenChange={setPromotionDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              {promotionData.type === 'promotion' ? 'Promote' : 'Demote'} Employee
            </DialogTitle>
          </DialogHeader>
          {selectedUser && (
            <div className="mb-4 p-3 bg-muted rounded-lg">
              <p className="font-semibold">{selectedUser.name}</p>
              <p className="text-sm text-muted-foreground">
                Current: {selectedUser.designation || 'No Designation'} ({selectedUser.role})
              </p>
            </div>
          )}
          <form onSubmit={handlePromotionDemotion} className="space-y-4">
            <div>
              <Label htmlFor="newDesignation">New Designation</Label>
              {designations.length > 0 ? (
                <Select
                  value={promotionData.newDesignation}
                  onValueChange={(value) => setPromotionData({ ...promotionData, newDesignation: value })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select from org chart..." />
                  </SelectTrigger>
                  <SelectContent>
                    {designations.map(d => {
                      const filled = d.filledBy?.length || 0;
                      const vacant = d.maxHeadcount - filled;
                      return (
                        <SelectItem key={d.id} value={d.title}>
                          {d.title}
                          {d.departmentId ? ` — ${d.departmentId.name}` : ''}
                          {vacant <= 0 ? ' (Full)' : ` (${vacant} open)`}
                        </SelectItem>
                      );
                    })}
                  </SelectContent>
                </Select>
              ) : (
                <Input
                  id="newDesignation"
                  value={promotionData.newDesignation}
                  onChange={(e) => setPromotionData({ ...promotionData, newDesignation: e.target.value })}
                  required
                  placeholder="e.g., Senior Manager, Team Lead"
                />
              )}
            </div>
            <div>
              <Label htmlFor="newRole">New Role</Label>
              <Select
                value={promotionData.newRole}
                onValueChange={(value) => setPromotionData({ ...promotionData, newRole: value })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="employee">Employee</SelectItem>
                  <SelectItem value="staff">Staff</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label htmlFor="newReportingTo">Reports To</Label>
              <Select
                value={promotionData.reportingTo}
                onValueChange={(value) => setPromotionData({ ...promotionData, reportingTo: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select reporting manager (optional)" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">No Manager</SelectItem>
                  {users.filter(u => (u.id || u.id) !== (selectedUser?.id || selectedUser?.id)).map((user) => (
                    <SelectItem key={user.id || user.id} value={(user.id || user.id)!}>
                      {user.name} {user.designation ? `(${user.designation})` : ''}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="flex justify-end gap-2">
              <Button
                type="button"
                variant="outline"
                onClick={() => {
                  setPromotionDialogOpen(false);
                  setPromotionData({ newDesignation: '', newRole: 'employee', reportingTo: '', type: 'promotion' });
                }}
              >
                Cancel
              </Button>
              <Button type="submit">
                {promotionData.type === 'promotion' ? 'Promote' : 'Demote'} Employee
              </Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>
    </Card>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Edit, Trash2 } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import api from '@/lib/api';
import { useAuth } from '@/hooks/useAuth';
import { toast } from 'sonner';

export function HolidaysPanel() {
  const { user } = useAuth();
  const canManage = ['hr_admin', 'org_admin', 'superadmin'].includes(user?.role || '');
  const [holidays, setHolidays] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({ name: '', date: '', type: 'national', description: '' });

  useEffect(() => { fetchHolidays(); }, []);

  const fetchHolidays = async () => {
    setLoading(true);
    try {
      const res = await api.get('/hr/holidays');
      setHolidays(res.data.data || []);
    } catch (err) {
      console.error('Failed to fetch holidays:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (editingId) {
        await api.put(`/hr/holidays/${editingId}`, formData);
      } else {
        await api.post('/hr/holidays', formData);
      }
      setDialogOpen(false);
      resetForm();
      fetchHolidays();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to save holiday');
    }
  };

  const handleEdit = (h: any) => {
    setEditingId(h.id || h.id);
    setFormData({
      name: h.name || '',
      date: h.date ? new Date(h.date).toISOString().split('T')[0] : '',
      type: h.type || 'national',
      description: h.description || '',
    });
    setDialogOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this holiday?')) return;
    try {
      await api.delete(`/hr/holidays/${id}`);
      toast.success('Holiday deleted');
      fetchHolidays();
    } catch (err) {
      console.error('Failed to delete holiday:', err);
    }
  };

  const resetForm = () => {
    setEditingId(null);
    setFormData({ name: '', date: '', type: 'national', description: '' });
  };

  const typeColors: any = {
    national: 'bg-blue-100 text-blue-800',
    regional: 'bg-purple-100 text-purple-800',
    company: 'bg-green-100 text-green-800',
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Holiday Calendar</h2>
          <p className="text-muted-foreground">Company holidays and observances</p>
        </div>
        {canManage && (
          <Dialog open={dialogOpen} onOpenChange={(open) => { setDialogOpen(open); if (!open) resetForm(); }}>
            <DialogTrigger asChild>
              <Button><Plus className="w-4 h-4 mr-2" />Add Holiday</Button>
            </DialogTrigger>
            <DialogContent className="max-w-md">
              <DialogHeader>
                <DialogTitle>{editingId ? 'Edit Holiday' : 'Add New Holiday'}</DialogTitle>
              </DialogHeader>
              <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                  <Label>Holiday Name</Label>
                  <Input value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} required />
                </div>
                <div>
                  <Label>Date</Label>
                  <Input type="date" value={formData.date} onChange={(e) => setFormData({ ...formData, date: e.target.value })} required />
                </div>
                <div>
                  <Label>Type</Label>
                  <Select value={formData.type} onValueChange={(v) => setFormData({ ...formData, type: v })}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="national">National</SelectItem>
                      <SelectItem value="regional">Regional</SelectItem>
                      <SelectItem value="company">Company</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label>Description (optional)</Label>
                  <Input value={formData.description} onChange={(e) => setFormData({ ...formData, description: e.target.value })} />
                </div>
                <div className="flex gap-2">
                  <Button type="submit" className="flex-1">Save</Button>
                  <Button type="button" variant="outline" onClick={() => setDialogOpen(false)}>Cancel</Button>
                </div>
              </form>
            </DialogContent>
          </Dialog>
        )}
      </div>

      <Card>
        <CardHeader><CardTitle>Holiday List</CardTitle></CardHeader>
        <CardContent>
          {loading ? (
            <div className="text-center py-8">Loading...</div>
          ) : holidays.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">No holidays found</div>
          ) : (
            <div className="space-y-2">
              {holidays.filter(h => h && (h.id || h.id)).map((h) => {
                const hid = h.id || h.id;
                const d = new Date(h.date);
                const isUpcoming = d >= new Date();
                return (
                  <div key={hid} className="flex items-center justify-between p-4 border rounded-lg hover:bg-muted/50">
                    <div className="flex items-center gap-4">
                      <div className={`flex flex-col items-center justify-center w-14 h-14 rounded-lg ${isUpcoming ? 'bg-primary/10' : 'bg-muted'}`}>
                        <div className="text-xl font-bold">{d.getDate()}</div>
                        <div className="text-xs text-muted-foreground uppercase">{d.toLocaleDateString('en-US', { month: 'short' })}</div>
                      </div>
                      <div>
                        <div className={`font-medium ${!isUpcoming ? 'text-muted-foreground' : ''}`}>{h.name}</div>
                        <div className="text-sm text-muted-foreground">{d.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</div>
                        {h.description && <div className="text-xs text-muted-foreground">{h.description}</div>}
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <Badge className={typeColors[h.type] || ''}>{h.type}</Badge>
                      {canManage && (
                        <>
                          <Button variant="ghost" size="sm" onClick={() => handleEdit(h)}><Edit className="w-4 h-4" /></Button>
                          <Button variant="ghost" size="sm" onClick={() => handleDelete(hid)}><Trash2 className="w-4 h-4" /></Button>
                        </>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { RefreshCw, TrendingUp, TrendingDown, ArrowUpRight, ArrowDownRight } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import {
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, CartesianGrid,
  Tooltip, Legend, LineChart, Line,
} from 'recharts';
import { cn } from '@/lib/utils';
import api from '@/lib/api';
import { toast } from 'sonner';

interface MonthlyRow {
  month: string;
  income: { invoices: number; enrollments: number; payments: number; total: number };
  expenditure: { expenses: number; salaries: number; total: number };
  net: number;
}

interface ReportData {
  period: { from: string; to: string };
  monthly: MonthlyRow[];
  totals: { income: number; expenditure: number; netProfit: number; profitMargin: number };
  incomeBreakdown: { invoices: number; enrollments: number; payments: number };
  expenditureBreakdown: { salaries: number; expenses: number; byCategory: { id: string; amount: number; count: number }[] };
}

const fmt = (n: number) =>
  n >= 100000 ? `₹${(n / 100000).toFixed(1)}L` :
  n >= 1000 ? `₹${(n / 1000).toFixed(1)}K` : `₹${n.toLocaleString()}`;

const fmtMonth = (m: string) => {
  const [y, mo] = m.split('-');
  return new Date(+y, +mo - 1).toLocaleString('default', { month: 'short', year: '2-digit' });
};

export function IncomeExpenditurePanel() {
  const [data, setData] = useState<ReportData | null>(null);
  const [loading, setLoading] = useState(false);
  const [from, setFrom] = useState(() => {
    const now = new Date();
    const yr = now.getMonth() >= 3 ? now.getFullYear() : now.getFullYear() - 1;
    return `${yr}-04-01`;
  });
  const [to, setTo] = useState(() => {
    const now = new Date();
    return now.toISOString().slice(0, 10);
  });

  const fetchReport = async () => {
    setLoading(true);
    try {
      const res = await api.get(`/finance/reports/income-expenditure?from=${from}&to=${to}`);
      setData(res.data.data);
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to load report');
    } finally {
      setLoading(false);
    }
  };

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { fetchReport(); }, []);

  const chartData = data?.monthly.map(m => ({
    name: fmtMonth(m.month),
    Income: m.income.total,
    Expenditure: m.expenditure.total,
    Net: m.net,
  })) || [];

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h2 className="text-2xl font-bold">Income & Expenditure</h2>
          <p className="text-muted-foreground text-sm mt-1">Monthly breakdown of all income and expenditure.</p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <input type="date" value={from} onChange={e => setFrom(e.target.value)}
            className="h-8 px-2 text-sm rounded-lg border border-border bg-background" />
          <span className="text-muted-foreground text-sm">to</span>
          <input type="date" value={to} onChange={e => setTo(e.target.value)}
            className="h-8 px-2 text-sm rounded-lg border border-border bg-background" />
          <Button size="sm" onClick={fetchReport} disabled={loading}>
            <RefreshCw className={cn('w-4 h-4 mr-2', loading && 'animate-spin')} />Apply
          </Button>
        </div>
      </div>

      {/* Summary Cards */}
      {data && (
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <SummaryCard
            label="Total Income"
            value={fmt(data.totals.income)}
            icon={<TrendingUp className="w-5 h-5" />}
            color="text-green-600 bg-green-50 dark:bg-green-900/20"
            sub={`${data.monthly.length} months`}
          />
          <SummaryCard
            label="Total Expenditure"
            value={fmt(data.totals.expenditure)}
            icon={<TrendingDown className="w-5 h-5" />}
            color="text-red-500 bg-red-50 dark:bg-red-900/20"
            sub="Salaries + Expenses"
          />
          <SummaryCard
            label="Net Surplus / Deficit"
            value={fmt(Math.abs(data.totals.netProfit))}
            icon={data.totals.netProfit >= 0 ? <ArrowUpRight className="w-5 h-5" /> : <ArrowDownRight className="w-5 h-5" />}
            color={data.totals.netProfit >= 0 ? 'text-green-600 bg-green-50 dark:bg-green-900/20' : 'text-red-500 bg-red-50 dark:bg-red-900/20'}
            sub={`${data.totals.profitMargin}% margin`}
          />
        </div>
      )}

      {/* Bar Chart */}
      <Card>
        <CardHeader>
          <CardTitle>Monthly Income vs Expenditure</CardTitle>
          <CardDescription>Side-by-side comparison per month</CardDescription>
        </CardHeader>
        <CardContent className="h-72">
          {loading ? (
            <div className="h-full flex items-center justify-center">
              <RefreshCw className="w-6 h-6 animate-spin text-muted-foreground" />
            </div>
          ) : chartData.length === 0 ? (
            <div className="h-full flex items-center justify-center text-muted-foreground text-sm">No data for selected period</div>
          ) : (
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} margin={{ top: 5, right: 20, left: 0, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="hsl(var(--border))" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: 'hsl(var(--muted-foreground))', fontSize: 11 }} />
                <YAxis axisLine={false} tickLine={false} tick={{ fill: 'hsl(var(--muted-foreground))', fontSize: 11 }} tickFormatter={v => fmt(v)} />
                <Tooltip
                  contentStyle={{ backgroundColor: 'hsl(var(--card))', border: '1px solid hsl(var(--border))', borderRadius: '10px', fontSize: 12 }}
                  formatter={(v: number) => fmt(v)}
                />
                <Legend />
                <Bar dataKey="Income" fill="hsl(var(--success))" radius={[4, 4, 0, 0]} barSize={20} />
                <Bar dataKey="Expenditure" fill="hsl(var(--destructive))" radius={[4, 4, 0, 0]} barSize={20} />
              </BarChart>
            </ResponsiveContainer>
          )}
        </CardContent>
      </Card>

      {/* Net trend line */}
      <Card>
        <CardHeader>
          <CardTitle>Net Surplus / Deficit Trend</CardTitle>
          <CardDescription>Monthly net position (income minus expenditure)</CardDescription>
        </CardHeader>
        <CardContent className="h-52">
          {chartData.length > 0 && (
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={chartData} margin={{ top: 5, right: 20, left: 0, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="hsl(var(--border))" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: 'hsl(var(--muted-foreground))', fontSize: 11 }} />
                <YAxis axisLine={false} tickLine={false} tick={{ fill: 'hsl(var(--muted-foreground))', fontSize: 11 }} tickFormatter={v => fmt(v)} />
                <Tooltip
                  contentStyle={{ backgroundColor: 'hsl(var(--card))', border: '1px solid hsl(var(--border))', borderRadius: '10px', fontSize: 12 }}
                  formatter={(v: number) => fmt(v)}
                />
                <Line type="monotone" dataKey="Net" stroke="hsl(var(--primary))" strokeWidth={2} dot={{ r: 4 }} />
              </LineChart>
            </ResponsiveContainer>
          )}
        </CardContent>
      </Card>

      {/* Monthly Table */}
      {data && data.monthly.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>Monthly Statement</CardTitle>
          </CardHeader>
          <CardContent className="p-0">
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead className="bg-muted/50 border-b border-border">
                  <tr>
                    <th className="text-left p-3 font-medium text-muted-foreground">Month</th>
                    <th className="text-right p-3 font-medium text-muted-foreground">Invoices</th>
                    <th className="text-right p-3 font-medium text-muted-foreground">Enrollments</th>
                    <th className="text-right p-3 font-medium text-muted-foreground">Total Income</th>
                    <th className="text-right p-3 font-medium text-muted-foreground">Salaries</th>
                    <th className="text-right p-3 font-medium text-muted-foreground">Expenses</th>
                    <th className="text-right p-3 font-medium text-muted-foreground">Total Exp.</th>
                    <th className="text-right p-3 font-medium text-muted-foreground">Net</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {data.monthly.map(row => (
                    <tr key={row.month} className="hover:bg-muted/30 transition-colors">
                      <td className="p-3 font-medium">{fmtMonth(row.month)}</td>
                      <td className="p-3 text-right text-muted-foreground">{fmt(row.income.invoices)}</td>
                      <td className="p-3 text-right text-muted-foreground">{fmt(row.income.enrollments)}</td>
                      <td className="p-3 text-right font-semibold text-green-600">{fmt(row.income.total)}</td>
                      <td className="p-3 text-right text-muted-foreground">{fmt(row.expenditure.salaries)}</td>
                      <td className="p-3 text-right text-muted-foreground">{fmt(row.expenditure.expenses)}</td>
                      <td className="p-3 text-right font-semibold text-red-500">{fmt(row.expenditure.total)}</td>
                      <td className={cn('p-3 text-right font-bold', row.net >= 0 ? 'text-green-600' : 'text-red-500')}>
                        {row.net >= 0 ? '+' : ''}{fmt(row.net)}
                      </td>
                    </tr>
                  ))}
                </tbody>
                <tfoot className="border-t-2 border-border bg-muted/30">
                  <tr>
                    <td className="p-3 font-bold">Total</td>
                    <td className="p-3 text-right font-bold">{fmt(data.incomeBreakdown.invoices)}</td>
                    <td className="p-3 text-right font-bold">{fmt(data.incomeBreakdown.enrollments)}</td>
                    <td className="p-3 text-right font-bold text-green-600">{fmt(data.totals.income)}</td>
                    <td className="p-3 text-right font-bold">{fmt(data.expenditureBreakdown.salaries)}</td>
                    <td className="p-3 text-right font-bold">{fmt(data.expenditureBreakdown.expenses)}</td>
                    <td className="p-3 text-right font-bold text-red-500">{fmt(data.totals.expenditure)}</td>
                    <td className={cn('p-3 text-right font-bold text-lg', data.totals.netProfit >= 0 ? 'text-green-600' : 'text-red-500')}>
                      {data.totals.netProfit >= 0 ? '+' : ''}{fmt(data.totals.netProfit)}
                    </td>
                  </tr>
                </tfoot>
              </table>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Income & Expenditure Breakdown */}
      {data && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <Card>
            <CardHeader><CardTitle className="text-base">Income Sources</CardTitle></CardHeader>
            <CardContent className="space-y-3">
              <BreakdownRow label="Invoices" amount={data.incomeBreakdown.invoices} total={data.totals.income} color="bg-green-500" />
              <BreakdownRow label="Enrollment Fees" amount={data.incomeBreakdown.enrollments} total={data.totals.income} color="bg-emerald-400" />
              <BreakdownRow label="Payment Entries" amount={data.incomeBreakdown.payments} total={data.totals.income} color="bg-teal-400" />
            </CardContent>
          </Card>
          <Card>
            <CardHeader><CardTitle className="text-base">Expenditure Breakdown</CardTitle></CardHeader>
            <CardContent className="space-y-3">
              <BreakdownRow label="Salaries (Payroll)" amount={data.expenditureBreakdown.salaries} total={data.totals.expenditure} color="bg-red-500" />
              <BreakdownRow label="Expense Claims" amount={data.expenditureBreakdown.expenses} total={data.totals.expenditure} color="bg-orange-400" />
              {data.expenditureBreakdown.byCategory.slice(0, 4).map(c => (
                <BreakdownRow key={c.id} label={`  └ ${c.id}`} amount={c.amount} total={data.expenditureBreakdown.expenses} color="bg-orange-200" />
              ))}
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  );
}

function SummaryCard({ label, value, icon, color, sub }: any) {
  return (
    <Card>
      <CardContent className="p-5 flex items-center gap-4">
        <div className={cn('p-3 rounded-xl', color)}>{icon}</div>
        <div>
          <p className="text-xs text-muted-foreground uppercase tracking-wider">{label}</p>
          <p className="text-2xl font-bold">{value}</p>
          <p className="text-xs text-muted-foreground">{sub}</p>
        </div>
      </CardContent>
    </Card>
  );
}

function BreakdownRow({ label, amount, total, color }: { label: string; amount: number; total: number; color: string }) {
  const pct = total > 0 ? Math.round((amount / total) * 100) : 0;
  return (
    <div className="space-y-1">
      <div className="flex justify-between text-sm">
        <span className="text-muted-foreground">{label}</span>
        <span className="font-semibold">{fmt(amount)} <span className="text-muted-foreground font-normal text-xs">({pct}%)</span></span>
      </div>
      <div className="h-1.5 bg-muted rounded-full overflow-hidden">
        <div className={cn('h-full rounded-full', color)} style={{ width: `${pct}%` }} />
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Edit, Trash2, FileText, Eye } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { toast } from 'sonner';
import api from '@/lib/api';
import { useAuth } from '@/hooks/useAuth';

export function InternalMarksPanel() {
  const { user } = useAuth();
  const isCenterAdmin = user?.role === 'center_admin';
  const isReadOnly = !isCenterAdmin; // ops_admin and others are read-only

  const [marks, setMarks] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    studentId: '',
    subjectName: '',
    marks: '',
    maxMarks: '100',
    examType: 'internal'
  });

  useEffect(() => {
    fetchMarks();
    fetchStudents();
  }, []);

  const fetchMarks = async () => {
    setLoading(true);
    try {
      const res = await api.get('/operations/marks');
      setMarks(res.data.data || []);
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to fetch marks');
    } finally {
      setLoading(false);
    }
  };

  const fetchStudents = async () => {
    try {
      const res = await api.get('/students');
      setStudents(res.data.data || []);
    } catch {
      // non-critical
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const studentId = formData.studentId;
    const payload = {
      studentId,
      subjectId: studentId,
      subjectName: formData.subjectName,
      marks: Number(formData.marks),
      maxMarks: Number(formData.maxMarks),
      examType: formData.examType
    };
    try {
      if (editingId) {
        await api.put(`/operations/marks/${editingId}`, payload);
        toast.success('Marks updated');
      } else {
        await api.post('/operations/marks', payload);
        toast.success('Marks added');
      }
      setDialogOpen(false);
      resetForm();
      fetchMarks();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to save marks');
    }
  };

  const handleEdit = (m: any) => {
    const studentId = typeof m.studentId === 'object'
      ? (m.studentId?.id || m.studentId?.id)
      : m.studentId;
    setEditingId(m.id || m.id);
    setFormData({
      studentId: studentId?.toString() || '',
      subjectName: m.subjectName || '',
      marks: m.marks?.toString() || '',
      maxMarks: m.maxMarks?.toString() || '100',
      examType: m.examType || 'internal'
    });
    setDialogOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this marks record?')) return;
    try {
      await api.delete(`/operations/marks/${id}`);
      toast.success('Marks deleted');
      fetchMarks();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to delete');
    }
  };

  const resetForm = () => {
    setEditingId(null);
    setFormData({ studentId: '', subjectName: '', marks: '', maxMarks: '100', examType: 'internal' });
  };

  const getGradeBadge = (marks: number, maxMarks: number) => {
    const pct = (marks / maxMarks) * 100;
    if (pct >= 90) return <Badge className="bg-success/10 text-success text-[10px]">A+</Badge>;
    if (pct >= 75) return <Badge className="bg-primary/10 text-primary text-[10px]">A</Badge>;
    if (pct >= 60) return <Badge className="bg-info/10 text-info text-[10px]">B</Badge>;
    if (pct >= 45) return <Badge className="bg-warning/10 text-warning text-[10px]">C</Badge>;
    return <Badge className="bg-error/10 text-error text-[10px]">F</Badge>;
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Internal Marks</h2>
          <p className="text-muted-foreground text-sm mt-1">
            {isReadOnly
              ? 'View student assessment marks entered by study centers'
              : 'Enter and manage student internal assessment marks'}
          </p>
        </div>
        {!isReadOnly && (
          <Dialog open={dialogOpen} onOpenChange={(open) => { setDialogOpen(open); if (!open) resetForm(); }}>
            <DialogTrigger asChild>
              <Button><Plus className="w-4 h-4 mr-2" />Add Marks</Button>
            </DialogTrigger>
            <DialogContent className="max-w-lg">
              <DialogHeader>
                <DialogTitle>{editingId ? 'Edit Marks' : 'Add Marks'}</DialogTitle>
              </DialogHeader>
              <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                  <Label>Student</Label>
                  <Select value={formData.studentId} onValueChange={(v) => setFormData({ ...formData, studentId: v })}>
                    <SelectTrigger><SelectValue placeholder="Select student" /></SelectTrigger>
                    <SelectContent>
                      {students.filter(s => s && (s.id || s.id)).map((s) => (
                        <SelectItem key={s.id || s.id} value={(s.id || s.id).toString()}>
                          {s.name}{s.enrollmentNo ? ` (${s.enrollmentNo})` : ''}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label>Subject Name</Label>
                  <Input value={formData.subjectName} onChange={(e) => setFormData({ ...formData, subjectName: e.target.value })} required />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <Label>Marks Obtained</Label>
                    <Input type="number" min="0" value={formData.marks} onChange={(e) => setFormData({ ...formData, marks: e.target.value })} required />
                  </div>
                  <div>
                    <Label>Maximum Marks</Label>
                    <Input type="number" min="1" value={formData.maxMarks} onChange={(e) => setFormData({ ...formData, maxMarks: e.target.value })} required />
                  </div>
                </div>
                <div>
                  <Label>Exam Type</Label>
                  <Select value={formData.examType} onValueChange={(v) => setFormData({ ...formData, examType: v })}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="internal">Internal</SelectItem>
                      <SelectItem value="practical">Practical</SelectItem>
                      <SelectItem value="assignment">Assignment</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="flex gap-2">
                  <Button type="submit" className="flex-1">Save</Button>
                  <Button type="button" variant="outline" onClick={() => setDialogOpen(false)}>Cancel</Button>
                </div>
              </form>
            </DialogContent>
          </Dialog>
        )}
        {isReadOnly && (
          <Badge variant="outline" className="flex items-center gap-1.5 px-3 py-1.5">
            <Eye className="w-3.5 h-3.5" />
            Read Only
          </Badge>
        )}
      </div>

      {/* Summary stats */}
      {marks.length > 0 && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {[
            { label: 'Total Records', value: marks.length },
            { label: 'Students', value: new Set(marks.map(m => typeof m.studentId === 'object' ? m.studentId?.id : m.studentId)).size },
            { label: 'Avg Score', value: `${Math.round(marks.reduce((s, m) => s + (m.maxMarks ? (m.marks / m.maxMarks) * 100 : 0), 0) / marks.length)}%` },
            { label: 'Subjects', value: new Set(marks.map(m => m.subjectName)).size },
          ].map(stat => (
            <Card key={stat.label}>
              <CardContent className="p-4">
                <p className="text-xs text-muted-foreground uppercase tracking-widest">{stat.label}</p>
                <p className="text-2xl font-bold mt-1">{stat.value}</p>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      <Card>
        <CardHeader>
          <CardTitle>Marks Records</CardTitle>
          <CardDescription>
            {isReadOnly ? 'Submitted by study centers' : 'Your entered marks'}
          </CardDescription>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="space-y-3">{[1,2,3].map(i => <div key={i} className="h-16 bg-muted rounded-lg animate-pulse" />)}</div>
          ) : marks.length === 0 ? (
            <div className="text-center py-12 text-muted-foreground">
              <FileText className="w-10 h-10 mx-auto mb-3 opacity-30" />
              <p className="text-sm">No marks records found</p>
              {!isReadOnly && <p className="text-xs mt-1">Click "Add Marks" to enter student marks</p>}
            </div>
          ) : (
            <div className="space-y-2">
              {marks.filter(m => m && (m.id || m.id)).map((m) => {
                const mid = m.id || m.id;
                const studentName = typeof m.studentId === 'object' ? m.studentId?.name : 'Unknown Student';
                const enrollNo = typeof m.studentId === 'object' ? m.studentId?.enrollmentNo : null;
                const centerName = typeof m.studyCenterId === 'object' ? m.studyCenterId?.name : null;
                const pct = m.maxMarks ? ((m.marks / m.maxMarks) * 100).toFixed(1) : 0;
                return (
                  <div key={mid} className="flex items-center justify-between p-4 border rounded-lg hover:bg-muted/50 transition-colors">
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
                        <FileText className="w-5 h-5 text-primary" />
                      </div>
                      <div>
                        <div className="font-medium text-sm">
                          {studentName}
                          {enrollNo && <span className="text-muted-foreground text-xs ml-2">({enrollNo})</span>}
                        </div>
                        <div className="text-xs text-muted-foreground mt-0.5">
                          {m.subjectName || 'N/A'} • <span className="capitalize">{m.examType}</span> • {m.marks}/{m.maxMarks} ({pct}%)
                          {centerName && <span className="ml-2 text-primary/70">• {centerName}</span>}
                        </div>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      {getGradeBadge(m.marks, m.maxMarks)}
                      {!isReadOnly && (
                        <>
                          <Button variant="ghost" size="sm" onClick={() => handleEdit(m)}>
                            <Edit className="w-4 h-4" />
                          </Button>
                          <Button variant="ghost" size="sm" className="text-destructive hover:text-destructive" onClick={() => handleDelete(mid)}>
                            <Trash2 className="w-4 h-4" />
                          </Button>
                        </>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Edit, Trash2, FileText } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import api from '@/lib/api';

export function InvoicesPanel() {
  const [invoices, setInvoices] = useState<any[]>([]);
  const [centers, setCenters] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    centerId: '',
    invoiceNo: '',
    itemDescription: '',
    itemQty: '1',
    itemRate: '',
    tax: '0',
    dueDate: '',
    status: 'draft'
  });

  useEffect(() => {
    fetchInvoices();
    fetchCenters();
  }, []);

  const fetchInvoices = async () => {
    setLoading(true);
    try {
      const res = await api.get('/finance/invoices');
      setInvoices(res.data.data || []);
    } catch (err) {
      console.error('Failed to fetch invoices:', err);
    } finally {
      setLoading(false);
    }
  };

  const fetchCenters = async () => {
    try {
      const res = await api.get('/operations/centers');
      setCenters(res.data.data || []);
    } catch (err) {
      console.error('Failed to fetch centers:', err);
    }
  };

  const calcTotal = () => {
    const qty = Number(formData.itemQty) || 0;
    const rate = Number(formData.itemRate) || 0;
    const tax = Number(formData.tax) || 0;
    const amount = qty * rate;
    return { amount, total: amount + tax };
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const { amount, total } = calcTotal();
    const payload: any = {
      centerId: formData.centerId,
      invoiceNo: formData.invoiceNo,
      items: [{
        description: formData.itemDescription,
        quantity: Number(formData.itemQty),
        rate: Number(formData.itemRate),
        amount
      }],
      amount,
      tax: Number(formData.tax),
      total,
      status: formData.status
    };
    if (formData.dueDate) payload.dueDate = formData.dueDate;

    try {
      if (editingId) {
        await api.put(`/finance/invoices/${editingId}`, payload);
      } else {
        await api.post('/finance/invoices', payload);
      }
      setDialogOpen(false);
      resetForm();
      fetchInvoices();
    } catch (err: any) {
      alert(err.response?.data?.message || 'Failed to save invoice');
    }
  };

  const handleEdit = (inv: any) => {
    const centerId = inv.center?.id || (typeof inv.centerId === 'object'
      ? (inv.centerId?.id || inv.centerId?.id)
      : inv.centerId);
    const firstItem = inv.items?.[0] || {};
    setEditingId(inv.id || inv.id);
    setFormData({
      centerId: centerId?.toString() || '',
      invoiceNo: inv.invoiceNo || '',
      itemDescription: firstItem.description || '',
      itemQty: firstItem.quantity?.toString() || '1',
      itemRate: firstItem.rate?.toString() || '',
      tax: inv.tax?.toString() || '0',
      dueDate: inv.dueDate ? new Date(inv.dueDate).toISOString().split('T')[0] : '',
      status: inv.status || 'draft'
    });
    setDialogOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this invoice?')) return;
    const remarks = prompt('Enter deletion remarks (required for audit):');
    if (!remarks) return;
    try {
      await api.delete(`/finance/invoices/${id}`, { data: { remarks } });
      fetchInvoices();
    } catch (err) {
      console.error('Failed to delete invoice:', err);
    }
  };

  const resetForm = () => {
    setEditingId(null);
    setFormData({ centerId: '', invoiceNo: '', itemDescription: '', itemQty: '1', itemRate: '', tax: '0', dueDate: '', status: 'draft' });
  };

  const { total } = calcTotal();

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Invoice Management</h2>
          <p className="text-muted-foreground">Manage invoices and billing</p>
        </div>
        <Dialog open={dialogOpen} onOpenChange={(open) => { setDialogOpen(open); if (!open) resetForm(); }}>
          <DialogTrigger asChild>
            <Button><Plus className="w-4 h-4 mr-2" />Add Invoice</Button>
          </DialogTrigger>
          <DialogContent className="max-w-lg">
            <DialogHeader>
              <DialogTitle>{editingId ? 'Edit Invoice' : 'Add New Invoice'}</DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <Label>Study Center</Label>
                <Select value={formData.centerId} onValueChange={(v) => setFormData({ ...formData, centerId: v })}>
                  <SelectTrigger><SelectValue placeholder="Select center" /></SelectTrigger>
                  <SelectContent>
                    {centers.filter(c => c && (c.id || c.id)).map((c) => (
                      <SelectItem key={c.id || c.id} value={(c.id || c.id).toString()}>
                        {c.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label>Invoice No</Label>
                <Input value={formData.invoiceNo} onChange={(e) => setFormData({ ...formData, invoiceNo: e.target.value })} required placeholder="e.g. INV-001" />
              </div>
              <div>
                <Label>Item Description</Label>
                <Input value={formData.itemDescription} onChange={(e) => setFormData({ ...formData, itemDescription: e.target.value })} required />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Quantity</Label>
                  <Input type="number" min="1" value={formData.itemQty} onChange={(e) => setFormData({ ...formData, itemQty: e.target.value })} required />
                </div>
                <div>
                  <Label>Rate</Label>
                  <Input type="number" min="0" value={formData.itemRate} onChange={(e) => setFormData({ ...formData, itemRate: e.target.value })} required />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Tax</Label>
                  <Input type="number" min="0" value={formData.tax} onChange={(e) => setFormData({ ...formData, tax: e.target.value })} />
                </div>
                <div>
                  <Label>Total (auto)</Label>
                  <Input value={total.toFixed(2)} readOnly className="bg-muted" />
                </div>
              </div>
              <div>
                <Label>Due Date (optional)</Label>
                <Input type="date" value={formData.dueDate} onChange={(e) => setFormData({ ...formData, dueDate: e.target.value })} />
              </div>
              <div>
                <Label>Status</Label>
                <Select value={formData.status} onValueChange={(v) => setFormData({ ...formData, status: v })}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="draft">Draft</SelectItem>
                    <SelectItem value="sent">Sent</SelectItem>
                    <SelectItem value="paid">Paid</SelectItem>
                    <SelectItem value="overdue">Overdue</SelectItem>
                    <SelectItem value="cancelled">Cancelled</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="flex gap-2">
                <Button type="submit" className="flex-1">Save</Button>
                <Button type="button" variant="outline" onClick={() => setDialogOpen(false)}>Cancel</Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      <Card>
        <CardHeader><CardTitle>Invoices</CardTitle></CardHeader>
        <CardContent>
          {loading ? (
            <div className="text-center py-8">Loading...</div>
          ) : invoices.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">No invoices found</div>
          ) : (
            <div className="space-y-2">
              {invoices.filter(inv => inv && (inv.id || inv.id)).map((inv) => {
                const invId = inv.id || inv.id;
                const centerName = inv.center?.name || (typeof inv.centerId === 'object' ? inv.centerId?.name : '');
                return (
                  <div key={invId} className="flex items-center justify-between p-4 border rounded-lg hover:bg-muted/50">
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center">
                        <FileText className="w-5 h-5 text-primary" />
                      </div>
                      <div>
                        <div className="font-medium">{inv.invoiceNo}</div>
                        <div className="text-sm text-muted-foreground">
                          {centerName && `${centerName} • `}Total: ₹{inv.total}
                          {inv.dueDate && ` • Due: ${new Date(inv.dueDate).toLocaleDateString()}`}
                        </div>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <Badge>{inv.status}</Badge>
                      <Button variant="ghost" size="sm" onClick={() => handleEdit(inv)}><Edit className="w-4 h-4" /></Button>
                      <Button variant="ghost" size="sm" onClick={() => handleDelete(invId)}><Trash2 className="w-4 h-4" /></Button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Edit, Trash2, Users, CheckCircle, Link2, Copy, Building2 } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
