      centerName: '',
      contactName: '',
      email: '',
      phone: '',
      address: '',
      source: 'website',
      status: 'new',
      notes: ''
    });
  };

  const getStatusColor = (status: string) => {
    const colors: any = {
      new: 'bg-blue-100 text-blue-800',
      contacted: 'bg-yellow-100 text-yellow-800',
      qualified: 'bg-purple-100 text-purple-800',
