                </div>
              </div>
              <div>
                <Label>Notes</Label>
                <Textarea value={formData.notes} onChange={(e) => setFormData({...formData, notes: e.target.value})} rows={3} />
              </div>
              <div className="flex gap-2">
                <Button type="submit" className="flex-1">Save</Button>
                <Button type="button" variant="outline" onClick={() => setDialogOpen(false)}>Cancel</Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Leads</CardTitle>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="text-center py-8">Loading...</div>
          ) : leads.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">No leads found</div>
          ) : (
            <div className="space-y-2">
              {leads.filter(lead => lead && (lead.id || lead.id)).map((lead) => {
                const leadId = lead.id || lead.id;
                return (
                  <div key={leadId} className="flex items-center justify-between p-4 border rounded-lg hover:bg-muted/50">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-full bg-primary/10 flex items-center justify-center">
                        <Users className="w-6 h-6 text-primary" />
                      </div>
                      <div className="flex-1">
                        <div className="font-medium">{lead.centerName}</div>
                        <div className="text-sm text-muted-foreground">
                          {lead.contactName} • {lead.email} • {lead.phone} • {lead.source}
                        </div>
                        {lead.notes && (
                          <div className="text-xs text-muted-foreground mt-1 line-clamp-1">{lead.notes}</div>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <Badge className={getStatusColor(lead.status)}>{lead.status}</Badge>
                      {lead.status !== 'converted' && lead.status !== 'lost' && (
                        <>
                          <Button 
                            variant="ghost" 
                            size="sm" 
                            onClick={() => openConvertToCenterDialog(lead)} 
                            title="Convert to Study Center"
                          >
                            <Building2 className="w-4 h-4 text-primary" />
                          </Button>
                          <Button 
                            variant="ghost" 
                            size="sm" 
                            onClick={() => handleConvert(leadId)} 
                            title="Convert to Student"
                          >
                            <CheckCircle className="w-4 h-4 text-success" />
                          </Button>
                        </>
                      )}
                      <Button variant="ghost" size="sm" onClick={() => handleEdit(lead)}>
                        <Edit className="w-4 h-4" />
                      </Button>
                      <Button variant="ghost" size="sm" onClick={() => handleDelete(leadId)}>
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Convert to Study Center Dialog */}
      <Dialog open={convertDialogOpen} onOpenChange={setConvertDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Convert Lead to Study Center</DialogTitle>
            <p className="text-sm text-muted-foreground mt-2">
              Create a new study center from this lead
            </p>
          </DialogHeader>
          <form onSubmit={handleConvertToCenter} className="space-y-4">
            <div>
              <Label htmlFor="center-name">Center Name</Label>
              <Input
                id="center-name"
                value={centerFormData.name}
                onChange={(e) => setCenterFormData({ ...centerFormData, name: e.target.value })}
                required
              />
            </div>
            <div>
              <Label htmlFor="center-code">Center Code</Label>
              <Input
                id="center-code"
                value={centerFormData.code}
                onChange={(e) => setCenterFormData({ ...centerFormData, code: e.target.value })}
                required
                placeholder="e.g., CTR001"
              />
            </div>
            <div>
              <Label htmlFor="center-address">Address</Label>
              <Textarea
                id="center-address"
                value={centerFormData.address}
                onChange={(e) => setCenterFormData({ ...centerFormData, address: e.target.value })}
                required
                rows={2}
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label htmlFor="center-contact">Contact</Label>
                <Input
                  id="center-contact"
                  value={centerFormData.contact}
                  onChange={(e) => setCenterFormData({ ...centerFormData, contact: e.target.value })}
                  required
                />
              </div>
              <div>
                <Label htmlFor="center-email">Email</Label>
                <Input
                  id="center-email"
                  type="email"
                  value={centerFormData.email}
                  onChange={(e) => setCenterFormData({ ...centerFormData, email: e.target.value })}
                  required
                />
              </div>
            </div>
            <div className="flex gap-2">
              <Button type="submit" className="flex-1">
                <Building2 className="w-4 h-4 mr-2" />
                Create Study Center
              </Button>
              <Button
                type="button"
                variant="outline"
                onClick={() => setConvertDialogOpen(false)}
              >
                Cancel
              </Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Calendar, Edit, Save, RefreshCw, Plus, Zap } from 'lucide-react';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { toast } from 'sonner';
import api from '@/lib/api';

interface LeaveAllocation {
  id?: string;
  userId: any;
  year: number;
  sickLeave: number;
  casualLeave: number;
  earnedLeave: number;
  complementaryLeave: number;
  usedSick: number;
  usedCasual: number;
  usedEarned: number;
  usedComplementary: number;
}

interface User {
  id: string;
  name: string;
  email: string;
  role: string;
  designation?: string;
}

export function LeaveAllocationPanel() {
  const [allocations, setAllocations] = useState<LeaveAllocation[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [year, setYear] = useState(new Date().getFullYear());
  const [dialogOpen, setDialogOpen] = useState(false);
  const [bulkDialogOpen, setBulkDialogOpen] = useState(false);
  const [editingUserId, setEditingUserId] = useState('');
  const [saving, setSaving] = useState(false);
  const [search, setSearch] = useState('');

  const [form, setForm] = useState({
    sickLeave: 12, casualLeave: 12, earnedLeave: 15, complementaryLeave: 0,
  });
  const [bulkForm, setBulkForm] = useState({
    sickLeave: 12, casualLeave: 12, earnedLeave: 15, complementaryLeave: 0,
  });

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { fetchAll(); }, [year]);

  const fetchAll = async () => {
    setLoading(true);
    try {
      const [allocRes, usersRes] = await Promise.all([
        api.get(`/hr/leave-allocations?year=${year}`),
        api.get('/users'),
      ]);
      setAllocations(allocRes.data.data || []);
      const allUsers: User[] = usersRes.data.data || [];
      setUsers(allUsers.filter(u => !['ceo', 'org_admin', 'superadmin'].includes(u.role)));
    } catch {
      toast.error('Failed to load leave allocations');
    } finally {
      setLoading(false);
    }
  };

  const openEdit = (alloc?: LeaveAllocation, userId?: string) => {
    if (alloc) {
      setEditingUserId(typeof alloc.userId === 'object' ? alloc.userId.id : alloc.userId);
      setForm({
        sickLeave: alloc.sickLeave,
        casualLeave: alloc.casualLeave,
        earnedLeave: alloc.earnedLeave,
        complementaryLeave: alloc.complementaryLeave,
      });
    } else {
      setEditingUserId(userId || '');
      setForm({ sickLeave: 12, casualLeave: 12, earnedLeave: 15, complementaryLeave: 0 });
    }
    setDialogOpen(true);
  };

  const handleSave = async () => {
    if (!editingUserId) { toast.error('Select an employee'); return; }
    setSaving(true);
    try {
      await api.put(`/hr/leave-allocations/${editingUserId}`, { ...form, year });
      toast.success('Leave allocation saved');
      setDialogOpen(false);
      fetchAll();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to save');
    } finally {
      setSaving(false);
    }
  };

  const handleBulkInit = async () => {
    setSaving(true);
    try {
      const res = await api.post('/hr/leave-allocations/bulk-init', { ...bulkForm, year });
      toast.success(res.data.message);
      setBulkDialogOpen(false);
      fetchAll();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to initialize');
    } finally {
      setSaving(false);
    }
  };

  const allocatedUserIds = new Set(allocations.map(a =>
    typeof a.userId === 'object' ? a.userId.id : a.userId
  ));
  const unallocatedUsers = users.filter(u => !allocatedUserIds.has(u.id));

  const filtered = allocations.filter(a => {
    const name = (typeof a.userId === 'object' ? a.userId.name : '') || '';
    return name.toLowerCase().includes(search.toLowerCase());
  });

  const remaining = (total: number, used: number) => Math.max(0, total - used);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h2 className="text-2xl font-bold">Leave Allocations</h2>
          <p className="text-muted-foreground text-sm mt-1">Manage sick, casual, earned & complementary leave per employee</p>
        </div>
        <div className="flex gap-2 flex-wrap">
          <select
            className="border rounded-md px-3 py-1.5 text-sm bg-background"
            value={year}
            onChange={e => setYear(Number(e.target.value))}
          >
            {[2024, 2025, 2026, 2027].map(y => <option key={y} value={y}>{y}</option>)}
          </select>
          <Button variant="outline" size="sm" onClick={fetchAll}>
            <RefreshCw className="w-4 h-4 mr-1" /> Refresh
          </Button>
          <Button variant="outline" size="sm" onClick={() => setBulkDialogOpen(true)}>
            <Zap className="w-4 h-4 mr-1" /> Bulk Init
          </Button>
          <Button size="sm" onClick={() => openEdit()}>
            <Plus className="w-4 h-4 mr-1" /> Add
          </Button>
        </div>
      </div>

      <Input placeholder="Search employee..." value={search} onChange={e => setSearch(e.target.value)} className="max-w-xs" />

      {loading ? (
        <div className="space-y-3">{[1,2,3].map(i => <div key={i} className="h-20 bg-muted rounded-xl animate-pulse" />)}</div>
      ) : filtered.length === 0 ? (
        <Card>
          <CardContent className="py-16 text-center text-muted-foreground">
            <Calendar className="w-10 h-10 mx-auto mb-3 opacity-30" />
            <p>No leave allocations for {year}</p>
            <p className="text-xs mt-1">Use "Bulk Init" to set up all employees at once</p>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-3">
          {filtered.map(alloc => {
            const user = typeof alloc.userId === 'object' ? alloc.userId : null;
            const uid = user?.id || alloc.userId;
            return (
              <Card key={uid} className="hover:border-primary/30 transition-colors">
                <CardContent className="p-4">
                  <div className="flex items-start justify-between gap-4">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 flex-wrap mb-2">
                        <span className="font-semibold">{user?.name || 'Employee'}</span>
                        <Badge variant="outline" className="text-xs capitalize">{user?.role?.replace(/_/g, ' ')}</Badge>
                        {user?.designation && <Badge variant="outline" className="text-xs">{user.designation}</Badge>}
                      </div>
                      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 text-sm">
                        {[
                          { label: 'Sick', total: alloc.sickLeave, used: alloc.usedSick, color: 'text-red-500' },
                          { label: 'Casual', total: alloc.casualLeave, used: alloc.usedCasual, color: 'text-blue-500' },
                          { label: 'Earned', total: alloc.earnedLeave, used: alloc.usedEarned, color: 'text-green-500' },
                          { label: 'Comp.', total: alloc.complementaryLeave, used: alloc.usedComplementary, color: 'text-purple-500' },
                        ].map(({ label, total, used, color }) => (
                          <div key={label}>
                            <p className="text-xs text-muted-foreground">{label}</p>
                            <p className={`font-semibold ${color}`}>{remaining(total, used)}<span className="text-muted-foreground font-normal text-xs">/{total}</span></p>
                          </div>
                        ))}
                      </div>
                    </div>
                    <Button size="sm" variant="outline" onClick={() => openEdit(alloc)}>
                      <Edit className="w-3.5 h-3.5" />
                    </Button>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Edit Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Leave Allocation — {year}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 pt-2">
            {!allocations.find(a => (typeof a.userId === 'object' ? a.userId.id : a.userId) === editingUserId) && (
              <div className="space-y-2">
                <Label>Employee</Label>
                <Select value={editingUserId} onValueChange={setEditingUserId}>
                  <SelectTrigger><SelectValue placeholder="Select employee..." /></SelectTrigger>
                  <SelectContent>
                    {unallocatedUsers.map(u => (
                      <SelectItem key={u.id} value={u.id}>{u.name} — {u.role.replace(/_/g, ' ')}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}
            <div className="grid grid-cols-2 gap-4">
              {([
                { key: 'sickLeave', label: 'Sick Leave (days)' },
                { key: 'casualLeave', label: 'Casual Leave (days)' },
                { key: 'earnedLeave', label: 'Earned Leave (days)' },
                { key: 'complementaryLeave', label: 'Complementary Leave (days)' },
              ] as const).map(({ key, label }) => (
                <div key={key} className="space-y-1">
                  <Label>{label}</Label>
                  <Input type="number" min="0" value={form[key]}
                    onChange={e => setForm(f => ({ ...f, [key]: Number(e.target.value) }))} />
                </div>
              ))}
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDialogOpen(false)}>Cancel</Button>
            <Button onClick={handleSave} disabled={saving}>
              <Save className="w-4 h-4 mr-1" />{saving ? 'Saving...' : 'Save'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Bulk Init Dialog */}
      <Dialog open={bulkDialogOpen} onOpenChange={setBulkDialogOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Bulk Initialize Leave — {year}</DialogTitle>
          </DialogHeader>
          <p className="text-sm text-muted-foreground">Sets default leave balances for all active employees who don't have an allocation yet for {year}.</p>
          <div className="grid grid-cols-2 gap-4 pt-2">
            {([
              { key: 'sickLeave', label: 'Sick Leave' },
              { key: 'casualLeave', label: 'Casual Leave' },
              { key: 'earnedLeave', label: 'Earned Leave' },
              { key: 'complementaryLeave', label: 'Complementary Leave' },
            ] as const).map(({ key, label }) => (
              <div key={key} className="space-y-1">
                <Label>{label}</Label>
                <Input type="number" min="0" value={bulkForm[key]}
                  onChange={e => setBulkForm(f => ({ ...f, [key]: Number(e.target.value) }))} />
              </div>
            ))}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setBulkDialogOpen(false)}>Cancel</Button>
            <Button onClick={handleBulkInit} disabled={saving}>
              <Zap className="w-4 h-4 mr-1" />{saving ? 'Initializing...' : 'Initialize All'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Trash2, CheckCircle, XCircle, Clock, RefreshCw, ChevronDown, ChevronUp } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { cn } from '@/lib/utils';
import { toast } from 'sonner';
import { useAuth } from '@/hooks/useAuth';
import api from '@/lib/api';

interface LeaveRequest {
  id: string;
  employeeId: { id: string; name: string; email: string; designation?: string } | null;
  departmentId?: { id: string; name: string } | null;
  type: string;
  startDate: string;
  endDate: string;
  reason: string;
  status: 'pending' | 'dept_approved' | 'approved' | 'rejected';
  deptAdminRemarks?: string;
  hrRemarks?: string;
  deptApprovedBy?: { name: string } | null;
  hrApprovedBy?: { name: string } | null;
  appliedAt: string;
  createdAt: string;
}

const STATUS_CONFIG: Record<string, { label: string; color: string }> = {
  pending:      { label: 'Pending',          color: 'bg-yellow-500/10 text-yellow-600 border-yellow-500/20' },
  dept_approved:{ label: 'Dept Approved',    color: 'bg-blue-500/10 text-blue-600 border-blue-500/20' },
  approved:     { label: 'Fully Approved',   color: 'bg-green-500/10 text-green-600 border-green-500/20' },
  rejected:     { label: 'Rejected',         color: 'bg-red-500/10 text-red-600 border-red-500/20' },
};

const DEPT_MANAGER_ROLES = ['ops_admin', 'finance_admin', 'sales_admin', 'center_admin', 'ops_sub_admin'];

export function LeavesPanel() {
  const { user } = useAuth();
  const [leaves, setLeaves] = useState<LeaveRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('all');

  // Create dialog
  const [createOpen, setCreateOpen] = useState(false);
  const [form, setForm] = useState({ type: 'sick', startDate: '', endDate: '', reason: '' });
  const [submitting, setSubmitting] = useState(false);

  // Action dialog (approve/reject with remarks)
  const [actionDialog, setActionDialog] = useState(false);
  const [actionLeave, setActionLeave] = useState<LeaveRequest | null>(null);
  const [actionType, setActionType] = useState<'dept' | 'hr'>('dept');
  const [actionMode, setActionMode] = useState<'approve' | 'reject'>('approve');
  const [remarks, setRemarks] = useState('');
  const [actionSubmitting, setActionSubmitting] = useState(false);

  // Delete dialog
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [deleteLeave, setDeleteLeave] = useState<LeaveRequest | null>(null);

  // Expanded card for remarks
  const [expanded, setExpanded] = useState<string | null>(null);

  const role = user?.role || '';
  const userId = user?.id?.toString() || '';
  const isBranchManager = Boolean((user as any)?.branchId);
  const isDeptManager = DEPT_MANAGER_ROLES.includes(role) || isBranchManager;
  const isHR = role === 'hr_admin';
  const isEmployee = !isDeptManager && !isHR && role !== 'superadmin' && role !== 'org_admin' && role !== 'ceo';

  const fetchLeaves = async () => {
    setLoading(true);
    try {
      // Employees only see their own leaves; managers/HR see all
      const endpoint = (isEmployee) ? '/hr/leaves/my' : '/hr/leaves';
      const res = await api.get(endpoint);
      setLeaves(res.data.data || []);
    } catch {
      toast.error('Failed to fetch leave requests');
    } finally {
      setLoading(false);
    }
  };

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { fetchLeaves(); }, []);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    setSubmitting(true);
    try {
      await api.post('/hr/leaves', form);
      toast.success('Leave request submitted. Your department manager will review it.');
      setCreateOpen(false);
      setForm({ type: 'sick', startDate: '', endDate: '', reason: '' });
      fetchLeaves();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to submit leave request');
    } finally {
      setSubmitting(false);
    }
  };

  const openAction = (leave: LeaveRequest, type: 'dept' | 'hr', mode: 'approve' | 'reject') => {
    setActionLeave(leave);
    setActionType(type);
    setActionMode(mode);
    setRemarks('');
    setActionDialog(true);
  };

  const handleAction = async () => {
    if (!actionLeave) return;
    if (actionMode === 'reject' && !remarks.trim()) {
      toast.error('Please provide a reason for rejection');
      return;
    }
    setActionSubmitting(true);
    try {
      const endpoint = actionType === 'dept'
        ? `/hr/leaves/${actionLeave.id}/dept-approve`
        : `/hr/leaves/${actionLeave.id}/hr-approve`;
      await api.patch(endpoint, { action: actionMode, remarks });
      toast.success(actionMode === 'approve' ? 'Leave approved' : 'Leave rejected');
      setActionDialog(false);
      fetchLeaves();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Action failed');
    } finally {
      setActionSubmitting(false);
    }
  };

  const handleDelete = async () => {
    if (!deleteLeave) return;
    try {
      await api.delete(`/hr/leaves/${deleteLeave.id}`);
      toast.success('Leave request deleted');
      setDeleteOpen(false);
      fetchLeaves();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to delete');
    }
  };

  // Filter tabs
  const filtered = leaves.filter(l => {
    if (activeTab === 'all') return true;
    if (activeTab === 'mine') return l.employeeId?.id === userId;
    return l.status === activeTab;
  });

  const counts = {
    all: leaves.length,
    pending: leaves.filter(l => l.status === 'pending').length,
    dept_approved: leaves.filter(l => l.status === 'dept_approved').length,
    approved: leaves.filter(l => l.status === 'approved').length,
    rejected: leaves.filter(l => l.status === 'rejected').length,
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Leave Requests</h2>
          <p className="text-muted-foreground text-sm mt-1">
            {isDeptManager
              ? 'Review and approve leave requests from your department.'
              : isHR
              ? 'Final approval for department-approved leave requests.'
              : 'Submit and track your leave requests.'}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" onClick={fetchLeaves} disabled={loading}>
            <RefreshCw className={cn('w-4 h-4 mr-2', loading && 'animate-spin')} />
            Refresh
          </Button>
          {/* Employees and managers can submit leaves */}
          {!isHR && (
            <Button size="sm" onClick={() => setCreateOpen(true)}>
              <Plus className="w-4 h-4 mr-2" />
              New Request
            </Button>
          )}
        </div>
      </div>

      {/* Summary KPIs */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        {[
          { label: 'Pending', count: counts.pending, color: 'text-yellow-600' },
          { label: 'Dept Approved', count: counts.dept_approved, color: 'text-blue-600' },
          { label: 'Approved', count: counts.approved, color: 'text-green-600' },
          { label: 'Rejected', count: counts.rejected, color: 'text-red-600' },
        ].map(({ label, count, color }) => (
          <Card key={label}>
            <CardContent className="pt-4 pb-4">
              <p className={cn('text-2xl font-bold', color)}>{count}</p>
              <p className="text-xs text-muted-foreground mt-0.5">{label}</p>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Tabs */}
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="flex-wrap h-auto gap-1">
          <TabsTrigger value="all">All ({counts.all})</TabsTrigger>
          <TabsTrigger value="pending">Pending ({counts.pending})</TabsTrigger>
          <TabsTrigger value="dept_approved">Dept Approved ({counts.dept_approved})</TabsTrigger>
          <TabsTrigger value="approved">Approved ({counts.approved})</TabsTrigger>
          <TabsTrigger value="rejected">Rejected ({counts.rejected})</TabsTrigger>
          {!isEmployee && <TabsTrigger value="mine">My Requests</TabsTrigger>}
        </TabsList>

        <TabsContent value={activeTab} className="mt-4">
          {loading ? (
            <div className="space-y-3">
              {[1,2,3].map(i => <div key={i} className="h-28 bg-muted rounded-xl animate-pulse" />)}
            </div>
          ) : filtered.length === 0 ? (
            <Card>
              <CardContent className="py-16 text-center text-muted-foreground">
                <Clock className="w-10 h-10 mx-auto mb-3 opacity-30" />
                <p>No leave requests found</p>
              </CardContent>
            </Card>
          ) : (
            <div className="space-y-3">
              {filtered.map(leave => {
                const cfg = STATUS_CONFIG[leave.status] || STATUS_CONFIG.pending;
                const isExpanded = expanded === leave.id;
                const isOwner = leave.employeeId?.id === userId;
                const canDeptAct = isDeptManager && leave.status === 'pending';
                const canHRAct = isHR && leave.status === 'dept_approved';

                return (
                  <Card key={leave.id} className="hover:border-primary/30 transition-colors">
                    <CardContent className="p-5">
                      <div className="flex items-start justify-between gap-4">
                        <div className="flex-1 min-w-0">
                          {/* Top row */}
                          <div className="flex items-center gap-2 flex-wrap mb-2">
                            <Badge className={cn('text-[10px] font-bold uppercase border', cfg.color)}>
                              {cfg.label}
                            </Badge>
                            <Badge variant="outline" className="text-[10px] capitalize">{leave.type}</Badge>
                            {leave.departmentId && (
                              <Badge variant="outline" className="text-[10px]">{leave.departmentId.name}</Badge>
                            )}
                          </div>

                          {/* Employee name */}
                          <p className="font-semibold text-sm">
                            {leave.employeeId?.name || 'Employee'}
                            {leave.employeeId?.designation && (
                              <span className="text-muted-foreground font-normal ml-1 text-xs">· {leave.employeeId.designation}</span>
                            )}
                          </p>

                          {/* Dates + reason */}
                          <div className="flex flex-wrap gap-x-4 gap-y-0.5 mt-1 text-xs text-muted-foreground">
                            <span>{new Date(leave.startDate).toLocaleDateString()} → {new Date(leave.endDate).toLocaleDateString()}</span>
                            <span className="line-clamp-1">{leave.reason}</span>
                          </div>

                          {/* Expandable remarks */}
                          {(leave.deptAdminRemarks || leave.hrRemarks) && (
                            <button
                              className="flex items-center gap-1 mt-2 text-xs text-primary hover:underline"
                              onClick={() => setExpanded(isExpanded ? null : leave.id)}
                            >
                              {isExpanded ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
                              {isExpanded ? 'Hide remarks' : 'View remarks'}
                            </button>
                          )}

                          {isExpanded && (
                            <div className="mt-3 space-y-2 text-xs border-t pt-3">
                              {leave.deptAdminRemarks && (
                                <div>
                                  <span className="font-semibold text-foreground/70">Dept Manager:</span>
                                  <span className="ml-1 text-muted-foreground">{leave.deptAdminRemarks}</span>
                                  {leave.deptApprovedBy && (
                                    <span className="ml-1 text-muted-foreground/60">— {(leave.deptApprovedBy as any).name}</span>
                                  )}
                                </div>
                              )}
                              {leave.hrRemarks && (
                                <div>
                                  <span className="font-semibold text-foreground/70">HR:</span>
                                  <span className="ml-1 text-muted-foreground">{leave.hrRemarks}</span>
                                  {leave.hrApprovedBy && (
                                    <span className="ml-1 text-muted-foreground/60">— {(leave.hrApprovedBy as any).name}</span>
                                  )}
                                </div>
                              )}
                            </div>
                          )}
                        </div>

                        {/* Action buttons */}
                        <div className="flex flex-col gap-2 shrink-0">
                          {canDeptAct && (
                            <>
                              <Button size="sm" className="h-8 text-xs bg-green-600 hover:bg-green-700 text-white" onClick={() => openAction(leave, 'dept', 'approve')}>
                                <CheckCircle className="w-3 h-3 mr-1" /> Approve
                              </Button>
                              <Button size="sm" variant="outline" className="h-8 text-xs text-red-600 border-red-200 hover:bg-red-50" onClick={() => openAction(leave, 'dept', 'reject')}>
                                <XCircle className="w-3 h-3 mr-1" /> Reject
                              </Button>
                            </>
                          )}
                          {canHRAct && (
                            <>
                              <Button size="sm" className="h-8 text-xs bg-green-600 hover:bg-green-700 text-white" onClick={() => openAction(leave, 'hr', 'approve')}>
                                <CheckCircle className="w-3 h-3 mr-1" /> Final Approve
                              </Button>
                              <Button size="sm" variant="outline" className="h-8 text-xs text-red-600 border-red-200 hover:bg-red-50" onClick={() => openAction(leave, 'hr', 'reject')}>
                                <XCircle className="w-3 h-3 mr-1" /> Reject
                              </Button>
                            </>
                          )}
                          {/* Owner can delete pending requests */}
                          {isOwner && leave.status === 'pending' && (
                            <Button size="sm" variant="ghost" className="h-8 text-xs text-destructive" onClick={() => { setDeleteLeave(leave); setDeleteOpen(true); }}>
                              <Trash2 className="w-3 h-3" />
                            </Button>
                          )}
                        </div>
                      </div>

                      {/* Workflow progress bar */}
                      <div className="mt-4 flex items-center gap-2 text-[10px] text-muted-foreground">
                        <StepDot active={true} done={true} label="Submitted" />
                        <div className={cn('flex-1 h-px', leave.status !== 'pending' ? 'bg-primary' : 'bg-muted')} />
                        <StepDot
                          active={leave.status !== 'pending'}
                          done={['dept_approved', 'approved'].includes(leave.status)}
                          rejected={leave.status === 'rejected' && !!leave.deptAdminRemarks && !leave.hrRemarks}
                          label="Dept Manager"
                        />
                        <div className={cn('flex-1 h-px', leave.status === 'approved' ? 'bg-primary' : 'bg-muted')} />
                        <StepDot
                          active={leave.status === 'approved' || (leave.status === 'rejected' && !!leave.hrRemarks)}
                          done={leave.status === 'approved'}
                          rejected={leave.status === 'rejected' && !!leave.hrRemarks}
                          label="HR Admin"
                        />
                      </div>
                    </CardContent>
                  </Card>
                );
              })}
            </div>
          )}
        </TabsContent>
      </Tabs>

      {/* Create Leave Dialog */}
      <Dialog open={createOpen} onOpenChange={setCreateOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Submit Leave Request</DialogTitle>
          </DialogHeader>
          <form onSubmit={handleCreate} className="space-y-4 pt-2">
            <div className="space-y-2">
              <Label>Leave Type</Label>
              <Select value={form.type} onValueChange={v => setForm(f => ({ ...f, type: v }))}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="sick">Sick Leave</SelectItem>
                  <SelectItem value="casual">Casual Leave</SelectItem>
                  <SelectItem value="earned">Earned Leave</SelectItem>
                  <SelectItem value="unpaid">Unpaid Leave</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Start Date</Label>
                <Input type="date" value={form.startDate} onChange={e => setForm(f => ({ ...f, startDate: e.target.value }))} required />
              </div>
              <div className="space-y-2">
                <Label>End Date</Label>
                <Input type="date" value={form.endDate} onChange={e => setForm(f => ({ ...f, endDate: e.target.value }))} required />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Reason</Label>
              <Textarea value={form.reason} onChange={e => setForm(f => ({ ...f, reason: e.target.value }))} placeholder="Explain the reason for your leave..." rows={3} required />
            </div>
            <DialogFooter>
              <Button type="button" variant="outline" onClick={() => setCreateOpen(false)}>Cancel</Button>
              <Button type="submit" disabled={submitting}>{submitting ? 'Submitting...' : 'Submit Request'}</Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* Approve/Reject Action Dialog */}
      <Dialog open={actionDialog} onOpenChange={setActionDialog}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>
              {actionMode === 'approve' ? 'Approve' : 'Reject'} Leave Request
              <span className="text-muted-foreground font-normal text-sm ml-2">
                ({actionType === 'dept' ? 'Department' : 'HR'} Review)
              </span>
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4 pt-2">
            {actionLeave && (
              <div className="p-3 rounded-lg bg-muted text-sm space-y-1">
                <p className="font-semibold">{actionLeave.employeeId?.name}</p>
                <p className="text-muted-foreground capitalize">{actionLeave.type} leave · {new Date(actionLeave.startDate).toLocaleDateString()} → {new Date(actionLeave.endDate).toLocaleDateString()}</p>
                <p className="text-muted-foreground text-xs">{actionLeave.reason}</p>
              </div>
            )}
            <div className="space-y-2">
              <Label>
                {actionMode === 'reject' ? 'Rejection Reason' : 'Remarks'}{' '}
                {actionMode === 'reject' && <span className="text-destructive">*</span>}
              </Label>
              <Textarea
                value={remarks}
                onChange={e => setRemarks(e.target.value)}
                placeholder={actionMode === 'reject' ? 'Explain why this leave is being rejected...' : 'Optional remarks...'}
                rows={3}
              />
            </div>
            <DialogFooter>
              <Button variant="outline" onClick={() => setActionDialog(false)}>Cancel</Button>
              <Button
                onClick={handleAction}
                disabled={actionSubmitting}
                className={actionMode === 'approve' ? 'bg-green-600 hover:bg-green-700 text-white' : 'bg-red-600 hover:bg-red-700 text-white'}
              >
                {actionSubmitting ? 'Processing...' : actionMode === 'approve' ? 'Confirm Approval' : 'Confirm Rejection'}
              </Button>
            </DialogFooter>
          </div>
        </DialogContent>
      </Dialog>

      {/* Delete Dialog */}
      <Dialog open={deleteOpen} onOpenChange={setDeleteOpen}>
        <DialogContent className="max-w-sm">
          <DialogHeader>
            <DialogTitle>Delete Leave Request</DialogTitle>
          </DialogHeader>
          <p className="text-sm text-muted-foreground">Are you sure you want to withdraw this leave request?</p>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDeleteOpen(false)}>Cancel</Button>
            <Button variant="destructive" onClick={handleDelete}>Delete</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

function StepDot({ active, done, rejected, label }: { active: boolean; done: boolean; rejected?: boolean; label: string }) {
  return (
    <div className="flex flex-col items-center gap-1">
      <div className={cn(
        'w-4 h-4 rounded-full border-2 flex items-center justify-center',
        done ? 'bg-green-500 border-green-500' :
        rejected ? 'bg-red-500 border-red-500' :
        active ? 'bg-primary border-primary' :
        'bg-muted border-muted-foreground/30'
      )}>
        {(done || rejected) && <div className="w-1.5 h-1.5 rounded-full bg-white" />}
      </div>
      <span className="text-[9px] text-muted-foreground whitespace-nowrap">{label}</span>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Edit, Trash2, Key } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import api from '@/lib/api';

export function LicensesPanel() {
  const [licenses, setLicenses] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    type: 'basic',
    maxUsers: '10',
    maxStorage: '1024',
    durationMonths: '12',
    price: '',
    status: 'active',
    features: '',
  });

  useEffect(() => { fetchLicenses(); }, []);

  const fetchLicenses = async () => {
    setLoading(true);
    try {
      const res = await api.get('/licenses');
      setLicenses(res.data.data || []);
    } catch (err) {
      console.error('Failed to fetch licenses:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const payload = {
      name: formData.name,
      type: formData.type,
      maxUsers: Number(formData.maxUsers),
      maxStorage: Number(formData.maxStorage),
      durationMonths: Number(formData.durationMonths),
      price: Number(formData.price),
      status: formData.status,
      features: formData.features ? formData.features.split(',').map(f => f.trim()).filter(Boolean) : [],
    };
    try {
      if (editingId) {
        await api.put(`/licenses/${editingId}`, payload);
      } else {
        await api.post('/licenses', payload);
      }
      setDialogOpen(false);
      resetForm();
      fetchLicenses();
    } catch (err: any) {
      alert(err.response?.data?.message || 'Failed to save license');
    }
  };

  const handleEdit = (l: any) => {
    setEditingId(l.id || l.id);
    setFormData({
      name: l.name || '',
      type: l.type || 'basic',
      maxUsers: l.maxUsers?.toString() || '10',
      maxStorage: l.maxStorage?.toString() || '1024',
      durationMonths: l.durationMonths?.toString() || '12',
      price: l.price?.toString() || '',
      status: l.status || 'active',
      features: Array.isArray(l.features) ? l.features.join(', ') : '',
    });
    setDialogOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this license?')) return;
    try {
      await api.delete(`/licenses/${id}`);
      fetchLicenses();
    } catch (err) {
      console.error('Failed to delete license:', err);
    }
  };

  const resetForm = () => {
    setEditingId(null);
    setFormData({ name: '', type: 'basic', maxUsers: '10', maxStorage: '1024', durationMonths: '12', price: '', status: 'active', features: '' });
  };

  const typeColor: Record<string, string> = {
    basic: 'bg-blue-100 text-blue-800',
    premium: 'bg-purple-100 text-purple-800',
    enterprise: 'bg-amber-100 text-amber-800',
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">License Management</h2>
          <p className="text-muted-foreground">Manage software licenses and subscription plans</p>
        </div>
        <Dialog open={dialogOpen} onOpenChange={(open) => { setDialogOpen(open); if (!open) resetForm(); }}>
          <DialogTrigger asChild>
            <Button><Plus className="w-4 h-4 mr-2" />Add License</Button>
          </DialogTrigger>
          <DialogContent className="max-w-lg">
            <DialogHeader>
              <DialogTitle>{editingId ? 'Edit License' : 'Add New License'}</DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <Label>License Name</Label>
                <Input value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} required placeholder="e.g., Basic Plan" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Type</Label>
                  <Select value={formData.type} onValueChange={(v) => setFormData({ ...formData, type: v })}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="basic">Basic</SelectItem>
                      <SelectItem value="premium">Premium</SelectItem>
                      <SelectItem value="enterprise">Enterprise</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label>Status</Label>
                  <Select value={formData.status} onValueChange={(v) => setFormData({ ...formData, status: v })}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="active">Active</SelectItem>
                      <SelectItem value="inactive">Inactive</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Max Users</Label>
                  <Input type="number" min="1" value={formData.maxUsers} onChange={(e) => setFormData({ ...formData, maxUsers: e.target.value })} required />
                </div>
                <div>
                  <Label>Max Storage (MB)</Label>
                  <Input type="number" min="1" value={formData.maxStorage} onChange={(e) => setFormData({ ...formData, maxStorage: e.target.value })} required />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Duration (months)</Label>
                  <Input type="number" min="1" value={formData.durationMonths} onChange={(e) => setFormData({ ...formData, durationMonths: e.target.value })} required />
                </div>
                <div>
                  <Label>Price</Label>
                  <Input type="number" min="0" step="0.01" value={formData.price} onChange={(e) => setFormData({ ...formData, price: e.target.value })} required />
                </div>
              </div>
              <div>
                <Label>Features (comma-separated)</Label>
                <Input value={formData.features} onChange={(e) => setFormData({ ...formData, features: e.target.value })} placeholder="e.g., Analytics, API Access, SSO" />
              </div>
              <div className="flex gap-2">
                <Button type="submit" className="flex-1">Save</Button>
                <Button type="button" variant="outline" onClick={() => setDialogOpen(false)}>Cancel</Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      <Card>
        <CardHeader><CardTitle>Licenses</CardTitle></CardHeader>
        <CardContent>
          {loading ? (
            <div className="text-center py-8">Loading...</div>
          ) : licenses.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">No licenses found</div>
          ) : (
            <div className="space-y-3">
              {licenses.filter(l => l && (l.id || l.id)).map((l) => {
                const lid = l.id || l.id;
                return (
                  <div key={lid} className="flex items-center justify-between p-4 border rounded-lg hover:bg-muted/50">
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center">
                        <Key className="w-5 h-5 text-primary" />
                      </div>
                      <div>
                        <div className="flex items-center gap-2">
                          <span className="font-medium">{l.name}</span>
                          <Badge className={typeColor[l.type] || 'bg-gray-100 text-gray-800'}>{l.type}</Badge>
                          <Badge variant={l.status === 'active' ? 'default' : 'outline'}>{l.status}</Badge>
                        </div>
                        <div className="text-sm text-muted-foreground mt-1">
                          {l.maxUsers} users • {l.maxStorage} MB • {l.durationMonths} months • ₹{l.price.toLocaleString()}
                        </div>
                        {l.features?.length > 0 && (
                          <div className="text-xs text-muted-foreground mt-1">{l.features.join(', ')}</div>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <Button variant="ghost" size="sm" onClick={() => handleEdit(l)}><Edit className="w-4 h-4" /></Button>
                      <Button variant="ghost" size="sm" onClick={() => handleDelete(lid)}><Trash2 className="w-4 h-4" /></Button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

