  custom: 'bg-purple-100 text-purple-800',
};

export function ManagerAssignmentPanel() {
  const [departments, setDepartments] = useState<Department[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedDepts, setExpandedDepts] = useState<Set<string>>(new Set());

  // Dialog state
  const [dialogOpen, setDialogOpen] = useState(false);
  const [assignTarget, setAssignTarget] = useState<{
    type: 'department' | 'subdepartment';
    id: string;
    name: string;
    currentManagerId?: string;
  } | null>(null);
  const [selectedManagerId, setSelectedManagerId] = useState('none');

  useEffect(() => {
    fetchAll();
  }, []);

  const fetchAll = async () => {
    setLoading(true);
    try {
      const [deptsRes, subDeptsRes, usersRes] = await Promise.all([
        api.get('/departments'),
        api.get('/sub-departments'),
        api.get('/users'),
      ]);

      const depts: Department[] = deptsRes.data.data || [];
      const subs: SubDepartment[] = subDeptsRes.data.data || [];
      const allUsers: User[] = usersRes.data.data || [];

      // Attach sub-departments to their parent departments
      const deptsWithSubs = depts.map((dept) => ({
        ...dept,
        subDepartments: subs.filter((s) => {
          const parentId =
            typeof s.parentDeptId === 'object'
              ? s.parentDeptId?.id
              : s.parentDeptId;
          return parentId === dept.id;
        }),
      }));

      setDepartments(deptsWithSubs);
      // Filter out superadmin/org_admin for manager candidates
      setUsers(allUsers.filter((u) => !['superadmin', 'org_admin'].includes(u.role)));
    } catch (_err) {
      toast.error('Failed to load hierarchy data');
    } finally {
      setLoading(false);
    }
  };

  const toggleExpand = (deptId: string) => {
    setExpandedDepts((prev) => {
      const next = new Set(prev);
      if (next.has(deptId)) { next.delete(deptId); } else { next.add(deptId); }
      return next;
    });
  };

  const openAssignDialog = (
    type: 'department' | 'subdepartment',
    id: string,
    name: string,
    currentManager?: any
  ) => {
    const currentId =
      typeof currentManager === 'object'
        ? currentManager?.id
        : currentManager;
    setAssignTarget({ type, id, name, currentManagerId: currentId });
    setSelectedManagerId(currentId || 'none');
    setDialogOpen(true);
  };

  const handleAssign = async () => {
    if (!assignTarget) return;
    const managerId = selectedManagerId === 'none' ? null : selectedManagerId;

    try {
      if (assignTarget.type === 'department') {
        if (managerId) {
          await api.put(`/departments/${assignTarget.id}/assign-manager`, { managerId });
        } else {
          await api.delete(`/departments/${assignTarget.id}/remove-manager`);
        }
      } else {
        await api.patch(`/sub-departments/${assignTarget.id}`, {
          managerId: managerId || null,
        });
      }
      toast.success(`Manager ${managerId ? 'assigned' : 'removed'} for ${assignTarget.name}`);
      setDialogOpen(false);
      fetchAll();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to assign manager');
    }
  };

  const getManagerName = (managerId: any) => {
    if (!managerId) return null;
    if (typeof managerId === 'object') return managerId.name;
    const user = users.find((u) => u.id === managerId);
    return user?.name || null;
  };

  if (loading) {
    return (
      <Card>
        <CardContent className="p-8">
          <div className="space-y-3">
            {[1, 2, 3].map((i) => (
              <div key={i} className="h-16 bg-muted rounded-lg animate-pulse" />
            ))}
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <>
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Crown className="w-5 h-5 text-primary" />
            Manager Assignment — Hierarchy View
          </CardTitle>
          <p className="text-sm text-muted-foreground">
            Assign or change managers for departments and their sub-departments
          </p>
        </CardHeader>
        <CardContent className="space-y-3">
          {departments.length === 0 && (
            <div className="text-center py-12 text-muted-foreground">
              <Building className="w-12 h-12 mx-auto mb-3 opacity-40" />
              <p>No departments found</p>
            </div>
          )}

          {departments.map((dept) => {
            const isExpanded = expandedDepts.has(dept.id);
            const hasSubs = (dept.subDepartments?.length ?? 0) > 0;
            const managerName = getManagerName(dept.managerId);

            return (
              <div key={dept.id} className="border rounded-xl overflow-hidden">
                {/* Department row */}
                <div className="flex items-center gap-3 p-4 bg-muted/30 hover:bg-muted/50 transition-colors">
                  <button
                    onClick={() => hasSubs && toggleExpand(dept.id)}
                    className="text-muted-foreground hover:text-foreground transition-colors"
                    disabled={!hasSubs}
                  >
                    {hasSubs ? (
                      isExpanded ? (
                        <ChevronDown className="w-4 h-4" />
                      ) : (
                        <ChevronRight className="w-4 h-4" />
                      )
                    ) : (
                      <div className="w-4" />
                    )}
                  </button>

                  <Building className="w-4 h-4 text-primary shrink-0" />

                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="font-semibold">{dept.name}</span>
                      <Badge
                        className={`text-xs ${DEPT_TYPE_COLORS[dept.type] || 'bg-gray-100 text-gray-800'}`}
                        variant="outline"
                      >
                        {dept.type}
                      </Badge>
                      {hasSubs && (
                        <span className="text-xs text-muted-foreground">
                          {(dept.subDepartments?.length ?? 0)} sub-dept{(dept.subDepartments?.length ?? 0) !== 1 ? 's' : ''}
                        </span>
                      )}
                    </div>
                    <div className="flex items-center gap-1 mt-0.5">
                      {managerName ? (
                        <>
                          <UserCheck className="w-3 h-3 text-green-600" />
                          <span className="text-xs text-green-700 font-medium">{managerName}</span>
                        </>
                      ) : (
                        <>
                          <UserX className="w-3 h-3 text-muted-foreground" />
                          <span className="text-xs text-muted-foreground">No manager assigned</span>
                        </>
                      )}
                    </div>
                  </div>

                  <Button
                    size="sm"
                    variant={managerName ? 'outline' : 'default'}
                    onClick={() =>
                      openAssignDialog('department', dept.id, dept.name, dept.managerId)
                    }
                  >
                    <Users className="w-3 h-3 mr-1" />
                    {managerName ? 'Change' : 'Assign'}
                  </Button>
                </div>

                {/* Sub-departments */}
                {isExpanded && dept.subDepartments && dept.subDepartments.length > 0 && (
                  <div className="border-t divide-y">
                    {dept.subDepartments.map((sub) => {
                      const subManagerName = getManagerName(sub.managerId);
                      return (
                        <div
                          key={sub.id}
                          className="flex items-center gap-3 p-3 pl-10 bg-background hover:bg-muted/20 transition-colors"
                        >
                          <Building2 className="w-4 h-4 text-muted-foreground shrink-0" />

                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2">
                              <span className="text-sm font-medium">{sub.name}</span>
                              <Badge
                                variant="outline"
                                className={`text-xs ${sub.status === 'active' ? 'bg-green-50 text-green-700' : 'bg-gray-50 text-gray-600'}`}
                              >
                                {sub.status}
                              </Badge>
                            </div>
                            <div className="flex items-center gap-1 mt-0.5">
                              {subManagerName ? (
                                <>
                                  <UserCheck className="w-3 h-3 text-green-600" />
                                  <span className="text-xs text-green-700 font-medium">{subManagerName}</span>
                                </>
                              ) : (
                                <>
                                  <UserX className="w-3 h-3 text-muted-foreground" />
                                  <span className="text-xs text-muted-foreground">No manager assigned</span>
                                </>
                              )}
                            </div>
                          </div>

                          <Button
                            size="sm"
                            variant={subManagerName ? 'outline' : 'default'}
                            onClick={() =>
                              openAssignDialog('subdepartment', sub.id, sub.name, sub.managerId)
                            }
                          >
                            <Users className="w-3 h-3 mr-1" />
                            {subManagerName ? 'Change' : 'Assign'}
                          </Button>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          })}
        </CardContent>
      </Card>

      {/* Assign Manager Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Assign Manager</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div>
              <p className="text-sm text-muted-foreground">
                {assignTarget?.type === 'department' ? 'Department' : 'Sub-Department'}:{' '}
                <span className="font-semibold text-foreground">{assignTarget?.name}</span>
              </p>
            </div>
            <div className="space-y-2">
              <Label>Select Manager</Label>
              <Select value={selectedManagerId} onValueChange={setSelectedManagerId}>
                <SelectTrigger>
                  <SelectValue placeholder="Choose a manager" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">— Remove Manager —</SelectItem>
                  {users.map((user) => (
                    <SelectItem key={user.id} value={user.id}>
                      {user.name}
                      {' — '}
                      {user.designation || user.role.replace(/_/g, ' ')}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleAssign}>
              {selectedManagerId === 'none' ? 'Remove Manager' : 'Assign Manager'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import { useState, useEffect } from 'react';
import { Megaphone, CalendarDays, BarChart2, RefreshCw, CheckCircle } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { toast } from 'sonner';
import api from '@/lib/api';
import { useAuth } from '@/hooks/useAuth';

const PRIORITY_COLORS: Record<string, string> = {
  high: 'bg-red-100 text-red-800',
  medium: 'bg-yellow-100 text-yellow-800',
  low: 'bg-green-100 text-green-800',
};

const TYPE_COLORS: Record<string, string> = {
  general: 'bg-blue-100 text-blue-800',
  hr: 'bg-purple-100 text-purple-800',
  ops: 'bg-orange-100 text-orange-800',
  finance: 'bg-emerald-100 text-emerald-800',
  sales: 'bg-cyan-100 text-cyan-800',
};

const HOLIDAY_TYPE_COLORS: Record<string, string> = {
  national: 'bg-blue-100 text-blue-800',
  regional: 'bg-purple-100 text-purple-800',
  company: 'bg-green-100 text-green-800',
};

export function NoticeBoardPanel() {
  const { user } = useAuth();
  const [announcements, setAnnouncements] = useState<any[]>([]);
  const [holidays, setHolidays] = useState<any[]>([]);
  const [polls, setPolls] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [votedPolls, setVotedPolls] = useState<Record<string, number[]>>({});

  useEffect(() => { fetchAll(); }, []);

  const fetchAll = async () => {
    setLoading(true);
    try {
      const [aRes, hRes, pRes] = await Promise.all([
        api.get('/hr/announcements'),
        api.get('/hr/holidays'),
        api.get('/hr/polls'),
      ]);
      setAnnouncements(aRes.data.data || []);
      setHolidays(hRes.data.data || []);
      setPolls((pRes.data.data || []).filter((p: any) => p.isActive));
    } catch { toast.error('Failed to load notice board'); }
    finally { setLoading(false); }
  };

  const handleVote = async (pollId: string, optionIndex: number) => {
    const poll = polls.find(p => p.id === pollId);
    if (!poll) return;
    const current = votedPolls[pollId] || [];
    let newIndexes: number[];
    if (poll.allowMultiple) {
      newIndexes = current.includes(optionIndex)
        ? current.filter((i: number) => i !== optionIndex)
        : [...current, optionIndex];
    } else {
      newIndexes = [optionIndex];
    }
    try {
      await api.post(`/hr/polls/${pollId}/vote`, { optionIndexes: newIndexes });
      setVotedPolls(prev => ({ ...prev, [pollId]: newIndexes }));
      fetchAll();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to vote');
    }
  };

  const totalVotes = (poll: any) => poll.options.reduce((s: number, o: any) => s + o.votes.length, 0);
  const pct = (votes: number, total: number) => total === 0 ? 0 : Math.round((votes / total) * 100);
  const hasVoted = (poll: any) => {
    const uid = user?.id || (user as any)?.id;
    return poll.options.some((o: any) => o.votes.includes(uid));
  };
  const myVotes = (poll: any) => {
    const uid = user?.id || (user as any)?.id;
    return poll.options.map((o: any, i: number) => o.votes.includes(uid) ? i : -1).filter((i: number) => i >= 0);
  };

  const upcomingHolidays = holidays
    .filter(h => new Date(h.date) >= new Date())
    .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Notice Board</h2>
          <p className="text-muted-foreground text-sm">Announcements, holidays, and polls from HR</p>
        </div>
        <Button variant="outline" size="sm" onClick={fetchAll}>
          <RefreshCw className="w-4 h-4 mr-1" /> Refresh
        </Button>
      </div>

      <Tabs defaultValue="announcements">
        <TabsList>
          <TabsTrigger value="announcements">
            <Megaphone className="w-4 h-4 mr-1.5" />
            Announcements {announcements.length > 0 && `(${announcements.length})`}
          </TabsTrigger>
          <TabsTrigger value="holidays">
            <CalendarDays className="w-4 h-4 mr-1.5" />
            Holidays {upcomingHolidays.length > 0 && `(${upcomingHolidays.length})`}
          </TabsTrigger>
          <TabsTrigger value="polls">
            <BarChart2 className="w-4 h-4 mr-1.5" />
            Polls {polls.length > 0 && `(${polls.length})`}
          </TabsTrigger>
        </TabsList>

        {/* Announcements */}
        <TabsContent value="announcements" className="mt-4">
          {loading ? (
            <div className="space-y-3">{[1,2,3].map(i => <div key={i} className="h-20 bg-muted rounded-lg animate-pulse" />)}</div>
          ) : announcements.length === 0 ? (
            <Card><CardContent className="py-12 text-center text-muted-foreground">
              <Megaphone className="w-8 h-8 mx-auto mb-2 opacity-30" />
              <p>No announcements</p>
            </CardContent></Card>
          ) : (
            <div className="space-y-3">
              {announcements.map(a => (
                <Card key={a.id} className={a.priority === 'high' ? 'border-red-200' : ''}>
                  <CardContent className="p-4">
                    <div className="flex items-start gap-3">
                      <div className="w-9 h-9 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
                        <Megaphone className="w-4 h-4 text-primary" />
                      </div>
                      <div className="flex-1">
                        <p className="font-semibold">{a.title}</p>
                        <p className="text-sm text-muted-foreground mt-1">{a.content}</p>
                        <div className="flex flex-wrap gap-2 mt-2">
                          <Badge className={`text-xs ${TYPE_COLORS[a.type] || ''}`}>{a.type}</Badge>
                          <Badge className={`text-xs ${PRIORITY_COLORS[a.priority] || ''}`}>{a.priority}</Badge>
                          {a.postedBy?.name && <span className="text-xs text-muted-foreground">— {a.postedBy.name}</span>}
                          <span className="text-xs text-muted-foreground">{new Date(a.postedAt || a.createdAt).toLocaleDateString()}</span>
                        </div>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </TabsContent>

        {/* Holidays */}
        <TabsContent value="holidays" className="mt-4">
          {loading ? (
            <div className="space-y-3">{[1,2,3].map(i => <div key={i} className="h-16 bg-muted rounded-lg animate-pulse" />)}</div>
          ) : holidays.length === 0 ? (
            <Card><CardContent className="py-12 text-center text-muted-foreground">
              <CalendarDays className="w-8 h-8 mx-auto mb-2 opacity-30" />
              <p>No holidays published yet</p>
            </CardContent></Card>
          ) : (
            <div className="space-y-3">
              {/* Upcoming */}
              {upcomingHolidays.length > 0 && (
                <div>
                  <p className="text-sm font-semibold text-muted-foreground mb-2">Upcoming</p>
                  <div className="space-y-2">
                    {upcomingHolidays.map(h => {
                      const d = new Date(h.date);
                      const isToday = d.toDateString() === new Date().toDateString();
                      return (
                        <Card key={h.id} className={isToday ? 'border-primary' : ''}>
                          <CardContent className="p-3 flex items-center gap-4">
                            <div className="flex flex-col items-center justify-center w-12 h-12 bg-primary/10 rounded-lg shrink-0">
                              <span className="text-lg font-bold leading-none">{d.getDate()}</span>
                              <span className="text-xs text-muted-foreground uppercase">{d.toLocaleDateString('en-US', { month: 'short' })}</span>
                            </div>
                            <div className="flex-1">
                              <p className="font-semibold text-sm">{h.name}</p>
                              <p className="text-xs text-muted-foreground">{d.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
                            </div>
                            <Badge className={`text-xs ${HOLIDAY_TYPE_COLORS[h.type] || ''}`}>{h.type}</Badge>
                            {isToday && <Badge className="text-xs bg-primary text-primary-foreground">Today</Badge>}
                          </CardContent>
                        </Card>
                      );
                    })}
                  </div>
                </div>
              )}
              {/* Past */}
              {holidays.filter(h => new Date(h.date) < new Date()).length > 0 && (
                <div>
                  <p className="text-sm font-semibold text-muted-foreground mb-2 mt-4">Past</p>
                  <div className="space-y-2 opacity-60">
                    {holidays.filter(h => new Date(h.date) < new Date()).map(h => {
                      const d = new Date(h.date);
                      return (
                        <div key={h.id} className="flex items-center gap-4 p-3 border rounded-lg">
                          <div className="flex flex-col items-center justify-center w-12 h-12 bg-muted rounded-lg shrink-0">
                            <span className="text-lg font-bold leading-none">{d.getDate()}</span>
                            <span className="text-xs text-muted-foreground uppercase">{d.toLocaleDateString('en-US', { month: 'short' })}</span>
                          </div>
                          <div className="flex-1">
                            <p className="font-medium text-sm">{h.name}</p>
                            <p className="text-xs text-muted-foreground">{d.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
                          </div>
                          <Badge variant="outline" className="text-xs">{h.type}</Badge>
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>
          )}
        </TabsContent>

        {/* Polls */}
        <TabsContent value="polls" className="mt-4">
          {loading ? (
            <div className="space-y-4">{[1,2].map(i => <div key={i} className="h-40 bg-muted rounded-xl animate-pulse" />)}</div>
          ) : polls.length === 0 ? (
            <Card><CardContent className="py-12 text-center text-muted-foreground">
              <BarChart2 className="w-8 h-8 mx-auto mb-2 opacity-30" />
              <p>No active polls</p>
            </CardContent></Card>
          ) : (
            <div className="space-y-4">
              {polls.map(poll => {
                const total = totalVotes(poll);
                const voted = hasVoted(poll);
                const myVoteIdxs = myVotes(poll);
                const expired = poll.expiresAt && new Date(poll.expiresAt) < new Date();
                const canVote = !expired;

                return (
                  <Card key={poll.id}>
                    <CardHeader className="pb-3">
                      <CardTitle className="text-base">{poll.question}</CardTitle>
                      <div className="flex flex-wrap gap-2">
                        {poll.allowMultiple && <Badge variant="outline" className="text-xs">Multi-choice</Badge>}
                        {poll.expiresAt && <span className="text-xs text-muted-foreground">Expires {new Date(poll.expiresAt).toLocaleDateString()}</span>}
                        <span className="text-xs text-muted-foreground">{total} vote{total !== 1 ? 's' : ''}</span>
                      </div>
                    </CardHeader>
                    <CardContent className="space-y-2">
                      {poll.options.map((opt: any, idx: number) => {
                        const isMyVote = myVoteIdxs.includes(idx);
                        const optPct = pct(opt.votes.length, total);
                        return (
                          <button
                            key={idx}
                            className={`w-full text-left p-3 rounded-lg border transition-colors relative overflow-hidden ${
                              isMyVote ? 'border-primary bg-primary/5' : canVote && !voted ? 'hover:border-primary/50 hover:bg-muted/50' : 'cursor-default'
                            }`}
                            onClick={() => canVote ? handleVote(poll.id, idx) : undefined}
                          >
                            {(voted || !canVote) && (
                              <div className="absolute inset-0 bg-primary/10 rounded-lg" style={{ width: `${optPct}%` }} />
                            )}
                            <div className="relative flex items-center justify-between">
                              <div className="flex items-center gap-2">
                                {isMyVote && <CheckCircle className="w-4 h-4 text-primary shrink-0" />}
                                <span className="text-sm font-medium">{opt.text}</span>
                              </div>
                              {(voted || !canVote) && (
                                <span className="text-xs font-semibold text-muted-foreground">{optPct}% ({opt.votes.length})</span>
                              )}
                            </div>
                          </button>
                        );
                      })}
                      {canVote && !voted && <p className="text-xs text-muted-foreground pt-1">Click an option to vote</p>}
                      {voted && <p className="text-xs text-primary pt-1">You voted — click another option to change</p>}
                    </CardContent>
                  </Card>
                );
              })}
            </div>
          )}
        </TabsContent>
      </Tabs>
    </div>
  );
}

import { useState } from 'react';
