import { useState, useEffect } from 'react';
import { FileText, CheckCircle, XCircle, RefreshCw, ExternalLink } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent } from '@/components/ui/card';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import api from '@/lib/api';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';

interface University { id: string; name: string; code: string; }
interface Center {
  id: string;
  name: string;
  code: string;
  email: string;
  contact: string;
  address: string;
  status: string;
  associatedUniversityIds: University[];
  pendingDocuments: { name: string; url: string }[];
  referredBy?: { name: string; email: string };
  createdAt: string;
}

export function OpsCenterVerificationPanel() {
  const [centers, setCenters] = useState<Center[]>([]);
  const [loading, setLoading] = useState(false);
  const [dialog, setDialog] = useState<{ center: Center; action: 'approve' | 'reject' } | null>(null);
  const [remarks, setRemarks] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const fetch = async () => {
    setLoading(true);
    try {
      const res = await api.get('/operations/centers/pending-verification');
      setCenters(res.data.data || []);
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to load centers');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetch(); }, []);

  const handleAction = async () => {
    if (!dialog) return;
    if (dialog.action === 'reject' && !remarks.trim()) {
      toast.error('Remarks are required when rejecting');
      return;
    }
    setSubmitting(true);
    try {
      await api.put(`/operations/centers/${dialog.center.id}/verify`, {
        action: dialog.action,
        remarks,
      });
      toast.success(dialog.action === 'approve' ? 'Center approved — moved to pending payment' : 'Center rejected');
      setDialog(null);
      setRemarks('');
      fetch();
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Action failed');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Pending Verification</h2>
          <p className="text-muted-foreground text-sm mt-1">Review and verify study center documents.</p>
        </div>
        <Button variant="outline" size="sm" onClick={fetch} disabled={loading}>
          <RefreshCw className={cn('w-4 h-4 mr-2', loading && 'animate-spin')} />Refresh
        </Button>
      </div>

      {loading ? (
        <div className="space-y-3">{[1,2,3].map(i => <div key={i} className="h-24 bg-muted rounded-xl animate-pulse" />)}</div>
      ) : centers.length === 0 ? (
        <Card><CardContent className="py-16 text-center text-muted-foreground">
          <CheckCircle className="w-10 h-10 mx-auto mb-3 opacity-30" />
          <p>No centers pending verification.</p>
        </CardContent></Card>
      ) : (
        <div className="space-y-4">
          {centers.map(c => (
            <Card key={c.id} className="hover:border-primary/30 transition-colors">
              <CardContent className="p-5">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <h4 className="font-semibold">{c.name}</h4>
                      <Badge variant="outline" className="text-[10px]">{c.code}</Badge>
                    </div>
                    <p className="text-xs text-muted-foreground">{c.email} · {c.contact}</p>
                    <p className="text-xs text-muted-foreground mt-0.5">{c.address}</p>
                    <div className="flex flex-wrap gap-1 mt-2">
                      {(c.associatedUniversityIds || []).map(u => (
                        <Badge key={u.id} variant="secondary" className="text-[10px]">{u.name}</Badge>
                      ))}
                    </div>
                    {(c.pendingDocuments?.length ?? 0) > 0 && (
                      <div className="flex flex-wrap gap-2 mt-2">
                        {(c.pendingDocuments || []).map((doc, i) => (
                          <a
                            key={i}
                            href={doc.url}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="flex items-center gap-1 text-xs text-primary hover:underline"
                          >
                            <FileText className="w-3 h-3" />{doc.name}
                            <ExternalLink className="w-3 h-3" />
                          </a>
                        ))}
                      </div>
                    )}
                    {c.referredBy && (
                      <p className="text-xs text-muted-foreground mt-1">Referred by: {c.referredBy.name}</p>
                    )}
                  </div>
                  <div className="flex gap-2 shrink-0">
                    <Button size="sm" variant="outline" className="text-error border-error/30 hover:bg-error/10"
                      onClick={() => { setDialog({ center: c, action: 'reject' }); setRemarks(''); }}>
                      <XCircle className="w-4 h-4 mr-1" />Reject
                    </Button>
                    <Button size="sm" onClick={() => { setDialog({ center: c, action: 'approve' }); setRemarks(''); }}>
                      <CheckCircle className="w-4 h-4 mr-1" />Approve
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      <Dialog open={!!dialog} onOpenChange={() => { setDialog(null); setRemarks(''); }}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              {dialog?.action === 'approve' ? 'Approve' : 'Reject'} — {dialog?.center.name}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <Label>Remarks {dialog?.action === 'reject' && <span className="text-error">*</span>}</Label>
            <Textarea
              value={remarks}
              onChange={e => setRemarks(e.target.value)}
              placeholder={dialog?.action === 'reject' ? 'Reason for rejection (required)' : 'Optional remarks'}
              rows={3}
            />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => { setDialog(null); setRemarks(''); }}>Cancel</Button>
            <Button
              onClick={handleAction}
              disabled={submitting}
              variant={dialog?.action === 'reject' ? 'destructive' : 'default'}
            >
              {submitting ? 'Processing...' : dialog?.action === 'approve' ? 'Approve' : 'Reject'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Trash2, RefreshCw } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import api from '@/lib/api';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';

interface Center { id: string; name: string; code: string; }
interface Program { id: string; name: string; code: string; courseType?: string; }
interface University { id: string; name: string; code: string; }
interface Allocation { id: string; programId: string; program: Program; allocatedAt: string; }
interface UniAllocation { id: string; universityId: string; university: University; allocatedAt: string; }

export function OpsProgramAllocationPanel() {
  const [centers, setCenters] = useState<Center[]>([]);
  const [selectedCenter, setSelectedCenter] = useState('');
  const [allocations, setAllocations] = useState<Allocation[]>([]);
  const [uniAllocations, setUniAllocations] = useState<UniAllocation[]>([]);
  const [programs, setPrograms] = useState<Program[]>([]);
  const [universities, setUniversities] = useState<University[]>([]);
  const [loading, setLoading] = useState(false);
  const [open, setOpen] = useState(false);
  const [uniOpen, setUniOpen] = useState(false);
  const [selectedProgram, setSelectedProgram] = useState('');
  const [selectedUniversity, setSelectedUniversity] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [activeSubTab, setActiveSubTab] = useState<'programs' | 'universities'>('programs');

  useEffect(() => {
    api.get('/operations/centers?status=active').then(r => setCenters(r.data.data || [])).catch(() => {});
    api.get('/operations/programs').then(r => setPrograms(r.data.data || [])).catch(() => {});
    api.get('/operations/universities?status=active').then(r => setUniversities(r.data.data || [])).catch(() => {});
  }, []);

  const fetchAllocations = async (centerId: string) => {
    if (!centerId) return;
    setLoading(true);
    try {
      const [progRes, uniRes] = await Promise.all([
        api.get(`/operations/centers/${centerId}/allocations`),
        api.get(`/operations/centers/${centerId}/uni-allocations`),
      ]);
      setAllocations(progRes.data.data || []);
      setUniAllocations(uniRes.data.data || []);
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to load allocations');
    } finally {
      setLoading(false);
    }
  };

  const handleCenterChange = (id: string) => {
    setSelectedCenter(id);
    fetchAllocations(id);
  };

  const handleAllocate = async () => {
    if (!selectedProgram) { toast.error('Select a program'); return; }
    setSubmitting(true);
    try {
      await api.post(`/operations/centers/${selectedCenter}/allocations`, { programId: selectedProgram });
      toast.success('Program allocated');
      setOpen(false);
      setSelectedProgram('');
      fetchAllocations(selectedCenter);
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to allocate');
    } finally {
      setSubmitting(false);
    }
  };

  const handleAllocateUniversity = async () => {
    if (!selectedUniversity) { toast.error('Select a university'); return; }
    setSubmitting(true);
    try {
      await api.post(`/operations/centers/${selectedCenter}/uni-allocations`, { universityId: selectedUniversity });
      toast.success('University allocated');
      setUniOpen(false);
      setSelectedUniversity('');
      fetchAllocations(selectedCenter);
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to allocate university');
    } finally {
      setSubmitting(false);
    }
  };

  const handleRemove = async (allocId: string) => {
    try {
      await api.delete(`/operations/centers/${selectedCenter}/allocations/${allocId}`);
      toast.success('Allocation removed');
      fetchAllocations(selectedCenter);
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to remove');
    }
  };

  const handleRemoveUniversity = async (allocId: string) => {
    try {
      await api.delete(`/operations/centers/${selectedCenter}/uni-allocations/${allocId}`);
      toast.success('University allocation removed');
      fetchAllocations(selectedCenter);
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to remove university');
    }
  };

  const allocatedProgramIds = allocations.map(a => a.programId);
  const availablePrograms = programs.filter(p => !allocatedProgramIds.includes(p.id));

  const allocatedUniIds = uniAllocations.map(a => a.universityId);
  const availableUniversities = universities.filter(u => !allocatedUniIds.includes(u.id));

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-bold">Allocations</h2>
        <p className="text-muted-foreground text-sm mt-1">Manage which programs and universities each active study center is allocated to enroll students in.</p>
      </div>

      <div className="flex items-center gap-3">
        <Select value={selectedCenter} onValueChange={handleCenterChange}>
          <SelectTrigger className="w-72">
            <SelectValue placeholder="Select a study center" />
          </SelectTrigger>
          <SelectContent>
            {centers.map(c => (
              <SelectItem key={c.id} value={c.id}>{c.name} ({c.code})</SelectItem>
            ))}
          </SelectContent>
        </Select>
        {selectedCenter && (
          <>
            <Button variant="outline" size="sm" onClick={() => fetchAllocations(selectedCenter)} disabled={loading}>
              <RefreshCw className={cn('w-4 h-4', loading && 'animate-spin')} />
            </Button>
            {activeSubTab === 'programs' ? (
              <Button size="sm" onClick={() => setOpen(true)} disabled={availablePrograms.length === 0}>
                <Plus className="w-4 h-4 mr-2" />Add Program
              </Button>
            ) : (
              <Button size="sm" onClick={() => setUniOpen(true)} disabled={availableUniversities.length === 0}>
                <Plus className="w-4 h-4 mr-2" />Add University
              </Button>
            )}
          </>
        )}
      </div>

      {selectedCenter && (
        <>
          {/* Sub tabs */}
          <div className="flex border-b border-border">
            <button
              onClick={() => setActiveSubTab('programs')}
              className={cn(
                'px-4 py-2 text-sm font-semibold border-b-2 -mb-px transition-colors',
                activeSubTab === 'programs' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground'
              )}
            >
              Program Allocations
            </button>
            <button
              onClick={() => setActiveSubTab('universities')}
              className={cn(
                'px-4 py-2 text-sm font-semibold border-b-2 -mb-px transition-colors',
                activeSubTab === 'universities' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground'
              )}
            >
              University Allocations
            </button>
          </div>

          {loading ? (
            <div className="space-y-2">{[1, 2, 3].map(i => <div key={i} className="h-12 bg-muted rounded-xl animate-pulse" />)}</div>
          ) : activeSubTab === 'programs' ? (
            allocations.length === 0 ? (
              <Card><CardContent className="py-10 text-center text-muted-foreground text-sm">
                No programs allocated yet.
              </CardContent></Card>
            ) : (
              <Card>
                <CardHeader><CardTitle className="text-base">Allocated Programs ({allocations.length})</CardTitle></CardHeader>
                <CardContent className="space-y-2">
                  {allocations.map(a => (
                    <div key={a.id} className="flex items-center justify-between p-3 rounded-lg bg-muted/40">
                      <div>
                        <span className="font-medium text-sm">{a.program?.name}</span>
                        <span className="text-muted-foreground text-xs ml-2">({a.program?.code})</span>
                        {a.program?.courseType && (
                          <Badge variant="outline" className="ml-2 text-[10px]">{a.program?.courseType}</Badge>
                        )}
                      </div>
                      <Button variant="ghost" size="sm" className="text-error hover:text-error" onClick={() => handleRemove(a.id)}>
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>
                  ))}
                </CardContent>
              </Card>
            )
          ) : (
            uniAllocations.length === 0 ? (
              <Card><CardContent className="py-10 text-center text-muted-foreground text-sm">
                No universities allocated yet.
              </CardContent></Card>
            ) : (
              <Card>
                <CardHeader><CardTitle className="text-base">Allocated Universities ({uniAllocations.length})</CardTitle></CardHeader>
                <CardContent className="space-y-2">
                  {uniAllocations.map(a => (
                    <div key={a.id} className="flex items-center justify-between p-3 rounded-lg bg-muted/40">
                      <div>
                        <span className="font-medium text-sm">{a.university?.name}</span>
                        <span className="text-muted-foreground text-xs ml-2">({a.university?.code})</span>
                      </div>
                      <Button variant="ghost" size="sm" className="text-error hover:text-error" onClick={() => handleRemoveUniversity(a.id)}>
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>
                  ))}
                </CardContent>
              </Card>
            )
          )}
        </>
      )}

      {/* Program Allocation Dialog */}
      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent>
          <DialogHeader><DialogTitle>Allocate Program</DialogTitle></DialogHeader>
          <div className="py-2">
            <Select value={selectedProgram} onValueChange={setSelectedProgram}>
              <SelectTrigger>
                <SelectValue placeholder="Select a program" />
              </SelectTrigger>
              <SelectContent>
                {availablePrograms.map(p => (
                  <SelectItem key={p.id} value={p.id}>{p.name} ({p.code})</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => { setOpen(false); setSelectedProgram(''); }}>Cancel</Button>
            <Button onClick={handleAllocate} disabled={submitting || !selectedProgram}>
              {submitting ? 'Allocating...' : 'Allocate'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* University Allocation Dialog */}
      <Dialog open={uniOpen} onOpenChange={setUniOpen}>
        <DialogContent>
          <DialogHeader><DialogTitle>Allocate University</DialogTitle></DialogHeader>
          <div className="py-2">
            <Select value={selectedUniversity} onValueChange={setSelectedUniversity}>
              <SelectTrigger>
                <SelectValue placeholder="Select a university" />
              </SelectTrigger>
              <SelectContent>
                {availableUniversities.map(u => (
                  <SelectItem key={u.id} value={u.id}>{u.name} ({u.code})</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => { setUniOpen(false); setSelectedUniversity(''); }}>Cancel</Button>
            <Button onClick={handleAllocateUniversity} disabled={submitting || !selectedUniversity}>
              {submitting ? 'Allocating...' : 'Allocate'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Edit, Trash2, Calendar } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import api from '@/lib/api';
import { useAuth } from '@/hooks/useAuth';
import { toast } from 'sonner';

export function OrgAdminSessionsPanel() {
  const { user } = useAuth();
  console.log('OrgAdminSessionsPanel for user organization:', user?.organizationId);
  const [sessions, setSessions] = useState<any[]>([]);
  const [universities, setUniversities] = useState<any[]>([]);
  const [programs, setPrograms] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    name: '',
    universityId: '',
    programId: '',
    startDate: '',
    endDate: '',
    capacity: 0,
    status: 'active'
  });

  useEffect(() => {
    fetchSessions();
    fetchUniversities();
    fetchPrograms();
  }, []);

  const fetchSessions = async () => {
    setLoading(true);
    try {
      const res = await api.get('/operations/sessions');
      setSessions(res.data.data || []);
    } catch (err) {
      console.error('Failed to fetch sessions:', err);
      toast.error('Failed to fetch sessions');
    } finally {
      setLoading(false);
    }
  };

  const fetchUniversities = async () => {
    try {
      const res = await api.get('/operations/universities');
      setUniversities(res.data.data || []);
    } catch (err) {
      console.error('Failed to fetch universities:', err);
    }
  };

  const fetchPrograms = async () => {
    try {
      const res = await api.get('/operations/programs');
      setPrograms(res.data.data || []);
    } catch (err) {
      console.error('Failed to fetch programs:', err);
    }
  };

  const filteredPrograms = formData.universityId
    ? programs.filter(p => p.universityId === formData.universityId || p.university?.id === formData.universityId)
    : programs;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const payload: any = {
        name: formData.name,
        startDate: new Date(formData.startDate).toISOString(),
        endDate: new Date(formData.endDate).toISOString(),
        capacity: formData.capacity ? parseInt(String(formData.capacity)) : 0,
        status: formData.status
      };

      if (formData.universityId) payload.universityId = formData.universityId;
      if (formData.programId) payload.programId = formData.programId;

      if (editingId) {
        await api.put(`/operations/sessions/${editingId}`, payload);
        toast.success('Session updated successfully');
      } else {
        await api.post('/operations/sessions', payload);
        toast.success('Session created successfully');
      }
      setDialogOpen(false);
      resetForm();
      fetchSessions();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to save session');
    }
  };

  const handleEdit = (s: any) => {
    setEditingId(s.id);
    setFormData({
      name: s.name || '',
      universityId: s.universityId || '',
      programId: s.programId || '',
      startDate: s.startDate ? new Date(s.startDate).toISOString().split('T')[0] : '',
      endDate: s.endDate ? new Date(s.endDate).toISOString().split('T')[0] : '',
      capacity: s.capacity || 0,
      status: s.status || 'active'
    });
    setDialogOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this admission session?')) return;
    try {
      await api.delete(`/operations/sessions/${id}`);
      toast.success('Session deleted successfully');
      fetchSessions();
    } catch (err) {
      console.error('Failed to delete session:', err);
      toast.error('Failed to delete session');
    }
  };

  const resetForm = () => {
    setEditingId(null);
    setFormData({
      name: '',
      universityId: '',
      programId: '',
      startDate: '',
      endDate: '',
      capacity: 0,
      status: 'active'
    });
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Admission Sessions</h2>
          <p className="text-muted-foreground">Manage intakes and admission cycles per program and university</p>
        </div>
        <Dialog open={dialogOpen} onOpenChange={(open) => { setDialogOpen(open); if (!open) resetForm(); }}>
          <DialogTrigger asChild>
            <Button className="premium-gradient text-white"><Plus className="w-4 h-4 mr-2" />Add Session</Button>
          </DialogTrigger>
          <DialogContent className="max-w-lg">
            <DialogHeader>
              <DialogTitle>{editingId ? 'Edit Admission Session' : 'Create Admission Session'}</DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4 pt-2">
              <div>
                <Label>Session Name / Batch</Label>
                <Input 
                  placeholder="e.g. Autumn 2026 Batch A" 
                  value={formData.name} 
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })} 
                  required 
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>University</Label>
                  <Select 
                    value={formData.universityId || 'none'} 
                    onValueChange={(v) => setFormData({ ...formData, universityId: v === 'none' ? '' : v, programId: '' })}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="All Universities" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="none">All Universities</SelectItem>
                      {universities.map((u) => (
                        <SelectItem key={u.id} value={u.id}>{u.name}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div>
                  <Label>Program</Label>
                  <Select 
                    value={formData.programId || 'none'} 
                    onValueChange={(v) => setFormData({ ...formData, programId: v === 'none' ? '' : v })}
                    disabled={!formData.universityId}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder={formData.universityId ? "Select Program" : "Select University First"} />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="none">All Programs</SelectItem>
                      {filteredPrograms.map((p) => (
                        <SelectItem key={p.id} value={p.id}>{p.name}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Start Date</Label>
                  <Input 
                    type="date" 
                    value={formData.startDate} 
                    onChange={(e) => setFormData({ ...formData, startDate: e.target.value })} 
                    required 
                  />
                </div>
                <div>
                  <Label>End Date</Label>
                  <Input 
                    type="date" 
                    value={formData.endDate} 
                    onChange={(e) => setFormData({ ...formData, endDate: e.target.value })} 
                    required 
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Capacity Limit (Optional)</Label>
                  <Input 
                    type="number" 
                    placeholder="Unlimited" 
                    value={formData.capacity || ''} 
                    onChange={(e) => setFormData({ ...formData, capacity: e.target.value ? parseInt(e.target.value) : 0 })} 
                  />
                </div>

                <div>
                  <Label>Status</Label>
                  <Select 
                    value={formData.status} 
                    onValueChange={(v) => setFormData({ ...formData, status: v })}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="pending">Pending</SelectItem>
                      <SelectItem value="approved">Approved</SelectItem>
                      <SelectItem value="active">Active</SelectItem>
                      <SelectItem value="closed">Closed</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="flex gap-2 pt-4">
                <Button type="submit" className="flex-1 premium-gradient text-white">Save Session</Button>
                <Button type="button" variant="outline" onClick={() => setDialogOpen(false)}>Cancel</Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      <Card className="border-none shadow-xl bg-card/60 backdrop-blur-xl">
        <CardHeader>
          <CardTitle>Intakes & Admission Cycles</CardTitle>
          <CardDescription>Academic configurations for running programs</CardDescription>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="text-center py-8 text-muted-foreground animate-pulse">Loading sessions...</div>
          ) : sessions.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">No sessions created yet</div>
          ) : (
            <div className="space-y-4">
              {sessions.map((s) => {
                const programName = programs.find(p => p.id === s.programId)?.name || 'All Programs';
                const uniName = universities.find(u => u.id === s.universityId)?.name || 'All Universities';

                return (
                  <div key={s.id} className="flex flex-col sm:flex-row sm:items-center justify-between p-4 border rounded-xl hover:bg-muted/40 transition-all gap-4">
                    <div className="flex items-start gap-4">
                      <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center flex-shrink-0">
                        <Calendar className="w-5 h-5 text-primary" />
                      </div>
                      <div>
                        <div className="flex items-center gap-2 flex-wrap">
                          <span className="font-semibold text-lg">{s.name}</span>
                          <Badge variant="secondary" className="text-xs">{s.status}</Badge>
                        </div>
                        <div className="text-sm text-muted-foreground mt-1 space-y-1">
                          <p>
                            <span className="font-medium text-foreground">University:</span> {uniName}
                          </p>
                          <p>
                            <span className="font-medium text-foreground">Program:</span> {programName}
                          </p>
                          <p>
                            <span className="font-medium text-foreground">Duration:</span> {new Date(s.startDate).toLocaleDateString()} – {new Date(s.endDate).toLocaleDateString()}
                          </p>
                          {s.capacity ? (
                            <p>
                              <span className="font-medium text-foreground">Capacity:</span> {s.capacity} seats
                            </p>
                          ) : null}
                        </div>
                      </div>
                    </div>
                    <div className="flex items-center gap-2 self-end sm:self-center">
                      <Button variant="ghost" size="sm" onClick={() => handleEdit(s)}>
                        <Edit className="w-4 h-4 text-muted-foreground hover:text-foreground" />
                      </Button>
                      <Button variant="ghost" size="sm" onClick={() => handleDelete(s.id)}>
                        <Trash2 className="w-4 h-4 text-red-500 hover:text-red-700" />
                      </Button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Plus, RefreshCw, UserPlus, Trash2, Edit2, Users, ChevronDown, ChevronUp, Layers, Building2, MapPin } from 'lucide-react';
import api from '@/lib/api';

// ─── Types ────────────────────────────────────────────────────────────────────
interface Dept { id: string; name: string; type: string; }
interface SubDept { id: string; name: string; parentDeptId: string | { id: string; name: string }; }
interface Branch {
  id: string; name: string; code: string; address: string; city?: string;
  branchManagerId?: { id: string; name: string; role: string; userId?: string; designation?: string };
  salesDeptId?: { id: string; name: string; type: string };
  operationsDeptId?: { id: string; name: string; type: string };
  additionalDeptIds?: { id: string; name: string; type: string }[];
}
interface OrgUser { id: string; name: string; email: string; role: string; designation?: string; userId?: string; }
interface DesignationNode {
  id: string;
  title: string;
  level: number;
  maxHeadcount: number;
  departmentId?: Dept;
  subDepartmentId?: SubDept;
  branchId?: { id: string; name: string; code: string };
  parentDesignationId?: { id: string; title: string };
  filledBy: OrgUser[];
  status: string;
}

const ROLE_COLORS: Record<string, string> = {
  org_admin: '#7c3aed', ceo: '#2563eb', ops_admin: '#ea580c',
  finance_admin: '#16a34a', hr_admin: '#db2777', sales_admin: '#ca8a04',
  center_admin: '#0d9488', ops_sub_admin: '#f97316', employee: '#6b7280', staff: '#94a3b8',
};

// ─── OrgNode ──────────────────────────────────────────────────────────────────
function OrgNode({
  node, allNodes, allUsers, allDepts,
  onEdit, onDelete, onAssign, onUnassign, onAddChild, depth = 0,
}: {
  node: DesignationNode; allNodes: DesignationNode[]; allUsers: OrgUser[]; allDepts: Dept[];
  onEdit: (n: DesignationNode) => void; onDelete: (n: DesignationNode) => void;
  onAssign: (n: DesignationNode) => void; onUnassign: (n: DesignationNode, userId: string) => void;
  onAddChild: (parent: DesignationNode) => void; depth?: number;
}) {
  const [expanded, setExpanded] = useState(true);
  const children = allNodes.filter(n => {
    const pid = typeof n.parentDesignationId === 'object' ? (n.parentDesignationId as any)?.id : n.parentDesignationId;
    return pid === node.id;
  });
  const filled = node.filledBy?.length || 0;
  const vacant = node.maxHeadcount - filled;
  const isFull = vacant <= 0;

  const boxColor = node.branchId
    ? '#0891b2'  // cyan for branch-scoped positions
    : node.departmentId
      ? ROLE_COLORS[node.departmentId.type] || '#6366f1'
      : '#6366f1';

  const subDeptName = node.subDepartmentId
    ? (typeof node.subDepartmentId === 'object' ? node.subDepartmentId.name : '')
    : null;

  return (
    <div className="flex flex-col items-center">
      <div className="relative group" style={{ minWidth: 190 }}>
        <div className="rounded-xl border-2 bg-white shadow-md px-4 py-3 text-center transition-all hover:shadow-lg"
          style={{ borderColor: boxColor, minWidth: 190 }}>

          {/* Branch badge */}
          {node.branchId && (
            <span className="text-[10px] font-semibold uppercase tracking-wide px-2 py-0.5 rounded-full mb-1 inline-flex items-center gap-1"
              style={{ background: '#0891b222', color: '#0891b2' }}>
              <Building2 className="h-2.5 w-2.5" />
              {node.branchId.name} [{node.branchId.code}]
            </span>
          )}

          {/* Dept badge */}
          {node.departmentId && !node.branchId && (
            <span className="text-[10px] font-semibold uppercase tracking-wide px-2 py-0.5 rounded-full mb-1 inline-block"
              style={{ background: boxColor + '22', color: boxColor }}>
              {node.departmentId.name}
            </span>
          )}

          {/* Sub-dept badge */}
          {subDeptName && (
            <span className="text-[10px] font-medium px-2 py-0.5 rounded-full mb-1 inline-flex items-center gap-1 bg-slate-100 text-slate-600">
              <Layers className="h-2.5 w-2.5" />{subDeptName}
            </span>
          )}

          <p className="font-bold text-sm text-gray-800 leading-tight">{node.title}</p>

          <div className="flex items-center justify-center gap-1 mt-1">
            <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${isFull ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>
              {filled}/{node.maxHeadcount} filled
            </span>
          </div>

          {filled > 0 && (
            <div className="mt-2 space-y-1">
              {node.filledBy.map(u => (
                <div key={u.id} className="flex items-center gap-1 bg-gray-50 rounded-lg px-2 py-1">
                  <div className="w-5 h-5 rounded-full flex items-center justify-center text-white text-[9px] font-bold shrink-0"
                    style={{ background: ROLE_COLORS[u.role] || '#6366f1' }}>
                    {u.name.charAt(0)}
                  </div>
                  <span className="text-xs text-gray-700 truncate flex-1">{u.name}</span>
                  <button onClick={() => onUnassign(node, u.id)}
                    className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100 transition-opacity">
                    <Trash2 className="h-3 w-3" />
                  </button>
                </div>
              ))}
            </div>
          )}

          {vacant > 0 && (
            <button onClick={() => onAssign(node)}
              className="mt-2 w-full flex items-center justify-center gap-1 text-xs border border-dashed rounded-lg py-1 text-gray-400 hover:text-indigo-600 hover:border-indigo-400 transition-colors">
              <UserPlus className="h-3 w-3" />
              {vacant} vacant {vacant === 1 ? 'slot' : 'slots'}
            </button>
          )}

          <div className="absolute -top-2 -right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
            <button onClick={() => onEdit(node)}
              className="w-6 h-6 bg-white border rounded-full shadow flex items-center justify-center hover:bg-indigo-50">
              <Edit2 className="h-3 w-3 text-indigo-600" />
            </button>
            <button onClick={() => onAddChild(node)}
              className="w-6 h-6 bg-white border rounded-full shadow flex items-center justify-center hover:bg-green-50">
              <Plus className="h-3 w-3 text-green-600" />
            </button>
            <button onClick={() => onDelete(node)}
              className="w-6 h-6 bg-white border rounded-full shadow flex items-center justify-center hover:bg-red-50">
              <Trash2 className="h-3 w-3 text-red-500" />
            </button>
          </div>
        </div>
      </div>

      {children.length > 0 && (
        <>
          <div className="w-px bg-gray-300" style={{ height: 24 }} />
          <button onClick={() => setExpanded(!expanded)} className="text-gray-400 hover:text-gray-600 mb-1">
            {expanded ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
          </button>
          {expanded && (
            <div className="flex flex-col items-center">
              {children.length > 1 ? (
                <>
                  {/* horizontal bar connecting siblings */}
                  <div className="relative flex items-start">
                    {/* top horizontal line */}
                    <div className="absolute top-0 left-1/2 -translate-x-1/2"
                      style={{
                        width: `calc(100% - 190px)`,
                        height: 1,
                        background: '#d1d5db',
                        top: 0,
                      }}
                    />
                    {children.map(child => (
                      <div key={child.id} className="flex flex-col items-center" style={{ padding: '0 20px' }}>
                        <div className="w-px bg-gray-300" style={{ height: 20 }} />
                        <OrgNode node={child} allNodes={allNodes} allUsers={allUsers} allDepts={allDepts}
                          onEdit={onEdit} onDelete={onDelete} onAssign={onAssign}
                          onUnassign={onUnassign} onAddChild={onAddChild} depth={depth + 1} />
                      </div>
                    ))}
                  </div>
                </>
              ) : (
                <OrgNode node={children[0]} allNodes={allNodes} allUsers={allUsers} allDepts={allDepts}
                  onEdit={onEdit} onDelete={onDelete} onAssign={onAssign}
                  onUnassign={onUnassign} onAddChild={onAddChild} depth={depth + 1} />
              )}
            </div>
          )}
        </>
      )}
    </div>
  );
}

// ─── Branch section in the chart ─────────────────────────────────────────────
function DeptNode({ dept, color }: { dept: { id: string; name: string; type: string }; color: string }) {
  return (
    <div className="flex flex-col items-center">
      <div className="w-px bg-gray-300" style={{ height: 24 }} />
      <div className="rounded-xl border-2 bg-white shadow-sm px-4 py-3 text-center"
        style={{ borderColor: color, minWidth: 160 }}>
        <span className="text-[10px] font-semibold uppercase tracking-wide px-2 py-0.5 rounded-full mb-1 inline-block"
          style={{ background: color + '22', color }}>
          {dept.type}
        </span>
        <p className="font-semibold text-sm text-gray-800 leading-tight">{dept.name}</p>
      </div>
    </div>
  );
}

function BranchSection({
  branch, allNodes, allUsers, allDepts,
  onEdit, onDelete, onAssign, onUnassign, onAddChild, onAddBranchPosition,
}: {
  branch: Branch; allNodes: DesignationNode[]; allUsers: OrgUser[]; allDepts: Dept[];
  onEdit: (n: DesignationNode) => void; onDelete: (n: DesignationNode) => void;
  onAssign: (n: DesignationNode) => void; onUnassign: (n: DesignationNode, userId: string) => void;
  onAddChild: (parent: DesignationNode) => void; onAddBranchPosition: (branch: Branch) => void;
}) {
  const [expanded, setExpanded] = useState(true);

  // Designation nodes scoped to this branch with no parent = roots of branch subtree
  const branchRoots = allNodes.filter(n => {
    const bId = typeof n.branchId === 'object' ? (n.branchId as any)?.id : n.branchId;
    const hasParent = typeof n.parentDesignationId === 'object' ? !!(n.parentDesignationId as any)?.id : !!n.parentDesignationId;
    return bId === branch.id && !hasParent;
  });

  // Branch manager controls Sales and Operations only — Finance and HR are org-wide
  const BRANCH_CONTROLLED_TYPES = new Set(['sales', 'operations']);
  const controlledDepts: Array<{ id: string; name: string; type: string }> = [];
  const salesDeptObj = typeof branch.salesDeptId === 'object' && branch.salesDeptId ? branch.salesDeptId : (branch as any).salesDept;
  const operationsDeptObj = typeof branch.operationsDeptId === 'object' && branch.operationsDeptId ? branch.operationsDeptId : (branch as any).operationsDept;

  if (salesDeptObj && salesDeptObj.id) {
    controlledDepts.push({ id: salesDeptObj.id, name: salesDeptObj.name, type: 'sales' });
  }
  if (operationsDeptObj && operationsDeptObj.id) {
    controlledDepts.push({ id: operationsDeptObj.id, name: operationsDeptObj.name, type: 'operations' });
  }
  if (branch.additionalDeptIds) {
    branch.additionalDeptIds
      .filter(d => BRANCH_CONTROLLED_TYPES.has(d.type))
      .forEach(d => {
        if (d && d.id && !controlledDepts.find(x => x.id === d.id)) {
          controlledDepts.push({ id: d.id, name: d.name, type: d.type });
        }
      });
  }

  const DEPT_COLORS: Record<string, string> = {
    sales: '#ca8a04', operations: '#ea580c', finance: '#16a34a',
    hr: '#db2777', ceo: '#2563eb', custom: '#6366f1',
  };

  const mgr = branch.branchManagerId;

  return (
    <div className="border-2 rounded-2xl p-5 bg-cyan-50/50" style={{ borderColor: '#0891b244' }}>
      {/* Branch header */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-xl bg-cyan-600 flex items-center justify-center text-white">
            <Building2 className="h-5 w-5" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <span className="font-bold text-base text-cyan-900">{branch.name}</span>
              <span className="text-xs font-mono bg-cyan-100 text-cyan-700 px-2 py-0.5 rounded">
                {branch.code}
              </span>
            </div>
            <div className="flex items-center gap-1 text-xs text-cyan-700 mt-0.5">
              <MapPin className="h-3 w-3" />{branch.address}{branch.city ? `, ${branch.city}` : ''}
            </div>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <Button size="sm" variant="outline" className="text-xs h-7"
            onClick={() => onAddBranchPosition(branch)}>
            <Plus className="h-3 w-3 mr-1" /> Add Position
          </Button>
          <button onClick={() => setExpanded(!expanded)} className="text-cyan-500 hover:text-cyan-700">
            {expanded ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
          </button>
        </div>
      </div>

      {expanded && (
        <div className="overflow-x-auto">
          <div className="flex flex-col items-center min-w-max pb-4">

            {/* ── Branch Manager node ── */}
            {mgr ? (
              <div className="relative group" style={{ minWidth: 200 }}>
                <div className="rounded-xl border-2 bg-white shadow-md px-4 py-3 text-center"
                  style={{ borderColor: '#0891b2', minWidth: 200 }}>
                  <span className="text-[10px] font-semibold uppercase tracking-wide px-2 py-0.5 rounded-full mb-1 inline-flex items-center gap-1"
                    style={{ background: '#0891b222', color: '#0891b2' }}>
                    <Building2 className="h-2.5 w-2.5" /> Branch Manager
                  </span>
                  <p className="font-bold text-sm text-gray-800">{mgr.name}</p>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    {mgr.designation || mgr.role.replace(/_/g, ' ')}
                  </p>
                  <div className="mt-2 flex items-center justify-center gap-1">
                    <span className="text-xs bg-green-100 text-green-700 px-2 py-0.5 rounded-full font-medium">
                      Controls {controlledDepts.length} dept{controlledDepts.length !== 1 ? 's' : ''}
                    </span>
                  </div>
                </div>
              </div>
            ) : (
              <div className="rounded-xl border-2 border-dashed px-4 py-3 text-center text-sm text-muted-foreground"
                style={{ borderColor: '#0891b244', minWidth: 200 }}>
                <Building2 className="h-5 w-5 mx-auto mb-1 text-cyan-400" />
                No branch manager assigned
              </div>
            )}

            {/* Connector down to dept row */}
            {controlledDepts.length > 0 && (
              <>
                <div className="w-px bg-gray-300" style={{ height: 20 }} />
                {/* Horizontal bar spanning all dept nodes */}
                <div className="flex items-start justify-center">
                  {controlledDepts.map((dept) => (
                    <div key={dept.id} className="flex flex-col items-center" style={{ padding: '0 20px' }}>
                      {controlledDepts.length > 1 && (
                        <div className="w-px bg-gray-300" style={{ height: 20 }} />
                      )}
                      <DeptNode dept={dept} color={DEPT_COLORS[dept.type] || '#6366f1'} />
                    </div>
                  ))}
                </div>
              </>
            )}

            {/* Designation nodes for this branch (below the dept row) */}
            {branchRoots.length > 0 && (
              <>
                <div className="w-px bg-gray-300" style={{ height: 24 }} />
                <div className="flex gap-10 justify-center pt-2">
                  {branchRoots.map(root => (
                    <OrgNode key={root.id} node={root} allNodes={allNodes} allUsers={allUsers} allDepts={allDepts}
                      onEdit={onEdit} onDelete={onDelete} onAssign={onAssign}
                      onUnassign={onUnassign} onAddChild={onAddChild} />
                  ))}
                </div>
              </>
            )}

            {branchRoots.length === 0 && controlledDepts.length === 0 && (
              <div className="text-center py-6 text-sm text-muted-foreground border-2 border-dashed border-cyan-200 rounded-xl mt-4 w-full">
                No positions defined for this branch yet.
                <br />
                <button onClick={() => onAddBranchPosition(branch)}
                  className="text-cyan-600 hover:underline text-xs mt-1 inline-flex items-center gap-1">
                  <Plus className="h-3 w-3" /> Add first position
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

// ─── Main Panel ───────────────────────────────────────────────────────────────
export function OrgHierarchyPanel() {
  const [nodes, setNodes] = useState<DesignationNode[]>([]);
  const [allUsers, setAllUsers] = useState<OrgUser[]>([]);
  const [allDepts, setAllDepts] = useState<Dept[]>([]);
  const [allSubDepts, setAllSubDepts] = useState<SubDept[]>([]);
  const [allBranches, setAllBranches] = useState<Branch[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  // ── Create / Edit designation dialog ──
  const [designDialog, setDesignDialog] = useState(false);
  const [editingNode, setEditingNode] = useState<DesignationNode | null>(null);
  const [designForm, setDesignForm] = useState({
    title: '', departmentId: '', subDepartmentId: '', branchId: '',
    level: '1', maxHeadcount: '1', parentDesignationId: '',
  });

  // ── Create sub-department dialog ──
  const [subDeptDialog, setSubDeptDialog] = useState(false);
  const [subDeptForm, setSubDeptForm] = useState({ name: '', parentDeptId: '' });
  const [subDeptSaving, setSubDeptSaving] = useState(false);

  // ── Assign user dialog ──
  const [assignDialog, setAssignDialog] = useState(false);
  const [assignTarget, setAssignTarget] = useState<DesignationNode | null>(null);
  const [assignUserId, setAssignUserId] = useState('');

  const fetchAll = async () => {
    setLoading(true);
    try {
      const [nodesRes, usersRes, deptsRes, subDeptsRes, branchRes] = await Promise.all([
        api.get('/org/designations'),
        api.get('/users'),
        api.get('/departments'),
        api.get('/sub-departments'),
        api.get('/org/branches'),
      ]);
      setNodes(nodesRes.data.data || []);
      setAllUsers(usersRes.data.data || []);
      setAllDepts(deptsRes.data.data || []);
      setAllSubDepts(subDeptsRes.data.data || []);
      setAllBranches(branchRes.data.data || []);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchAll(); }, []);

  const filteredSubDepts = designForm.departmentId
    ? allSubDepts.filter(sd => {
        if (!sd.parentDeptId) return false;
        const parentId = typeof sd.parentDeptId === 'object' ? sd.parentDeptId.id : sd.parentDeptId;
        return parentId === designForm.departmentId;
      })
    : allSubDepts;

  const openCreate = (parent?: DesignationNode) => {
    setEditingNode(null);
    setDesignForm({
      title: '',
      departmentId: parent?.departmentId?.id || '',
      subDepartmentId: '',
      branchId: parent?.branchId?.id || '',
      level: parent ? String((parent.level || 1) + 1) : '1',
      maxHeadcount: '1',
      parentDesignationId: parent?.id || '',
    });
    setDesignDialog(true);
  };

  // Open create dialog pre-scoped to a branch
  const openCreateForBranch = (branch: Branch) => {
    setEditingNode(null);
    setDesignForm({
      title: 'Branch Manager',
      departmentId: '',
      subDepartmentId: '',
      branchId: branch.id,
      level: '2',
      maxHeadcount: '1',
      parentDesignationId: '',
    });
    setDesignDialog(true);
  };

  const openEdit = (node: DesignationNode) => {
    setEditingNode(node);
    setDesignForm({
      title: node.title,
      departmentId: node.departmentId?.id || '',
      subDepartmentId: node.subDepartmentId?.id || '',
      branchId: node.branchId?.id || '',
      level: String(node.level),
      maxHeadcount: String(node.maxHeadcount),
      parentDesignationId: node.parentDesignationId?.id || '',
    });
    setDesignDialog(true);
  };

  const handleSaveDesignation = async () => {
    if (!designForm.title) return;
    setSaving(true);
    try {
      const payload = {
        title: designForm.title,
        departmentId: designForm.departmentId || null,
        subDepartmentId: designForm.subDepartmentId || null,
        branchId: designForm.branchId || null,
        level: Number(designForm.level),
        maxHeadcount: Number(designForm.maxHeadcount),
        parentDesignationId: designForm.parentDesignationId || null,
      };
      if (editingNode) {
        await api.patch(`/org/designations/${editingNode.id}`, payload);
      } else {
        await api.post('/org/designations', payload);
      }
      setDesignDialog(false);
      fetchAll();
    } catch (e) {
      console.error(e);
    } finally {
      setSaving(false);
    }
  };

  const handleCreateSubDept = async () => {
    if (!subDeptForm.name || !subDeptForm.parentDeptId) return;
    setSubDeptSaving(true);
    try {
      await api.post('/sub-departments', subDeptForm);
      setSubDeptDialog(false);
      setSubDeptForm({ name: '', parentDeptId: '' });
      const res = await api.get('/sub-departments');
      setAllSubDepts(res.data.data || []);
    } catch (e) {
      console.error(e);
    } finally {
      setSubDeptSaving(false);
    }
  };

  const handleDelete = async (node: DesignationNode) => {
    if (!confirm(`Delete "${node.title}"? This cannot be undone.`)) return;
    try {
      await api.delete(`/org/designations/${node.id}`);
      fetchAll();
    } catch (e) { console.error(e); }
  };

  const openAssign = (node: DesignationNode) => {
    setAssignTarget(node);
    setAssignUserId('');
    setAssignDialog(true);
  };

  const handleAssign = async () => {
    if (!assignTarget || !assignUserId) return;
    setSaving(true);
    try {
      await api.patch(`/org/designations/${assignTarget.id}/assign`, { userId: assignUserId });
      setAssignDialog(false);
      fetchAll();
    } catch (e) { console.error(e); }
    finally { setSaving(false); }
  };

  const handleUnassign = async (node: DesignationNode, userId: string) => {
    try {
      await api.patch(`/org/designations/${node.id}/unassign`, { userId });
      fetchAll();
    } catch (e) { console.error(e); }
  };

  // Global (non-branch) root nodes
  const globalRoots = nodes.filter(n => {
    const hasParent = typeof n.parentDesignationId === 'object' ? !!(n.parentDesignationId as any)?.id : !!n.parentDesignationId;
    const hasBranch = typeof n.branchId === 'object' ? !!(n.branchId as any)?.id : !!n.branchId;
    return !hasParent && !hasBranch;
  });
  const assignedUserIds = new Set(nodes.flatMap(n => (n.filledBy || []).map(u => u.id)));
  const unassignedUsers = allUsers.filter(u => !assignedUserIds.has(u.id));

  if (loading) {
    return <div className="flex items-center justify-center h-64 text-muted-foreground">Loading org chart...</div>;
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold">Organisation Chart</h2>
          <p className="text-sm text-muted-foreground">
            Build the designation hierarchy. Branches have their own position trees.
          </p>
        </div>
        <div className="grid grid-cols-2 sm:flex sm:flex-row gap-2">
          <Button size="sm" variant="outline" onClick={() => setSubDeptDialog(true)} className="w-full sm:w-auto">
            <Layers className="h-4 w-4 mr-1" /> Sub-Dept
          </Button>
          <Button size="sm" variant="outline" onClick={fetchAll} className="w-full sm:w-auto">
            <RefreshCw className="h-4 w-4 mr-1" /> Refresh
          </Button>
          <Button size="sm" onClick={() => openCreate()} className="col-span-2 sm:col-span-1 w-full sm:w-auto">
            <Plus className="h-4 w-4 mr-1" /> Add Position
          </Button>
        </div>
      </div>

      {/* Legend */}
      <div className="flex flex-wrap gap-3 text-xs text-muted-foreground">
        <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-full bg-cyan-200 inline-block" /> Branch position</span>
        <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-full bg-amber-200 inline-block" /> Vacant slots</span>
        <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-full bg-green-200 inline-block" /> Fully filled</span>
        <span className="flex items-center gap-1"><Edit2 className="h-3 w-3" /> Hover a box to edit/add child/delete</span>
      </div>

      {/* Global org chart */}
      {globalRoots.length > 0 && (
        <div className="overflow-auto border rounded-xl bg-gray-50 p-4 sm:p-8">
          <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-6 text-center">
            Organisation — Head Office
          </p>
          <div className="inline-flex gap-12 justify-center min-w-full pb-4">
            {globalRoots.map(root => (
              <OrgNode key={root.id} node={root} allNodes={nodes} allUsers={allUsers} allDepts={allDepts}
                onEdit={openEdit} onDelete={handleDelete} onAssign={openAssign}
                onUnassign={handleUnassign} onAddChild={openCreate} />
            ))}
          </div>
        </div>
      )}

      {globalRoots.length === 0 && allBranches.length === 0 && (
        <div className="border-2 border-dashed rounded-xl p-16 text-center">
          <Users className="h-12 w-12 text-muted-foreground mx-auto mb-3" />
          <p className="text-muted-foreground mb-4">No positions defined yet.</p>
          <p className="text-sm text-muted-foreground mb-6">
            Start by adding the top-level position (e.g. "CEO"), then add positions below it.
            Create branches in the Branches tab to add branch-specific hierarchies.
          </p>
          <Button onClick={() => openCreate()}>
            <Plus className="h-4 w-4 mr-2" /> Add First Position
          </Button>
        </div>
      )}

      {/* Branch sections */}
      {allBranches.length > 0 && (
        <div className="space-y-4">
          <p className="text-sm font-semibold text-muted-foreground uppercase tracking-wide">
            Branch Hierarchies ({allBranches.length})
          </p>
          {allBranches.map(branch => (
            <BranchSection
              key={branch.id}
              branch={branch}
              allNodes={nodes}
              allUsers={allUsers}
              allDepts={allDepts}
              onEdit={openEdit}
              onDelete={handleDelete}
              onAssign={openAssign}
              onUnassign={handleUnassign}
              onAddChild={openCreate}
              onAddBranchPosition={openCreateForBranch}
            />
          ))}
        </div>
      )}

      {/* Unassigned users */}
      {unassignedUsers.length > 0 && (
        <div className="border rounded-xl p-4 bg-amber-50">
          <p className="text-sm font-semibold text-amber-700 mb-2">
            {unassignedUsers.length} people not yet placed in the chart
          </p>
          <div className="flex flex-wrap gap-2">
            {unassignedUsers.map(u => (
              <span key={u.id} className="text-xs bg-white border rounded-full px-3 py-1 flex items-center gap-1">
                <span className="w-4 h-4 rounded-full inline-flex items-center justify-center text-white text-[9px] font-bold"
                  style={{ background: ROLE_COLORS[u.role] || '#6366f1' }}>
                  {u.name.charAt(0)}
                </span>
                {u.name}
                <span className="text-gray-400">({(u.designation || u.role).replace(/_/g, ' ')})</span>
              </span>
            ))}
          </div>
        </div>
      )}

      {/* ── Create / Edit Designation Dialog ── */}
      <Dialog open={designDialog} onOpenChange={setDesignDialog}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>{editingNode ? 'Edit Position' : 'Add Position'}</DialogTitle>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <div className="space-y-1">
              <Label>Position Title *</Label>
              <Input placeholder="e.g. CEO, Branch Manager, Sales Executive"
                value={designForm.title}
                onChange={e => setDesignForm(p => ({ ...p, title: e.target.value }))} />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <Label>Level (1 = top)</Label>
                <Input type="number" min={1} value={designForm.level}
                  onChange={e => setDesignForm(p => ({ ...p, level: e.target.value }))} />
              </div>
              <div className="space-y-1">
                <Label>Max Headcount</Label>
                <Input type="number" min={1} value={designForm.maxHeadcount}
                  onChange={e => setDesignForm(p => ({ ...p, maxHeadcount: e.target.value }))} />
              </div>
            </div>

            {/* Branch selector */}
            <div className="space-y-1">
              <Label>Branch (leave empty for head office)</Label>
              <Select value={designForm.branchId || '__none__'}
                onValueChange={v => setDesignForm(p => ({ ...p, branchId: v === '__none__' ? '' : v }))}>
                <SelectTrigger><SelectValue placeholder="Head office / global" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="__none__">Head office / global</SelectItem>
                  {allBranches.map(b => (
                    <SelectItem key={b.id} value={b.id}>
                      {b.name} [{b.code}] — {b.address}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-1">
              <Label>Department</Label>
              <Select value={designForm.departmentId || '__none__'}
                onValueChange={v => setDesignForm(p => ({
                  ...p, departmentId: v === '__none__' ? '' : v, subDepartmentId: '',
                }))}>
                <SelectTrigger><SelectValue placeholder="Select department..." /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="__none__">None</SelectItem>
                  {allDepts.map(d => <SelectItem key={d.id} value={d.id}>{d.name}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>

            {designForm.departmentId && (
              <div className="space-y-1">
                <div className="flex items-center justify-between">
                  <Label>Sub-Department</Label>
                  <button type="button"
                    onClick={() => { setSubDeptForm({ name: '', parentDeptId: designForm.departmentId }); setSubDeptDialog(true); }}
                    className="text-xs text-indigo-600 hover:underline flex items-center gap-1">
                    <Plus className="h-3 w-3" /> New
                  </button>
                </div>
                <Select value={designForm.subDepartmentId || '__none__'}
                  onValueChange={v => setDesignForm(p => ({ ...p, subDepartmentId: v === '__none__' ? '' : v }))}>
                  <SelectTrigger><SelectValue placeholder="Select sub-department..." /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="__none__">None</SelectItem>
                    {filteredSubDepts.map(sd => (
                      <SelectItem key={sd.id} value={sd.id}>{sd.name}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                {filteredSubDepts.length === 0 && (
                  <p className="text-xs text-muted-foreground">No sub-departments for this department yet.</p>
                )}
              </div>
            )}

            <div className="space-y-1">
              <Label>Reports To (parent position)</Label>
              <Select value={designForm.parentDesignationId || '__none__'}
                onValueChange={v => setDesignForm(p => ({ ...p, parentDesignationId: v === '__none__' ? '' : v }))}>
                <SelectTrigger><SelectValue placeholder="None (top-level)" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="__none__">None (top-level)</SelectItem>
                  {nodes
                    .filter(n => n.id !== editingNode?.id)
                    .map(n => (
                      <SelectItem key={n.id} value={n.id}>
                        {n.title}{n.branchId ? ` [${n.branchId.code}]` : ''}
                      </SelectItem>
                    ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDesignDialog(false)}>Cancel</Button>
            <Button onClick={handleSaveDesignation} disabled={saving || !designForm.title}>
              {saving ? 'Saving...' : editingNode ? 'Save Changes' : 'Create Position'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* ── Create Sub-Department Dialog ── */}
      <Dialog open={subDeptDialog} onOpenChange={setSubDeptDialog}>
        <DialogContent className="max-w-sm">
          <DialogHeader><DialogTitle>Add Sub-Department</DialogTitle></DialogHeader>
          <div className="space-y-3 py-2">
            <div className="space-y-1">
              <Label>Name *</Label>
              <Input placeholder="e.g. Admissions, Accounts Payable"
                value={subDeptForm.name}
                onChange={e => setSubDeptForm(p => ({ ...p, name: e.target.value }))} />
            </div>
            <div className="space-y-1">
              <Label>Parent Department *</Label>
              <Select value={subDeptForm.parentDeptId || '__none__'}
                onValueChange={v => setSubDeptForm(p => ({ ...p, parentDeptId: v === '__none__' ? '' : v }))}>
                <SelectTrigger><SelectValue placeholder="Select department..." /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="__none__">Select...</SelectItem>
                  {allDepts.map(d => <SelectItem key={d.id} value={d.id}>{d.name}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setSubDeptDialog(false)}>Cancel</Button>
            <Button onClick={handleCreateSubDept}
              disabled={subDeptSaving || !subDeptForm.name || !subDeptForm.parentDeptId}>
              {subDeptSaving ? 'Creating...' : 'Create Sub-Department'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* ── Assign User Dialog ── */}
      <Dialog open={assignDialog} onOpenChange={setAssignDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Assign to "{assignTarget?.title}"
              {assignTarget?.branchId && (
                <span className="text-sm font-normal text-cyan-600 ml-2">
                  [{assignTarget.branchId.code}]
                </span>
              )}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <p className="text-sm text-muted-foreground">
              {(assignTarget?.maxHeadcount || 1) - (assignTarget?.filledBy?.length || 0)} slot(s) available
            </p>
            <div className="space-y-1">
              <Label>Select Person</Label>
              <Select value={assignUserId} onValueChange={setAssignUserId}>
                <SelectTrigger><SelectValue placeholder="Choose a person..." /></SelectTrigger>
                <SelectContent>
                  {allUsers
                    .filter(u => !assignTarget?.filledBy?.find(f => f.id === u.id))
                    .map(u => (
                      <SelectItem key={u.id} value={u.id}>
                        {u.name} — {u.designation || u.role.replace(/_/g, ' ')} {u.userId ? `(${u.userId})` : ''}
                      </SelectItem>
                    ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setAssignDialog(false)}>Cancel</Button>
            <Button onClick={handleAssign} disabled={saving || !assignUserId}>
              {saving ? 'Assigning...' : 'Assign'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Edit, Trash2, Building2, Calendar, Shield } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { toast } from 'sonner';
import api from '@/lib/api';

interface Organization {
  id: string;
  name: string;
  email: string;
  phone: string;
  address: string;
  status: string;
  licenseId?: any;
  licenseExpiry?: string;
  createdAt: string;
}

export function OrganizationsPanel() {
  const [organizations, setOrganizations] = useState<Organization[]>([]);
  const [loading, setLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const [editingOrg, setEditingOrg] = useState<Organization | null>(null);
  const [deletingOrg, setDeletingOrg] = useState<Organization | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    address: '',
  });

  useEffect(() => {
    fetchOrganizations();
  }, []);

  const fetchOrganizations = async () => {
    try {
      setLoading(true);
      console.log('Fetching organizations...');
      const response = await api.get('/organizations');
      console.log('Organizations response:', response.data);
      setOrganizations(response.data.data || []);
    } catch (error: any) {
      console.error('Fetch error:', error);
      toast.error('Failed to fetch organizations');
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = () => {
    setEditingOrg(null);
    setFormData({ name: '', email: '', phone: '', address: '' });
    setIsDialogOpen(true);
  };

  const handleEdit = (org: Organization) => {
    setEditingOrg(org);
    setFormData({
      name: org.name,
      email: org.email,
      phone: org.phone,
      address: org.address,
    });
    setIsDialogOpen(true);
  };

  const handleDelete = (org: Organization) => {
    setDeletingOrg(org);
    setIsDeleteDialogOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      if (editingOrg) {
        // Update existing organization
        console.log('Updating organization:', editingOrg.id, formData);
        const response = await api.put(`/organizations/${editingOrg.id}`, formData);
        console.log('Update response:', response);
        toast.success('Organization updated successfully');
      } else {
        // Create new organization
        console.log('Creating organization:', formData);
        const response = await api.post('/organizations', formData);
        console.log('Create response:', response);
        toast.success('Organization created successfully');
      }

      setIsDialogOpen(false);
      fetchOrganizations();
    } catch (error: any) {
      console.error('Error details:', error);
      console.error('Error response:', error.response);
      toast.error(error.response?.data?.message || 'Operation failed');
    }
  };

  const confirmDelete = async () => {
    if (!deletingOrg) return;

    try {
      await api.delete(`/organizations/${deletingOrg.id}`);
      toast.success('Organization deleted successfully');
      setIsDeleteDialogOpen(false);
      fetchOrganizations();
    } catch (error: any) {
      toast.error(error.response?.data?.message || 'Failed to delete organization');
      console.error(error);
    }
  };

  if (loading) {
    return (
      <div className="p-8">
        <div className="h-64 bg-muted rounded-xl animate-pulse" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold tracking-tight">Organizations</h2>
          <p className="text-muted-foreground text-sm">
            Manage all organizations in the system
          </p>
        </div>
        <Button onClick={handleCreate}>
          <Plus className="w-4 h-4 mr-2" />
          New Organization
        </Button>
      </div>

      {/* Organizations Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {organizations.map((org) => (
          <Card key={org.id} className="hover:shadow-lg transition-shadow">
            <CardHeader className="pb-3">
              <div className="flex items-start justify-between">
                <div className="flex items-center gap-3">
                  <div className="p-2 rounded-lg bg-primary/10">
                    <Building2 className="w-5 h-5 text-primary" />
                  </div>
                  <div>
                    <CardTitle className="text-lg">{org.name}</CardTitle>
                    <Badge
                      variant={org.status === 'active' ? 'default' : 'secondary'}
                      className="mt-1"
                    >
                      {org.status}
                    </Badge>
                  </div>
                </div>
              </div>
            </CardHeader>
            <CardContent className="space-y-3">
              <div className="space-y-2 text-sm">
                <div className="flex items-center gap-2 text-muted-foreground">
                  <span className="font-medium">Email:</span>
                  <span className="truncate">{org.email}</span>
                </div>
                <div className="flex items-center gap-2 text-muted-foreground">
                  <span className="font-medium">Phone:</span>
                  <span>{org.phone}</span>
                </div>
                {org.licenseId && (
                  <div className="flex items-center gap-2 text-muted-foreground">
                    <Shield className="w-3 h-3" />
                    <span className="text-xs">
                      {org.licenseId.name || 'Licensed'}
                    </span>
                  </div>
                )}
                {org.licenseExpiry && (
                  <div className="flex items-center gap-2 text-muted-foreground">
                    <Calendar className="w-3 h-3" />
                    <span className="text-xs">
                      Expires: {new Date(org.licenseExpiry).toLocaleDateString()}
                    </span>
                  </div>
                )}
              </div>

              <div className="flex gap-2 pt-3 border-t">
                <Button
                  variant="outline"
                  size="sm"
                  className="flex-1"
                  onClick={() => handleEdit(org)}
                >
                  <Edit className="w-3 h-3 mr-2" />
                  Edit
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  className="flex-1 text-destructive hover:text-destructive"
                  onClick={() => handleDelete(org)}
                >
                  <Trash2 className="w-3 h-3 mr-2" />
                  Delete
                </Button>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {organizations.length === 0 && (
        <Card>
          <CardContent className="flex flex-col items-center justify-center py-12">
            <Building2 className="w-12 h-12 text-muted-foreground mb-4" />
            <h3 className="text-lg font-semibold mb-2">No organizations found</h3>
            <p className="text-muted-foreground text-sm mb-4">
              Get started by creating your first organization
            </p>
            <Button onClick={handleCreate}>
              <Plus className="w-4 h-4 mr-2" />
              Create Organization
            </Button>
          </CardContent>
        </Card>
      )}

      {/* Create/Edit Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              {editingOrg ? 'Edit Organization' : 'Create New Organization'}
            </DialogTitle>
            <DialogDescription>
              {editingOrg
                ? 'Update the organization details below'
                : 'Fill in the details to create a new organization'}
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={handleSubmit}>
            <div className="space-y-4 py-4">
              <div className="space-y-2">
                <Label htmlFor="name">Organization Name *</Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  placeholder="Enter organization name"
                  required
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="email">Email *</Label>
                <Input
                  id="email"
                  type="email"
                  value={formData.email}
                  onChange={(e) =>
                    setFormData({ ...formData, email: e.target.value })
                  }
                  placeholder="contact@organization.com"
                  required
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="phone">Phone *</Label>
                <Input
                  id="phone"
                  value={formData.phone}
                  onChange={(e) =>
                    setFormData({ ...formData, phone: e.target.value })
                  }
                  placeholder="+1234567890"
                  required
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="address">Address *</Label>
                <Input
                  id="address"
                  value={formData.address}
                  onChange={(e) =>
                    setFormData({ ...formData, address: e.target.value })
                  }
                  placeholder="123 Street, City, Country"
                  required
                />
              </div>
            </div>
            <DialogFooter>
              <Button
                type="button"
                variant="outline"
                onClick={() => setIsDialogOpen(false)}
              >
                Cancel
              </Button>
              <Button type="submit">
                {editingOrg ? 'Update' : 'Create'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <Dialog open={isDeleteDialogOpen} onOpenChange={setIsDeleteDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Delete Organization</DialogTitle>
            <DialogDescription>
              Are you sure you want to delete "{deletingOrg?.name}"? This action
              cannot be undone and will remove all associated data.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setIsDeleteDialogOpen(false)}
            >
              Cancel
            </Button>
            <Button variant="destructive" onClick={confirmDelete}>
              Delete
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Edit, Trash2, IndianRupee } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import api from '@/lib/api';

export function PaymentsPanel() {
  const [payments, setPayments] = useState<any[]>([]);
  const [invoices, setInvoices] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    invoiceId: '',
    amount: '',
    method: 'cash',
    referenceNo: ''
  });

  useEffect(() => {
    fetchPayments();
    fetchInvoices();
  }, []);

  const fetchPayments = async () => {
    setLoading(true);
    try {
      const response = await api.get('/finance/payments');
      setPayments(response.data.data || []);
    } catch (error) {
      console.error('Failed to fetch payments:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchInvoices = async () => {
    try {
      const response = await api.get('/finance/invoices');
      setInvoices(response.data.data || []);
    } catch (error) {
      console.error('Failed to fetch invoices:', error);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (editingId) {
        await api.put(`/finance/payments/${editingId}`, formData);
      } else {
        await api.post('/finance/payments', formData);
      }
      setDialogOpen(false);
      resetForm();
      fetchPayments();
    } catch (error: any) {
      console.error('Failed to save payment:', error);
      alert(error.response?.data?.message || 'Failed to save payment');
    }
  };

  const handleEdit = (payment: any) => {
    const paymentId = payment.id || payment.id;
    const rawInvoice = payment.invoiceId;
    const invoiceId = typeof rawInvoice === 'object' && rawInvoice !== null
      ? (rawInvoice.id || rawInvoice.id)
      : rawInvoice;
    setEditingId(paymentId);
    setFormData({
      invoiceId: invoiceId?.toString() || '',
      amount: payment.amount?.toString() || '',
      method: payment.method || 'cash',
      referenceNo: payment.referenceNo || ''
    });
    setDialogOpen(true);
  };

  const handleDelete = async (id: string) => {
    const remarks = prompt('Enter deletion remarks (required for audit):');
    if (!remarks) return;
    try {
      await api.delete(`/finance/payments/${id}`, { data: { remarks } });
      fetchPayments();
    } catch (error) {
      console.error('Failed to delete payment:', error);
    }
  };

  const resetForm = () => {
    setEditingId(null);
    setFormData({
      invoiceId: '',
      amount: '',
      method: 'cash',
      referenceNo: ''
    });
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Payment Management</h2>
          <p className="text-muted-foreground">Track and manage payment entries</p>
        </div>
        <Dialog open={dialogOpen} onOpenChange={(open) => { setDialogOpen(open); if (!open) resetForm(); }}>
          <DialogTrigger asChild>
            <Button><Plus className="w-4 h-4 mr-2" />Add Payment</Button>
          </DialogTrigger>
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <DialogTitle>{editingId ? 'Edit Payment' : 'Add New Payment'}</DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <Label>Invoice</Label>
                <Select value={formData.invoiceId} onValueChange={(value) => setFormData({...formData, invoiceId: value})}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select invoice" />
                  </SelectTrigger>
                  <SelectContent>
                    {invoices.filter(inv => inv && (inv.id || inv.id)).map((inv) => (
                      <SelectItem key={inv.id || inv.id} value={(inv.id || inv.id).toString()}>
                        {inv.invoiceNo || inv.id} - ₹{inv.total || inv.amount}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Amount</Label>
                  <Input type="number" value={formData.amount} onChange={(e) => setFormData({...formData, amount: e.target.value})} required />
                </div>
                <div>
                  <Label>Payment Method</Label>
                  <Select value={formData.method} onValueChange={(value) => setFormData({...formData, method: value})}>
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="cash">Cash</SelectItem>
                      <SelectItem value="cheque">Cheque</SelectItem>
                      <SelectItem value="bank_transfer">Bank Transfer</SelectItem>
                      <SelectItem value="upi">UPI</SelectItem>
                      <SelectItem value="card">Card</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <div>
                <Label>Reference No</Label>
                <Input value={formData.referenceNo} onChange={(e) => setFormData({...formData, referenceNo: e.target.value})} />
              </div>
              <div className="flex gap-2">
                <Button type="submit" className="flex-1">Save</Button>
                <Button type="button" variant="outline" onClick={() => setDialogOpen(false)}>Cancel</Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Payments</CardTitle>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="text-center py-8">Loading...</div>
          ) : payments.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">No payments found</div>
          ) : (
            <div className="space-y-2">
              {payments.filter(payment => payment && (payment.id || payment.id)).map((payment) => {
                const paymentId = payment.id || payment.id;
                return (
                  <div key={paymentId} className="flex items-center justify-between p-4 border rounded-lg hover:bg-muted/50">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-full bg-success/10 flex items-center justify-center">
                        <IndianRupee className="w-6 h-6 text-success" />
                      </div>
                      <div className="flex-1">
                        <div className="font-medium">₹{payment.amount}</div>
                        <div className="text-sm text-muted-foreground">
                          {payment.method} • {payment.referenceNo || 'No reference'}
                        </div>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <Button variant="ghost" size="sm" onClick={() => handleEdit(payment)}>
                        <Edit className="w-4 h-4" />
                      </Button>
                      <Button variant="ghost" size="sm" onClick={() => handleDelete(paymentId)}>
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
