import { useState, useEffect } from 'react';
import { Plus, Trash2, RefreshCw, BarChart2, CheckCircle } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Switch } from '@/components/ui/switch';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { toast } from 'sonner';
import api from '@/lib/api';
import { useAuth } from '@/hooks/useAuth';

interface PollOption {
  text: string;
  votes: string[];
}

interface Poll {
  id: string;
  question: string;
  options: PollOption[];
  createdBy?: { name: string };
  expiresAt?: string;
  isActive: boolean;
  allowMultiple: boolean;
  createdAt: string;
}

export function PollsPanel() {
  const { user } = useAuth();
  const isHR = user?.role === 'hr_admin';
  const [polls, setPolls] = useState<Poll[]>([]);
  const [loading, setLoading] = useState(false);
  const [createOpen, setCreateOpen] = useState(false);
  const [votedPolls, setVotedPolls] = useState<Record<string, number[]>>({});

  const [form, setForm] = useState({
    question: '',
    options: ['', ''],
    expiresAt: '',
    allowMultiple: false,
  });

  useEffect(() => { fetchPolls(); }, []);

  const fetchPolls = async () => {
    setLoading(true);
    try {
      const res = await api.get('/hr/polls');
      setPolls(res.data.data || []);
    } catch { toast.error('Failed to load polls'); }
    finally { setLoading(false); }
  };

  const handleCreate = async () => {
    const opts = form.options.filter(o => o.trim());
    if (!form.question.trim() || opts.length < 2) {
      toast.error('Question and at least 2 options required');
      return;
    }
    try {
      await api.post('/hr/polls', {
        question: form.question,
        options: opts,
        expiresAt: form.expiresAt || undefined,
        allowMultiple: form.allowMultiple,
      });
      toast.success('Poll created');
      setCreateOpen(false);
      setForm({ question: '', options: ['', ''], expiresAt: '', allowMultiple: false });
      fetchPolls();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to create poll');
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this poll?')) return;
    try {
      await api.delete(`/hr/polls/${id}`);
      toast.success('Poll deleted');
      fetchPolls();
    } catch { toast.error('Failed to delete'); }
  };

  const handleToggleActive = async (poll: Poll) => {
    try {
      await api.put(`/hr/polls/${poll.id}`, { isActive: !poll.isActive });
      fetchPolls();
    } catch { toast.error('Failed to update'); }
  };

  const handleVote = async (pollId: string, optionIndex: number) => {
    const current = votedPolls[pollId] || [];
    const poll = polls.find(p => p.id === pollId);
    if (!poll) return;

    let newIndexes: number[];
    if (poll.allowMultiple) {
      newIndexes = current.includes(optionIndex)
        ? current.filter(i => i !== optionIndex)
        : [...current, optionIndex];
    } else {
      newIndexes = [optionIndex];
    }

    try {
      await api.post(`/hr/polls/${pollId}/vote`, { optionIndexes: newIndexes });
      setVotedPolls(prev => ({ ...prev, [pollId]: newIndexes }));
      fetchPolls();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to vote');
    }
  };

  const totalVotes = (poll: Poll) => poll.options.reduce((s, o) => s + o.votes.length, 0);
  const pct = (votes: number, total: number) => total === 0 ? 0 : Math.round((votes / total) * 100);
  const hasVoted = (poll: Poll) => {
    const uid = user?.id || (user as any)?.id;
    return poll.options.some(o => o.votes.includes(uid));
  };
  const myVotes = (poll: Poll) => {
    const uid = user?.id || (user as any)?.id;
    return poll.options.map((o, i) => o.votes.includes(uid) ? i : -1).filter(i => i >= 0);
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Polls</h2>
          <p className="text-muted-foreground text-sm">
            {isHR ? 'Create polls for all employees to vote on' : 'Vote on active polls from HR'}
          </p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={fetchPolls}>
            <RefreshCw className="w-4 h-4 mr-1" /> Refresh
          </Button>
          {isHR && (
            <Button size="sm" onClick={() => setCreateOpen(true)}>
              <Plus className="w-4 h-4 mr-1" /> Create Poll
            </Button>
          )}
        </div>
      </div>

      {loading ? (
        <div className="space-y-4">{[1,2].map(i => <div key={i} className="h-40 bg-muted rounded-xl animate-pulse" />)}</div>
      ) : polls.length === 0 ? (
        <Card>
          <CardContent className="py-16 text-center text-muted-foreground">
            <BarChart2 className="w-10 h-10 mx-auto mb-3 opacity-30" />
            <p>No polls yet</p>
            {isHR && <p className="text-xs mt-1">Create a poll to gather employee feedback</p>}
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-4">
          {polls.map(poll => {
            const total = totalVotes(poll);
            const voted = hasVoted(poll);
            const myVoteIdxs = myVotes(poll);
            const expired = poll.expiresAt && new Date(poll.expiresAt) < new Date();
            const canVote = poll.isActive && !expired;

            return (
              <Card key={poll.id} className={!poll.isActive || expired ? 'opacity-60' : ''}>
                <CardHeader className="pb-3">
                  <div className="flex items-start justify-between gap-3">
                    <div className="flex-1">
                      <CardTitle className="text-base">{poll.question}</CardTitle>
                      <div className="flex flex-wrap gap-2 mt-1">
                        <Badge variant={poll.isActive && !expired ? 'default' : 'secondary'} className="text-xs">
                          {expired ? 'Expired' : poll.isActive ? 'Active' : 'Closed'}
                        </Badge>
                        {poll.allowMultiple && <Badge variant="outline" className="text-xs">Multi-choice</Badge>}
                        {poll.expiresAt && (
                          <span className="text-xs text-muted-foreground">
                            Expires {new Date(poll.expiresAt).toLocaleDateString()}
                          </span>
                        )}
                        <span className="text-xs text-muted-foreground">{total} vote{total !== 1 ? 's' : ''}</span>
                      </div>
                    </div>
                    {isHR && (
                      <div className="flex items-center gap-2 shrink-0">
                        <Switch checked={poll.isActive} onCheckedChange={() => handleToggleActive(poll)} />
                        <Button variant="ghost" size="sm" onClick={() => handleDelete(poll.id)}>
                          <Trash2 className="w-4 h-4 text-destructive" />
                        </Button>
                      </div>
                    )}
                  </div>
                </CardHeader>
                <CardContent className="space-y-2">
                  {poll.options.map((opt, idx) => {
                    const isMyVote = myVoteIdxs.includes(idx);
                    const optPct = pct(opt.votes.length, total);
                    return (
                      <div key={idx}>
                        <button
                          className={`w-full text-left p-3 rounded-lg border transition-colors relative overflow-hidden ${
                            isMyVote
                              ? 'border-primary bg-primary/5'
                              : canVote && !voted
                              ? 'hover:border-primary/50 hover:bg-muted/50'
                              : 'cursor-default'
                          }`}
                          onClick={() => canVote ? handleVote(poll.id, idx) : undefined}
                          disabled={!canVote && !voted}
                        >
                          {/* Progress bar background */}
                          {(voted || !canVote) && (
                            <div
                              className="absolute inset-0 bg-primary/10 rounded-lg transition-all"
                              style={{ width: `${optPct}%` }}
                            />
                          )}
                          <div className="relative flex items-center justify-between">
                            <div className="flex items-center gap-2">
                              {isMyVote && <CheckCircle className="w-4 h-4 text-primary shrink-0" />}
                              <span className="text-sm font-medium">{opt.text}</span>
                            </div>
                            {(voted || !canVote) && (
                              <span className="text-xs font-semibold text-muted-foreground">
                                {optPct}% ({opt.votes.length})
                              </span>
                            )}
                          </div>
                        </button>
                      </div>
                    );
                  })}
                  {canVote && !voted && (
                    <p className="text-xs text-muted-foreground pt-1">Click an option to vote</p>
                  )}
                  {voted && canVote && (
                    <p className="text-xs text-primary pt-1">You voted — click another option to change your vote</p>
                  )}
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Create Poll Dialog */}
      <Dialog open={createOpen} onOpenChange={setCreateOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader><DialogTitle>Create Poll</DialogTitle></DialogHeader>
          <div className="space-y-4 pt-2">
            <div className="space-y-1">
              <Label>Question</Label>
              <Input
                value={form.question}
                onChange={e => setForm(f => ({ ...f, question: e.target.value }))}
                placeholder="What would you like to ask?"
              />
            </div>
            <div className="space-y-2">
              <Label>Options</Label>
              {form.options.map((opt, idx) => (
                <div key={idx} className="flex gap-2">
                  <Input
                    value={opt}
                    onChange={e => {
                      const opts = [...form.options];
                      opts[idx] = e.target.value;
                      setForm(f => ({ ...f, options: opts }));
                    }}
                    placeholder={`Option ${idx + 1}`}
                  />
                  {form.options.length > 2 && (
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={() => setForm(f => ({ ...f, options: f.options.filter((_, i) => i !== idx) }))}
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  )}
                </div>
              ))}
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => setForm(f => ({ ...f, options: [...f.options, ''] }))}
              >
                <Plus className="w-4 h-4 mr-1" /> Add Option
              </Button>
            </div>
            <div className="space-y-1">
              <Label>Expires On (optional)</Label>
              <Input
                type="date"
                value={form.expiresAt}
                onChange={e => setForm(f => ({ ...f, expiresAt: e.target.value }))}
              />
            </div>
            <div className="flex items-center gap-3">
              <Switch
                checked={form.allowMultiple}
                onCheckedChange={v => setForm(f => ({ ...f, allowMultiple: v }))}
              />
              <Label>Allow multiple choices</Label>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setCreateOpen(false)}>Cancel</Button>
            <Button onClick={handleCreate}>Create Poll</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { RefreshCw, TrendingUp, TrendingDown } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { ResponsiveContainer, AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip } from 'recharts';
import { cn } from '@/lib/utils';
import api from '@/lib/api';
import { toast } from 'sonner';

interface MonthlyRow {
  month: string;
  income: { total: number };
  expenditure: { total: number };
  net: number;
}

interface ReportData {
  period: { from: string; to: string };
  monthly: MonthlyRow[];
  totals: { income: number; expenditure: number; netProfit: number; profitMargin: number };
  incomeBreakdown: { invoices: number; enrollments: number; payments: number };
  expenditureBreakdown: { salaries: number; expenses: number; byCategory: { id: string; amount: number }[] };
}

const fmt = (n: number) =>
  n >= 100000 ? `₹${(n / 100000).toFixed(2)}L` :
  n >= 1000 ? `₹${(n / 1000).toFixed(1)}K` : `₹${n.toLocaleString()}`;

const fmtMonth = (m: string) => {
  const [y, mo] = m.split('-');
  return new Date(+y, +mo - 1).toLocaleString('default', { month: 'short', year: '2-digit' });
};

export function ProfitLossPanel() {
  const [data, setData] = useState<ReportData | null>(null);
  const [loading, setLoading] = useState(false);
  const [from, setFrom] = useState(() => {
    const now = new Date();
    const yr = now.getMonth() >= 3 ? now.getFullYear() : now.getFullYear() - 1;
    return `${yr}-04-01`;
  });
  const [to, setTo] = useState(() => new Date().toISOString().slice(0, 10));

  const fetchReport = async () => {
    setLoading(true);
    try {
      const res = await api.get(`/finance/reports/income-expenditure?from=${from}&to=${to}`);
      setData(res.data.data);
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to load report');
    } finally {
      setLoading(false);
    }
  };

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { fetchReport(); }, []);

  const isProfit = (data?.totals.netProfit ?? 0) >= 0;

  const chartData = data?.monthly.map(m => ({
    name: fmtMonth(m.month),
    Revenue: m.income.total,
    Costs: m.expenditure.total,
    'Net P&L': m.net,
  })) || [];

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h2 className="text-2xl font-bold">Profit & Loss Account</h2>
          <p className="text-muted-foreground text-sm mt-1">Financial performance summary for the selected period.</p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <input type="date" value={from} onChange={e => setFrom(e.target.value)}
            className="h-8 px-2 text-sm rounded-lg border border-border bg-background" />
          <span className="text-muted-foreground text-sm">to</span>
          <input type="date" value={to} onChange={e => setTo(e.target.value)}
            className="h-8 px-2 text-sm rounded-lg border border-border bg-background" />
          <Button size="sm" onClick={fetchReport} disabled={loading}>
            <RefreshCw className={cn('w-4 h-4 mr-2', loading && 'animate-spin')} />Apply
          </Button>
        </div>
      </div>

      {/* P&L Statement Card */}
      {data && (
        <Card className={cn('border-2', isProfit ? 'border-green-200 dark:border-green-800' : 'border-red-200 dark:border-red-800')}>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              {isProfit
                ? <TrendingUp className="w-5 h-5 text-green-600" />
                : <TrendingDown className="w-5 h-5 text-red-500" />}
              Profit & Loss Statement
              <span className="text-sm font-normal text-muted-foreground ml-2">
                {new Date(data.period.from).toLocaleDateString()} – {new Date(data.period.to).toLocaleDateString()}
              </span>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-0 divide-y divide-border">
              {/* INCOME section */}
              <PLSection title="INCOME" isHeader />
              <PLRow label="Invoice Revenue" amount={data.incomeBreakdown.invoices} indent={1} />
              <PLRow label="Enrollment Fees" amount={data.incomeBreakdown.enrollments} indent={1} />
              <PLRow label="Payment Entries" amount={data.incomeBreakdown.payments} indent={1} />
              <PLRow label="Gross Income" amount={data.totals.income} bold positive />

              {/* EXPENDITURE section */}
              <PLSection title="EXPENDITURE" isHeader />
              <PLRow label="Salaries & Payroll" amount={data.expenditureBreakdown.salaries} indent={1} />
              <PLRow label="Operational Expenses" amount={data.expenditureBreakdown.expenses} indent={1} />
              {data.expenditureBreakdown.byCategory.map(c => (
                <PLRow key={c.id} label={c.id} amount={c.amount} indent={2} muted />
              ))}
              <PLRow label="Total Expenditure" amount={data.totals.expenditure} bold negative />

              {/* NET */}
              <div className={cn(
                'flex items-center justify-between p-4 rounded-xl mt-2',
                isProfit ? 'bg-green-50 dark:bg-green-900/20' : 'bg-red-50 dark:bg-red-900/20'
              )}>
                <div>
                  <p className={cn('text-lg font-bold', isProfit ? 'text-green-700 dark:text-green-400' : 'text-red-600 dark:text-red-400')}>
                    {isProfit ? 'Net Profit' : 'Net Loss'}
                  </p>
                  <p className="text-xs text-muted-foreground">Profit margin: {data.totals.profitMargin}%</p>
                </div>
                <p className={cn('text-3xl font-bold', isProfit ? 'text-green-700 dark:text-green-400' : 'text-red-600 dark:text-red-400')}>
                  {isProfit ? '+' : '-'}{fmt(Math.abs(data.totals.netProfit))}
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Area Chart */}
      <Card>
        <CardHeader>
          <CardTitle>Revenue vs Costs — Monthly Trend</CardTitle>
        </CardHeader>
        <CardContent className="h-64">
          {loading ? (
            <div className="h-full flex items-center justify-center">
              <RefreshCw className="w-6 h-6 animate-spin text-muted-foreground" />
            </div>
          ) : chartData.length === 0 ? (
            <div className="h-full flex items-center justify-center text-muted-foreground text-sm">No data for selected period</div>
