          </div>
        </TabsContent>

        {/* Invite Links */}
        <TabsContent value="invite_links">
          <div className="space-y-4">
            <div className="flex justify-end">
              <Button onClick={() => setOpen(true)}>
                <Plus className="w-4 h-4 mr-2" />Generate Invite Link
              </Button>
            </div>
            {invites.length === 0 ? (
              <Card><CardContent className="py-12 text-center text-muted-foreground">
                <Link className="w-10 h-10 mx-auto mb-3 opacity-20" />
                <p>No invite links yet. Generate one to get started.</p>
              </CardContent></Card>
            ) : (
              <div className="space-y-3">
                {invites.map(inv => (
                  <Card key={inv.id} className="hover:border-primary/30 transition-colors">
                    <CardContent className="p-4 flex items-center justify-between gap-4">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 flex-wrap mb-1">
                          <Badge className={cn('text-[10px] uppercase font-bold', STATUS_COLOR[inv.status])}>{inv.status}</Badge>
                          <span className="text-xs text-muted-foreground">Expires: {new Date(inv.expiresAt).toLocaleDateString()}</span>
                        </div>
                        <p className="text-sm font-mono text-muted-foreground truncate">{inv.token.substring(0, 28)}...</p>
                        <div className="flex flex-wrap gap-1 mt-1">
                          {(inv.universityIds || []).map((u: any) => (
                            <Badge key={u.id || u} variant="outline" className="text-[10px]">{u.name || u}</Badge>
                          ))}
                        </div>
                      </div>
                      {inv.status === 'pending' && (
                        <Button variant="outline" size="sm" onClick={() => copyLink(inv)}>
                          {copied === inv.id ? <Check className="w-4 h-4 text-success" /> : <Copy className="w-4 h-4" />}
                        </Button>
                      )}
                    </CardContent>
                  </Card>
                ))}
              </div>
            )}
          </div>
        </TabsContent>

        {/* Universities */}
        <TabsContent value="universities">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {universities.length === 0 ? (
              <p className="text-muted-foreground col-span-3 text-center py-8">No universities assigned to your sub-department</p>
            ) : universities.map((u: any) => (
              <Card key={u.id} className="hover:border-primary/30 transition-colors">
                <CardContent className="p-4 flex items-start gap-3">
                  <div className="p-2 rounded-lg bg-primary/10 text-primary shrink-0"><Building2 className="w-4 h-4" /></div>
                  <div>
                    <p className="font-semibold text-sm">{u.name}</p>
                    <p className="text-xs text-muted-foreground">{u.code}</p>
                    <Badge variant="outline" className={cn('text-[9px] mt-1 uppercase', u.status === 'active' ? 'text-success border-success/30' : 'text-muted-foreground')}>
                      {u.status || 'active'}
                    </Badge>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        </TabsContent>

        {/* Study Centers */}
        <TabsContent value="centers">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {centers.length === 0 ? (
              <p className="text-muted-foreground col-span-3 text-center py-8">No study centers assigned</p>
            ) : centers.map((c: any) => {
              const stats = centerEnrollMap[c.id?.toString()] || { total: 0, enrolled: 0, pending: 0 };
              return (
                <Card key={c.id} className="hover:border-primary/30 transition-colors">
                  <CardContent className="p-4">
                    <div className="flex items-start justify-between mb-3">
                      <div>
                        <p className="font-semibold text-sm">{c.name}</p>
                        <p className="text-xs text-muted-foreground">{c.code} · {c.city}, {c.state}</p>
                      </div>
                      <Badge variant="outline" className={cn('text-[9px] uppercase', c.status === 'active' ? 'text-success border-success/30' : 'text-muted-foreground')}>
                        {c.status}
                      </Badge>
                    </div>
                    <div className="grid grid-cols-3 gap-2 text-center">
                      <div className="bg-muted/40 rounded-lg p-2">
                        <p className="text-xs text-muted-foreground">Total</p>
                        <p className="font-bold text-sm">{stats.total}</p>
                      </div>
                      <div className="bg-success/10 rounded-lg p-2">
                        <p className="text-xs text-success">Enrolled</p>
                        <p className="font-bold text-sm text-success">{stats.enrolled}</p>
                      </div>
                      <div className="bg-warning/10 rounded-lg p-2">
                        <p className="text-xs text-warning">Pending</p>
                        <p className="font-bold text-sm text-warning">{stats.pending}</p>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              );
            })}
          </div>
        </TabsContent>

        {/* Enrollments */}
        <TabsContent value="enrollments" className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <Card><CardContent className="p-5">
              <p className="text-xs text-muted-foreground uppercase font-medium">Total Applications</p>
              <p className="text-3xl font-bold mt-1">{totalAll}</p>
            </CardContent></Card>
            <Card><CardContent className="p-5">
              <p className="text-xs text-muted-foreground uppercase font-medium">Enrolled</p>
              <p className="text-3xl font-bold mt-1 text-success">{totalEnrolled}</p>
              <p className="text-[10px] text-muted-foreground">{totalAll > 0 ? Math.round((totalEnrolled/totalAll)*100) : 0}% conversion</p>
            </CardContent></Card>
            <Card><CardContent className="p-5">
              <p className="text-xs text-muted-foreground uppercase font-medium">Pending</p>
              <p className="text-3xl font-bold mt-1 text-warning">{totalPending}</p>
            </CardContent></Card>
          </div>
          <Card className="border-none shadow-xl bg-card/60 backdrop-blur-xl">
            <CardHeader>
              <CardTitle>Monthly Enrollment Trend</CardTitle>
              <CardDescription>Applications vs enrolled — last 6 months</CardDescription>
            </CardHeader>
            <CardContent className="h-[260px]">
              {chartData.length === 0 ? (
                <div className="h-full flex items-center justify-center text-muted-foreground text-sm">No data yet</div>
              ) : (
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData} margin={{ top: 5, right: 20, left: 0, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="hsl(var(--border))" />
                    <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fill: 'hsl(var(--muted-foreground))', fontSize: 12 }} />
                    <YAxis axisLine={false} tickLine={false} tick={{ fill: 'hsl(var(--muted-foreground))', fontSize: 12 }} allowDecimals={false} />
                    <Tooltip contentStyle={{ backgroundColor: 'hsl(var(--card))', border: '1px solid hsl(var(--border))', borderRadius: '12px' }} />
                    <Bar dataKey="total" name="Applications" radius={[4,4,0,0]} barSize={32} fill="hsl(var(--primary))" opacity={0.35} />
                    <Bar dataKey="enrolled" name="Enrolled" radius={[4,4,0,0]} barSize={32} fill="hsl(var(--primary))" />
                  </BarChart>
                </ResponsiveContainer>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Generate invite dialog */}
      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent>
          <DialogHeader><DialogTitle>Generate Invite Link</DialogTitle></DialogHeader>
          <div className="space-y-4 py-2">
            <Label>Select Universities (assigned to your sub-department)</Label>
            {universities.length === 0 ? (
              <p className="text-sm text-muted-foreground">No universities assigned to your sub-department.</p>
            ) : (
              <div className="space-y-2 max-h-60 overflow-y-auto">
                {universities.map((u: any) => (
                  <div key={u.id} className="flex items-center gap-3 p-2 rounded-lg hover:bg-muted/50">
                    <Checkbox id={u.id} checked={selected.includes(u.id)} onCheckedChange={() => toggleUniversity(u.id)} />
                    <label htmlFor={u.id} className="text-sm cursor-pointer flex-1">
                      {u.name} <span className="text-muted-foreground text-xs">({u.code})</span>
                    </label>
                  </div>
                ))}
              </div>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => { setOpen(false); setSelected([]); }}>Cancel</Button>
            <Button onClick={handleGenerate} disabled={submitting || selected.length === 0}>
              {submitting ? 'Generating...' : 'Generate & Copy Link'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

function StatCard({ icon, label, value, color, sub }: any) {
  const colorMap: any = {
    primary: 'bg-primary/10 text-primary',
    info: 'bg-info/10 text-info',
    success: 'bg-success/10 text-success',
    warning: 'bg-warning/10 text-warning',
  };
  return (
    <Card>
      <CardContent className="p-5 flex items-center gap-3">
        <div className={cn('p-2.5 rounded-xl shrink-0', colorMap[color])}>{icon}</div>
        <div>
          <p className="text-xs text-muted-foreground uppercase font-medium">{label}</p>
          <p className="text-2xl font-bold">{value}</p>
          {sub && <p className="text-[10px] text-muted-foreground">{sub}</p>}
        </div>
      </CardContent>
    </Card>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Edit, Trash2, Target } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Progress } from '@/components/ui/progress';
import api from '@/lib/api';
import { toast } from 'sonner';
import { useAuth } from '@/hooks/useAuth';

interface TargetsPanelProps {
  endpoint: string; // '/finance/targets' or '/sales/targets'
  title?: string;
}

export function TargetsPanel({ endpoint, title = 'Target Management' }: TargetsPanelProps) {
  const { user } = useAuth();
  const canManage = user?.role === 'sales_admin' || user?.role === 'ceo' || user?.role === 'org_admin' || user?.role === 'superadmin';

  const [targets, setTargets] = useState<any[]>([]);
  const [employees, setEmployees] = useState<any[]>([]);
  const [departments, setDepartments] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    employeeId: '',
    departmentId: '',
    target: '',
    achieved: '0',
    period: 'monthly',
    type: 'revenue'
  });

  useEffect(() => {
    fetchTargets();
    fetchEmployees();
    fetchDepartments();
  }, []);

  const fetchTargets = async () => {
    setLoading(true);
    try {
      const res = await api.get(endpoint);
      setTargets(res.data.data || []);
    } catch (err) {
      console.error('Failed to fetch targets:', err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    try {
      const res = await api.get('/users');
      setEmployees(res.data.data || []);
    } catch (err) {
      console.error('Failed to fetch employees:', err);
    }
  };

  const fetchDepartments = async () => {
    try {
      const res = await api.get('/departments');
      setDepartments(res.data.data || []);
    } catch (err) {
      console.error('Failed to fetch departments:', err);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const payload: any = {
      target: Number(formData.target),
      achieved: Number(formData.achieved),
      period: formData.period,
      type: formData.type
    };
    if (formData.employeeId && formData.employeeId !== 'none') payload.employeeId = formData.employeeId;
    if (formData.departmentId && formData.departmentId !== 'none') payload.departmentId = formData.departmentId;

    try {
      if (editingId) {
        await api.put(`${endpoint}/${editingId}`, payload);
      } else {
        await api.post(endpoint, payload);
      }
      setDialogOpen(false);
      resetForm();
      fetchTargets();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to save target');
    }
  };

  const handleEdit = (t: any) => {
    const empId = typeof t.employeeId === 'object' ? (t.employeeId?.id || t.employeeId?.id) : t.employeeId;
    const deptId = typeof t.departmentId === 'object' ? (t.departmentId?.id || t.departmentId?.id) : t.departmentId;
    setEditingId(t.id || t.id);
    setFormData({
      employeeId: empId?.toString() || '',
      departmentId: deptId?.toString() || '',
      target: t.target?.toString() || '',
      achieved: t.achieved?.toString() || '0',
      period: t.period || 'monthly',
      type: t.type || 'revenue'
    });
    setDialogOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this target?')) return;
    try {
      await api.delete(`${endpoint}/${id}`);
      fetchTargets();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to delete target');
    }
  };

  const resetForm = () => {
    setEditingId(null);
    setFormData({ employeeId: '', departmentId: '', target: '', achieved: '0', period: 'monthly', type: 'revenue' });
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">{title}</h2>
          <p className="text-muted-foreground">Set and track performance targets</p>
        </div>
        <Dialog open={dialogOpen} onOpenChange={(open) => { setDialogOpen(open); if (!open) resetForm(); }}>
          {canManage && (
          <DialogTrigger asChild>
            <Button><Plus className="w-4 h-4 mr-2" />Add Target</Button>
          </DialogTrigger>
          )}
          <DialogContent className="max-w-lg">
            <DialogHeader>
              <DialogTitle>{editingId ? 'Edit Target' : 'Add New Target'}</DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Employee (optional)</Label>
                  <Select value={formData.employeeId} onValueChange={(v) => setFormData({ ...formData, employeeId: v })}>
                    <SelectTrigger><SelectValue placeholder="Select employee" /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="none">None</SelectItem>
                      {employees.filter(e => e && (e.id || e.id)).map((e) => (
                        <SelectItem key={e.id || e.id} value={(e.id || e.id).toString()}>
                          {e.name || e.email}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label>Department (optional)</Label>
                  <Select value={formData.departmentId} onValueChange={(v) => setFormData({ ...formData, departmentId: v })}>
                    <SelectTrigger><SelectValue placeholder="Select department" /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="none">None</SelectItem>
                      {departments.filter(d => d && (d.id || d.id)).map((d) => (
                        <SelectItem key={d.id || d.id} value={(d.id || d.id).toString()}>
                          {d.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Target Amount</Label>
                  <Input type="number" min="0" value={formData.target} onChange={(e) => setFormData({ ...formData, target: e.target.value })} required />
                </div>
                <div>
                  <Label>Achieved Amount</Label>
                  <Input type="number" min="0" value={formData.achieved} onChange={(e) => setFormData({ ...formData, achieved: e.target.value })} />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Period</Label>
                  <Select value={formData.period} onValueChange={(v) => setFormData({ ...formData, period: v })}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="weekly">Weekly</SelectItem>
                      <SelectItem value="monthly">Monthly</SelectItem>
                      <SelectItem value="quarterly">Quarterly</SelectItem>
                      <SelectItem value="yearly">Yearly</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label>Type</Label>
                  <Select value={formData.type} onValueChange={(v) => setFormData({ ...formData, type: v })}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="revenue">Revenue</SelectItem>
                      <SelectItem value="students">Students</SelectItem>
                      <SelectItem value="centers">Centers</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <div className="flex gap-2">
                <Button type="submit" className="flex-1">Save</Button>
                <Button type="button" variant="outline" onClick={() => setDialogOpen(false)}>Cancel</Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      <Card>
        <CardHeader><CardTitle>Targets</CardTitle></CardHeader>
        <CardContent>
          {loading ? (
            <div className="text-center py-8">Loading...</div>
          ) : targets.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">No targets found</div>
          ) : (
            <div className="space-y-4">
              {targets.filter(t => t && (t.id || t.id)).map((t) => {
                const tid = t.id || t.id;
                const pct = t.target ? Math.min(100, ((t.achieved || 0) / t.target) * 100) : 0;
                const empName = typeof t.employeeId === 'object' ? t.employeeId?.name : '';
                const deptName = typeof t.departmentId === 'object' ? t.departmentId?.name : '';
                return (
                  <div key={tid} className="p-4 border rounded-lg hover:bg-muted/50">
                    <div className="flex items-center justify-between mb-3">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center">
                          <Target className="w-5 h-5 text-primary" />
                        </div>
                        <div>
                          <div className="font-medium">{empName || deptName || 'General Target'}</div>
                          <div className="text-sm text-muted-foreground">{t.type} • {t.period}</div>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        {canManage && (
                          <>
                            <Button variant="ghost" size="sm" onClick={() => handleEdit(t)}><Edit className="w-4 h-4" /></Button>
                            <Button variant="ghost" size="sm" onClick={() => handleDelete(tid)}><Trash2 className="w-4 h-4" /></Button>
                          </>
                        )}
                      </div>
                    </div>
                    <div className="space-y-1">
                      <div className="flex justify-between text-sm">
                        <span>{t.achieved || 0} / {t.target}</span>
                        <span className="font-bold">{pct.toFixed(1)}%</span>
                      </div>
                      <Progress value={pct} />
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
