} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { useAuth } from '@/hooks/useAuth';
import api from '@/lib/api';

interface Task {
  id?: string;
  title: string;
  description: string;
  assignedTo: any;
  assignedBy: any;
  departmentId?: any;
  priority: string;
  status: string;
  deadline: string;
  completedAt?: string;
  remarks?: string;
  evidence?: string[];
}

interface SubUser {
  id: string;
  name: string;
  email: string;
  designation?: string;
  role?: string;
  departmentId?: string;
}

export function TasksPanel() {
  const { user } = useAuth();
  const [tasks, setTasks] = useState<Task[]>([]);
  const [subordinates, setSubordinates] = useState<SubUser[]>([]);
  const [loading, setLoading] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [completeDialogOpen, setCompleteDialogOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [completingTask, setCompletingTask] = useState<Task | null>(null);
  const [activeTab, setActiveTab] = useState('all');

  const [formData, setFormData] = useState({
    title: '',
    description: '',
    assignedTo: '',
    priority: 'medium',
    deadline: '',
  });

  const [completeData, setCompleteData] = useState({ remarks: '', files: null as FileList | null });

  useEffect(() => {
    fetchTasks();
    fetchSubordinates();
  }, []);

  const fetchTasks = async () => {
    setLoading(true);
    try {
      const res = await api.get('/tasks');
      setTasks(res.data.data || []);
    } catch (e) {
      console.error('Failed to fetch tasks:', e);
    } finally {
      setLoading(false);
    }
  };

  const fetchSubordinates = async () => {
    try {
      const res = await api.get('/tasks/assignable-users');
      setSubordinates(res.data.data || []);
    } catch (e) {
      console.error('Failed to fetch assignable users:', e);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.assignedTo) return;

    // Auto-derive departmentId from the selected subordinate
    const selectedUser = subordinates.find(s => s.id === formData.assignedTo);
    const payload: any = { ...formData };
    if (selectedUser?.departmentId) {
      payload.departmentId = selectedUser.departmentId;
    }

    try {
      if (editingTask) {
        await api.put(`/tasks/${editingTask.id || editingTask.id}`, payload);
      } else {
        await api.post('/tasks', payload);
      }
      setDialogOpen(false);
      resetForm();
      fetchTasks();
    } catch (e: any) {
      alert(e.response?.data?.message || 'Failed to save task.');
    }
  };

  const handleComplete = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!completingTask) return;
    try {
      const fd = new FormData();
      fd.append('remarks', completeData.remarks);
      if (completeData.files) {
        Array.from(completeData.files).forEach(f => fd.append('evidence', f));
      }
      await api.put(`/tasks/${completingTask.id || completingTask.id}/complete`, fd, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      setCompleteDialogOpen(false);
      setCompleteData({ remarks: '', files: null });
      setCompletingTask(null);
      fetchTasks();
    } catch (e: any) {
      alert(e.response?.data?.message || 'Failed to complete task.');
    }
  };

  const handleDelete = async (taskId: string) => {
    if (!confirm('Delete this task?')) return;
    try {
      await api.delete(`/tasks/${taskId}`);
      fetchTasks();
    } catch (e) {
      console.error('Failed to delete task:', e);
    }
  };

  const openEditDialog = (task: Task) => {
    setEditingTask(task);
    setFormData({
      title: task.title,
      description: task.description,
      assignedTo: task.assignedTo?.id || task.assignedTo?.id || task.assignedTo || '',
      priority: task.priority,
      deadline: task.deadline ? new Date(task.deadline).toISOString().split('T')[0] : '',
    });
    setDialogOpen(true);
  };

  const resetForm = () => {
    setFormData({ title: '', description: '', assignedTo: '', priority: 'medium', deadline: '' });
    setEditingTask(null);
  };

  const priorityColor = (p: string) => ({
    critical: 'bg-red-100 text-red-800',
    high: 'bg-orange-100 text-orange-800',
    medium: 'bg-yellow-100 text-yellow-800',
    low: 'bg-green-100 text-green-800',
  }[p] || 'bg-gray-100 text-gray-800');

  const statusColor = (s: string) => ({
    completed: 'bg-green-100 text-green-800',
    in_progress: 'bg-blue-100 text-blue-800',
    overdue: 'bg-red-100 text-red-800',
    pending: 'bg-gray-100 text-gray-800',
  }[s] || 'bg-gray-100 text-gray-800');

  const currentUserId = user?.id || (user as any)?.id;

  const filteredTasks = (() => {
    switch (activeTab) {
      case 'assigned': return tasks.filter(t => (t.assignedBy?.id || t.assignedBy?.id || t.assignedBy) === currentUserId);
      case 'my': return tasks.filter(t => (t.assignedTo?.id || t.assignedTo?.id || t.assignedTo) === currentUserId);
      case 'pending': return tasks.filter(t => t.status === 'pending' || t.status === 'in_progress');
      case 'completed': return tasks.filter(t => t.status === 'completed');
      default: return tasks;
    }
  })();

  if (loading) return (
    <Card><CardContent className="p-8 text-center text-muted-foreground">Loading tasks...</CardContent></Card>
  );

  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between">
        <div>
          <CardTitle>Task Management</CardTitle>
          <p className="text-sm text-muted-foreground mt-1">Assign and track tasks for your team</p>
        </div>
        <Dialog open={dialogOpen} onOpenChange={open => { setDialogOpen(open); if (!open) resetForm(); }}>
          <DialogTrigger asChild>
            <Button><Plus className="w-4 h-4 mr-2" />Assign Task</Button>
          </DialogTrigger>
          <DialogContent className="max-w-lg">
            <DialogHeader>
              <DialogTitle>{editingTask ? 'Edit Task' : 'Assign New Task'}</DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <Label>Task Title</Label>
                <Input
                  value={formData.title}
                  onChange={e => setFormData({ ...formData, title: e.target.value })}
                  required placeholder="e.g., Prepare monthly report"
                />
              </div>
              <div>
                <Label>Description</Label>
                <Textarea
                  value={formData.description}
                  onChange={e => setFormData({ ...formData, description: e.target.value })}
                  required placeholder="Detailed task description..." rows={3}
                />
              </div>
              <div>
                <Label>Assign To</Label>
                <Select
                  value={formData.assignedTo}
                  onValueChange={v => setFormData({ ...formData, assignedTo: v })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select team member" />
                  </SelectTrigger>
                  <SelectContent>
                    {subordinates.length === 0 ? (
                      <SelectItem value="__none__" disabled>No direct reports found</SelectItem>
                    ) : (
                      subordinates.map(s => (
                        <SelectItem key={s.id} value={s.id}>
                          {s.name}{s.designation ? ` — ${s.designation}` : ''}
                        </SelectItem>
                      ))
                    )}
                  </SelectContent>
                </Select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Priority</Label>
                  <Select value={formData.priority} onValueChange={v => setFormData({ ...formData, priority: v })}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="low">Low</SelectItem>
                      <SelectItem value="medium">Medium</SelectItem>
                      <SelectItem value="high">High</SelectItem>
                      <SelectItem value="critical">Critical</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label>Deadline</Label>
                  <Input
                    type="date"
                    value={formData.deadline}
                    onChange={e => setFormData({ ...formData, deadline: e.target.value })}
                    required
                  />
                </div>
              </div>
              <div className="flex justify-end gap-2">
                <Button type="button" variant="outline" onClick={() => { setDialogOpen(false); resetForm(); }}>Cancel</Button>
                <Button type="submit" disabled={!formData.assignedTo || formData.assignedTo === '__none__'}>
                  {editingTask ? 'Update' : 'Assign'} Task
                </Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>
      </CardHeader>

      <CardContent>
        <Tabs value={activeTab} onValueChange={setActiveTab} className="space-y-4">
          <TabsList>
            <TabsTrigger value="all">All Tasks</TabsTrigger>
            <TabsTrigger value="assigned">Assigned by Me</TabsTrigger>
            <TabsTrigger value="my">My Tasks</TabsTrigger>
            <TabsTrigger value="pending">Pending</TabsTrigger>
            <TabsTrigger value="completed">Completed</TabsTrigger>
          </TabsList>

          <TabsContent value={activeTab}>
            {filteredTasks.length === 0 ? (
              <div className="text-center py-12 text-muted-foreground">
                <Users className="w-12 h-12 mx-auto mb-4 opacity-50" />
                <p>No tasks found</p>
              </div>
            ) : (
              <div className="space-y-3">
                {filteredTasks.map(task => {
                  const taskId = task.id || task.id || '';
                  const isAssignedByMe = (task.assignedBy?.id || task.assignedBy?.id || task.assignedBy) === currentUserId;
                  const isAssignedToMe = (task.assignedTo?.id || task.assignedTo?.id || task.assignedTo) === currentUserId;
                  return (
                    <div key={taskId} className="flex items-start justify-between p-4 border rounded-lg hover:bg-muted/50 transition-colors">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <h3 className="font-semibold">{task.title}</h3>
                          <Badge className={priorityColor(task.priority)}>{task.priority}</Badge>
                          <Badge className={statusColor(task.status)}>{task.status.replace('_', ' ')}</Badge>
                        </div>
                        <p className="text-sm text-muted-foreground mb-2">{task.description}</p>
                        <div className="flex flex-wrap gap-3 text-xs text-muted-foreground">
                          <span>To: {task.assignedTo?.name || 'Unknown'}</span>
                          <span>By: {task.assignedBy?.name || 'Unknown'}</span>
                          <span>Due: {new Date(task.deadline).toLocaleDateString()}</span>
                        </div>
                        {task.remarks && <p className="text-xs text-muted-foreground mt-1 italic">{task.remarks}</p>}
                        {task.evidence && task.evidence.length > 0 && (
                          <div className="flex flex-wrap gap-2 mt-2">
                            {task.evidence.map((url, i) => (
                              <a
                                key={i}
                                href={url.startsWith('/') ? `${url}` : url}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="flex items-center gap-1 text-xs text-primary hover:underline"
                              >
                                <Paperclip className="w-3 h-3" />Evidence {i + 1}
                              </a>
                            ))}
                          </div>
                        )}
                      </div>
                      <div className="flex items-center gap-2 ml-3 shrink-0">
                        {isAssignedToMe && task.status !== 'completed' && (
                          <Button variant="outline" size="sm" onClick={() => { setCompletingTask(task); setCompleteDialogOpen(true); }}>
                            <CheckCircle className="w-4 h-4" />
                          </Button>
                        )}
                        {isAssignedByMe && (
                          <>
                            <Button variant="outline" size="sm" onClick={() => openEditDialog(task)}>
                              <Edit className="w-4 h-4" />
                            </Button>
                            <Button variant="outline" size="sm" onClick={() => handleDelete(taskId)}>
                              <Trash2 className="w-4 h-4" />
                            </Button>
                          </>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </TabsContent>
        </Tabs>
      </CardContent>

      {/* Complete Task Dialog */}
      <Dialog open={completeDialogOpen} onOpenChange={setCompleteDialogOpen}>
        <DialogContent>
          <DialogHeader><DialogTitle>Complete Task</DialogTitle></DialogHeader>
          {completingTask && (
            <div className="mb-3 p-3 bg-muted rounded-lg">
              <p className="font-semibold">{completingTask.title}</p>
              <p className="text-sm text-muted-foreground">{completingTask.description}</p>
            </div>
          )}
          <form onSubmit={handleComplete} className="space-y-4">
            <div>
              <Label>Completion Remarks</Label>
              <Textarea
                value={completeData.remarks}
                onChange={e => setCompleteData({ ...completeData, remarks: e.target.value })}
                placeholder="Notes about completion..." rows={3}
              />
            </div>
            <div>
              <Label>Evidence / Screenshots (optional)</Label>
              <label className="flex flex-col items-center gap-2 p-4 border-2 border-dashed rounded-lg cursor-pointer hover:border-primary/50 transition-colors mt-1">
                <Upload className="w-6 h-6 text-muted-foreground" />
                <span className="text-sm text-muted-foreground">
                  {completeData.files && completeData.files.length > 0
                    ? `${completeData.files.length} file(s) selected`
                    : 'Click to upload screenshots or files'}
                </span>
                <span className="text-xs text-muted-foreground">PNG, JPG, PDF, DOC — up to 5 files</span>
                <input
                  type="file"
                  multiple
                  accept=".png,.jpg,.jpeg,.pdf,.doc,.docx"
                  className="hidden"
                  onChange={e => setCompleteData({ ...completeData, files: e.target.files })}
                />
              </label>
              {completeData.files && completeData.files.length > 0 && (
                <ul className="mt-2 space-y-1">
                  {Array.from(completeData.files).map((f, i) => (
                    <li key={i} className="text-xs text-muted-foreground flex items-center gap-1">
                      <Paperclip className="w-3 h-3" />{f.name}
                    </li>
                  ))}
                </ul>
              )}
            </div>
            <div className="flex justify-end gap-2">
              <Button type="button" variant="outline" onClick={() => { setCompleteDialogOpen(false); setCompleteData({ remarks: '', files: null }); }}>Cancel</Button>
              <Button type="submit">Mark as Complete</Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>
    </Card>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Edit, Trash2, Building2, GitBranch, Globe, Lock } from 'lucide-react';
// Card import removed — using custom sections instead
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { useAuth } from '@/hooks/useAuth';
import api from '@/lib/api';

interface Branch { id: string; name: string; code: string; }
interface University {
  id: string; name: string; code: string; address?: string;
  contact?: string; status: string; coordinatorName?: string;
  allowedBranchIds: Branch[];
}

export function UniversitiesPanel() {
  const { user } = useAuth();
  const isOrgAdmin = ['org_admin', 'superadmin'].includes(user?.role || '');

  const [universities, setUniversities] = useState<University[]>([]);
  const [branches, setBranches] = useState<Branch[]>([]);
  const [loading, setLoading] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    name: '', code: '', address: '', contact: '', coordinatorName: '', status: 'active',
  });
  const [selectedBranchIds, setSelectedBranchIds] = useState<string[]>([]);
  const [accessMode, setAccessMode] = useState<'all' | 'exclusive' | 'multi'>('all');

  useEffect(() => {
    fetchUniversities();
    if (isOrgAdmin) fetchBranches();
  }, []);

  const fetchUniversities = async () => {
    setLoading(true);
    try {
      const res = await api.get('/operations/universities');
      setUniversities(res.data.data || []);
    } catch (err) {
      console.error('Failed to fetch universities:', err);
    } finally {
      setLoading(false);
    }
  };

  const fetchBranches = async () => {
    try {
      const res = await api.get('/org/branches');
      setBranches(res.data.data || []);
    } catch (err) {
      console.error('Failed to fetch branches:', err);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const payload = {
        ...formData,
        allowedBranchIds: selectedBranchIds,
      };
      if (editingId) {
        await api.put(`/operations/universities/${editingId}`, payload);
      } else {
        await api.post('/operations/universities', payload);
      }
      setDialogOpen(false);
      resetForm();
      fetchUniversities();
    } catch (err: any) {
      alert(err.response?.data?.message || 'Failed to save university');
    }
  };

  const handleEdit = (u: University) => {
    setEditingId(u.id);
    setFormData({ name: u.name, code: u.code, address: u.address || '', contact: u.contact || '', coordinatorName: u.coordinatorName || '', status: u.status });
    const ids = (u.allowedBranchIds || []).map(b => b.id);
    setSelectedBranchIds(ids);
    if (ids.length === 0) setAccessMode('all');
    else if (ids.length === 1) setAccessMode('exclusive');
    else setAccessMode('multi');
    setDialogOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this university?')) return;
    try {
      await api.delete(`/operations/universities/${id}`);
      fetchUniversities();
    } catch (err) {
      console.error('Failed to delete university:', err);
    }
  };

  const resetForm = () => {
    setEditingId(null);
    setFormData({ name: '', code: '', address: '', contact: '', coordinatorName: '', status: 'active' });
    setSelectedBranchIds([]);
    setAccessMode('all');
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">University Management</h2>
          <p className="text-muted-foreground">Manage affiliated universities and institutions</p>
        </div>
        <Dialog open={dialogOpen} onOpenChange={(open) => { setDialogOpen(open); if (!open) resetForm(); }}>
          {isOrgAdmin && (
            <DialogTrigger asChild>
              <Button><Plus className="w-4 h-4 mr-2" />Add University</Button>
            </DialogTrigger>
          )}
          <DialogContent className="max-w-lg">
            <DialogHeader>
              <DialogTitle>{editingId ? 'Edit University' : 'Add New University'}</DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>University Name</Label>
                  <Input value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} required />
                </div>
                <div>
                  <Label>University Code</Label>
                  <Input value={formData.code} onChange={(e) => setFormData({ ...formData, code: e.target.value })} required />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Contact (Phone/Email)</Label>
                  <Input value={formData.contact} onChange={(e) => setFormData({ ...formData, contact: e.target.value })} />
                </div>
                <div>
                  <Label>Coordinator Name (optional)</Label>
                  <Input value={formData.coordinatorName} onChange={(e) => setFormData({ ...formData, coordinatorName: e.target.value })} />
                </div>
              </div>
              <div>
                <Label>Address</Label>
                <Input value={formData.address} onChange={(e) => setFormData({ ...formData, address: e.target.value })} />
              </div>
              <div>
                <Label>Status</Label>
                <Select value={formData.status} onValueChange={(v) => setFormData({ ...formData, status: v })}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="active">Active</SelectItem>
                    <SelectItem value="inactive">Inactive</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              {/* ── Branch Access ── */}
              {isOrgAdmin && branches.length > 0 && (
                <div className="rounded-xl border-2 border-dashed border-cyan-200 bg-cyan-50/40 p-4 space-y-3">
                  <div className="flex items-center gap-2">
                    <div className="w-7 h-7 rounded-lg bg-cyan-600 flex items-center justify-center">
                      <GitBranch className="h-4 w-4 text-white" />
                    </div>
                    <div>
                      <p className="text-sm font-semibold text-cyan-900">Branch Access Control</p>
                      <p className="text-xs text-cyan-700">Who can see and use this university?</p>
                    </div>
                  </div>

                  {/* Mode cards */}
                  <div className="grid grid-cols-3 gap-2">
                    <button type="button"
                      onClick={() => { setAccessMode('all'); setSelectedBranchIds([]); }}
                      className={`rounded-lg border-2 p-3 text-left transition-all ${
                        accessMode === 'all'
                          ? 'border-green-500 bg-green-50'
                          : 'border-slate-200 bg-white hover:border-green-300'}`}>
                      <Globe className={`h-5 w-5 mb-1 ${accessMode === 'all' ? 'text-green-600' : 'text-slate-400'}`} />
                      <p className={`text-xs font-semibold ${accessMode === 'all' ? 'text-green-700' : 'text-slate-600'}`}>
                        All Branches
                      </p>
                      <p className="text-[10px] text-muted-foreground mt-0.5">Visible to everyone</p>
                    </button>

                    <button type="button"
                      onClick={() => { setAccessMode('exclusive'); setSelectedBranchIds(selectedBranchIds.slice(0, 1)); }}
                      className={`rounded-lg border-2 p-3 text-left transition-all ${
                        accessMode === 'exclusive'
                          ? 'border-amber-500 bg-amber-50'
                          : 'border-slate-200 bg-white hover:border-amber-300'}`}>
                      <Lock className={`h-5 w-5 mb-1 ${accessMode === 'exclusive' ? 'text-amber-600' : 'text-slate-400'}`} />
                      <p className={`text-xs font-semibold ${accessMode === 'exclusive' ? 'text-amber-700' : 'text-slate-600'}`}>
                        Exclusive
                      </p>
                      <p className="text-[10px] text-muted-foreground mt-0.5">One branch only</p>
                    </button>

                    <button type="button"
                      onClick={() => setAccessMode('multi')}
                      className={`rounded-lg border-2 p-3 text-left transition-all ${
                        accessMode === 'multi'
                          ? 'border-cyan-500 bg-cyan-50'
                          : 'border-slate-200 bg-white hover:border-cyan-300'}`}>
                      <GitBranch className={`h-5 w-5 mb-1 ${accessMode === 'multi' ? 'text-cyan-600' : 'text-slate-400'}`} />
                      <p className={`text-xs font-semibold ${accessMode === 'multi' ? 'text-cyan-700' : 'text-slate-600'}`}>
                        Select Branches
                      </p>
                      <p className="text-[10px] text-muted-foreground mt-0.5">Pick 2 or more</p>
                    </button>
                  </div>

                  {/* All branches — confirmation note */}
                  {accessMode === 'all' && (
                    <div className="flex items-start gap-2 bg-green-50 border border-green-200 rounded-lg px-3 py-2">
                      <Globe className="h-4 w-4 text-green-600 mt-0.5 shrink-0" />
                      <p className="text-xs text-green-800">
                        This university will be visible and usable by <strong>all branches</strong> in your organisation.
                      </p>
                    </div>
                  )}

                  {/* Exclusive — single branch picker */}
                  {accessMode === 'exclusive' && (
                    <div className="space-y-2">
                      <Select
                        value={selectedBranchIds[0] || '__none__'}
                        onValueChange={v => setSelectedBranchIds(v === '__none__' ? [] : [v])}>
                        <SelectTrigger className="bg-white">
                          <SelectValue placeholder="Choose the exclusive branch..." />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="__none__">— Choose a branch —</SelectItem>
                          {branches.map(b => (
                            <SelectItem key={b.id} value={b.id}>
                              {b.name} [{b.code}]
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                      {selectedBranchIds[0] ? (
                        <div className="flex items-start gap-2 bg-amber-50 border border-amber-300 rounded-lg px-3 py-2">
                          <Lock className="h-4 w-4 text-amber-600 mt-0.5 shrink-0" />
                          <p className="text-xs text-amber-800">
                            <strong>Exclusive to {branches.find(b => b.id === selectedBranchIds[0])?.name}.</strong>{' '}
                            All other branches will not see this university in their lists.
                          </p>
                        </div>
                      ) : (
                        <p className="text-xs text-amber-600">Select a branch above to make this university exclusive to it.</p>
                      )}
                    </div>
                  )}

                  {/* Multi — checklist */}
                  {accessMode === 'multi' && (
                    <div className="space-y-2">
                      <div className="bg-white border rounded-lg divide-y">
                        {branches.map(b => {
                          const checked = selectedBranchIds.includes(b.id);
                          return (
                            <label key={b.id}
                              className="flex items-center gap-3 px-3 py-2.5 cursor-pointer hover:bg-slate-50 transition-colors">
                              <div className={`w-4 h-4 rounded border-2 flex items-center justify-center shrink-0 transition-colors ${
                                checked ? 'bg-cyan-600 border-cyan-600' : 'border-slate-300'}`}
                                onClick={() => setSelectedBranchIds(prev =>
                                  prev.includes(b.id) ? prev.filter(x => x !== b.id) : [...prev, b.id]
                                )}>
                                {checked && <span className="text-white text-[10px] font-bold">✓</span>}
                              </div>
                              <span className="text-sm font-medium">{b.name}</span>
                              <span className="text-xs font-mono text-muted-foreground ml-auto">[{b.code}]</span>
                            </label>
                          );
                        })}
                      </div>
                      {selectedBranchIds.length > 0 ? (
                        <div className="flex items-start gap-2 bg-cyan-50 border border-cyan-200 rounded-lg px-3 py-2">
                          <GitBranch className="h-4 w-4 text-cyan-600 mt-0.5 shrink-0" />
                          <p className="text-xs text-cyan-800">
                            Accessible by <strong>{selectedBranchIds.length} branch{selectedBranchIds.length > 1 ? 'es' : ''}</strong>.
                            Branches not selected won't see this university.
                          </p>
                        </div>
                      ) : (
                        <p className="text-xs text-muted-foreground">Check at least one branch.</p>
                      )}
                    </div>
                  )}
                </div>
              )}

              <div className="flex gap-2">
                <Button type="submit" className="flex-1">Save</Button>
                <Button type="button" variant="outline" onClick={() => setDialogOpen(false)}>Cancel</Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      {/* ── Grouped university list ── */}
      {loading ? (
        <div className="text-center py-16 text-muted-foreground">Loading...</div>
      ) : universities.length === 0 ? (
        <div className="text-center py-16 text-muted-foreground">No universities found</div>
      ) : (() => {
        // Build groups
        // 1. "All Branches" — universities with no branch restriction
        const globalUnis = universities.filter(u => (u.allowedBranchIds || []).length === 0);

        // 2. Per-branch groups — collect all branches that appear in any university
        const branchMap = new Map<string, { branch: Branch; unis: University[] }>();
        universities.forEach(u => {
          (u.allowedBranchIds || []).forEach(b => {
            if (!branchMap.has(b.id)) branchMap.set(b.id, { branch: b, unis: [] });
            // Only add once per university per branch
            if (!branchMap.get(b.id)!.unis.find(x => x.id === u.id)) {
              branchMap.get(b.id)!.unis.push(u);
            }
          });
        });

        const UniRow = ({ u }: { u: University }) => (
          <div className="flex items-center justify-between px-4 py-3 hover:bg-muted/40 transition-colors">
            <div className="flex items-center gap-3">
              <div className="w-9 h-9 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
                <Building2 className="w-4 h-4 text-primary" />
              </div>
              <div>
                <p className="font-medium text-sm">{u.name}</p>
                <p className="text-xs text-muted-foreground">
                  {u.code}{u.contact ? ` • ${u.contact}` : ''}{u.address ? ` • ${u.address}` : ''}
                </p>
              </div>
            </div>
            <div className="flex items-center gap-2 shrink-0">
              <Badge variant={u.status === 'active' ? 'default' : 'secondary'} className="text-xs">{u.status}</Badge>
              {isOrgAdmin && (
                <>
                  <Button variant="ghost" size="sm" onClick={() => handleEdit(u)}><Edit className="w-3.5 h-3.5" /></Button>
                  <Button variant="ghost" size="sm" onClick={() => handleDelete(u.id)}><Trash2 className="w-3.5 h-3.5" /></Button>
                </>
              )}
            </div>
          </div>
        );

        return (
          <div className="space-y-4">
            {/* All-branches section */}
            {globalUnis.length > 0 && (
              <div className="border rounded-xl overflow-hidden">
                <div className="flex items-center gap-2 px-4 py-3 bg-slate-50 border-b">
                  <Globe className="h-4 w-4 text-slate-500" />
                  <span className="text-sm font-semibold text-slate-700">All Branches</span>
                  <span className="ml-auto text-xs text-muted-foreground">{globalUnis.length} universit{globalUnis.length > 1 ? 'ies' : 'y'}</span>
                </div>
                <div className="divide-y">
                  {globalUnis.map(u => <UniRow key={u.id} u={u} />)}
                </div>
              </div>
            )}

            {/* Per-branch sections */}
            {Array.from(branchMap.values()).map(({ branch, unis }) => (
              <div key={branch.id} className="border-2 rounded-xl overflow-hidden" style={{ borderColor: '#0891b233' }}>
                <div className="flex items-center gap-2 px-4 py-3 border-b" style={{ background: '#0891b211' }}>
                  <div className="w-6 h-6 rounded-lg bg-cyan-600 flex items-center justify-center">
                    <GitBranch className="h-3.5 w-3.5 text-white" />
                  </div>
                  <span className="text-sm font-semibold text-cyan-900">{branch.name}</span>
                  <span className="text-xs font-mono text-cyan-600 bg-cyan-100 px-1.5 py-0.5 rounded">{branch.code}</span>
                  {unis.length === 1 && unis[0].allowedBranchIds.length === 1 && (
                    <span className="flex items-center gap-1 text-[10px] font-semibold text-amber-700 bg-amber-100 px-2 py-0.5 rounded-full ml-1">
                      <Lock className="h-2.5 w-2.5" /> Exclusive
                    </span>
                  )}
                  <span className="ml-auto text-xs text-muted-foreground">{unis.length} universit{unis.length > 1 ? 'ies' : 'y'}</span>
                </div>
                <div className="divide-y">
                  {unis.map(u => <UniRow key={u.id} u={u} />)}
                </div>
              </div>
            ))}
          </div>
        );
      })()}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { CheckCircle, XCircle, RefreshCw, GraduationCap } from 'lucide-react';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { cn } from '@/lib/utils';
import api from '@/lib/api';
import { toast } from 'sonner';

interface Enrollment {
  id: string;
  enrollmentNumber?: string;
  studentName: string;
  studentEmail: string;
  studentPhone: string;
  studentAddress: string;
  createdAt: string;
  program: { id: string; name: string; code: string; courseType: string };
  studyCenter: { id: string; name: string; code: string };
  session: { id: string; name: string };
}

export function UniversityEnrollmentReviewPanel() {
  const [enrollments, setEnrollments] = useState<Enrollment[]>([]);
  const [loading, setLoading] = useState(false);
  const [rejectDialog, setRejectDialog] = useState<{ open: boolean; id: string; studentName: string }>({ open: false, id: '', studentName: '' });
  const [remarks, setRemarks] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const fetchQueue = async () => {
    setLoading(true);
    try {
      const res = await api.get('/enrollment/university-review');
      setEnrollments(res.data.data || []);
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to load review queue');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchQueue(); }, []);

  const handleApprove = async (id: string) => {
    try {
      await api.put(`/enrollment/university-review/${id}/approve`);
      toast.success('Enrollment approved — student is now enrolled');
      setEnrollments(prev => prev.filter(e => e.id !== id));
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to approve');
    }
  };

  const handleReject = async () => {
    if (!remarks.trim()) { toast.error('Remarks are required'); return; }
    setSubmitting(true);
    try {
      await api.put(`/enrollment/university-review/${rejectDialog.id}/reject`, { remarks });
      toast.success('Enrollment rejected — partner portal and operations have been notified');
      setEnrollments(prev => prev.filter(e => e.id !== rejectDialog.id));
      setRejectDialog({ open: false, id: '', studentName: '' });
      setRemarks('');
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to reject');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold">Pending Enrollment Review</h2>
          <p className="text-sm text-muted-foreground mt-1">
            Review student enrollments forwarded by Operations for final approval.
          </p>
        </div>
        <div className="flex items-center gap-3">
          <Badge variant="outline">{enrollments.length} pending</Badge>
          <Button variant="outline" size="sm" onClick={fetchQueue} disabled={loading}>
            <RefreshCw className={cn('w-4 h-4 mr-2', loading && 'animate-spin')} />
            Refresh
          </Button>
        </div>
      </div>

      {loading ? (
        <div className="space-y-3">
          {[1, 2, 3].map(i => <div key={i} className="h-28 bg-muted rounded-xl animate-pulse" />)}
        </div>
      ) : enrollments.length === 0 ? (
        <Card>
          <CardContent className="py-16 text-center text-muted-foreground">
            <GraduationCap className="w-10 h-10 mx-auto mb-3 opacity-30" />
            <p className="font-medium">No enrollments pending review</p>
            <p className="text-sm mt-1">All caught up — check back later.</p>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-4">
          {enrollments.map(e => (
            <Card key={e.id} className="hover:border-primary/30 transition-colors">
              <CardContent className="p-5">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-2 flex-wrap">
                      {e.enrollmentNumber && (
                        <span className="font-mono text-xs bg-muted px-2 py-0.5 rounded">{e.enrollmentNumber}</span>
                      )}
                      <Badge variant="secondary" className="text-xs">{e.program.courseType}</Badge>
                    </div>
                    <h4 className="font-semibold text-base">{e.studentName}</h4>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-0.5 mt-2 text-sm text-muted-foreground">
                      <span>{e.studentEmail}</span>
                      <span>{e.studentPhone}</span>
                      <span className="font-medium text-foreground">{e.program.name} ({e.program.code})</span>
                      <span>Partner: {e.studyCenter.name}</span>
                      <span>Session: {e.session.name}</span>
                      <span>Submitted: {new Date(e.createdAt).toLocaleDateString()}</span>
                    </div>
                  </div>
                  <div className="flex gap-2 shrink-0 flex-col sm:flex-row">
                    <Button
                      size="sm"
                      variant="outline"
                      className="text-destructive border-destructive/30 hover:bg-destructive/10"
                      onClick={() => { setRejectDialog({ open: true, id: e.id, studentName: e.studentName }); setRemarks(''); }}
                    >
                      <XCircle className="w-4 h-4 mr-1" />
                      Reject
                    </Button>
                    <Button size="sm" onClick={() => handleApprove(e.id)}>
                      <CheckCircle className="w-4 h-4 mr-1" />
                      Approve
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      <Dialog open={rejectDialog.open} onOpenChange={o => { if (!o) { setRejectDialog({ open: false, id: '', studentName: '' }); setRemarks(''); } }}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Reject Enrollment — {rejectDialog.studentName}</DialogTitle>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <Label>Rejection Remark <span className="text-destructive">*</span></Label>
            <Textarea
              value={remarks}
              onChange={e => setRemarks(e.target.value)}
              placeholder="Provide a reason for rejection. This will be shared with the partner portal and operations team."
              rows={4}
            />
            <p className="text-xs text-muted-foreground">This remark will be sent as a notification to the partner portal and operations department.</p>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => { setRejectDialog({ open: false, id: '', studentName: '' }); setRemarks(''); }}>
              Cancel
            </Button>
            <Button variant="destructive" onClick={handleReject} disabled={submitting || !remarks.trim()}>
              {submitting ? 'Rejecting...' : 'Reject Enrollment'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { GraduationCap, Building2, BookOpen, Users, RefreshCw, Search, ChevronLeft, TrendingUp } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import api from '@/lib/api';
import { toast } from 'sonner';

interface University {
  id: string;
  name: string;
  code: string;
  address?: string;
  contact?: string;
  status: string;
}

interface Enrollment {
  id: string;
  enrollmentNumber?: string;
  studentName: string;
  studentEmail: string;
  studentPhone: string;
  enrolledAt?: string;
  program: { id: string; name: string; code: string; courseType: string };
  studyCenter: { id: string; name: string; code: string; city?: string };
  session: { id: string; name: string };
}

interface Metrics {
  totalEnrolled: number;
  totalPrograms: number;
  totalCenters: number;
  recentEnrollments: number;
  university: { id: string; name: string; code: string };
}

export function UniversityStudentsPanel() {
  const [universities, setUniversities] = useState<University[]>([]);
  const [selectedUniversity, setSelectedUniversity] = useState<University | null>(null);
  const [enrollments, setEnrollments] = useState<Enrollment[]>([]);
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState('');
  const [programFilter, setProgramFilter] = useState('all');
  const [programs, setPrograms] = useState<{ id: string; name: string }[]>([]);

  useEffect(() => { fetchUniversities(); }, []);

  const fetchUniversities = async () => {
    setLoading(true);
    try {
      const res = await api.get('/operations/universities');
      setUniversities(res.data.data || []);
    } catch {
      toast.error('Failed to load universities');
    } finally {
      setLoading(false);
    }
  };

  const openUniversity = async (uni: University) => {
    setSelectedUniversity(uni);
    setLoading(true);
    try {
      const [studentsRes, metricsRes, programsRes] = await Promise.all([
        api.get(`/operations/universities/${uni.id}/students`),
        api.get(`/operations/universities/${uni.id}/metrics`),
        api.get('/operations/programs', { params: { universityId: uni.id } }),
      ]);
      setEnrollments(studentsRes.data.data || []);
      setMetrics(metricsRes.data.data || null);
      setPrograms(programsRes.data.data || []);
    } catch {
      toast.error('Failed to load university data');
    } finally {
      setLoading(false);
    }
  };

  const refreshStudents = async () => {
    if (!selectedUniversity) return;
    setLoading(true);
    try {
      const params: any = {};
      if (search) params.search = search;
      if (programFilter !== 'all') params.programId = programFilter;
      const res = await api.get(`/operations/universities/${selectedUniversity.id}/students`, { params });
      setEnrollments(res.data.data || []);
    } catch {
      toast.error('Failed to refresh');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (selectedUniversity) refreshStudents();
  }, [search, programFilter]);

  // ── University list view ──────────────────────────────────────────────────
  if (!selectedUniversity) {
    return (
      <div className="space-y-6">
        <div>
          <h2 className="text-xl font-bold">University Panels</h2>
          <p className="text-sm text-muted-foreground mt-1">Select a university to view its enrolled students</p>
        </div>

        {loading ? (
          <div className="flex items-center justify-center h-40 text-muted-foreground">Loading universities...</div>
        ) : universities.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-40 text-muted-foreground gap-2">
            <Building2 className="w-8 h-8 opacity-40" />
            <p>No universities found</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {universities.map(uni => (
              <button
                key={uni.id}
                onClick={() => openUniversity(uni)}
                className="text-left p-5 rounded-xl border border-border bg-card hover:border-primary/50 hover:shadow-md transition-all group"
              >
                <div className="flex items-start justify-between mb-3">
                  <div className="p-2.5 rounded-xl bg-primary/10 group-hover:bg-primary/20 transition-colors">
                    <Building2 className="w-5 h-5 text-primary" />
                  </div>
                  <Badge variant={uni.status === 'active' ? 'default' : 'secondary'} className="text-xs">
                    {uni.status}
                  </Badge>
                </div>
                <h3 className="font-bold text-sm leading-tight">{uni.name}</h3>
                <p className="text-xs text-muted-foreground mt-1">{uni.code}</p>
                {uni.address && <p className="text-xs text-muted-foreground mt-0.5 truncate">{uni.address}</p>}
                <div className="mt-3 flex items-center gap-1 text-xs text-primary font-medium">
                  <GraduationCap className="w-3.5 h-3.5" />
                  View enrolled students
                </div>
              </button>
            ))}
          </div>
        )}
      </div>
    );
  }

  // ── University detail view ────────────────────────────────────────────────
  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-3">
        <Button variant="ghost" size="sm" onClick={() => { setSelectedUniversity(null); setEnrollments([]); setMetrics(null); }}>
          <ChevronLeft className="w-4 h-4 mr-1" />
          All Universities
        </Button>
        <div className="h-4 w-px bg-border" />
        <div>
          <h2 className="text-lg font-bold">{selectedUniversity.name}</h2>
          <p className="text-xs text-muted-foreground">{selectedUniversity.code}</p>
        </div>
      </div>

      {/* Metrics */}
      {metrics && (
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
          <MetricCard icon={<GraduationCap className="w-4 h-4" />} label="Total Enrolled" value={metrics.totalEnrolled} />
          <MetricCard icon={<BookOpen className="w-4 h-4" />} label="Active Programs" value={metrics.totalPrograms} />
          <MetricCard icon={<Building2 className="w-4 h-4" />} label="Partner Portals" value={metrics.totalCenters} />
          <MetricCard icon={<TrendingUp className="w-4 h-4" />} label="Last 30 Days" value={metrics.recentEnrollments} />
        </div>
      )}

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Search by name, email or enrollment no..."
            className="pl-9"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
        <Select value={programFilter} onValueChange={setProgramFilter}>
          <SelectTrigger className="w-full sm:w-52">
            <SelectValue placeholder="All Programs" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Programs</SelectItem>
            {programs.map(p => (
              <SelectItem key={p.id} value={p.id}>{(p as any).name}</SelectItem>
            ))}
          </SelectContent>
        </Select>
        <Button variant="outline" size="icon" onClick={refreshStudents} disabled={loading}>
          <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
        </Button>
      </div>

      {/* Students table */}
      <Card className="border-none shadow-sm">
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="text-base">Enrolled Students</CardTitle>
              <CardDescription>Students verified by Operations and enrolled in this university's programs</CardDescription>
            </div>
            <Badge variant="outline">{enrollments.length} students</Badge>
          </div>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="flex items-center justify-center h-32 text-muted-foreground text-sm">Loading...</div>
          ) : enrollments.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-32 text-muted-foreground gap-2">
              <Users className="w-8 h-8 opacity-30" />
              <p className="text-sm">No enrolled students found</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-border text-xs text-muted-foreground">
                    <th className="text-left py-2 pr-4 font-medium">Enrollment No.</th>
                    <th className="text-left py-2 pr-4 font-medium">Student</th>
                    <th className="text-left py-2 pr-4 font-medium">Program</th>
                    <th className="text-left py-2 pr-4 font-medium">Partner Portal</th>
                    <th className="text-left py-2 pr-4 font-medium">Session</th>
                    <th className="text-left py-2 font-medium">Enrolled On</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {enrollments.map(e => (
                    <tr key={e.id} className="hover:bg-muted/30 transition-colors">
                      <td className="py-3 pr-4">
                        <span className="font-mono text-xs bg-muted px-2 py-0.5 rounded">
                          {e.enrollmentNumber || '—'}
                        </span>
                      </td>
                      <td className="py-3 pr-4">
                        <p className="font-medium">{e.studentName}</p>
                        <p className="text-xs text-muted-foreground">{e.studentEmail}</p>
                      </td>
                      <td className="py-3 pr-4">
                        <p className="font-medium">{e.program.name}</p>
                        <p className="text-xs text-muted-foreground">{e.program.code} · {e.program.courseType}</p>
                      </td>
                      <td className="py-3 pr-4">
                        <p className="font-medium">{e.studyCenter.name}</p>
                        <p className="text-xs text-muted-foreground">{e.studyCenter.city || e.studyCenter.code}</p>
                      </td>
                      <td className="py-3 pr-4">
                        <span className="text-xs">{e.session.name}</span>
                      </td>
                      <td className="py-3 text-xs text-muted-foreground">
                        {e.enrolledAt ? new Date(e.enrolledAt).toLocaleDateString() : '—'}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

function MetricCard({ icon, label, value }: { icon: React.ReactNode; label: string; value: number }) {
  return (
    <Card className="border-none shadow-sm">
      <CardContent className="p-4 flex items-center gap-3">
        <div className="p-2 rounded-lg bg-primary/10 text-primary">{icon}</div>
        <div>
          <p className="text-xs text-muted-foreground">{label}</p>
          <p className="text-xl font-bold">{value}</p>
        </div>
      </CardContent>
    </Card>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Edit, Trash2, User, Building2, Shield, Upload, Download, AlertTriangle, CheckCircle2, Search } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useAuth } from '@/hooks/useAuth';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { toast } from 'sonner';
import api from '@/lib/api';
import * as XLSX from 'xlsx';

interface User {
  id: string;
  userId?: string;
  name: string;
  email: string;
  role: string;
  status: string;
  organizationId?: any;
  departmentId?: any;
  canAddPrograms?: boolean;
  createdAt: string;
}

interface Organization {
  id: string;
  name: string;
}

interface Department {
  id: string;
  name: string;
}

export function UsersPanel() {
  const { user: currentUser } = useAuth();
  const [users, setUsers] = useState<User[]>([]);
  const [organizations, setOrganizations] = useState<Organization[]>([]);
  const [departments, setDepartments] = useState<Department[]>([]);
  const [loading, setLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [deletingUser, setDeletingUser] = useState<User | null>(null);
  const [isImportDialogOpen, setIsImportDialogOpen] = useState(false);
  const [importUsers, setImportUsers] = useState<any[]>([]);
  const [importErrors, setImportErrors] = useState<any[]>([]);
  const [importing, setImporting] = useState(false);
  const [importSummary, setImportSummary] = useState<any | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    role: 'employee',
    organizationId: '',
    departmentId: '',
    canAddPrograms: false,
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      setLoading(true);
      const [usersRes, orgsRes, deptsRes] = await Promise.all([
        api.get('/users'),
        api.get('/organizations'),
        api.get('/departments'),
      ]);
      setUsers(usersRes.data.data || []);
      setOrganizations(orgsRes.data.data || []);
      setDepartments(deptsRes.data.data || []);
    } catch (error: any) {
      toast.error('Failed to fetch data');
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const downloadTemplate = () => {
    const templateData = [
      {
        Name: 'John Doe',
        Email: 'john.doe@example.com',
        Password: 'password123',
        Role: 'employee',
        Department: 'Operations',
        CanAddPrograms: 'No'
      },
      {
        Name: 'Jane Smith',
        Email: 'jane.smith@example.com',
        Password: 'password123',
        Role: 'hr_admin',
        Department: 'Human Resources',
        CanAddPrograms: 'No'
      }
    ];
    const worksheet = XLSX.utils.json_to_sheet(templateData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Template');
    XLSX.writeFile(workbook, 'users_import_template.xlsx');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = new Uint8Array(event.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const parsedData: any[] = XLSX.utils.sheet_to_json(worksheet);

        if (parsedData.length === 0) {
          toast.error('The uploaded file is empty');
          return;
        }

        // Map excel header titles to keys we need
        const mappedUsers = parsedData.map((row: any) => ({
          name: row.Name || row.name || '',
          email: row.Email || row.email || '',
          password: row.Password || row.password || '',
          role: row.Role || row.role || '',
          department: row.Department || row.department || '',
          canAddPrograms: row.CanAddPrograms || row.canAddPrograms || 'No'
        }));

        // Client-side validation
        const errors: any[] = [];
        const emails = new Set();
        mappedUsers.forEach((u, index) => {
          const rowNum = index + 2;
          if (!u.name) errors.push({ row: rowNum, message: 'Name is missing' });
          if (!u.email) {
            errors.push({ row: rowNum, message: 'Email is missing' });
          } else {
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailRegex.test(u.email)) {
              errors.push({ row: rowNum, message: `Invalid email format: ${u.email}` });
            }
            if (emails.has(u.email.toLowerCase())) {
              errors.push({ row: rowNum, message: `Duplicate email in sheet: ${u.email}` });
            }
            emails.add(u.email.toLowerCase());
          }
          if (!u.role) {
            errors.push({ row: rowNum, message: 'Role is missing' });
          } else {
            const validRoles = ['org_admin', 'ceo', 'hr_admin', 'finance_admin', 'ops_admin', 'sales_admin', 'center_admin', 'employee'];
            if (!validRoles.includes(u.role.toLowerCase())) {
              errors.push({ row: rowNum, message: `Invalid role: ${u.role}. Must be one of: ${validRoles.join(', ')}` });
            }
          }
        });

        setImportUsers(mappedUsers);
        setImportErrors(errors);
        setImportSummary(null);
      } catch (err: any) {
        console.error(err);
        toast.error('Failed to parse Excel file');
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleImportSubmit = async () => {
    if (importUsers.length === 0) return;
    setImporting(true);
    try {
      const res = await api.post('/users/bulk-import', { users: importUsers });
      setImportSummary(res.data.data);
      toast.success(`Successfully imported ${res.data.data.successCount} users`);
      fetchData();
    } catch (err: any) {
      console.error(err);
      toast.error(err.response?.data?.message || 'Bulk import failed');
    } finally {
      setImporting(false);
    }
  };

  const handleCreate = () => {
    setEditingUser(null);
    setFormData({
      name: '',
      email: '',
      password: '',
      role: 'employee',
      organizationId: currentUser?.role === 'superadmin' ? '' : (currentUser?.organizationId || ''),
      departmentId: '',
      canAddPrograms: false,
    });
    setIsDialogOpen(true);
  };

  const handleEdit = (user: User) => {
    setEditingUser(user);
    setFormData({
      name: user.name,
      email: user.email,
      password: '',
      role: user.role,
      organizationId: user.organizationId?.id || user.organizationId || currentUser?.organizationId || '',
      departmentId: user.departmentId?.id || user.departmentId || '',
      canAddPrograms: user.canAddPrograms || false,
    });
    setIsDialogOpen(true);
  };

  const handleDelete = (user: User) => {
    setDeletingUser(user);
    setIsDeleteDialogOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const payload = { ...formData };

      // Remove empty departmentId
      if (!payload.departmentId) {
        delete (payload as any).departmentId;
      }

      // Remove password if editing and password is empty
      if (editingUser && !payload.password) {
        delete (payload as any).password;
      }

      console.log('Submitting user data:', payload);

      if (editingUser) {
        await api.put(`/users/${editingUser.id}`, payload);
        toast.success('User updated successfully');
      } else {
        await api.post('/users', payload);
        toast.success('User created successfully');
      }

      setIsDialogOpen(false);
      fetchData();
    } catch (error: any) {
      const errorMessage = error.response?.data?.message || error.response?.data?.error || 'Operation failed';
      toast.error(errorMessage);
      console.error('Full error:', error);
      console.error('Error response:', error.response?.data);
    }
  };

  const confirmDelete = async () => {
    if (!deletingUser) return;

    try {
      await api.delete(`/users/${deletingUser.id}`);
      toast.success('User deleted successfully');
      setIsDeleteDialogOpen(false);
      fetchData();
    } catch (error: any) {
      toast.error(error.response?.data?.message || 'Failed to delete user');
      console.error(error);
    }
  };

  const getRoleBadgeColor = (role: string) => {
    const colors: any = {
      superadmin: 'bg-purple-500',
      org_admin: 'bg-blue-500',
      ceo: 'bg-indigo-500',
      hr_admin: 'bg-orange-500',
      finance_admin: 'bg-green-500',
      ops_admin: 'bg-cyan-500',
      sales_admin: 'bg-pink-500',
      employee: 'bg-gray-500',
    };
    return colors[role] || 'bg-gray-500';
  };

  if (loading) {
    return (
      <div className="p-8">
        <div className="h-64 bg-muted rounded-xl animate-pulse" />
      </div>
    );
  }

  const filteredUsers = users.filter((u) => {
    const q = searchQuery.toLowerCase();
    return (
      !q ||
      u.name?.toLowerCase().includes(q) ||
      u.email?.toLowerCase().includes(q) ||
      u.role?.toLowerCase().includes(q) ||
      u.userId?.toLowerCase().includes(q)
    );
  });

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold tracking-tight">Users</h2>
          <p className="text-muted-foreground text-sm">
            Manage all users across organizations
          </p>
        </div>
        <div className="flex flex-col sm:flex-row gap-2 w-full sm:w-auto">
          <Button
            onClick={() => {
              setImportUsers([]);
              setImportErrors([]);
              setImportSummary(null);
              setIsImportDialogOpen(true);
            }}
            variant="outline"
            className="w-full sm:w-auto"
          >
            <Upload className="w-4 h-4 mr-2" />
            Bulk Import
          </Button>
          <Button onClick={handleCreate} className="w-full sm:w-auto">
            <Plus className="w-4 h-4 mr-2" />
            New User
          </Button>
        </div>
      </div>

      {/* Search Bar */}
      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
        <Input
          placeholder="Search by name, email, role or user ID…"
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="pl-9"
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredUsers.map((user) => (
          <Card key={user.id} className="hover:shadow-lg transition-shadow">
            <CardHeader className="pb-3">
              <div className="flex items-start justify-between">
                <div className="flex items-center gap-3">
                  <div className="p-2 rounded-lg bg-primary/10">
                    <User className="w-5 h-5 text-primary" />
                  </div>
                  <div>
                    <CardTitle className="text-lg">{user.name}</CardTitle>
                    <Badge className={`mt-1 ${getRoleBadgeColor(user.role)} text-white border-none`}>
                      {user.role.replace('_', ' ')}
                    </Badge>
                  </div>
                </div>
              </div>
            </CardHeader>
            <CardContent className="space-y-3">
              <div className="space-y-2 text-sm">
                <div className="flex items-center gap-2 text-muted-foreground">
                  <span className="font-medium">Email:</span>
                  <span className="truncate">{user.email}</span>
                </div>
                {user.organizationId && (
                  <div className="flex items-center gap-2 text-muted-foreground">
                    <Building2 className="w-3 h-3" />
                    <span className="text-xs truncate">
                      {user.organizationId.name || 'Organization'}
                    </span>
                  </div>
                )}
                {user.departmentId && (
                  <div className="flex items-center gap-2 text-muted-foreground">
                    <Shield className="w-3 h-3" />
                    <span className="text-xs truncate">
                      {user.departmentId.name || 'Department'}
                    </span>
                  </div>
                )}
                <div className="flex items-center gap-2">
                  <Badge variant={user.status === 'active' ? 'default' : 'secondary'}>
                    {user.status}
                  </Badge>
                </div>
              </div>

              <div className="flex gap-2 pt-3 border-t">
                <Button
                  variant="outline"
                  size="sm"
                  className="flex-1"
                  onClick={() => handleEdit(user)}
                >
                  <Edit className="w-3 h-3 mr-2" />
                  Edit
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  className="flex-1 text-destructive hover:text-destructive"
                  onClick={() => handleDelete(user)}
                >
                  <Trash2 className="w-3 h-3 mr-2" />
                  Delete
                </Button>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {filteredUsers.length === 0 && (
        <Card>
          <CardContent className="flex flex-col items-center justify-center py-12">
            <User className="w-12 h-12 text-muted-foreground mb-4" />
            <h3 className="text-lg font-semibold mb-2">
              {searchQuery ? 'No users match your search' : 'No users found'}
            </h3>
            <p className="text-muted-foreground text-sm mb-4">
              {searchQuery ? 'Try a different keyword.' : 'Get started by creating your first user'}
            </p>
            {!searchQuery && (
              <Button onClick={handleCreate}>
                <Plus className="w-4 h-4 mr-2" />
                Create User
              </Button>
            )}
          </CardContent>
        </Card>
      )}

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-h-[90vh] flex flex-col p-0 gap-0 sm:max-w-lg">
          <DialogHeader className="p-6 pb-4 border-b">
            <DialogTitle>
              {editingUser ? 'Edit User' : 'Create New User'}
            </DialogTitle>
            <DialogDescription>
              {editingUser
                ? 'Update the user details below'
                : 'Fill in the details to create a new user'}
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={handleSubmit} className="flex flex-col flex-1 overflow-hidden">
            <div className="flex-1 overflow-y-auto p-6 space-y-4">
              <div className="space-y-2">
                <Label htmlFor="name">Name *</Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  placeholder="John Doe"
                  required
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="email">Email *</Label>
                <Input
                  id="email"
                  type="email"
                  value={formData.email}
                  onChange={(e) =>
                    setFormData({ ...formData, email: e.target.value })
                  }
                  placeholder="user@example.com"
                  required
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="password">
                  Password {editingUser ? '(leave blank to keep current)' : '*'}
                </Label>
                <Input
                  id="password"
                  type="password"
                  value={formData.password}
                  onChange={(e) =>
                    setFormData({ ...formData, password: e.target.value })
                  }
                  placeholder="••••••••"
                  required={!editingUser}
                />
              </div>
              {currentUser?.role === 'superadmin' && (
                <div className="space-y-2">
                  <Label htmlFor="organizationId">Organization *</Label>
                  <Select
                    value={formData.organizationId}
                    onValueChange={(value) =>
                      setFormData({ ...formData, organizationId: value })
                    }
                    required
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Select organization" />
                    </SelectTrigger>
                    <SelectContent>
                      {organizations.map((org) => (
                        <SelectItem key={org.id} value={org.id}>
                          {org.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              )}
              <div className="space-y-2">
                <Label htmlFor="role">Role *</Label>
                <Select
                  value={formData.role}
                  onValueChange={(value) =>
                    setFormData({ ...formData, role: value })
                  }
                  required
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select role" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="org_admin">Organization Admin</SelectItem>
                    <SelectItem value="ceo">CEO</SelectItem>
                    <SelectItem value="hr_admin">HR Admin</SelectItem>
                    <SelectItem value="finance_admin">Finance Admin</SelectItem>
                    <SelectItem value="ops_admin">Operations Admin</SelectItem>
                    <SelectItem value="sales_admin">Sales Admin</SelectItem>
                    <SelectItem value="center_admin">Center Admin</SelectItem>
                    <SelectItem value="employee">Employee</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label htmlFor="departmentId">Department (Optional)</Label>
                <Select
                  value={formData.departmentId || undefined}
                  onValueChange={(value) =>
                    setFormData({ ...formData, departmentId: value || '' })
                  }
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select department (optional)" />
                  </SelectTrigger>
                  <SelectContent>
                    {departments.map((dept) => (
                      <SelectItem key={dept.id} value={dept.id}>
                        {dept.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="flex items-center gap-2 pt-2">
                <input
                  type="checkbox"
                  id="canAddPrograms"
                  checked={formData.canAddPrograms}
                  onChange={(e) =>
                    setFormData({ ...formData, canAddPrograms: e.target.checked })
                  }
                  className="h-4 w-4 rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
                />
                <Label htmlFor="canAddPrograms" className="text-sm font-medium cursor-pointer">
                  Can Add Programs against Universities
                </Label>
              </div>
            </div>
            <DialogFooter className="p-6 pt-4 border-t bg-muted/20">
              <Button
                type="button"
                variant="outline"
                onClick={() => setIsDialogOpen(false)}
              >
                Cancel
              </Button>
              <Button type="submit">
                {editingUser ? 'Update' : 'Create'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      <Dialog open={isDeleteDialogOpen} onOpenChange={setIsDeleteDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Delete User</DialogTitle>
            <DialogDescription>
              Are you sure you want to delete "{deletingUser?.name}"? This action
              cannot be undone.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setIsDeleteDialogOpen(false)}
            >
              Cancel
            </Button>
            <Button variant="destructive" onClick={confirmDelete}>
              Delete
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={isImportDialogOpen} onOpenChange={setIsImportDialogOpen}>
        <DialogContent className="max-h-[90vh] flex flex-col p-0 gap-0 sm:max-w-2xl">
          <DialogHeader className="p-6 pb-4 border-b">
            <DialogTitle>Bulk Import Users</DialogTitle>
            <DialogDescription>
              Upload an Excel (.xlsx, .xls) or CSV file containing user details.
            </DialogDescription>
          </DialogHeader>

          <div className="flex-1 overflow-y-auto p-6 space-y-6">
            {/* Step 1: Template and File Upload */}
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 p-4 rounded-lg border bg-muted/40">
              <div className="space-y-1">
                <h4 className="font-semibold text-sm">Need a template?</h4>
                <p className="text-xs text-muted-foreground">Download the Excel template to prepare your user details.</p>
              </div>
              <Button type="button" variant="outline" size="sm" onClick={downloadTemplate} className="w-full sm:w-auto">
                <Download className="w-4 h-4 mr-2" />
                Download Template
              </Button>
            </div>

            <div className="space-y-2">
              <Label htmlFor="importFile" className="text-sm font-semibold">Select Excel/CSV File</Label>
              <Input
                id="importFile"
                type="file"
                accept=".xlsx, .xls, .csv"
                onChange={handleFileUpload}
                className="cursor-pointer"
              />
            </div>

            {/* Validation Errors */}
            {importErrors.length > 0 && (
              <div className="p-4 rounded-lg bg-destructive/10 border border-destructive/20 text-destructive text-sm space-y-2">
                <div className="flex items-center gap-2 font-semibold">
                  <AlertTriangle className="w-4 h-4" />
                  Please fix the following {importErrors.length} errors in your file:
                </div>
                <ul className="list-disc pl-5 space-y-1 text-xs max-h-40 overflow-y-auto">
                  {importErrors.map((err, idx) => (
                    <li key={idx}>
                      <strong>Row {err.row}:</strong> {err.message}
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {/* Summary display after import */}
            {importSummary && (
              <div className={`p-4 rounded-lg border text-sm space-y-3 ${importSummary.failedCount > 0 ? 'bg-amber-500/10 border-amber-500/20 text-amber-800 dark:text-amber-300' : 'bg-green-500/10 border-green-500/20 text-green-800 dark:text-green-300'}`}>
                <div className="flex items-center gap-2 font-semibold text-base">
                  <CheckCircle2 className="w-5 h-5 text-green-500" />
                  Import Completed
                </div>
                <div className="grid grid-cols-3 gap-4 text-center">
                  <div className="p-2 rounded bg-background/50">
                    <div className="font-bold text-lg">{importSummary.total}</div>
                    <div className="text-xs text-muted-foreground">Total Rows</div>
                  </div>
                  <div className="p-2 rounded bg-background/50">
                    <div className="font-bold text-lg text-green-600 dark:text-green-400">{importSummary.successCount}</div>
                    <div className="text-xs text-muted-foreground">Succeeded</div>
                  </div>
                  <div className="p-2 rounded bg-background/50">
                    <div className="font-bold text-lg text-destructive">{importSummary.failedCount}</div>
                    <div className="text-xs text-muted-foreground">Failed</div>
                  </div>
                </div>

                {importSummary.errors.length > 0 && (
                  <div className="space-y-1.5 pt-2 border-t border-muted">
                    <div className="font-semibold text-xs">Import Warnings/Failures:</div>
                    <ul className="list-disc pl-5 space-y-1 text-xs max-h-40 overflow-y-auto">
                      {importSummary.errors.map((err: any, idx: number) => (
                        <li key={idx}>
                          <strong>Row {err.row} ({err.email}):</strong> {err.message}
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
              </div>
            )}

            {/* Preview parsed users */}
            {importUsers.length > 0 && !importSummary && (
              <div className="space-y-2.5">
                <div className="flex items-center justify-between">
                  <h4 className="font-semibold text-sm">Preview ({importUsers.length} users parsed)</h4>
                </div>
                <div className="rounded-md border max-h-60 overflow-auto">
                  <table className="w-full text-sm">
                    <thead className="bg-muted/80 sticky top-0 font-semibold text-muted-foreground border-b text-left">
                      <tr>
                        <th className="p-2 pl-3">Row</th>
                        <th className="p-2">Name</th>
                        <th className="p-2">Email</th>
                        <th className="p-2">Role</th>
                        <th className="p-2">Department</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y">
                      {importUsers.map((u, idx) => (
                        <tr key={idx} className="hover:bg-muted/30">
                          <td className="p-2 pl-3 text-muted-foreground text-xs">{idx + 2}</td>
                          <td className="p-2 font-medium">{u.name}</td>
                          <td className="p-2 text-xs truncate max-w-[150px]">{u.email}</td>
                          <td className="p-2"><Badge variant="outline">{u.role}</Badge></td>
                          <td className="p-2 text-xs text-muted-foreground">{u.department || '-'}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </div>

          <DialogFooter className="p-6 pt-4 border-t bg-muted/20">
            <Button
              type="button"
              variant="outline"
              onClick={() => setIsImportDialogOpen(false)}
            >
              {importSummary ? 'Close' : 'Cancel'}
            </Button>
            {importUsers.length > 0 && !importSummary && (
              <Button
                type="button"
                onClick={handleImportSubmit}
                disabled={importErrors.length > 0 || importing}
              >
                {importing ? 'Importing...' : `Import ${importUsers.length} Users`}
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Edit, Trash2, CheckCircle, UserPlus } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import api from '@/lib/api';

export function VacanciesPanel() {
  const [vacancies, setVacancies] = useState<any[]>([]);
  const [departments, setDepartments] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [hireDialogOpen, setHireDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [selectedVacancy, setSelectedVacancy] = useState<any>(null);
  const [formData, setFormData] = useState({
    designation: '',
    departmentId: '',
    count: '1',
    status: 'open'
  });

  const [hireFormData, setHireFormData] = useState({
    name: '',
    email: '',
    password: '',
    role: 'employee',
  });

  useEffect(() => {
    fetchVacancies();
    fetchDepartments();
  }, []);

  const fetchVacancies = async () => {
    setLoading(true);
    try {
      const response = await api.get('/hr/vacancies');
      setVacancies(response.data.data || []);
    } catch (error) {
      console.error('Failed to fetch vacancies:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchDepartments = async () => {
    try {
      const response = await api.get('/departments');
      setDepartments(response.data.data || []);
    } catch (error) {
      console.error('Failed to fetch departments:', error);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (editingId) {
        await api.put(`/hr/vacancies/${editingId}`, formData);
      } else {
        await api.post('/hr/vacancies', formData);
      }
      setDialogOpen(false);
      resetForm();
      fetchVacancies();
    } catch (error: any) {
      console.error('Failed to save vacancy:', error);
      alert(error.response?.data?.message || 'Failed to save vacancy');
    }
  };

  const handleEdit = (vacancy: any) => {
    const vid = vacancy.id || vacancy.id;
    setEditingId(vid);
    setFormData({
      designation: vacancy.designation || '',
      departmentId: (typeof vacancy.departmentId === 'object' ? vacancy.departmentId?.id || vacancy.departmentId?.id : vacancy.departmentId) || '',
      count: vacancy.count?.toString() || '1',
      status: vacancy.status || 'open'
    });
    setDialogOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this vacancy?')) return;
    try {
      await api.delete(`/hr/vacancies/${id}`);
      fetchVacancies();
    } catch (error) {
      console.error('Failed to delete vacancy:', error);
    }
  };

  const handleClose = async (id: string) => {
    if (!confirm('Close this vacancy?')) return;
    try {
      await api.put(`/hr/vacancies/${id}/close`);
      fetchVacancies();
    } catch (error) {
      console.error('Failed to close vacancy:', error);
    }
  };

  const openHireDialog = (vacancy: any) => {
    setSelectedVacancy(vacancy);
    setHireFormData({
      name: '',
      email: '',
      password: '',
      role: 'employee',
    });
    setHireDialogOpen(true);
  };

  const handleHireSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      // Create the user with the vacancy's department
      await api.post('/users', {
        ...hireFormData,
        departmentId: selectedVacancy.departmentId,
      });

      alert(`User ${hireFormData.name} created successfully and assigned to ${selectedVacancy.department?.name || 'department'}!`);
      setHireDialogOpen(false);
      setHireFormData({
        name: '',
        email: '',
        password: '',
        role: 'employee',
      });
      setSelectedVacancy(null);
    } catch (error: any) {
      console.error('Failed to create user:', error);
      alert(error.response?.data?.message || 'Failed to create user');
    }
  };

  const resetForm = () => {
    setEditingId(null);
    setFormData({
      designation: '',
      departmentId: '',
      count: '1',
      status: 'open'
    });
  };

  const getStatusBadge = (status: string) => {
    const variants: any = {
      open: 'bg-green-100 text-green-800',
      closed: 'bg-gray-100 text-gray-800',
    };
    return <Badge className={variants[status] || ''}>{status}</Badge>;
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Vacancy Management</h2>
          <p className="text-muted-foreground">Manage job openings and recruitment</p>
        </div>
        <Dialog open={dialogOpen} onOpenChange={(open) => { setDialogOpen(open); if (!open) resetForm(); }}>
          <DialogTrigger asChild>
            <Button><Plus className="w-4 h-4 mr-2" />Post Vacancy</Button>
          </DialogTrigger>
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <DialogTitle>{editingId ? 'Edit Vacancy' : 'Post New Vacancy'}</DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <Label>Designation / Job Title</Label>
                <Input value={formData.designation} onChange={(e) => setFormData({...formData, designation: e.target.value})} required placeholder="e.g., Software Engineer" />
              </div>
              <div>
                <Label>Department</Label>
                <Select value={formData.departmentId} onValueChange={(value) => setFormData({...formData, departmentId: value})}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select department" />
                  </SelectTrigger>
                  <SelectContent>
                    {departments.filter(dept => dept && (dept.id || dept.id)).map((dept) => (
                      <SelectItem key={dept.id || dept.id} value={(dept.id || dept.id).toString()}>
                        {dept.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label>Number of Positions</Label>
                <Input type="number" min="1" value={formData.count} onChange={(e) => setFormData({...formData, count: e.target.value})} required />
              </div>
              <div>
                <Label>Status</Label>
                <Select value={formData.status} onValueChange={(value) => setFormData({...formData, status: value})}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="open">Open</SelectItem>
                    <SelectItem value="closed">Closed</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="flex gap-2">
                <Button type="submit" className="flex-1">Save</Button>
                <Button type="button" variant="outline" onClick={() => setDialogOpen(false)}>Cancel</Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Current Vacancies</CardTitle>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="text-center py-8">Loading...</div>
          ) : vacancies.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">No vacancies found</div>
          ) : (
            <div className="space-y-4">
              {vacancies.map((vacancy) => {
                const vid = vacancy.id || vacancy.id || '';
                const deptName = typeof vacancy.departmentId === 'object'
                  ? vacancy.departmentId?.name
                  : vacancy.department?.name;
                const available = (vacancy.count || 0) - (vacancy.filled || 0);
                return (
                <div key={vid} className="p-4 border rounded-lg hover:bg-muted/50">
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center gap-2">
                        <h3 className="font-bold text-lg">{vacancy.designation}</h3>
                        {getStatusBadge(vacancy.status)}
                      </div>
                      <div className="text-sm text-muted-foreground mt-1">
                        {deptName} • {vacancy.count} position(s) • {vacancy.filled || 0} filled • {available} available
                      </div>
                    </div>
                    <div className="flex items-center gap-2 ml-4">
                      {vacancy.status === 'open' && (
                        <>
                          <Button 
                            variant="default" 
                            size="sm" 
                            onClick={() => openHireDialog(vacancy)}
                            title="Hire for this position"
                          >
                            <UserPlus className="w-4 h-4 mr-1" />
                            Hire
                          </Button>
                          <Button variant="ghost" size="sm" onClick={() => handleClose(vid)}>
                            <CheckCircle className="w-4 h-4" />
                          </Button>
                        </>
                      )}
                      <Button variant="ghost" size="sm" onClick={() => handleEdit(vacancy)}>
                        <Edit className="w-4 h-4" />
                      </Button>
                      <Button variant="ghost" size="sm" onClick={() => handleDelete(vid)}>
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>
                  </div>
                </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Hire Dialog */}
      <Dialog open={hireDialogOpen} onOpenChange={setHireDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Hire for: {selectedVacancy?.designation}</DialogTitle>
            <p className="text-sm text-muted-foreground mt-2">
              Create a new employee user for this position in {
                typeof selectedVacancy?.departmentId === 'object'
                  ? selectedVacancy?.departmentId?.name
                  : selectedVacancy?.department?.name
              }
            </p>
          </DialogHeader>
          <form onSubmit={handleHireSubmit} className="space-y-4">
            <div>
              <Label htmlFor="hire-name">Full Name</Label>
              <Input
                id="hire-name"
                value={hireFormData.name}
                onChange={(e) => setHireFormData({ ...hireFormData, name: e.target.value })}
                required
                placeholder="Enter employee name"
              />
            </div>
            <div>
              <Label htmlFor="hire-email">Email</Label>
              <Input
                id="hire-email"
                type="email"
                value={hireFormData.email}
                onChange={(e) => setHireFormData({ ...hireFormData, email: e.target.value })}
                required
                placeholder="employee@company.com"
              />
            </div>
            <div>
              <Label htmlFor="hire-password">Initial Password</Label>
              <Input
                id="hire-password"
                type="password"
                value={hireFormData.password}
                onChange={(e) => setHireFormData({ ...hireFormData, password: e.target.value })}
                required
                minLength={6}
                placeholder="Minimum 6 characters"
              />
            </div>
            <div>
              <Label htmlFor="hire-role">Role</Label>
              <Select
                value={hireFormData.role}
                onValueChange={(value) => setHireFormData({ ...hireFormData, role: value })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="employee">Employee</SelectItem>
                  <SelectItem value="staff">Staff</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="bg-muted p-3 rounded-lg">
              <p className="text-sm">
                <span className="font-medium">Department:</span> {
                  typeof selectedVacancy?.departmentId === 'object'
                    ? selectedVacancy?.departmentId?.name
                    : selectedVacancy?.department?.name
                }
              </p>
              <p className="text-xs text-muted-foreground mt-1">
                User will be automatically assigned to this department
              </p>
            </div>
            <div className="flex gap-2">
              <Button type="submit" className="flex-1">
                <UserPlus className="w-4 h-4 mr-2" />
                Create User & Hire
              </Button>
              <Button 
                type="button" 
                variant="outline" 
                onClick={() => setHireDialogOpen(false)}
              >
                Cancel
              </Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { RefreshCw, CheckCircle, XCircle, Filter } from 'lucide-react';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { cn } from '@/lib/utils';
import api from '@/lib/api';
import { toast } from 'sonner';

interface TopUp {
  id: string;
  studyCenterId: { name?: string; id?: string } | string;
  amount: number;
  paymentMethod: string;
  referenceNumber?: string;
  status: string;
  createdAt: string;
  remarks?: string;
}

interface LedgerEntry {
  id: string;
  date: string;
  type: 'credit' | 'debit';
  amount: number;
  method: string;
  reference: string;
  description: string;
  centerName: string;
  centerCode: string;
}

const STATUS_COLOR: Record<string, string> = {
  pending: 'bg-warning/10 text-warning',
  approved: 'bg-success/10 text-success',
  rejected: 'bg-destructive/10 text-destructive',
};

export function WalletTopUpsPanel() {
  const [activeTab, setActiveTab] = useState<'requests' | 'ledger'>('requests');
  const [topUps, setTopUps] = useState<TopUp[]>([]);
  const [ledger, setLedger] = useState<LedgerEntry[]>([]);
  const [centers, setCenters] = useState<any[]>([]);
  const [selectedCenter, setSelectedCenter] = useState<string>('__all__');
  const [loading, setLoading] = useState(false);
  const [rejectDialog, setRejectDialog] = useState<{ open: boolean; id: string }>({ open: false, id: '' });
  const [remarks, setRemarks] = useState('');

  const fetch = async () => {
    setLoading(true);
    try {
      if (activeTab === 'requests') {
        const res = await api.get('/finance/wallet-topups');
        setTopUps(res.data.data || []);
      } else {
        const res = await api.get(`/finance/wallet-ledger?studyCenterId=${selectedCenter}`);
        setLedger(res.data.data || []);
      }
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    // Load study centers list for filtering ledger
    api.get('/operations/centers').then(res => {
      setCenters(res.data.data || []);
    }).catch(() => {});
  }, []);

  useEffect(() => {
    fetch();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTab, selectedCenter]);

  const handleApprove = async (id: string) => {
    try {
      await api.put(`/finance/wallet-topups/${id}/approve`);
      toast.success('Top-up approved');
      fetch();
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to approve');
    }
  };

  const handleReject = async () => {
    try {
      await api.put(`/finance/wallet-topups/${rejectDialog.id}/reject`, { remarks });
      toast.success('Top-up rejected');
      setRejectDialog({ open: false, id: '' });
      setRemarks('');
      fetch();
    } catch (e: any) {
      toast.error(e.response?.data?.message || 'Failed to reject');
    }
  };

  const getCenterName = (t: TopUp) =>
    typeof t.studyCenterId === 'object' ? t.studyCenterId.name || 'Unknown' : t.studyCenterId;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-4">
        <div>
          <h2 className="text-2xl font-bold">Wallet Operations</h2>
          <p className="text-muted-foreground text-sm mt-1">Approve wallet top-up requests or view the unified study center ledger.</p>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex bg-muted p-1 rounded-lg">
            <button
              onClick={() => setActiveTab('requests')}
              className={cn(
                "px-3 py-1.5 text-xs font-semibold rounded-md transition-all",
                activeTab === 'requests' ? "bg-background shadow text-foreground" : "text-muted-foreground hover:text-foreground"
              )}
            >
              Top-Up Requests
            </button>
            <button
              onClick={() => setActiveTab('ledger')}
              className={cn(
                "px-3 py-1.5 text-xs font-semibold rounded-md transition-all",
                activeTab === 'ledger' ? "bg-background shadow text-foreground" : "text-muted-foreground hover:text-foreground"
              )}
            >
              Wallet Ledger
            </button>
          </div>
          <Button variant="outline" size="sm" onClick={fetch} disabled={loading}>
            <RefreshCw className={cn('w-4 h-4 mr-2', loading && 'animate-spin')} />Refresh
          </Button>
        </div>
      </div>

      {activeTab === 'ledger' && (
        <Card className="border shadow-sm">
          <CardContent className="py-4 flex items-center justify-between gap-4 flex-wrap">
            <div className="flex items-center gap-2">
              <Filter className="w-4 h-4 text-muted-foreground" />
              <span className="text-sm font-semibold text-muted-foreground">Filter by Center:</span>
            </div>
            <div className="w-[280px]">
              <Select value={selectedCenter} onValueChange={setSelectedCenter}>
                <SelectTrigger>
                  <SelectValue placeholder="All Study Centers" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="__all__">All Study Centers</SelectItem>
                  {centers.map((c: any) => (
                    <SelectItem key={c.id} value={c.id}>{c.name} ({c.code})</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </CardContent>
        </Card>
      )}

      {loading ? (
        <div className="space-y-3">{[1, 2, 3].map(i => <div key={i} className="h-20 bg-muted rounded-xl animate-pulse" />)}</div>
      ) : activeTab === 'requests' ? (
        topUps.length === 0 ? (
          <Card><CardContent className="py-16 text-center text-muted-foreground">No top-up requests found.</CardContent></Card>
        ) : (
          <div className="space-y-3">
            {topUps.map(t => (
              <Card key={t.id} className="hover:border-primary/30 transition-colors">
                <CardContent className="p-5 flex items-center justify-between gap-4">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <Badge className={cn('text-[10px] uppercase font-bold', STATUS_COLOR[t.status] || 'bg-muted text-muted-foreground')}>
                        {t.status}
                      </Badge>
                      <Badge variant="outline" className="text-xs">{t.paymentMethod}</Badge>
                    </div>
                    <h4 className="font-semibold">{getCenterName(t)}</h4>
                    <div className="flex items-center gap-4 mt-1 text-sm text-muted-foreground">
                      <span>Amount: <strong className="text-foreground">₹{t.amount.toLocaleString()}</strong></span>
                      {t.referenceNumber && <span>Ref: {t.referenceNumber}</span>}
                      <span>{new Date(t.createdAt).toLocaleDateString()}</span>
                    </div>
                  </div>
                  {t.status === 'pending' && (
                    <div className="flex gap-2">
                      <Button size="sm" variant="outline" className="text-success border-success/30 hover:bg-success/10" onClick={() => handleApprove(t.id)}>
                        <CheckCircle className="w-4 h-4 mr-1" />Approve
                      </Button>
                      <Button size="sm" variant="outline" className="text-destructive border-destructive/30 hover:bg-destructive/10" onClick={() => { setRejectDialog({ open: true, id: t.id }); setRemarks(''); }}>
                        <XCircle className="w-4 h-4 mr-1" />Reject
                      </Button>
                    </div>
                  )}
                </CardContent>
              </Card>
            ))}
          </div>
        )
      ) : ledger.length === 0 ? (
        <Card><CardContent className="py-16 text-center text-muted-foreground">No ledger transactions found.</CardContent></Card>
      ) : (
        <Card className="overflow-hidden border">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-muted/60 border-b">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-muted-foreground">Date</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-muted-foreground">Study Center</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-muted-foreground">Description</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-muted-foreground">Method</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-muted-foreground">Reference</th>
                  <th className="px-4 py-3 text-right text-xs font-semibold text-muted-foreground">Credit (₹)</th>
                  <th className="px-4 py-3 text-right text-xs font-semibold text-muted-foreground">Debit (₹)</th>
                </tr>
              </thead>
              <tbody className="divide-y">
                {ledger.map(item => (
                  <tr key={item.id} className="hover:bg-muted/30 transition-colors">
                    <td className="px-4 py-3 text-xs text-muted-foreground whitespace-nowrap">
                      {new Date(item.date).toLocaleDateString()}
                    </td>
                    <td className="px-4 py-3 font-medium">
                      <div className="font-semibold">{item.centerName}</div>
                      <div className="text-[10px] text-muted-foreground">{item.centerCode}</div>
                    </td>
                    <td className="px-4 py-3 max-w-xs truncate">{item.description}</td>
                    <td className="px-4 py-3 text-xs capitalize whitespace-nowrap">{item.method.replace('_', ' ')}</td>
                    <td className="px-4 py-3 text-xs font-mono text-muted-foreground">{item.reference}</td>
                    <td className="px-4 py-3 text-right font-semibold text-success">
                      {item.type === 'credit' ? `+₹${item.amount.toLocaleString()}` : '-'}
                    </td>
                    <td className="px-4 py-3 text-right font-semibold text-destructive">
                      {item.type === 'debit' ? `-₹${item.amount.toLocaleString()}` : '-'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      <Dialog open={rejectDialog.open} onOpenChange={o => setRejectDialog(d => ({ ...d, open: o }))}>
        <DialogContent>
          <DialogHeader><DialogTitle>Reject Top-Up</DialogTitle></DialogHeader>
          <div className="space-y-2 py-2">
            <Label>Remarks (required)</Label>
            <Input value={remarks} onChange={e => setRemarks(e.target.value)} placeholder="Reason for rejection..." />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setRejectDialog({ open: false, id: '' })}>Cancel</Button>
            <Button variant="destructive" onClick={handleReject} disabled={!remarks.trim()}>Reject</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

